/* Stockage sûr : si le navigateur bloque localStorage (fichier ouvert en local,
   navigation privée, cadre isolé), on bascule sur une mémoire de session.
   Sans ce filet, la lecture de la langue lève une erreur et tout le script meurt. */
var _LSMEM={},_LSDEMO=Object.create(null);
/* Les fichiers de présentation marketing choisissent seuls leur langue.
   Test rejoue le vrai premier lancement Client : son choix reste uniquement
   en mémoire pendant la session courante. */
if(VERDICT_PRESENTATION_PROFILE){
  try{
    var _presentationLang=(new URLSearchParams(location.search+(self.__vdq||"")).get('lang')||navigator.language||'fr').slice(0,2).toLowerCase();
    if(['fr','en','es','it','de','nl','pt'].indexOf(_presentationLang)<0)_presentationLang='fr';
    _LSMEM.verdict_locale=_presentationLang;_LSMEM.verdict_lang_asked='1';
  }catch(e){_LSMEM.verdict_locale='fr';_LSMEM.verdict_lang_asked='1';}
}
function verdictDemoPreferenceGlobale(k){return k==='verdict_locale'||k==='verdict_lang_asked';}
function verdictDemoStorageActive(){return typeof VERDICT_DEMO_SESSION!=='undefined'&&VERDICT_DEMO_SESSION===true&&!VERDICT_PRESENTATION_PROFILE&&!VERDICT_TEST_SESSION;}
function verdictDemoStorageReset(){_LSDEMO=Object.create(null);}
function lsGet(k){
  if(VERDICT_PRESENTATION_PROFILE||VERDICT_TEST_SESSION)return (k in _LSMEM)?_LSMEM[k]:null;
  /* En démonstration, seuls les deux choix de langue volontaires restent des
     préférences globales. Tous les autres marqueurs, brouillons, événements et
     états de visite appartiennent au bac à sable et ne lisent jamais le réel. */
  if(verdictDemoStorageActive()&&!verdictDemoPreferenceGlobale(k))return (k in _LSDEMO)?_LSDEMO[k]:null;
  try{ var v=localStorage.getItem(k); return (v===null&&k in _LSMEM)?_LSMEM[k]:v; }catch(e){ return (k in _LSMEM)?_LSMEM[k]:null; }
}
function lsSet(k,v){
  if(VERDICT_PRESENTATION_PROFILE||VERDICT_TEST_SESSION){_LSMEM[k]=v;return;}
  if(verdictDemoStorageActive()&&!verdictDemoPreferenceGlobale(k)){_LSDEMO[k]=String(v);return;}
  _LSMEM[k]=v;try{ localStorage.setItem(k,v); }catch(e){}
}
/* Mesure produit minimale et locale. Aucun montant, nom, e-mail, identifiant
   d'établissement ou texte libre n'entre dans ces événements. Ils servent à
   mesurer le chemin réel avant le lancement large, puis peuvent être exportés
   vers le Pilote. Un doublon identique dans les 30 secondes est ignoré. */
var VERDICT_EVENT_KEY='verdict:events:client:v1';
var VERDICT_EVENT_ALLOWED={
  app_open:1,return_monthly:1,demo_intent_selected:1,first_reading_visible:1,
  account_start_after_value:1,full_diagnostic_start:1,full_diagnostic_ready:1,
  action_started:1,action_completed:1,inventory_bridge_used:1,vera_replayed:1,
  demo_tour_step:1,demo_decision_step:1,demo_tour_completed:1,demo_tour_exit:1,demo_path_selected:1
};
function verdictSafeEventMeta(meta){
  var out={},allowed={mode:1,intent:1,source:1,view:1,partial:1,locale:1,route:1,stage:1,step:1,choice:1};
  meta=meta&&typeof meta==='object'?meta:{};
  Object.keys(meta).forEach(function(k){
    if(!allowed[k])return;var v=meta[k];
    if(typeof v==='boolean')out[k]=v;
    else if(typeof v==='string')out[k]=v.replace(/[^a-z0-9_.:-]/gi,'').slice(0,48);
  });
  return out;
}
window.verdictTrack=function(name,meta){
  if(!VERDICT_EVENT_ALLOWED[name])return false;
  try{
    var q=JSON.parse(lsGet(VERDICT_EVENT_KEY)||'[]');if(!Array.isArray(q))q=[];
    var now=new Date(),safe=verdictSafeEventMeta(meta),signature=name+'|'+JSON.stringify(safe);
    var last=q.length?q[q.length-1]:null;
    if(last&&last.signature===signature&&Date.parse(last.at)>Date.now()-30000)return false;
    q.push({schema:1,event:name,at:now.toISOString(),month:now.toISOString().slice(0,7),meta:safe,signature:signature});
    if(q.length>400)q=q.slice(-400);lsSet(VERDICT_EVENT_KEY,JSON.stringify(q));
    if(typeof window.gtag==='function')window.gtag('event',name,safe);
    return true;
  }catch(e){return false;}
};
window.verdictTrackMilestone=function(name,meta,suffix){
  var key='verdict:milestone:'+name+':'+String(suffix||'default').replace(/[^a-z0-9_-]/gi,'').slice(0,32);
  if(lsGet(key)==='1')return false;
  var ok=window.verdictTrack(name,meta);if(ok)lsSet(key,'1');return ok;
};
window.verdictMetricsExport=function(){
  var q=[];try{q=JSON.parse(lsGet(VERDICT_EVENT_KEY)||'[]');if(!Array.isArray(q))q=[];}catch(e){}
  return {schema:1,product:'Verdict Pro',release:'V10.17.2',generatedAt:new Date().toISOString(),events:q.map(function(x){return {event:x.event,at:x.at,month:x.month,meta:x.meta||{}};})};
};
/* Le retour mensuel est une preuve de rétention, pas une simple réouverture
   dans la même journée. */
(function(){
  var now=new Date(),month=now.toISOString().slice(0,7),previous=lsGet('verdict:last-open-month');
  window.verdictTrack('app_open',{source:'direct'});
  if(previous&&previous!==month)window.verdictTrack('return_monthly',{source:'direct'});
  lsSet('verdict:last-open-month',month);
})();
