function esc(s){ return (s==null?"":String(s)).replace(/[&<>"]/g,function(c){
  return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]; }); }
/* R313 — lecteur de nombres unique (moteur 2). Remplace quatre lectures divergentes :
   « 0.125 » lu 125 à l'import ventes, « 1,234.50 » lu 1,2345 et « 1e3 » lu 13 à l'import caisse.
   Règles : vide ou illisible = null (absent ≠ zéro) ; groupes de milliers vérifiés ; le dernier séparateur
   est décimal quand il y a les deux ; strict (imports) : « 1.234 » est ambigu → null, notation 1e3 refusée. */
function verdictReadNumber(v,strict){
  if(v===""||v==null)return null;
  if(typeof v==='number')return Number.isFinite(v)?v:null;
  if(typeof v!=='string'&&typeof v!=='bigint')return null;
  var raw=String(v).trim().replace(/^€|€$/g,'').replace(/%$/,'').trim();if(/\d[\s\u00a0\u202f\u2009']+\d/.test(raw)&&!/^[-+]?\d{1,3}(?:[\s\u00a0\u202f\u2009']\d{3})+(?:[.,]\d+)?$/.test(raw))return null;
  var s=String(v).trim().replace(/[\s\u00a0\u202f\u2009']/g,"").replace(/^€|€$/g,"").replace(/%$/,"");
  if(s==="")return null;
  if(/^[-+]?(\d+\.?\d*|\.\d+)e[-+]?\d+$/i.test(s)){ if(strict)return null; var e=Number(s); return Number.isFinite(e)?e:null; }
  if(!/^[-+]?[0-9.,]+$/.test(s)||!/[0-9]/.test(s))return null;
  var sign="";if(s.charAt(0)==="-"||s.charAt(0)==="+"){sign=s.charAt(0)==="-"?"-":"";s=s.slice(1);}
  var nc=s.split(",").length-1,nd=s.split(".").length-1,ip,fp="";
  if(nc&&nd){var dec=s.lastIndexOf(",")>s.lastIndexOf(".")?",":".",th=dec===","?".":",",parts=s.split(dec);
    if(parts.length!==2)return null;
    if(!(th==="."?/^\d{1,3}(\.\d{3})+$/:/^\d{1,3}(,\d{3})+$/).test(parts[0]))return null;
    ip=parts[0].split(th).join("");fp=parts[1];}
  else if(nc===1){var a=s.split(",");ip=a[0];fp=a[1];}
  else if(nc>1){if(!/^\d{1,3}(,\d{3})+$/.test(s))return null;ip=s.replace(/,/g,"");}
  else if(nd===1){var b=s.split(".");ip=b[0];fp=b[1];if(strict&&fp.length===3&&/^[1-9]\d{0,2}$/.test(ip))return null;}
  else if(nd>1){if(!/^\d{1,3}(\.\d{3})+$/.test(s))return null;ip=s.replace(/\./g,"");}
  else ip=s;
  if(!/^\d*$/.test(ip)||!/^\d*$/.test(fp)||(ip===""&&fp===""))return null;
  var n=Number(sign+(ip||"0")+(fp?"."+fp:""));
  return Number.isFinite(n)?n:null; }
function num(v){ /* R126 puis R313 : lecture unique, voir verdictReadNumber. */ return verdictReadNumber(v,false); }
function localeTag(){ return typeof LOCALE_TAG==='string'?LOCALE_TAG:'fr-FR'; }
function eur(n){ if(n==null||isNaN(n))return "\u2014";
  return Math.round(n).toLocaleString(localeTag()).replace(/\u202f/g,"\u00a0")+"\u00a0\u20ac"; }
function eur2(n){ if(n==null||isNaN(n))return "\u2014";
  return n.toLocaleString(localeTag(),{minimumFractionDigits:2,maximumFractionDigits:2}).replace(/\u202f/g,"\u00a0")+"\u00a0\u20ac"; }
function pc(n,d){ if(n==null||isNaN(n))return "\u2014";
  return n.toLocaleString(localeTag(),{minimumFractionDigits:d==null?1:d,maximumFractionDigits:d==null?1:d})+"\u00a0%"; }
function fr(n,d){ if(n==null||isNaN(n))return "\u2014";
  return n.toLocaleString(localeTag(),{minimumFractionDigits:d||0,maximumFractionDigits:d||0}).replace(/\u202f/g,"\u00a0"); }
var VERDICT_LAST_TRUSTED_GESTURE=0;
["pointerdown","keydown"].forEach(function(type){document.addEventListener(type,function(event){if(event.isTrusted)VERDICT_LAST_TRUSTED_GESTURE=Date.now();},true);});
function toast(m){ try{ if(navigator.vibrate&&Date.now()-VERDICT_LAST_TRUSTED_GESTURE<1200)navigator.vibrate(8); }catch(e){}
  var t=document.getElementById("toast"); t.textContent=m; t.classList.add("on");
  clearTimeout(t._t); t._t=setTimeout(function(){ t.classList.remove("on"); },2200); }
function ask(title,msg,label,cb,danger){
  var av=document.getElementById('aVera'); if(av)av.hidden=true;
  document.getElementById("aTitle").textContent=title;
  var am=document.getElementById("aMsg"); am.textContent=msg||""; am.style.whiteSpace='normal';
  var cancel=document.querySelector('#mAsk .row .btn.sec');
  if(cancel){ cancel.textContent='Annuler'; cancel.onclick=function(){ document.getElementById('mAsk').classList.remove('on'); }; }
  var ok=document.getElementById("aOk");
  ok.textContent=label||"Confirmer";
  ok.style.background=danger?"var(--red)":"";
  ok.style.color=danger?"#fff":"";
  ok.onclick=function(){ document.getElementById("mAsk").classList.remove("on"); cb(); };
  document.getElementById("mAsk").classList.add("on");
}
/* Accessibilité des feuilles dynamiques : un dialogue garde la trace du
   contrôle qui l'a ouvert, annonce son titre et rend le focus au même endroit
   à sa fermeture. Cette couche ne touche ni aux données ni aux calculs. */
var VERDICT_DIALOG_SEQ=0;
function a11yDialogFocusable(el){
  return el?Array.prototype.slice.call(el.querySelectorAll('button:not([disabled]),[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')):[];
}
function a11yDialogPrepare(el){
  if(!el)return;
  if(!el._a11yReturnFocus){
    var active=document.activeElement;
    if(active&&active!==document.body&&!el.contains(active))el._a11yReturnFocus=active;
  }
  el.setAttribute('role','dialog');
  el.setAttribute('aria-modal','true');
  var title=el.querySelector('h1,h2,h3');
  if(title){
    if(!title.id)title.id='verdict-dialog-title-'+(++VERDICT_DIALOG_SEQ);
    el.setAttribute('aria-labelledby',title.id);
    el.removeAttribute('aria-label');
    if(!title.hasAttribute('tabindex'))title.setAttribute('tabindex','-1');
    title.classList.add('a11y-dialog-title-focus');
  }else if(!el.hasAttribute('aria-label'))el.setAttribute('aria-label','Fenêtre Verdict');
  clearTimeout(el._a11yFocusTimer);
  el._a11yFocusTimer=setTimeout(function(){
    if(!el.isConnected||!el.classList.contains('on')||el.contains(document.activeElement))return;
    var target=el.querySelector('h1,h2,h3')||a11yDialogFocusable(el)[0]||el;
    if(target===el&&!el.hasAttribute('tabindex'))el.setAttribute('tabindex','-1');
    try{target.focus({preventScroll:true});}catch(e){try{target.focus();}catch(_){} }
  },0);
}
function a11yDialogRestore(el){
  if(!el)return;
  clearTimeout(el._a11yFocusTimer);
  var back=el._a11yReturnFocus;el._a11yReturnFocus=null;
  if(back&&back.isConnected)setTimeout(function(){try{back.focus({preventScroll:true});}catch(e){try{back.focus();}catch(_){} }},0);
}
function a11yTopDialog(){
  var all=document.querySelectorAll('.modal.on,#refSh.on'),top=null,z=-Infinity;
  Array.prototype.forEach.call(all,function(el){var n=parseInt((window.getComputedStyle?getComputedStyle(el).zIndex:'0'),10);if(!isFinite(n))n=0;if(n>=z){z=n;top=el;}});
  return top;
}
function a11yCloseDialog(el){
  if(!el)return;
  if(el.id==='mLang'){closeLang();return;}
  if(el.id==='mEtabs'){closeEtabs();return;}
  if(el.id==='refSh'){refRetourSecurise();return;}
  if(el.id==='shSco'&&typeof window.scoreSheetClose==='function'){window.scoreSheetClose();return;}
  if(el.id==='shCarte'&&typeof window.cardScoreSheetClose==='function'){window.cardScoreSheetClose();return;}
  if(el.id==='mDemoPowerIntro'&&typeof demoSuiteQuitter==='function'){demoSuiteQuitter('escape');return;}
  a11yDialogRestore(el);el.classList.remove('on');
}
document.addEventListener('keydown',function(e){
  var custom=e.target&&e.target.closest?e.target.closest('[role="button"][tabindex="0"]'):null;
  if(custom&&custom.tagName!=='BUTTON'&&custom.tagName!=='A'&&(e.key==='Enter'||e.key===' ')){
    e.preventDefault();custom.click();return;
  }
  var dialog=a11yTopDialog();if(!dialog)return;
  if(e.key==='Escape'){e.preventDefault();a11yCloseDialog(dialog);return;}
  if(e.key==='Tab'){
    var list=a11yDialogFocusable(dialog);if(!list.length){e.preventDefault();dialog.focus();return;}
    var first=list[0],last=list[list.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
  }
});
