function scoreClamp(score){
  var value=Number(score);return isFinite(value)?Math.max(0,Math.min(100,value)):0;
}
function ringSVG(score,hex,size){
  var available=typeof score==='number'&&isFinite(score)&&score>=0&&score<=100;
  score=scoreClamp(score);
  var r=(size-10)/2, c=2*Math.PI*r, off=c*(1-score/100);
  /* Inset en pourcentage : le point reste sur l'anneau aussi à 88/92 px. */
  var light=available?'<span class="orbit" aria-hidden="true" style="inset:'+(500/size)+'%;--ringcol:'+hex+';--score-orbit-rest:'+(score*3.6)+'deg"><i></i></span>':'';
  return '<svg width="'+size+'" height="'+size+'" viewBox="0 0 '+size+' '+size+'" preserveAspectRatio="xMidYMid meet"><circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="#1c2128" stroke-width="9"/>'+
    '<circle cx="'+size/2+'" cy="'+size/2+'" r="'+r+'" fill="none" stroke="'+hex+'" stroke-width="9" stroke-linecap="round" stroke-dasharray="'+c+'" stroke-dashoffset="'+off+'"/></svg>'+light;
}
