var VERDICT_I18N_PACKS=window.VERDICT_I18N_PACKS||{},VERDICT_I18N_LOADS={};
(function(){var style=document.createElement('style');style.id='verdict-i18n-loading-style';style.textContent='html.verdict-i18n-loading body{visibility:hidden!important}';(document.head||document.documentElement).appendChild(style);})();
function verdictInstallLanguagePack(l){
  var pack=VERDICT_I18N_PACKS[l],pos=typeof TR_ORDER!=='undefined'?TR_ORDER.indexOf(l):-1;
  if(!pack||!pack.dict||!pack.tr||pos<0)return false;
  I18N_DICT[l]=pack.dict;
  Object.keys(pack.tr).forEach(function(source){var row=TR[source]||[];row[pos]=pack.tr[source];TR[source]=row;});
  _trIdx=null;_trKeys=null;_trTplCache=null;
  if(typeof _trCountCache!=='undefined')_trCountCache=-1;
  if(typeof _trTextMemo!=='undefined')_trTextMemo={lang:'',count:-1,values:Object.create(null),order:[]};
  return true;
}
function verdictLoadLanguagePack(l,done){
  done=typeof done==='function'?done:function(){};
  if(l==='fr'){done(true);return;}
  if(VERDICT_I18N_PACKS[l]){done(verdictInstallLanguagePack(l));return;}
  if(VERDICT_I18N_LOADS[l]){VERDICT_I18N_LOADS[l].push(done);return;}
  VERDICT_I18N_LOADS[l]=[done];
  var script=document.createElement('script');script.async=true;script.src='assets/i18n/verdict-'+l+'.js';script.setAttribute('data-verdict-language-pack',l);
  function finish(ok){var queue=VERDICT_I18N_LOADS[l]||[];delete VERDICT_I18N_LOADS[l];if(script.parentNode)script.parentNode.removeChild(script);queue.forEach(function(callback){try{callback(ok);}catch(e){}});}
  script.onload=function(){finish(verdictInstallLanguagePack(l));};
  script.onerror=function(){finish(false);};
  (document.head||document.documentElement).appendChild(script);
}

