function trText(s,depth){
  var ix=trIndex(); if(!ix.map)return s;
  var raw=trNorm(s),trimmed=raw.trim();
  if(!trimmed)return s;
  function resolve(text){
    /* Une phrase exacte gagne toujours sur un gabarit générique tel que
       « Vous {x} ». Sinon « Vous pouvez… » devenait « You pouvez… ». */
    if(ix.map[text]!==undefined)return ix.map[text];
    var templ=trTemplateText(text); return templ!==null?templ:null;
  }
  var translated=resolve(trimmed),prefix='',core=trimmed;
  if(translated===null){
    var marked=trimmed.match(/^((?:(?:\d+[.)]|[✓✔●▶▸▲▼▾•→←⚠⚪➕ℹ·+\-–—]|[\uD800-\uDBFF][\uDC00-\uDFFF])\s+)+)([\s\S]+)$/);
    if(marked){prefix=marked[1];core=marked[2];translated=resolve(core);}
  }
  if(translated===null)return s;
  /* Une variable de gabarit peut elle-même être un libellé français court. */
  if(!depth&&translated.indexOf('{')<0){ translated=String(translated); }
  var start=raw.indexOf(trimmed),lead=raw.slice(0,start),tail=raw.slice(start+trimmed.length);
  return lead+prefix+translated+tail;
}
var _trObs=null,_trBusy=false;
function startTranslateObserver(){
  if(LOCALE==='fr'||_trObs||!window.MutationObserver)return;
  _trObs=new MutationObserver(function(muts){
    if(_trBusy)return;
    var targets=[];
    for(var i=0;i<muts.length;i++){
      var m=muts[i];
      if(m.type==='characterData'){ if(m.target.parentNode)targets.push(m.target.parentNode); }
      for(var j=0;j<m.addedNodes.length;j++){
        var n=m.addedNodes[j];
        if(n.nodeType===1||n.nodeType===3)targets.push(n.nodeType===3?n.parentNode:n);
      }
    }
    if(!targets.length)return;
    _trBusy=true;
    try{ for(var k=0;k<targets.length;k++){ if(targets[k])translateDOM(targets[k]); } }
    finally{ _trBusy=false; }
  });
  _trObs.observe(document.body,{childList:true,subtree:true,characterData:true});
}
/* R321 : en anglais le symbole € se place devant le montant (« €1,171.81 »), en néerlandais « € 1.171,81 ».
   Les montants sont déjà au format de la langue ; seul l'ordre change, après la traduction du texte. */
function vdMoneyOrder(s){
  if(typeof s!=='string'||s.indexOf('\u20ac')<0)return s;
  if(LOCALE==='en')return s.replace(/([+\u2212-]?)(\d[\d,]*(?:\.\d+)?)[\u00a0\u202f ]?\u20ac/g,'$1\u20ac$2');
  if(LOCALE==='nl')return s.replace(/([+\u2212-]?)(\d[\d.]*(?:,\d+)?)[\u00a0\u202f ]?\u20ac/g,'\u20ac\u00a0$1$2');
  return s;
}
function translateDOM(root){
  if(LOCALE==='fr')return;
  var r=root||document.body; if(!r)return;
  var w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT,null,false),n;
  var todo=[];
  while((n=w.nextNode())){
    var pt=n.parentNode;
    if(!pt)continue;
    var tag=pt.tagName;
    if(tag==='SCRIPT'||tag==='STYLE')continue;
    /* Point 13 V10.13.1 — le rapport financier est validé en français.
       Une traduction fragmentaire fabrique du franglais et peut changer le
       sens d'un calcul. Les six autres interfaces gardent donc le rapport
       français complet, précédé d'une notice déjà localisée. */
    if(pt.closest&&pt.closest('#auditBody'))continue;
    todo.push(n);
  }
  for(var i=0;i<todo.length;i++){
    var t0=todo[i].nodeValue, t1=vdMoneyOrder(trText(t0));
    if(t1!==t0) todo[i].nodeValue=t1;
  }
  var ph=r.querySelectorAll?r.querySelectorAll('[placeholder],[aria-label],[title]'):[];
  for(var j=0;j<ph.length;j++){
    if(ph[j].closest&&ph[j].closest('#auditBody'))continue;
    ['placeholder','aria-label','title'].forEach(function(attr){
      if(!ph[j].hasAttribute(attr))return;
      var p0=ph[j].getAttribute(attr),p1=trText(p0);
      if(p1!==p0)ph[j].setAttribute(attr,p1);
    });
  }
}
