/* ─────────────────────────────────────────────────────────────
   PALIER D'ACCÈS
   Le navigateur ne décide JAMAIS seul du palier. En production, le
   statut vient du serveur (VERDICT_TIER injecté après authentification).
   Sans droit serveur, l'application conserve les données locales mais les vues
   métier restent protégées.
   Le parcours « Découvrir Verdict » ouvre les modules Pro uniquement avec
   les données fictives de démonstration ; il ne donne aucun droit au compte.
   ───────────────────────────────────────────────────────────── */
window.VERDICT_DEMO=false;  /* production : jamais de Pro global côté navigateur */
/* V10.11.1 — le droit Pro vient toujours du serveur. Les données gardent une
   copie locale isolée par compte ; si le coffre chiffré est configuré, elles
   disposent aussi d'une copie versionnée dans le compte. */
function verdictAccountDefaultState(status){
  status=status||'checking';
  return {loaded:status!=='checking',service_status:status,service_code:'',service_error:'',auth:false,tier:'verdict',
    access_state:status==='unavailable'?'service_unavailable':status,trial:false,paid:false,email:'',storage_scope:'',trial_days_left:0,
    trial_ends_at:0,first_charge_at:0,current_period_end:0,has_billing_profile:false,has_subscription:false,billing_grace:false,
    cancel_at_period_end:false,csrf:'',multisite_pricing_enabled:true,multisite_owner_only:true,included_active_establishments:1,
    active_establishments:1,entitled_extra_establishments:0,establishment_limit:1,subscription_period:'',founder_price_lock:false};
}
/* Normalisation pure du contrat renvoyé par le service de compte. Une panne
   réseau n'est jamais transformée en « essai expiré » : c'est un état séparé. */
function verdictNormalizeAccountState(payload,status){
  status=status||'available';
  if(status!=='available')return verdictAccountDefaultState(status);
  var j=payload&&typeof payload==='object'?payload:{},u=j.user&&typeof j.user==='object'?j.user:null,s=verdictAccountDefaultState('available');
  s.loaded=true;s.auth=!!u;s.tier=u&&(u.tier==='pro'||u.tier==='pilotage')?u.tier:'verdict';s.access_state=u&&u.access_state||'anonymous';
  s.trial=!!(u&&u.trial);s.paid=!!(u&&u.paid);s.email=u&&u.email||'';s.storage_scope=u&&u.storage_scope||'';
  s.trial_days_left=Number(u&&u.trial_days_left)||0;s.trial_ends_at=Number(u&&u.trial_ends_at)||0;
  s.first_charge_at=Number(u&&u.first_charge_at)||0;s.current_period_end=Number(u&&u.current_period_end)||0;
  s.has_billing_profile=!!(u&&u.has_billing_profile);s.has_subscription=!!(u&&u.has_subscription);
  s.billing_grace=!!(u&&u.billing_grace);s.cancel_at_period_end=!!(u&&u.cancel_at_period_end);s.csrf=j.csrf||'';
  s.multisite_pricing_enabled=u&&u.multisite_pricing_enabled!==false;s.multisite_owner_only=u&&u.multisite_owner_only!==false;
  s.included_active_establishments=Math.max(1,Number(u&&u.included_active_establishments)||1);
  s.active_establishments=Math.max(1,Number(u&&u.active_establishments)||1);
  s.entitled_extra_establishments=Math.max(0,Number(u&&u.entitled_extra_establishments)||0);
  s.establishment_limit=Math.max(1,Number(u&&u.establishment_limit)||s.included_active_establishments);
  s.subscription_period=u&&u.subscription_period||'';s.founder_price_lock=!!(u&&u.founder_price_lock);
  /* Contrat de sûreté J15 : un payload serveur contradictoire ne doit jamais
     laisser un ancien drapeau d'essai/abonnement rouvrir les vues Pro. Les
     données restent dans le portefeuille ; seul le droit d'accès est fermé. */
  if(s.access_state==='expired'){
    s.tier='verdict';s.trial=false;s.paid=false;s.billing_grace=false;s.cancel_at_period_end=false;
  } return s;
}
function verdictAccountContract(s){
  if(!s||!s.loaded||s.service_status==='checking')return 'checking';
  if(s.service_status==='test')return 'test';
  if(s.service_status!=='available')return 'unavailable';
  if(!s.auth)return 'anonymous';
  if(s.access_state==='expired')return 'expired';
  if(s.billing_grace)return 'grace';
  if(s.access_state==='billing_issue')return 'billing_issue';
  if(s.trial)return 'trial';
  if(s.paid)return s.cancel_at_period_end?'canceling':'paid';
  return 'free';
}
function verdictAccountOnOutage(previous,error){
  /* Une panne après une réponse serveur Pro valide ne doit pas transformer le
     client en compte expiré. On conserve uniquement le dernier droit connu de
     cette session, marqué périmé. Au premier chargement sans preuve, on reste
     fermé : aucune autorisation ne sera inventée hors ligne. */
  var trusted=previous&&previous.loaded&&previous.service_status==='available'&&previous.auth&&(previous.tier==='pro'||previous.tier==='pilotage')&&
    (previous.trial||previous.paid||previous.billing_grace);
  if(trusted){
    var kept={};Object.keys(previous).forEach(function(k){kept[k]=previous[k];});
    kept.service_stale=true;kept.service_error=error&&error.message||'account_service_unavailable';return kept;
  }
  var unavailable=verdictNormalizeAccountState(null,'unavailable');
  unavailable.service_code=error&&error.payload&&error.payload.code||'account_service_unavailable';
  unavailable.service_error=error&&error.message||'account_service_unavailable';return unavailable;
}
