        condition:function(m){var r=repFamille("fc"); return m.fc > (r?r[2]:32);},
        diagnosis:"Coût matière au-dessus du repère Verdict",
        detail:"Vos achats représentent {fc}% du CA (repère de pilotage Verdict : 28%)",
        action:"Vérifiez d’abord achats, fiches, pertes et prix avant de modifier carte ou portions",
        timeEstimate:"week",
