/* V9.4 — une confirmation ne vaut que pour LES chiffres confirmés.
   Faiblesse trouvée en comparant avec la version de ChatGPT, qui traite ce cas
   mieux : je marquais l'anomalie confirmée une fois pour toutes. Le client
   pouvait confirmer « marge très élevée », puis modifier sa saisie — la
   confirmation restait valable sur des chiffres qu'il n'avait jamais validés.
   On enregistre donc l'empreinte des données au moment de la confirmation :
   dès qu'un chiffre bouge, la question se repose. */
function empreinteDonnees(){
  try{
    var q=DB.in||{}, k=['panier','tva','cmdj','jsem','mois','nour','boi','emb','autv','com',
      'dirb','dirn','dirt','salb','saln','salt','f1','f2','f3','f4','f5','f6','f7','f8','f9','f10'];
    var base=k.map(function(x){ var v=q[x]; return x+'='+(typeof v==='number'&&isFinite(v)?Math.round(v*10000)/10000:String(v)); }).join('|');
    var ctx=normalizedEstablishmentProfile(DB.establishmentProfile);
    return base+'|context='+Object.keys(ctx).map(function(x){return x+'='+String(ctx[x]||'');}).join(',');
  }catch(e){ return ''; }
}
function anomaliesNonConfirmees(){
  var out=[];
  try{ if(typeof DB==='undefined'||!DB||!DB.in)return out; }catch(e){ return out; }
  var c=DB.confirmations||{}, emp=empreinteDonnees();
  ANOMALIES.forEach(function(a){
    var t=false; try{ t=a.test(); }catch(e){}
    /* confirmée uniquement si elle l'a été SUR CES CHIFFRES-LÀ */
    if(t && c[a.k]!==emp) out.push(a);
  });
  return out;
}
function confirmerAnomalie(k){
  if(!DB.confirmations)DB.confirmations={};
  DB.confirmations[k]=empreinteDonnees();
  try{ save(); }catch(e){}
  try{ goVerdict(); }catch(e){}
}
function confirmerToutesAnomalies(){
  if(!DB.confirmations)DB.confirmations={};
  var emp=empreinteDonnees(), a=[];
  try{ a=anomaliesNonConfirmees(); }catch(e){}
  a.forEach(function(x){ DB.confirmations[x.k]=emp; });
  try{ save(); }catch(e){}
  try{ majValidationVisible(); }catch(e){}
  try{ goVerdict(); }catch(e){}
}

/* Point 3/10 — un score final n'est autorisé que par la combinaison complète
   « exercice clos + CA déclaré + provenance client ». Un simple booléen
   importé ne peut donc jamais transformer une démonstration, une prévision ou
   une période en cours en résultat final. */
function verdictFinalAllowed(d){
  try{
    d=d||(typeof DB!=='undefined'?DB:null);if(!d)return false;
    var p=d.dataProvenance||{},rs=d.refSource||{},ref=d.ref||{};
    var year=rs.exerciseYear!=null?rs.exerciseYear:ref.exercice;
    var declared=rs.ca!=null?rs.ca:ref.ca;
    return p.nature==='client_actual_closed_period'&&p.finalScoreAllowed===true&&
      verdictDirectAnnualSource(d)&&isFinite(Number(year))&&Number(year)>=1900&&
      isFinite(Number(declared))&&Number(declared)>0;
  }catch(e){return false;}
}

function verdictWeightedScore(d){
  var ca=d.ca;
  function p(x){ return ca>0?x/ca*100:0; }
  var v=VerdictFinance.metrics(d),senX=v.sen/100;
  var s={};
  s.rn=NOTES.rn(v.rn/100); s.mc=NOTES.mc(v.mc/100); s.cv=NOTES.cv(v.cv/100);
  s.ms=NOTES.ms(v.ms/100); s.acf=NOTES.acf(v.acf/100); s.tc=NOTES.tc(v.tc/100);
  s.pm=NOTES.pm(v.pm/100); s.sen=NOTES.sen(senX);
  s.fc=NOTES.fc(v.fc/100); s.pc=NOTES.pc(v.pc/100); s.com=NOTES.com(v.com/100);
  var prodAvailable=d.hNote>0&&d.cmdAn>0;
  s.prod=prodAvailable?NOTES.prod(d.mc/d.hNote):null;
  var n1=0,n2=0,n3=0,n3Weight=0,k;
  for(k in W1)n1+=s[k]*W1[k];
  for(k in W2)n2+=s[k]*W2[k];
  for(k in W3){if(k==='prod'&&!prodAvailable)continue;n3+=s[k]*W3[k];n3Weight+=W3[k];}
  if(n3Weight>0)n3=n3/n3Weight;
  var raw=.50*n1+.25*n2+.25*n3;
  var rnx=v.rn/100, cap=rnx<0?30:(rnx<0.05?60:(rnx<0.08?75:100));
  var score=Math.round(Math.min(raw,cap));

  return {v:v,s:s,n1:n1,n2:n2,n3:n3,cap:cap,score:isFinite(score)?score:0};
}
function moteur(over){
  var d=deriv(over), ca=d.ca;
  var validation=validate(d);
  d.validation=validation;
  var weighted=verdictWeightedScore(d),v=weighted.v,s=weighted.s,n1=weighted.n1,n2=weighted.n2,n3=weighted.n3,cap=weighted.cap,score=weighted.score;
  /* Les erreurs de domaine (ex. TVA -100 %) rendent certaines divisions
     impossibles avant que validate() ne les bloque. Même dans cet état
     refusé, le moteur ne doit jamais propager NaN/Infinity à l'interface. */
  if(!isFinite(score)||isNaN(score))score=0;
  /* V8.0 — le score exige des données complètes. Une seule donnée critique
     inconnue et le diagnostic reste incomplet : mieux vaut pas de note du tout
     qu'une note fausse construite sur des absences prises pour des zéros. */
  var _manq=[]; try{ _manq=donneesManquantes(); }catch(e){}
  var _anom=[]; try{ _anom=anomaliesNonConfirmees(); }catch(e){}
  /* V8.4 — Steven : « j'ai mis au hasard et ça marche alors que c'est
     incohérent ». validate() détectait déjà tout (salaires > CA, achats > CA,
     point mort impossible…) mais son résultat n'était qu'AFFICHÉ après coup,
     jamais utilisé pour bloquer. Une erreur bloquante interdit désormais le
     score : on ne note pas une structure qui ne peut pas exister. */
  var _incoh=(validation && validation.errors) ? validation.errors : [];
  var _ready=!d.exactEngineError&&ca>0&&(d.panierTTC>0||verdictDirectAnnualSource(DB))&&_manq.length===0&&_anom.length===0&&_incoh.length===0;
  var _prov=(typeof DB!=='undefined'&&DB&&DB.dataProvenance)||{};
  var _finalAllowed=verdictFinalAllowed(typeof DB!=='undefined'?DB:null);
  var _status=!_ready?'incomplete':(_prov.nature==='model_estimate'?'simulation':(_prov.nature==='client_hypothesis'?'forecast':(_prov.nature==='client_observed_current_period'?'provisional':(_finalAllowed?'final':'confirmed-manual'))));
  /* Une donnée importée ou un stockage corrompu peut contourner les attributs
     min/max des champs HTML. La validation reste bloquante, mais aucun nombre
     non fini ne doit atteindre une carte, un PDF ou une animation. Chaque champ
     ainsi neutralisé est tracé nommément (nonCalculable) : un 0 de sécurité
     technique ne doit jamais se confondre avec un 0 réel pour un écran qui
     consulterait ce détail. */
  var _nonCalc=[];
  [['d',d],['v',v],['s',s]].forEach(function(pair){var _lab=pair[0],o=pair[1];Object.keys(o||{}).forEach(function(key){if(typeof o[key]==='number'&&!isFinite(o[key])){_nonCalc.push(_lab+'.'+key);o[key]=0;}});});
  if(!isFinite(n1)){_nonCalc.push('n1');n1=0;}if(!isFinite(n2)){_nonCalc.push('n2');n2=0;}if(!isFinite(n3)){_nonCalc.push('n3');n3=0;}if(!isFinite(cap)){_nonCalc.push('cap');cap=0;}
  return {d:d,v:v,s:s,n1:Math.round(n1),n2:Math.round(n2),n3:Math.round(n3),
    score:_ready?score:null,cap:cap,manquants:_manq,anomalies:_anom,incoherences:_incoh,nonCalculable:_nonCalc,
    ready:_ready,scoreStatus:_status,scoreFinalAllowed:_ready&&_finalAllowed,
    scoreFinal:_ready&&_finalAllowed?score:null};
}
