/* Arrondi comptable d'affichage par plus forts restes. Chaque ligne reste
   positive et la somme des dixiemes rejoint exactement le total affiche. */
function money100RoundRows(rows,targetPct){
  rows=rows||[];var target=Math.max(0,Math.round((+targetPct||0)*10)),base=0;
  var ranked=rows.map(function(x,i){
    var exact=Math.max(0,(+x.per100||0)*10),tenths=Math.floor(exact+1e-9);base+=tenths;
    return {row:x,index:i,tenths:tenths,remainder:exact-tenths};
  });
  ranked.sort(function(a,b){return b.remainder-a.remainder||(+b.row.eur||0)-(+a.row.eur||0)||a.index-b.index;});
  var delta=target-base,guard=0;
  while(delta>0&&ranked.length&&guard<10000){ranked[guard%ranked.length].tenths++;delta--;guard++;}
  while(delta<0&&ranked.length&&guard<20000){
    var q=ranked.slice().sort(function(a,b){return a.remainder-b.remainder||b.tenths-a.tenths||a.index-b.index;});
    var changed=false;for(var i=0;i<q.length&&delta<0;i++)if(q[i].tenths>0){q[i].tenths--;delta++;changed=true;}
    if(!changed)break;guard++;
  }
  ranked.forEach(function(x){x.row.display=x.tenths/10;});return rows;
}
/* ── Adaptateur de calcul de l'Audit Premium (V10.2) ──
   Les nouveaux chapitres lisent uniquement cette structure. Les simulations
   de prix repassent par moteur() : aucune règle de trois concurrente au moteur. */
function auditPremiumCalc(R){
  if(!R||!R.ready)return null;
  var d=R.d,v=R.v, c={};
  c.structure=[
    {l:'Chiffre d\u2019affaires HT',eur:d.ca,pct:100},
    {l:'Co\u00fbts variables',eur:-d.cvT,pct:v.cv},
    {l:'Marge sur co\u00fbts variables',eur:d.mc,pct:v.mc},
    {l:'Co\u00fbt humain charg\u00e9',eur:-d.sal,pct:v.ms},
    {l:'Autres charges fixes',eur:-d.af,pct:v.acf},
    {l:'Amortissements',eur:-d.amort,pct:d.ca>0?VerdictFinance.fraction(d.amort).div(d.ca).mul(100).number():0},
    {l:'Solde de pilotage avant imp\u00f4t',eur:d.res,pct:v.rn}
  ];
  var postes=[
    {l:'la mati\u00e8re',eur:d.mat||0},{l:'les autres co\u00fbts variables',eur:d.av||0},
    {l:'les plateformes',eur:d.com||0},{l:'les salaires',eur:d.sal||0},
    {l:'les autres charges fixes',eur:d.af||0}
  ].sort(function(a,b){return b.eur-a.eur;});
  c.reponses={poste:postes[0],postePct:d.ca>0?postes[0].eur/d.ca*100:0,
    resultat:d.res,resultatPct:v.rn,pointMort:v.pmEur,pointMortPct:v.pm,choc:v.sen};
  /* Point 2 — une seule identité économique, issue du moteur :
     CA HT = charges mesurées + solde. Les valeurs affichées au dixième sont
     réconciliées sur le poste le plus lourd afin que la lecture reste exacte
     malgré les arrondis. Aucun euro n'est recalculé dans la vue. */
  var m100Rows=[
    {id:'matter',l:'Matière · nourriture + boissons',eur:d.mat||0,c:'#f97316'},
    {id:'variable',l:'Emballages et autres variables',eur:d.av||0,c:'#a78bfa'},
    {id:'platforms',l:'Commissions plateformes',eur:d.com||0,c:'#8b5cf6'},
    {id:'team',l:'Équipe · coût chargé',eur:d.sal||0,c:'#60a5fa'},
    {id:'structure',l:'Structure hors équipe',eur:d.af||0,c:'#94a3b8'},
    {id:'amortization',l:'Amortissements',eur:d.amort||0,c:'#64748b'}
  ];
  m100Rows.forEach(function(x){x.per100=d.ca>0?x.eur/d.ca*100:0;});
  var m100Largest=m100Rows.slice().sort(function(a,b){return b.eur-a.eur;})[0];
  if(!m100Largest||!(m100Largest.eur>0))m100Largest=null;
  var m100Charges=VerdictFinance.money(VerdictFinance.sum([d.cvT||0,d.sal||0,d.af||0,d.amort||0])), m100Pct=d.ca>0?m100Charges/d.ca*100:0;
  var m100Status=d.res<0?'loss':(d.res>0?'positive':'neutral');
  money100RoundRows(m100Rows,m100Status==='neutral'?100:m100Pct);
  c.money100={
    annualExTax:true, rows:m100Rows, chargesEur:m100Charges, chargesPct:m100Pct,
    resultEur:d.res, resultPct:v.rn, balancePct:m100Pct+v.rn,
    status:m100Status, largest:m100Largest
  };
  var p3=point3Calc(R);
  c.seuil={atteignable:p3.attainable,eur:p3.breakEven,pct:p3.attainable&&d.ca>0?p3.breakEven/d.ca*100:999,
    securiteEur:p3.delta,securitePct:p3.attainable&&d.ca>0?p3.delta/d.ca*100:0,
    moisActifs:p3.activeMonths,joursActifs:p3.activeDays,
    parMoisActif:p3.requiredPerMonth,parJourOuvert:p3.requiredPerDay,
    commandesJour:p3.requiredOrders,tauxContribution:p3.contributionRate};
  c.productivite={commandes:d.cmdAn,jours:d.jAn,
    caJour:d.jAn>0?d.ca/d.jAn:null, contributionHeure:v.prod,
    etp:d.etp||0, caEtp:d.caSalarie==null?null:d.caSalarie};
  var p1=moteur({panier:d.panierTTC+1}), p2=moteur({panier:d.panierTTC+2});
  c.prix={base:d.panierTTC,
    plus1:p1&&p1.d?p1.d.res-d.res:0,
    plus1M:p1&&p1.d?(p1.d.res-d.res)/12:0,
    rn1:p1&&p1.v?p1.v.rn:v.rn,
    plus2:p2&&p2.d?p2.d.res-d.res:0,
    plus2M:p2&&p2.d?(p2.d.res-d.res)/12:0,
    rn2:p2&&p2.v?p2.v.rn:v.rn};
  c.canaux={commission:d.com,commissionPct:v.com,pfN:0,pfMarge:null};
  c.carte={ok:false,actifs:0,fiables:0,couverture:0,score:0,theo:0,marge:null,ecart:null,perte:0,best:[],weak:[]};
  try{
    var st=carteStats(), sc=scoreCarte(st), rows=[], pfM=[];
    c.carte.ok=!!(st&&st.actifs>0); c.carte.actifs=st.actifs||0;
    c.carte.score=sc&&isFinite(sc.total)?sc.total:0;
    c.carte.fiables=st.fiables||0;c.carte.couverture=st.actifs?Math.round((st.fiables||0)/st.actifs*100):0;
    c.carte.theo=st.theoR||0;c.carte.marge=st.ca>0?st.margePond:null;
    c.carte.ecart=st.theoR>0&&isFinite(v.fc)?v.fc-st.theoR:null;c.carte.perte=st.perte||0;
    c.canaux.pfN=st.pfN||0;
    (DB.plats||[]).forEach(function(p){
      var vol=+p.vol||0; if(vol<=0)return;
      var k=platCalc(p);if(!k.complete)return;var contrib=k.contribPond*vol;
      rows.push({nom:p.nom||'Plat',vol:vol,marge:k.contribPct,contrib:contrib});
      if(p.pf&&k.pf&&isFinite(k.pf.margePct))pfM.push(k.pf.margePct);
    });
    rows.sort(function(a,b){return b.contrib-a.contrib;});
    c.carte.best=rows.slice(0,3);
    if(rows.length>3)c.carte.weak=rows.slice(-3).reverse();
    if(pfM.length)c.canaux.pfMarge=pfM.reduce(function(a,b){return a+b;},0)/pfM.length;
  }catch(e){}
  return c;
}

