      htPrix=k.ht*.9*l+pfht*.9*f,
      pfCom=k.pf?(pfht-pfht*Math.min(100,(Number(DB.reg.compf)||0)+5)/100-(DB.reg.pack||0)-k.cout):0,
      comContrib=k.marge*l+pfCom*f;
