function cardScoreDishGap(p){
  var C=cardScoreGuideCopy(),k=platCalc(p||{}),share=p&&p.pf?Number(p.pfshare):0;
  if(!(Number(p&&p.ttc)>0))return {kind:'dish',platId:p&&p.id,fieldId:'p-ttc',label:C.price};
  if(!(p&&((p.rec&&p.rec.length)||(p.preps&&p.preps.length)))||!k.recetteComplete)return {kind:'dish',platId:p&&p.id,selector:'#recLines .rec-line select',label:C.recipe,recipe:true};
  if(p&&p.pf&&!(Number(p.pfttc)>0))return {kind:'dish',platId:p.id,fieldId:'p-pfPrix',label:C.deliveryPrice,standard:true};
  if(p&&p.pf&&(!isFinite(share)||share<0||share>100))return {kind:'dish',platId:p.id,fieldId:'p-pfShare',label:C.deliveryShare,standard:true};
  return {kind:'dish',platId:p&&p.id,fieldId:'p-vol',label:C.volume,note:C.zero};
}
function cardScoreMissingState(st){
  st=st||carteStats();var C=cardScoreGuideCopy(),ref=point5ReferenceState(),items=[];
  var pe=document.getElementById('p5-period'),se=document.getElementById('p5-source'),period=pe?pe.value:ref.period,source=se?se.value:ref.source;
  var periodOK=period==='demo'||/^\d{4}-(0[1-9]|1[0-2])$/.test(period||''),sourceOK=['caisse','import','manual','estimate','demo'].indexOf(source)>=0;
  if(!ref.ready){
    if(!periodOK)items.push({kind:'reference',fieldId:'p5-period',label:C.period});
    if(!sourceOK)items.push({kind:'reference',fieldId:'p5-source',label:C.source});
    if(periodOK&&sourceOK)items.push({kind:'reference',fieldId:'p5-save-ref',label:C.confirm,button:true});
  }
  var plats=DB.plats||[],active=plats.filter(function(p){return Number(p.vol)>0;});
  if(!plats.length)items.push({kind:'dish',platId:null,fieldId:'p-nom',label:C.dish,newDish:true});
  else if(!active.length){var first=plats[0];items.push({kind:'dish',platId:first.id,fieldId:'p-vol',label:C.volume,note:C.zero});}
  else{
    var incomplete=active.filter(function(p){return !platCalc(p).complete;})[0];
    if(incomplete)items.push(cardScoreDishGap(incomplete));
  }
  return {items:items,primary:items[0]||null,total:plats.length,active:active.length};
}
function cardScoreClearGuideMarks(){
  document.querySelectorAll('.verdict-guided-missing').forEach(function(el){el.classList.remove('verdict-guided-missing');el.removeAttribute('aria-invalid');el.removeAttribute('aria-describedby');});
  document.querySelectorAll('.verdict-guided-label').forEach(function(el){el.classList.remove('verdict-guided-label');});
  document.querySelectorAll('.card-score-guided-help').forEach(function(el){el.remove();});
}
function cardScoreMarkElement(el,item){
  if(!el)return;cardScoreClearGuideMarks();var C=cardScoreGuideCopy(),lab=el.closest&&el.closest('label.f');
  el.classList.add('verdict-guided-missing');if(lab)lab.classList.add('verdict-guided-label');
  if(el.tagName==='INPUT'||el.tagName==='SELECT'){el.setAttribute('aria-invalid','true');}
  var help=document.createElement('small'),hid='card-score-help-'+Date.now();help.id=hid;help.className='card-score-guided-help';help.textContent=(item.note||item.label)+' — '+C.required;el.setAttribute('aria-describedby',hid);el.insertAdjacentElement('afterend',help);
  function clear(){cardScoreClearGuideMarks();}el.addEventListener('input',clear,{once:true});el.addEventListener('change',clear,{once:true});
  try{el.scrollIntoView({behavior:scReduced()?'auto':'smooth',block:'center'});}catch(e){}setTimeout(function(){try{el.focus({preventScroll:true});}catch(e){}},220);
}
function cardScoreGuideOpen(state){
  state=state||cardScoreMissingState();var item=state.primary;if(!item)return;window._cardScoreGuideActive=true;window._cardScoreMissing=state;
  if(typeof VIEW==='undefined'||VIEW!=='carte'){try{go('carte');}catch(e){}}
  setTimeout(function(){
    if(item.kind==='reference'){
      if(window.VerdictCartePages&&!window.VerdictCartePages.guided())window.VerdictCartePages.open('imports',false);
      var el=document.getElementById(item.fieldId),details=(el&&el.closest)?el.closest('details'):null;if(details)details.open=true;cardScoreMarkElement(el,item);return;
    }
    openPlat(item.newDish?null:item.platId);
    setTimeout(function(){
      if(item.standard&&typeof setDishMode==='function')setDishMode('standard',true);
      if(item.recipe&&!document.querySelector('#recLines .rec-line')&&typeof addRecLine==='function')addRecLine();
      cardScoreMarkElement(item.fieldId?document.getElementById(item.fieldId):document.querySelector(item.selector),item);
    },80);
  },80);
}
function cardScoreGuideGo(){try{cardScoreSheetClose();}catch(e){}cardScoreGuideOpen(window._cardScoreMissing);}
function cardScoreGuideContinue(){
  var sc=scoreCarte(carteStats()),C=cardScoreGuideCopy();
  if(sc.available){window._cardScoreGuideActive=false;if(window.VerdictCartePages&&!window.VerdictCartePages.guided())window.VerdictCartePages.open('health',false);var hero=document.querySelector('.card-score-hero');if(hero){try{hero.scrollIntoView({behavior:scReduced()?'auto':'smooth',block:'center'});}catch(e){}try{hero.focus({preventScroll:true});}catch(e){}}toast(C.ready);return;}
  cardScoreGuideOpen(cardScoreMissingState());
}
function cardScoreGuideAfterDishSave(){
  if(!window._cardScoreGuideActive)return;setTimeout(cardScoreGuideContinue,100);
}
function cardScoreHeroHTML(st,R){
  var sc=scoreCarte(st),cd=cardDiagnosticStats(st,R),C=cardScoreCopy(),G=cardScoreGuideCopy(),z=zone(sc.total),col=sc.available?z.h:'#64748b';
  var scoreText=sc.available?String(sc.total):'—',reliability=sc.available?cardScoreReliability(sc,C):C.unavailable;
  var evidence=sc.available?(C.reliable+' '+cd.reliable+' / '+cd.active):(C.active+' '+cd.active+' · '+G.entered+' '+cd.total),touch=sc.available?C.touch:G.touch;
  return '<button type="button" class="score-hero card-score-hero" data-card-score="'+(sc.available?sc.total:'unavailable')+'" data-card-coverage="'+sc.coveragePct+'" onclick="cardScoreSheetOpen()" aria-label="'+esc(C.open)+'">'+
    '<span class="ring card-score-ring" style="--ringcol:'+col+'">'+ringSVG(sc.available?sc.total:null,col,104)+'<span class="num"><b style="color:'+col+'">'+scoreText+'</b><small>/100</small></span></span>'+
    '<span class="card-score-copy"><span class="card-score-kicker">'+esc(C.label)+'</span><strong style="color:'+col+'">'+esc(sc.available?z.t:C.unavailable)+'</strong><span class="card-score-independent">'+esc(C.independent)+'</span><span class="pillrow"><span class="pill">'+esc(evidence)+'</span><span class="pill">'+esc(reliability)+'</span></span><span class="card-score-touch">'+esc(touch)+'</span><span>Contribution mensuelle après coûts variables : '+eur(sc.economic.contribution)+' · Charges à couvrir : '+eur(sc.economic.fixed)+(sc.available?' · Couverture '+(sc.economic.coverage==null?'—':pc(sc.economic.coverage*100,1)):' · À confirmer : mois complet, carte complète et charges renseignées.')+'</span></span><span class="card-score-arrow" aria-hidden="true">›</span>'+
  '</button>';
}
/* Le Score Verdict® global et l’Indice Carte répondent à deux questions différentes.
   La Structure explique le score global ; la Carte reste indépendante. */
function cardDiagnosticStats(st,R){
  st=st||carteStats();R=R||moteur();
  var total=(DB.plats||[]).length,active=st.actifs||0,reliable=st.fiables||0;
  var coverage=active?Math.round(reliable/active*100):0,actual=R&&R.ready&&R.v?Number(R.v.fc):null;
  var gap=(actual!=null&&isFinite(actual)&&st.theoR>0)?actual-st.theoR:null,priority=null;
  (DB.plats||[]).some(function(p){if(!(Number(p.vol)>0))return false;var z=platZone(p,st);if(z.k==='o'||z.k==='r'){priority={nom:p.nom||'Plat',action:z.act||z.lb};return true;}return false;});
  return {ready:active>0&&reliable>0,total:total,active:active,reliable:reliable,coverage:coverage,
    foodCost:st.theoR>0?st.theoR:null,margin:st.ca>0?st.margePond:null,actualFoodCost:actual,gap:gap,
    negative:st.perte||0,priority:priority};
}
