function updateDemoNotice(){
  var w=document.getElementById("wDemo");
  if(!w)return;
  var mk=DB.modele&&MODELES[DB.modele]?DB.modele:null;
  var isDemo=!!(DB.exempleCharge||(DB.dataProvenance&&DB.dataProvenance.nature==='model_estimate'));
  var lbl=mk?MODELES[mk].n:'Verdict';
  var tx=MODEL_NOTICE_TEXT[typeof LOCALE==='string'?LOCALE:'fr']||MODEL_NOTICE_TEXT.fr;
  w.innerHTML=isDemo?('&#128161; <b>'+esc(tx.lead)+'</b> '+esc(tx.body)+'<br><span style="display:inline-block;margin-top:7px">'+esc(lbl)+' · '+
    '<button class="btn ghost mini" style="display:inline;padding:2px 8px;font-size:13px" onclick="openModeles()">'+esc(tx.change)+'</button> · '+
    '<button class="btn ghost mini" style="display:inline;padding:2px 8px;font-size:13px" onclick="clearAll()">'+esc(tx.own)+'</button></span>'):'';
  w.classList.toggle("on",isDemo);
}
function saveIdentite(){
  var nom=document.getElementById("i-etabnom").value.trim();
  DB.etab=nom||"Mon établissement";
  DB.etabType=document.getElementById("i-etabtype").value;
  DB.etabVille=document.getElementById("i-etabville").value.trim();
  try{if(document.getElementById('in-ctx-delivery')){DB.establishmentProfile=readPassport('in');DB.veraUpdatedAt=new Date().toISOString();}}catch(e){}
  /* Renommer une simulation ne transforme jamais ses estimations en chiffres
     observés. Le bandeau reste jusqu'à une vraie saisie ou un import. */
  save();
  document.getElementById("etabName").textContent=DB.etab;
  updateDemoNotice();
  try{ if(typeof majBandeauDemo==='function')majBandeauDemo(); }catch(e){}
  drawEtabs();
  if(VIEW==="pil")drawPil();
}

/* ═══════════════════════════════════════════════════════════════════
   MES CHIFFRES — fraîcheur et bon sens (V4.56, étape 2)
   Verdict surveille la fraîcheur de ses sources sectorielles. Il doit
   surveiller aussi celle des chiffres du client : ce sont eux qui commandent
   le score. Un chiffre vieux ne se voit pas — sauf si on le dit.
   ═══════════════════════════════════════════════════════════════════ */
var MAJ_GROUPES={
  activite:{lib:'Votre activit\u00e9', ch:['panier','cmdj','jsem','mois','moisch','tva'], quoi:'panier moyen, commandes par jour, jours d\u2019ouverture'},
  achats:{lib:'Vos achats', ch:['nour','boi','emb','autv','com'], quoi:'nourriture, boissons, emballages, commissions'},
  salaires:{lib:'Vos salaires', ch:['dirb','dirn','dirt','salb','saln','salt'], quoi:'brut dirigeant et salari\u00e9s, taux de charges'},
  fixes:{lib:'Vos charges fixes', ch:['f1','f2','f3','f4','f5','f6','f7','f8','f9','f10'], quoi:'loyer, \u00e9nergie, assurances, comptable'},
  treso:{lib:'Votre tr\u00e9sorerie et vos objectifs', ch:['treso','obj'], quoi:'solde disponible, objectif de r\u00e9sultat'}
};
function majGroupe(cle){ for(var g in MAJ_GROUPES){ if(MAJ_GROUPES[g].ch.indexOf(cle)>=0)return g; } return null; }
function majMarquer(cle){
  var g=majGroupe(cle); if(!g)return;
  DB.maj=DB.maj||{}; DB.maj[g]=new Date().toISOString().slice(0,10);
}
function majMois(d){ if(!d)return null; return Math.round((new Date()-new Date(d))/864e5/30.4); }
function majVieux(){
  var out=[];
  for(var g in MAJ_GROUPES){
    var d=(DB.maj||{})[g], m=majMois(d);
    if(d&&m!=null&&m>=12) out.push({g:g,mois:m,lib:MAJ_GROUPES[g].lib,quoi:MAJ_GROUPES[g].quoi});
  }
  out.sort(function(a,b){ return b.mois-a.mois; });
  return out;
}
/* Le bon sens, jamais le reproche : on pose une question, on n'accuse pas. */
function majDoutes(){
  var R=moteur(); if(!R||!R.ready)return [];
  var v=R.v, d=R.d, o=[];
  if(v.tc>100) o.push({t:'Vos charges d\u00e9passent votre chiffre d\u2019affaires', d:'Total des charges : '+pct(v.tc)+' du CA. C\u2019est possible sur un exercice difficile, mais c\u2019est inhabituel \u2014 est-ce exact&nbsp;?'});
  if(v.ms>60) o.push({t:'Vos salaires p\u00e8sent plus de 60\u00a0% du chiffre d\u2019affaires', d:'Ce niveau se rencontre en cas de forte baisse d\u2019activit\u00e9. V\u00e9rifiez que le brut saisi est bien mensuel, et non annuel.'});
  if(v.fc>0&&v.fc<15) o.push({t:'Votre co\u00fbt mati\u00e8re para\u00eet tr\u00e8s bas', d:'Achats nourriture : '+pct(v.fc)+' du CA. Verdict classe ce niveau comme inhabituellement bas : les achats saisis couvrent-ils bien l\u2019ann\u00e9e enti\u00e8re&nbsp;?'});
  if(d.panierTTC>0&&d.panierTTC<5) o.push({t:'Votre panier moyen para\u00eet tr\u00e8s bas', d:eur(d.panierTTC)+' par addition. S\u2019agit-il bien du montant moyen d\u2019un ticket, taxes comprises&nbsp;?'});
  if(d.panierTTC>200) o.push({t:'Votre panier moyen para\u00eet tr\u00e8s \u00e9lev\u00e9', d:eur(d.panierTTC)+' par addition. S\u2019agit-il d\u2019un ticket, ou du total d\u2019une journ\u00e9e&nbsp;?'});
  if(d.cmdj>0&&d.cmdj<3) o.push({t:'Tr\u00e8s peu de commandes par jour', d:(Math.round(d.cmdj*10)/10)+' par jour d\u2019ouverture. Ce chiffre est une moyenne annuelle \u2014 est-ce bien le cas&nbsp;?'});
  return o;
}
function majHTML(){
  var V=majVieux(), D=majDoutes(), h='';
  if(V.length){
    var p=V[0];
    h+='<div class="card" style="border-left:3px solid #f97316">'+
      '<div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2)">\u00c0 v\u00e9rifier</div>'+
      '<b style="display:block;font-size:16.5px;margin:6px 0 4px">'+p.lib+' n\u2019ont pas boug\u00e9 depuis '+p.mois+' mois</b>'+
      '<p class="au-p" style="margin:0 0 10px">Depuis, un loyer a pu \u00eatre r\u00e9vis\u00e9, un contrat renn\u00e9goci\u00e9, un salaire modifi\u00e9. <b>Votre score est calcul\u00e9 sur ces chiffres.</b></p>'+
      '<p class="au-p" style="margin:0 0 10px;color:var(--txt)"><b>\u2192</b> V\u00e9rifiez '+p.quoi+'&nbsp;: deux minutes suffisent.</p>'+
      (V.length>1?'<p class="note" style="margin:0">'+(V.length-1)+' autre'+(V.length>2?'s':'')+' groupe'+(V.length>2?'s':'')+' dans le m\u00eame cas.</p>':'')+
      '</div>';
  }
  D.forEach(function(x){
    h+='<div class="card" style="border-left:3px solid #eab308">'+
      '<div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2)">C\u2019est inhabituel</div>'+
      '<b style="display:block;font-size:16px;margin:6px 0 4px">'+x.t+'</b>'+
      '<p class="au-p" style="margin:0">'+x.d+'</p></div>';
  });
  return h;
}
function majInject(){
  try{
    var v=document.getElementById('v-in'); if(!v)return;
    var vieux=document.getElementById('majBloc'); if(vieux)vieux.remove();
    var h=majHTML(); if(!h)return;
    var d=document.createElement('div'); d.id='majBloc'; d.innerHTML=h;
    var ancre=v.querySelector('.card'); if(ancre)v.insertBefore(d,ancre); else v.appendChild(d);
  }catch(e){}
}

function readInputs(){
  var bad=[],msgs=[];
  FIELDS.forEach(function(k){
    var el=document.getElementById("i-"+k); if(!el)return;
    var raw=el.value, v=num(raw);
    var invalid=(raw!=="" && (v==null||v<0));
    if(k==="tva"&&v!=null&&v>30)invalid=true;
    if((k==="jsem")&&v!=null&&v>7)invalid=true;
    if((k==="mois")&&v!=null&&v>12)invalid=true;
    if((k==="moisch")&&v!=null&&(v<1||v>12))invalid=true;
    el.classList.toggle("bad",invalid);
    if(invalid)bad.push(k);
    else { var _av=DB.in[k]; DB.in[k]=(raw===""?null:v); if(_av!==DB.in[k])majMarquer(k); }
  });
  save();
  var d=deriv();
  if(bad.length)msgs.push("Corrigez les champs en rouge — nombre positif attendu (TVA \u2264 30, jours \u2264 7, mois \u2264 12).");
  else if(d.ca>0){
    if(d.cvT>=d.ca)msgs.push("\u26a0 Charges variables \u2265 CA : chaque vente creuse la perte. Si les saisies sont justes, le verdict le dira sans d\u00e9tour.");
    else if(d.cvT+d.cf>d.ca*1.3)msgs.push("\u26a0 Total des charges tr\u00e8s sup\u00e9rieur au CA ("+pc((d.cvT+d.cf)/d.ca*100,0)+"). V\u00e9rifiez : montants annuels, HT.");
    if(d.mat>d.ca*0.55)msgs.push("\u26a0 Achats mati\u00e8re \u00e0 "+pc(d.mat/d.ca*100,0)+" du CA : tr\u00e8s inhabituel, v\u00e9rifiez ce montant.");
    if(d.panierTTC>200)msgs.push("\u26a0 Panier moyen "+eur(d.panierTTC)+" TTC : v\u00e9rifiez que c'est bien par ticket.");
  }
  var w=document.getElementById("wIn");
  w.innerHTML=msgs.join("<br>"); w.classList.toggle("on",msgs.length>0);
  drawAuto(d);
  /* V8.2 — la validation suit la frappe : chaque champ rempli fait disparaître
     son message, le récapitulatif au-dessus du bouton se met à jour tout seul. */
  try{ majValidationVisible(); }catch(e){}
  return bad.length===0;
}
function drawAuto(d){
  function line(k,v){ return '<div class="autoline"><span class="k">'+k+'</span><b>'+v+'</b></div>'; }
  document.getElementById("autoAct").innerHTML=
    line("Jours ouverts / mois",fr(d.jMois))+line("Jours ouverts / an",fr(d.jAn))+
    line("Panier moyen HT",d.panierHT>0?eur2(d.panierHT):"\u2014")+
    line("Commandes annuelles",d.cmdAn>0?fr(d.cmdAn):"\u2014")+
    line("CA annuel HT",d.ca>0?eur(d.ca):"\u2014");
  document.getElementById("autoSal").innerHTML=
    line("Masse salariale / mois",d.salM>0?eur(d.salM):"\u2014")+
    line("Masse salariale / an",d.sal>0?eur(d.sal):"\u2014");
  document.getElementById("autoFix").innerHTML=
    line("Total fixes / mois (hors salaires)",d.fixM>0?eur(d.fixM):"\u2014")+
    line("Total fixes / an",d.af>0?eur(d.af):"\u2014")+
    line("Charges fixes totales / an (salaires inclus)",d.cf>0?eur(d.cf):"\u2014");
  document.getElementById("autoVar").innerHTML=
    line("Total variable annuel",d.cvT>0?eur(d.cvT):"\u2014")+
    line("Co\u00fbt variable / commande",d.cvu>0?eur2(d.cvu):"\u2014")+
    line("% variable sur CA HT",d.ca>0?pc(d.cvT/d.ca*100):"En attente du CA");
}
function loadModel(){ openModeles(); }
/* ═══ SÉLECTEUR DES 15 MODÈLES SECTORIELS DE DÉMONSTRATION ═══ */
/* R242 : deux indices indépendants, toujours calculés sur le dossier demandé. */
function etabCarteMeta(d){
  var prev=DB;
  try{if(!d)return null;DB=d;var ref=point5ReferenceState(),s=scoreCarte(carteStats());
    return {score:s.available&&Number.isFinite(s.total)?Math.round(s.total):null,estimated:ref.estimated,demo:ref.demo};
  }catch(e){return null;}finally{DB=prev;}
}
function verdictIndicesHTML(p,c){
  var l=typeof LOCALE==='string'?LOCALE:'fr',words={fr:['Pilotage','Carte','Non calculable','Estimatif'],en:['Management','Menu','Not calculable','Estimated'],es:['Gestión','Carta','No calculable','Estimado'],it:['Gestione','Menu','Non calcolabile','Stimato'],de:['Steuerung','Speisekarte','Nicht berechenbar','Geschätzt'],nl:['Beheer','Menukaart','Niet berekenbaar','Geschat'],pt:['Gestão','Ementa','Não calculável','Estimado']},w=words[l]||words.fr;
  function chip(label,m,kind){var n=m&&Number.isFinite(m.score)?m.score:null,detail=kind==='pilotage'&&m&&!m.final?m.label:(m&&m.estimated?w[3]:'');
    return '<span data-index="'+kind+'" style="flex:1 1 125px;min-width:0;padding:7px 9px;border:1px solid var(--line);border-radius:10px;font-size:12px;white-space:normal"><span>'+esc(label)+'</span> <b style="color:'+(n===null?'var(--mut2)':zone(n).h)+'">'+(n===null?esc(w[2]):n+'<small>/100</small>')+'</b>'+(detail?'<small style="display:block;color:var(--mut2)">'+esc(detail)+'</small>':'')+'</span>';
  }
  return '<span class="etab-indices" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;text-align:left;font-weight:500">'+chip(w[0],p,'pilotage')+chip(w[1],c,'carte')+'</span>';
}
function etabIndicesHTML(id){return verdictIndicesHTML(etabScoreMeta(id),etabCarteMeta(STORE.etabs[id]));}
function modeleResume(k){
  if(!MODELES[k])return '';
  var prev=DB,r=null,d=freshDB(k),p=null;
  try{DB=d;r=moteur();if(r&&r.ready)p={score:Math.round(r.score),final:true};}catch(e){}finally{DB=prev;}
  return verdictIndicesHTML(p,etabCarteMeta(d))+(r&&r.ready?'<span style="display:block;margin-top:7px;font-size:12px;color:var(--mut)">'+eur(r.d.ca)+' &middot; '+pc(r.v.rn,1)+'</span>':'');
}
function modeleBouton(k){
  var M=MODELES[k],on=(DB.modele===k);if(!M)return '';
  var rank=modeleRank(k),weight=modelePriority(k);
  return '<button class="btn sec" style="width:100%;text-align:left;margin-bottom:8px;display:block;padding:12px 14px'+
    (on?';border-color:var(--green)':'')+'" onclick="pickModele(\''+k+'\')">'+
    '<div style="display:flex;align-items:center;gap:10px">'+
      '<span style="font:900 11px var(--mono);color:var(--mut2);min-width:24px">#'+rank+'</span>'+
      '<span style="flex:1;font-weight:700;font-size:14.5px">'+M.n+(on?' <span style="color:var(--green)">&#10003;</span>':'')+'</span>'+
    '</div><div style="font-size:12.5px;color:var(--mut2);margin:4px 0 0 34px;font-weight:500">Priorité France '+weight+'/5 &middot; '+
    M.plats.length+' plats &middot; '+M.ing.length+' ingr&eacute;dients</div>'+(k==='FoodTruck'?'<small style="display:block;margin:8px 0">Scénario fictif documenté · 55 tickets/jour · panier 14 € · 5 jours/semaine · 11 mois · camion acheté et amorti, emplacements et renfort inclus.</small>':'')+modeleResume(k)+'</button>';
}
function modeleDansDemonstration(){
  return !!((typeof getMode==='function'&&getMode()==='demo')||
    (DB&&DB.exempleCharge===true)||
    (DB&&DB.dataProvenance&&DB.dataProvenance.nature==='model_estimate')||
    (typeof VERDICT_DEMO_SESSION!=='undefined'&&VERDICT_DEMO_SESSION===true));
}
function openModeles(){
  var old=document.getElementById('mModeles'); if(old&&old.parentNode)old.parentNode.removeChild(old);
  var demoActif=modeleDansDemonstration(), disponibles=modelesDisponibles();
  var essentiels=MODELE_FEATURED.filter(function(k){return disponibles.indexOf(k)>=0;});
  var autres=disponibles.filter(function(k){return essentiels.indexOf(k)<0;});
  var h='<div class="sheet modeles-sheet"><div class="grab"></div>'+
    '<h3>'+(VERDICT_TEST_SESSION?'Ajouter un modèle fictif au portefeuille Test':'Charger un mod&egrave;le de d&eacute;monstration')+'</h3>'+
    '<p class="sub" style="margin:-8px 0 14px">'+
      (VERDICT_TEST_SESSION?
        'Le modèle devient un établissement Test séparé : vous pouvez le modifier, le comparer puis le supprimer. Il disparaît à la fermeture du mode Test.':demoActif?
        'Touchez un mod\u00e8le : Verdict actualise ses indicateurs avant de l’afficher. Toutes les donn\u00e9es restent fictives.':
        disponibles.length+' mod\u00e8les sectoriels illustratifs &mdash; chiffres, carte et ingr&eacute;dients complets. Aucun ne repr\u00e9sente un client Verdict. Le chargement remplace votre saisie actuelle.')+
    '</p><div class="modeles-scroll">'+
    '<div style="font:800 11px var(--mono);letter-spacing:.09em;color:var(--green);margin:2px 4px 9px">5 MODÈLES ESSENTIELS · FRANCE</div>';
  essentiels.forEach(function(k){h+=modeleBouton(k);});
  if(VERDICT_TEST_SESSION){
    h+='<div style="font:800 11px var(--mono);letter-spacing:.09em;color:var(--mut2);margin:16px 4px 9px">LES 10 AUTRES MODÈLES · TEST COMPLET</div>';
    autres.forEach(function(k){h+=modeleBouton(k);});
  }else{
    h+='<details style="margin-top:10px"><summary style="padding:12px 5px;color:var(--mut);font-weight:800">Voir les '+autres.length+' autres modèles classés</summary><div style="padding-top:8px">';
    autres.forEach(function(k){h+=modeleBouton(k);});
    h+='</div></details>';
  }
  h+='</div><div class="modeles-actions">'+(VERDICT_DEMO_FROM_PORTFOLIO&&VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE?'<button class="btn sec" onclick="retourPortefeuilleDepuisModele()">Retour à mes établissements réels</button>':'')+'<button class="btn ghost" onclick="annulerModeles()">'+(VERDICT_DEMO_FROM_PORTFOLIO&&VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE?'Fermer':'Annuler')+'</button></div></div>';
  var m=document.createElement('div'); m.className='modal on verdict-adaptive-modal'; m.id='mModeles'; m.innerHTML=h;
  m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');
  m.addEventListener('click',function(e){ if(e.target===m) annulerModeles(); });
  document.body.appendChild(m);
}
function closeModeles(){ var m=document.getElementById('mModeles'); if(m&&m.parentNode)m.parentNode.removeChild(m); }
function explorerModelesFictifs(){
  /* Le portefeuille réel est copié en mémoire avant l'exploration. Pendant la
     session fictive, save() et la synchronisation cloud sont neutralisés. */
  if(VERDICT_TEST_SESSION){openModeles();return;}
  if(!VERDICT_DEMO_FROM_PORTFOLIO){
    demoEntrerSession();
    VERDICT_DEMO_FROM_PORTFOLIO=true;
    VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE=false;
  }
  openModeles();
}
function annulerModeles(){
  closeModeles();
  if(VERDICT_DEMO_FROM_PORTFOLIO&&!VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE){
    demoRestaurerSessionReelle();VERDICT_DEMO_FROM_PORTFOLIO=false;
    try{go('pil');}catch(e){}
  }
}
function retourPortefeuilleDepuisModele(){
  closeModeles();demoFin();demoRestaurerSessionReelle();
  VERDICT_DEMO_FROM_PORTFOLIO=false;VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE=false;
  try{go('pil');window.scrollTo(0,0);}catch(e){}
}
function appliquerModele(k,demoActif){
  var M=MODELES[k]; if(!M)return false;
  var d=freshDB(k);
  /* Un changement de modèle pendant la démonstration reste entièrement dans
     l'univers fictif. Sans ces marqueurs, Dark kitchen était calculée, mais
     Verdict oubliait aussitôt qu'il s'agissait encore d'une démonstration. */
  if(demoActif){
    try{ ensemencerPiloteDemo(d,M); }catch(e){}
  }
  d.exempleCharge=true; d.userMode='demo'; d.onboardingDone=true;
  if(demoActif){d._demo={fictional:true,billable:false,persistent:false,canonical:String(k||'model')};d._billing=d._billing||{};d._billing.active=true;d._billing.entitlementLocked=false;}
  /* on remplace le contenu de l'établissement actif, sans casser la référence */
  verdictCompleteDemo(d);
  STORE.etabs[STORE.actif]=d; DB=d; MODELE_ACTIF=k;
  verdictModelMarkStarted(STORE.actif);
  save("load-demo-model"); fillInputs(); readInputs(); drawEtabs(); refreshAll();
  try{ majBandeauDemo(); }catch(e){}
  go("pil");
  var r=moteur();
  /* R306: the shared transition already covers the actual model calculation. */
  if(!window.VerdictTransition)replayIntro(M.e+" \u2014 score "+(r.ready?Math.round(r.score):"\u2014")+"/100",null,'discovery');
  return true;
}
function pickModele(k){
  var M=MODELES[k]; if(!M)return;
  var demoActif=modeleDansDemonstration();
  /* Dans une démonstration, il n'existe aucune donnée client à protéger : le
     toucher sur un modèle est déjà la décision. Afficher une deuxième feuille
     « Charger ? » créait une étape vide et pouvait être prise pour un bug. */
  if(demoActif){
    if(VERDICT_DEMO_FROM_PORTFOLIO)VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE=true;
    appliquerModele(k,true); closeModeles(); return;
  }
  ask("Explorer "+M.e+" ?","Le modèle s'ouvre dans une démonstration isolée. Votre établissement et vos chiffres restent exactement à leur place.","Ouvrir la démonstration",function(){
    demoEntrerSession();VERDICT_DEMO_FROM_PORTFOLIO=true;VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE=true;
    appliquerModele(k,true);
  });
  closeModeles();
}
function clearAll(){
  /* V5.02 — on dit exactement ce qui part et ce qui reste : une remise à zéro
     ne se confirme pas à l'aveugle. */
  ask("\u26a0\ufe0f Repartir de z\u00e9ro ?",
    "Seront effac\u00e9s : vos chiffres, votre diagnostic, votre carte et vos journ\u00e9es saisies. "+
    "Ne seront PAS effac\u00e9s : votre catalogue d\u2019ingr\u00e9dients et vos autres \u00e9tablissements. "+
    "Cette action est d\u00e9finitive.",
    "Oui, repartir de z\u00e9ro",function(){
    verdictBeforeRisk("reset-establishment").then(function(ok){if(!ok)return;
      verdictClientPurgeAux(VERDICT_STORAGE_SCOPE,STORE.actif);
      verdictUiStatePurge(VERDICT_STORAGE_SCOPE,STORE.actif);verdictModeWrite('');
      var d=freshDB(false); d.etab=DB.etab; d.etabVille=DB.etabVille;
      STORE.etabs[STORE.actif]=d; DB=d;
      save("reset-establishment"); fillInputs(); readInputs(); drawEtabs(); refreshAll(); go("pil"); replayIntro("Pr\u00eat pour vos chiffres");
    });
  },true);
}
/* ═══════════════════════════════════════════════════════════════════
   VALIDATION VISIBLE EN PERMANENCE (V8.2)
   Steven : « aucun score mais aucune erreur — reste sur la page et aide le
   client à remplir ». Le blocage seul ne sert à rien s'il est muet : le
   message vivait en haut de l'écran alors que le bouton est tout en bas.
   Désormais chaque champ manquant porte son propre message sous lui, et un
   récapitulatif s'affiche juste au-dessus du bouton — là où le doigt clique.
   ═══════════════════════════════════════════════════════════════════ */
/* V8.5 — Steven : le client doit comprendre, pas déchiffrer. Les libellés
   internes de validate() sont écrits pour le moteur ; on les traduit dans la
   langue d'un chef, et on ne garde que ce qui l'aide à trouver la case fautive. */
var INCOH_CLAIR={
  'CA < Charges fixes.':'Vos charges fixes d\u00e9passent votre chiffre d\u2019affaires. V\u00e9rifiez que loyer et charges sont bien des montants MENSUELS.',
  'CA < Achats.':'Vos achats d\u00e9passent votre chiffre d\u2019affaires. V\u00e9rifiez qu\u2019ils sont bien annuels et hors taxes.',
  'CA < Salaires.':'Vos salaires d\u00e9passent votre chiffre d\u2019affaires. V\u00e9rifiez que le brut saisi est bien MENSUEL, pas annuel.',
  'Salaires > CA.':'Vos salaires d\u00e9passent votre chiffre d\u2019affaires.',
  'Food cost > 100%.':'Vous achetez plus de mati\u00e8re que vous ne vendez : l\u2019un des deux chiffres est faux.',
  'Prime cost > 100%.':'Mati\u00e8re et salaires r\u00e9unis d\u00e9passent tout votre chiffre d\u2019affaires.',
  'Marge n\u00e9gative.':'Chaque vente vous co\u00fbte plus qu\u2019elle ne rapporte, avant m\u00eame les charges fixes.',
  'Point mort impossible.':'Vos charges ne pourraient jamais \u00eatre couvertes, quel que soit le volume vendu.',
  'Panier requis.':'Le panier moyen n\u2019est pas renseign\u00e9.',
  'Commandes requises.':'Le nombre de commandes n\u2019est pas renseign\u00e9.',
  'CA invalide.':'Le chiffre d\u2019affaires ne peut pas \u00eatre calcul\u00e9.'
};
function incohClair(L){
  var vus={}, out=[];
  (L||[]).forEach(function(x){
    var c=INCOH_CLAIR[x]||x;
    if(!vus[c]){ vus[c]=1; out.push(c); }      /* deux libellés peuvent dire la même chose */
  });
  return out.slice(0,4);                        /* quatre lignes maximum : au-delà on assomme */
}

function majValidationVisible(){
  var v=document.getElementById('v-in'); if(!v||!v.classList.contains('on'))return;
  var m=[],a=[];
  try{ m=donneesManquantes(); a=anomaliesNonConfirmees(); }catch(e){ return; }
  var cles={}; m.forEach(function(c){ cles[c.k]=c; });

  /* Un poste de charges fixes manquant mais replié serait obligatoire ET
     invisible : on déplie la section pour que le client puisse le remplir. */
  var cache=m.some(function(c){ return FIX_LABELS && FIX_LABELS[c.k] && !document.getElementById('i-'+c.k); });
  if(cache){
    try{ SHOW_ALL_FIX=true; drawFixFields(); }catch(e){}
    /* le champ vient d'être créé : il n'existait pas quand cette passe a
       commencé, donc on repasse une fois pour le marquer lui aussi. */
    if(!majValidationVisible._relance){
      majValidationVisible._relance=true;
      try{ majValidationVisible(); } finally { majValidationVisible._relance=false; }
      return;
    }
  }

  /* 1. message sous chaque champ concerné, retiré dès qu'il est rempli */
  CHAMPS_CRITIQUES.forEach(function(c){
    var el=document.getElementById('i-'+c.k); if(!el)return;
    var lab=el.parentNode, old=lab?lab.querySelector('.err-champ'):null;
    var manque=!!cles[c.k];
    /* classe dédiée : readInputs() gère 'bad' (valeur invalide) et l'efface à
       chaque frappe ; 'manque' (donnée absente) n'appartient qu'à la validation
       métier, sinon la bordure rouge disparaissait aussitôt posée. */
    el.classList.toggle('manque',manque);
    if(manque){
      if(!old&&lab){
        var s=document.createElement('small');
        s.className='err-champ';
        s.textContent='\u00c0 renseigner \u2014 si ce poste est r\u00e9ellement nul, saisissez 0.';
        lab.appendChild(s);
      }
    } else if(old&&old.parentNode){ old.parentNode.removeChild(old); }
  });

  /* 2. récapitulatif au contact du bouton */
  /* V8.6 — origine des montants convertis depuis le compte de résultat : le client doit
     pouvoir relier le 125 €/mois affiché aux 1 500 €/an qu'il a saisis. */
  try{
    var src=DB.refSource;
    if(src){
      [['f1',src.loy,'Loyer'],['salb',src.ms,'Masse salariale'],['f10',src.cf,'Autres charges fixes']]
      .forEach(function(o){
        var el=document.getElementById('i-'+o[0]); if(!el||o[1]==null)return;
        var lab=el.parentNode; if(!lab)return;
        var old=lab.querySelector('.src-champ'); if(old)old.remove();
        var s=document.createElement('small');
        s.className='src-champ';
        s.innerHTML='Depuis votre compte de résultat : <b>'+eur(o[1])+'/an</b> \u00f7 12';
        lab.appendChild(s);
      });
    }
  }catch(e){}
  var w=document.getElementById('wVerdict'), b=document.getElementById('btnVerdict');
  if(!w)return;
  var inc=[]; try{ var Rv=moteur(); inc=Rv.incoherences||[]; }catch(e){}
  /* V8.4 — l'ordre compte : sur un formulaire vide, validate() signale « panier
     requis » comme une erreur. Parler d'incohérence à ce moment-là serait faux
     et décourageant. On réclame d'abord ce qui manque ; on ne parle
     d'incohérence que lorsque tout est saisi. */
  if(inc.length && !m.length){
    w.innerHTML='<b>Vos chiffres ne sont pas coh\u00e9rents entre eux.</b><br>'+
      incohClair(inc).map(function(x){ return '\u2022 '+x; }).join('<br>')+
      '<br><span style="opacity:.85">Le plus souvent, un montant <b>annuel</b> a \u00e9t\u00e9 saisi dans une case <b>mensuelle</b> \u2014 ou l\u2019inverse. Relisez d\u2019abord les salaires et le loyer.</span>';
    w.classList.add('on');
    if(b)b.classList.add('attente');
    return;
  }
  if(m.length){
    w.innerHTML='<b>'+m.length+' information'+(m.length>1?'s':'')+' manque'+(m.length>1?'nt':'')+
      ' pour calculer votre score.</b><br>'+manquantsParSection(m).join('<br>')+
      '<br><span style="opacity:.85">Une case vide ne veut pas dire z\u00e9ro. Si un poste est r\u00e9ellement nul, saisissez 0 \u2014 c\u2019est une r\u00e9ponse.</span>';
    w.classList.add('on');
  } else if(a.length){
    w.innerHTML='<b>'+(a.length>1?a.length+' points \u00e0 confirmer':'1 point \u00e0 confirmer')+' avant de noter votre structure.</b>'+
      a.map(function(x){
        return '<div style="margin:10px 0 0"><b>'+x.lb+'</b><br><span style="opacity:.85">'+x.txt+'</span></div>';
      }).join('')+
      '<button type="button" class="btn sec" style="width:auto;padding:8px 13px;font-size:13px;margin:12px 0 0" '+
        'onclick="confirmerToutesAnomalies()">Oui, je confirme ces chiffres</button>';
    w.classList.add('on');
  } else {
    w.innerHTML=''; w.classList.remove('on');
  }
  if(b){ b.classList.toggle('attente', m.length>0||a.length>0); }
}

function goVerdict(){
  if(!readInputs()){ majValidationVisible(); toast("Corrigez d'abord les champs en rouge"); return; }
  /* V8.4 — une structure impossible ne se note pas, même complète. */
  var inc=[]; try{ inc=moteur().incoherences||[]; }catch(e){}
  var mq=[]; try{ mq=donneesManquantes(); }catch(e){}
  if(inc.length && !mq.length){
    majValidationVisible();
    var wv=document.getElementById('wVerdict');
    if(wv){ try{ wv.scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){} }
    try{ toast(inc.length+' incoh\u00e9rence'+(inc.length>1?'s':'')+' dans vos chiffres'); }catch(e){}
    return;
  }
  /* V8.0 — on ne laisse plus passer un formulaire incomplet vers un score.
     Toutes les erreurs sont signalées d'un coup (pas une par une), les valeurs
     déjà saisies sont conservées, et on ramène le client sur le premier manque. */
  var m=[]; try{ m=donneesManquantes(); }catch(e){}
  if(m.length){ signalerManquants(m); return; }
  /* V8.1 — les données sont complètes, mais décrivent-elles un vrai
     établissement ? Un zéro sur un poste vital se confirme, il ne se devine pas. */
  var a=[]; try{ a=anomaliesNonConfirmees(); }catch(e){}
  if(a.length){ signalerAnomalies(a); return; }
  go("data");
}
function signalerAnomalies(a){
  majValidationVisible();
  var w=document.getElementById("wVerdict");
  if(w){ try{ w.scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){} }
  try{ toast('\u00c0 confirmer avant le verdict'); }catch(e){}
}
function signalerManquants(m){
  /* Les postes de charges fixes vides sont repliés par défaut : si l'un d'eux
     bloque le calcul, on déplie la section, sinon le client ne peut ni le voir
     ni le corriger. */
  var besoinFix=m.some(function(c){ return FIX_LABELS && FIX_LABELS[c.k]; });
  if(besoinFix){ try{ SHOW_ALL_FIX=true; drawFixFields(); }catch(e){} }
  majValidationVisible();
  var premier=null;
  m.forEach(function(c){
    var el=document.getElementById("i-"+c.k);
    if(el&&!premier)premier=el;
  });
  try{ toast(m.length+' donn\u00e9e'+(m.length>1?'s':'')+' manquante'+(m.length>1?'s':'')+' pour le verdict'); }catch(e){}
  if(premier){ try{ premier.focus({preventScroll:true}); }catch(e){}
    try{ premier.scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){ premier.scrollIntoView(); } }
}
/* ═══ CENTRE D'AIDE V10.4 ═══
   Une seule source de vérité : les textes décrivent le moteur ACTUEL. Ils ne
   reprennent pas les anciens raccourcis (TVA = 10 %, ETP estimés, « marge
   nette ») qui pouvaient pousser un client à saisir une valeur inventée. */
var AIDE_RETOUR='pil';
var AIDE_V104=[
  {c:'Démarrer',t:'Quel parcours choisir ?',
   d:'Vous avez un exercice comptable clôturé et son compte de résultat : choisissez « J’ai un exercice clôturé » — ou, plus simple, « J’ai mon fichier comptable (FEC) » pour ne rien saisir. Vous êtes déjà ouvert sans premier exercice clôturé : choisissez « J’ai ouvert récemment » pour séparer les faits observés de la projection de travail, sans score annuel. Vous préparez une ouverture ou une reprise : choisissez « Je crée ou reprends ». Pour explorer sans vos chiffres, choisissez la démonstration fictive.',
   o:'Au démarrage, après le choix de la langue.'},
  {c:'Démarrer',t:'J’ai terminé la démonstration. Et maintenant ?',
   d:'La visite guidée ne tourne qu’une fois. Ensuite vous pouvez explorer librement le modèle. À tout moment, passez à vos propres chiffres ou créez un projet ; vous n’avez pas à refaire la visite.',
   o:'Bandeau bleu « Et ensuite ? » dans la démonstration, ou Centre d’aide → Mes chiffres.'},
  {c:'Saisir sans erreur',t:'0 ou case vide : ce n’est pas la même chose',
   d:'Saisissez 0 uniquement si le poste est réellement nul. Une case vide signifie « je ne sais pas / pas encore renseigné ». Si une donnée indispensable manque, Verdict vous dit laquelle au lieu de fabriquer un score.',
   o:'Paramètres → vos chiffres.'},
  {c:'Saisir sans erreur',t:'CA HT, TVA et période : quoi recopier ?',
   d:'Pour un exercice terminé, recopiez le chiffre d’affaires HT de votre compte de résultat sur la même période que vos charges. Utilisez votre TVA moyenne réellement constatée si le calcul en a besoin : Verdict n’impose jamais 10 % à tous les restaurants.',
   o:'Votre compte de résultat / export comptable ; en cas de doute, validez la base avec votre comptable.'},
  {c:'Saisir sans erreur',t:'Salaires, charges sociales et ETP',
   d:'Utilisez le coût employeur et les taux qui correspondent réellement à votre situation. Le nombre d’ETP est facultatif pour certains indicateurs : s’il n’est pas saisi, Verdict affiche « Non renseigné » au lieu de l’estimer à partir des salaires.',
   o:'Journal de paie, DSN ou données validées par votre paie/comptable.'},
  {c:'Saisir sans erreur',t:'Achats, loyer et autres charges',
   d:'Saisissez les achats annuels HT réellement facturés et les charges sur leur vraie période. Pour une charge qui court toute l’année, indiquez 12 mois ; sinon indiquez le nombre de mois réellement concernés. Aucun pourcentage de marché n’est ajouté en secret.',
   o:'Grand livre, compte de résultat, factures et contrats.'},
  {c:'Saisir sans erreur',t:'Verdict détecte une incohérence : suis-je bloqué ?',
   d:'Une donnée impossible ou indispensable manquante bloque le calcul et indique quoi corriger. Une donnée seulement improbable déclenche un avertissement : vous pouvez la corriger ou confirmer qu’elle est exacte. La confirmation est liée aux valeurs précises ; si elles changent, Verdict vérifie à nouveau.',
   o:'La donnée concernée est nommée dans le message, jamais seulement colorée en rouge.'},
  {c:'Comprendre',t:'Que signifie le score Verdict de 0 à 100 ?',
   d:'C’est un indice de pilotage interne à Verdict qui résume plusieurs dimensions de votre structure. Ce n’est ni une note comptable, ni une notation bancaire, ni un percentile national. Les repères Verdict et les statistiques publiques FIBEN sont affichés séparément.',
   o:'Accueil et Diagnostic → Score / Repères & secteur.'},
  {c:'Comprendre',t:'Résultat avant impôt, point mort et coûts matière',
   d:'Le résultat avant impôt est ce qui reste dans le modèle après les coûts saisis, avant fiscalité. Le point mort est le niveau de CA nécessaire pour couvrir les coûts modélisés. Le food cost lit les achats nourriture ; le coût matière global ajoute les boissons et autres matières selon la vue.',
   o:'Diagnostic. Les définitions utilisées sont rappelées à côté des indicateurs.'},
  {c:'Piloter',t:'Que dois-je faire au quotidien ?',
   d:'Sur l’Accueil, deux chiffres suffisent pour votre point du jour : le CA TTC encaissé et les tickets. Verdict recalcule le rythme à tenir à partir de votre structure. Une fermeture ou une saison particulière doit être renseignée ; elle n’est pas devinée.',
   o:'Accueil → Votre journée.'},
  {c:'Piloter',t:'Carte, stock et performance des services',
   d:'La Carte relie recettes, prix et volumes. Le Stock s’appuie sur vos comptages. Performance des services utilise vos heures équipe totales, votre CA du service et votre coût horaire chargé réel : si vous ne les donnez pas, Verdict ne les invente pas.',
   o:'Carte ; Plus → Achats/Stock ; Plus → Performance des services.'},
  {c:'Piloter',t:'Tester une nouvelle organisation sans se tromper',
   d:'Verdict sépare ce que vous avez réellement observé de ce que vous supposez pour la future organisation. Reliez au moins trois services comparables, saisissez seulement les variations de CA, d’heures et de coûts, puis lancez un test terrain de 2 à 8 semaines. L’estimation ne modifie ni votre score ni votre référence comptable : seuls les résultats réellement enregistrés pourront confirmer le choix.',
   o:'Plus → Simuler → Réponse 9 « Tester une organisation ».'},
  {c:'Piloter',t:'Pourquoi cette action est-elle première ?',
   d:'Verdict classe les écarts avec la même source dans Actions, l’Accueil, l’Audit et Vera. Il regarde l’urgence, le montant réellement observable, la fiabilité des données et la possibilité d’agir. Il affiche une seule action principale, explique pourquoi elle passe devant les autres et donne la mesure à vérifier. Un manque de trésorerie ou une perte constatée reste un écart à couvrir ; seul un changement futur testé est présenté comme une simulation. Une donnée ancienne passe d’abord en priorité et suspend les conseils financiers trop précis.',
   o:'Actions → Commencer et suivre. Verdict enregistre le point de départ, la date de contrôle et l’établissement actif sans modifier le score.'},
  {c:'Piloter',t:'Comment savoir si mon action a fonctionné ?',
   d:'Trajectoire conserve la valeur de départ, la mesure prévue, sa source et la date de contrôle. À l’échéance, Verdict cherche une donnée réellement nouvelle sur le même établissement et le même indicateur. Il conclut seulement « amélioration observée », « stable » ou « dégradation observée ». Il ne dit jamais que l’action a causé seule le résultat : saison, prix, météo, équipe et autres décisions peuvent aussi l’expliquer. Sans période ou source comparable, la conclusion reste « données insuffisantes ».',
   o:'Plus → Trajectoire. Une seule action prioritaire est suivie à la fois ; l’arrêt conserve l’historique.'},
  {c:'Piloter',t:'J’ai plusieurs restaurants : comment comparer ?',
   d:'Ouvrez « Mes établissements » : Verdict compare les ratios sur 100 € HT, jamais la taille brute. Une conclusion n’est donnée que si les données sont complètes, de même nature et sur la même période ; un profil différent est signalé. Les sociétés ne sont jamais fusionnées ni consolidées. Ensuite, changez d’établissement : Verdict conserve exactement la page où vous étiez.',
   o:'Barre des établissements en haut → roue dentée → Comparer, ou Centre d’aide → Mes établissements.'},
  {c:'Confiance & données',t:'Que contient l’Audit Premium ?',
   d:'L’audit reprend la même source de calcul en 20 chapitres, ajoute votre modèle CHR et vos réponses terrain, puis construit un plan pilotable sur 90 jours. Ses quatre sorties — Premium complet, comptable, banque/associé et rapport exécutif — ne recalculent rien. Il reste une lecture de pilotage avant impôt et ne remplace ni les comptes annuels ni l’avis de votre comptable ou de votre banque.',
   o:'Plus → Audit, puis choisissez le format d’export.'},
  {c:'Confiance & données',t:'Comment valider une étape du plan 90 jours ?',
   d:'Commencez par figer le point de départ. Le bouton d’une action lance ensuite un seul suivi dans Trajectoire avec l’indicateur, la source, la période et la date de contrôle. Un clic ne peut jamais rendre l’étape verte : il faut une nouvelle mesure comparable. Verdict conclut seulement amélioration observée, stable ou dégradation observée, sans inventer de causalité.',
   o:'Plus → Audit → Plan 90 jours, puis Plus → Trajectoire pour mesurer à l’échéance.'},
  {c:'Confiance & données',t:'Où sont mes données ? Que se passe-t-il avec l’abonnement ?',
   d:'Votre dossier reste enregistré sur cet appareil, avec une copie locale de secours et un export JSON. Lorsque le coffre de compte est réellement activé sur le serveur pour Verdict Pro, une copie chiffrée côté serveur permet aussi la synchronisation et la restauration sur un autre appareil. Verdict indique toujours l’état réel de cette protection ; ce coffre n’est pas un chiffrement de bout en bout. L’essai commercial de 14 jours est prévu après activation du serveur ; aucun paiement n’est actif dans cette livraison. Inventaire Cuisine & Bar reste gratuit.',
   o:'Paramètres → Sauvegarder/Restaurer ; Plus → Mon abonnement.'},
  {c:'Confiance & données',t:'Ce que Verdict ne décide pas à votre place',
   d:'Verdict ne remplace pas la comptabilité, la fiscalité, le droit social, la paie, un planning contractuel ou un conseil bancaire. Il ne se connecte pas automatiquement à votre banque ou à votre caisse dans cette version. Il chiffre, recoupe, alerte et simule ; vous validez la décision et les données sources.',
   o:'Quand une décision engage un contrat, un salarié, un impôt ou un financement, faites valider le point par le professionnel concerné.'}
];
/* L'aide fait partie de l'interface internationale : elle ne doit jamais
   retomber en français après un choix de langue. Les clés ci-dessous sont
   volontairement les phrases exactes rendues par aideDessiner(). */
Object.assign(TR,{
  "Coût dirigeant(s) / mois — base du calcul (€)":["Owner cost / month — calculation base (€)","Coste del dirigente / mes — base de cálculo (€)","Costo titolare / mese — base di calcolo (€)","Leitungskosten / Monat — Berechnungsbasis (€)","Kosten ondernemer / maand — rekenbasis (€)","Custo do dirigente / mês — base de cálculo (€)"],
  "Si c’est un brut, indiquez le taux ci-dessous. Si le montant est déjà chargé, saisissez-le tel quel et laissez le taux à 0.":["If this is gross pay, enter the rate below. If the amount already includes employer charges, enter it as-is and leave the rate at 0.","Si es un bruto, indique la tasa inferior. Si el importe ya incluye las cargas del empleador, introdúzcalo tal cual y deje la tasa en 0.","Se è un lordo, indica l’aliquota qui sotto. Se l’importo include già gli oneri del datore, inseriscilo così com’è e lascia l’aliquota a 0.","Bei einem Bruttobetrag geben Sie unten den Satz an. Sind Arbeitgeberabgaben bereits enthalten, übernehmen Sie den Betrag unverändert und lassen den Satz auf 0.","Is dit een brutobedrag, vul dan hieronder het tarief in. Zijn werkgeverslasten al inbegrepen, neem het bedrag over en laat het tarief op 0.","Se for um valor bruto, indique a taxa abaixo. Se já incluir os encargos do empregador, introduza-o tal como está e deixe a taxa em 0."],
  "Masse salariale / mois — base du calcul (€)":["Payroll / month — calculation base (€)","Masa salarial / mes — base de cálculo (€)","Costo del personale / mese — base di calcolo (€)","Personalkosten / Monat — Berechnungsbasis (€)","Loonkosten / maand — rekenbasis (€)","Folha salarial / mês — base de cálculo (€)"],
  "Brut + taux ci-dessous, ou coût chargé avec un taux à 0 si votre source donne déjà le total employeur.":["Gross pay + the rate below, or loaded employer cost with a 0 rate if your source already gives the full employer total.","Bruto + tasa inferior, o coste empresarial cargado con tasa 0 si su fuente ya da el total del empleador.","Lordo + aliquota qui sotto, oppure costo aziendale già caricato con aliquota 0 se la fonte riporta già il totale datore.","Brutto + Satz unten oder bereits belastete Arbeitgeberkosten mit Satz 0, wenn Ihre Quelle den Arbeitgebergesamtbetrag bereits enthält.","Bruto + tarief hieronder, of totale werkgeverskost met tarief 0 als uw bron die totale werkgeverskost al geeft.","Bruto + taxa abaixo, ou custo total do empregador com taxa 0 se a sua fonte já indicar esse total."],
  "Effectif équipe renseigné (ETP)":["Team headcount entered (FTE)","Plantilla indicada (ETC)","Organico inserito (FTE)","Erfasster Teamumfang (VZÄ)","Ingevulde teambezetting (FTE)","Equipa indicada (ETI)"],
  "Si le dirigeant est compté séparément à gauche, indiquez ici seulement le reste de l’équipe.":["If the owner is counted separately on the left, enter only the rest of the team here.","Si el dirigente se cuenta por separado a la izquierda, indique aquí solo el resto del equipo.","Se il titolare è conteggiato separatamente a sinistra, indica qui solo il resto del team.","Wird die Leitung links separat gezählt, geben Sie hier nur das übrige Team an.","Wordt de ondernemer links apart meegeteld, vul hier alleen de rest van het team in.","Se o dirigente for contado separadamente à esquerda, indique aqui apenas o resto da equipa."],
  "Centre d’aide":["Help centre","Centro de ayuda","Centro assistenza","Hilfe","Helpcentrum","Centro de ajuda"],
  "Une question, une réponse claire, puis l’endroit exact où agir.":["One question, one clear answer, then the exact place to act.","Una pregunta, una respuesta clara y el lugar exacto donde actuar.","Una domanda, una risposta chiara e il punto esatto in cui agire.","Eine Frage, eine klare Antwort und genau der Ort zum Handeln.","Eén vraag, één duidelijk antwoord en precies waar u moet handelen.","Uma pergunta, uma resposta clara e o local exato onde agir."],
  "Chercher : score, TVA, point mort, audit…":["Search: score, VAT, break-even, audit…","Buscar: puntuación, IVA, punto de equilibrio, auditoría…","Cerca: punteggio, IVA, pareggio, audit…","Suchen: Score, MwSt., Break-even, Audit…","Zoeken: score, btw, break-even, audit…","Pesquisar: pontuação, IVA, ponto de equilíbrio, auditoria…"],
  "Mes chiffres":["My figures","Mis cifras","I miei dati","Meine Zahlen","Mijn cijfers","Os meus números"],
  "Mes établissements":["My businesses","Mis establecimientos","I miei locali","Meine Betriebe","Mijn zaken","Os meus estabelecimentos"],
  "Mon audit":["My audit","Mi auditoría","Il mio audit","Mein Audit","Mijn audit","A minha auditoria"],
  "Règle simple :":["Simple rule:","Regla simple:","Regola semplice:","Einfache Regel:","Eenvoudige regel:","Regra simples:"],
  "Verdict ne remplace jamais une donnée inconnue par une moyenne cachée. Une hypothèse est nommée comme telle.":["Verdict never replaces unknown data with a hidden average. An assumption is always labelled as such.","Verdict nunca sustituye un dato desconocido por una media oculta. Toda hipótesis se identifica como tal.","Verdict non sostituisce mai un dato sconosciuto con una media nascosta. Ogni ipotesi è indicata come tale.","Verdict ersetzt unbekannte Daten niemals durch einen versteckten Durchschnitt. Annahmen werden als solche benannt.","Verdict vervangt onbekende gegevens nooit door een verborgen gemiddelde. Een aanname wordt altijd als zodanig benoemd.","O Verdict nunca substitui um dado desconhecido por uma média escondida. Uma hipótese é sempre identificada como tal."],
  "← Revenir où j’étais":["← Back to where I was","← Volver donde estaba","← Torna a dove ero","← Zurück zur vorherigen Stelle","← Terug naar waar ik was","← Voltar para onde estava"],
  "Où agir :":["Where to act:","Dónde actuar:","Dove agire:","Wo handeln:","Waar handelen:","Onde agir:"],
  "Aucune réponse pour":["No answer for","Ninguna respuesta para","Nessuna risposta per","Keine Antwort für","Geen antwoord voor","Nenhuma resposta para"],
  "Essayez":["Try","Pruebe","Prova","Versuchen Sie","Probeer","Experimente"],
  "Démarrer":["Get started","Empezar","Iniziare","Start","Starten","Começar"],
  "Saisir sans erreur":["Enter data safely","Introducir sin errores","Inserire senza errori","Fehlerfrei eingeben","Foutloos invoeren","Inserir sem erros"],
  "Comprendre":["Understand","Comprender","Capire","Verstehen","Begrijpen","Compreender"],
  "Piloter":["Manage","Pilotar","Gestire","Steuern","Sturen","Gerir"],
  "Confiance & données":["Trust & data","Confianza y datos","Fiducia e dati","Vertrauen & Daten","Vertrouwen & gegevens","Confiança e dados"],

  "Créer ma référence économique":["Create my economic baseline", "Crear mi referencia económica", "Crea il mio riferimento economico", "Meine wirtschaftliche Referenz erstellen", "Mijn economische referentie maken", "Criar a minha referência económica"],
  "Besoin de vos chiffres : panier, commandes, achats, salaires et charges. Verdict vous conduit uniquement vers ce qui manque.":["Your figures are needed: basket, orders, purchases, payroll and costs. Verdict only guides you to what is missing.", "Se necesitan sus cifras: ticket, pedidos, compras, salarios y gastos. Verdict solo le lleva a lo que falta.", "Servono i tuoi dati: scontrino, ordini, acquisti, salari e costi. Verdict ti guida solo verso ciò che manca.", "Ihre Zahlen werden benötigt: Bon, Bestellungen, Einkäufe, Löhne und Kosten. Verdict führt Sie nur zu dem, was fehlt.", "Uw cijfers zijn nodig: bon, bestellingen, inkopen, lonen en kosten. Verdict leidt u alleen naar wat ontbreekt.", "Faltam os seus números: ticket, pedidos, compras, salários e custos. O Verdict guia-o apenas para o que falta."],
  "Compléter mes chiffres":["Complete my figures", "Completar mis cifras", "Completa i miei dati", "Meine Zahlen vervollständigen", "Mijn cijfers aanvullen", "Completar os meus números"],
  "Basé sur vos fiches techniques. Ne reflète aucune perte réelle.":["Based on your recipe sheets. Does not reflect any real loss.", "Basado en sus fichas técnicas. No refleja ninguna pérdida real.", "Basato sulle tue schede tecniche. Non riflette alcuna perdita reale.", "Basierend auf Ihren Rezepturen. Spiegelt keinen tatsächlichen Verlust wider.", "Gebaseerd op uw receptfiches. Weerspiegelt geen echt verlies.", "Baseado nas suas fichas técnicas. Não reflete nenhuma perda real."],
  "L'écart food cost a besoin de vos chiffres (Saisie) ET de votre carte (plats). Remplissez la saisie.":["The food-cost gap needs your figures (Setup) AND your menu (dishes). Complete the setup.", "El desvío de food cost necesita sus cifras (Datos) Y su carta (platos). Complete los datos.", "Lo scarto food cost richiede i tuoi dati (Inserimento) E il tuo menu (piatti). Completa l’inserimento.", "Die Food-Cost-Abweichung braucht Ihre Zahlen (Eingabe) UND Ihre Karte (Gerichte). Füllen Sie die Eingabe aus.", "De foodcost-afwijking heeft uw cijfers (Invoer) EN uw kaart (gerechten) nodig. Vul de invoer in.", "O desvio de food cost precisa dos seus números (Introdução) E da sua carta (pratos). Preencha a introdução."],
  "Verdict calcule. Je vous l’explique, selon l’établissement et l’écran actifs, sans répéter votre score.":["Verdict calculates. I explain it, based on the active business and screen, without repeating your score.", "Verdict calcula. Yo se lo explico, según el establecimiento y la pantalla activos, sin repetir su puntuación.", "Verdict calcola. Te lo spiego, in base all’attività e alla schermata attive, senza ripetere il punteggio.", "Verdict rechnet. Ich erkläre es, je nach aktivem Betrieb und Bildschirm, ohne Ihren Score zu wiederholen.", "Verdict rekent. Ik leg het uit, op basis van de actieve zaak en het scherm, zonder uw score te herhalen.", "O Verdict calcula. Eu explico, segundo o estabelecimento e o ecrã ativos, sem repetir a sua pontuação."],
  "Commun / les deux":["Shared / both", "Común / ambos", "Comune / entrambi", "Gemeinsam / beide", "Gedeeld / beide", "Comum / ambos"],
  "Le module reste unique ; ce repère permet de filtrer sans ressaisir.":["The module stays single; this marker lets you filter without re-entering.", "El módulo sigue siendo único; esta marca permite filtrar sin volver a introducir.", "Il modulo resta unico; questo riferimento permette di filtrare senza reinserire.", "Das Modul bleibt einheitlich; diese Markierung erlaubt das Filtern ohne Neueingabe.", "De module blijft één geheel; met dit kenmerk filtert u zonder opnieuw in te voeren.", "O módulo continua único; esta marca permite filtrar sem reintroduzir."],
  "Enregistrer cet achat":["Save this purchase", "Guardar esta compra", "Salva questo acquisto", "Diesen Einkauf speichern", "Deze inkoop opslaan", "Guardar esta compra"],
  "Même compte Verdict : comptez en Cuisine ou au Bar, puis revenez ici sans recopier de code.":["Same Verdict account: count in the Kitchen or at the Bar, then come back here without retyping any code.", "Misma cuenta Verdict: cuente en Cocina o en el Bar y vuelva aquí sin copiar ningún código.", "Stesso account Verdict: conta in Cucina o al Bar, poi torna qui senza ricopiare alcun codice.", "Gleiches Verdict-Konto: zählen Sie in der Küche oder an der Bar und kommen Sie ohne Code-Eingabe hierher zurück.", "Hetzelfde Verdict-account: tel in de Keuken of aan de Bar en kom hier terug zonder code over te typen.", "Mesma conta Verdict: conte na Cozinha ou no Bar e volte aqui sem copiar nenhum código."],
  "Le minimum utile : date, service, personnes, heures équipe, CA et coût horaire réel. Les heures incluent le travail lié au service — préparation, nettoyage et clôture — mais pas congés, maladie, trajet ou pause repas.":["The useful minimum: date, service, people, team hours, revenue and real hourly cost. Hours include service-related work — preparation, cleaning and closing — but not leave, sickness, commute or meal breaks.", "Lo mínimo útil: fecha, servicio, personas, horas del equipo, ventas y coste horario real. Las horas incluyen el trabajo ligado al servicio — preparación, limpieza y cierre — pero no vacaciones, bajas, trayectos ni pausas de comida.", "Il minimo utile: data, servizio, persone, ore del team, incasso e costo orario reale. Le ore includono il lavoro legato al servizio — preparazione, pulizia e chiusura — ma non ferie, malattia, tragitti o pausa pasto.", "Das nötige Minimum: Datum, Service, Personen, Teamstunden, Umsatz und tatsächlicher Stundensatz. Die Stunden umfassen servicebezogene Arbeit — Vorbereitung, Reinigung und Abschluss — aber nicht Urlaub, Krankheit, Anfahrt oder Pausen.", "Het nuttige minimum: datum, dienst, personen, teamuren, omzet en werkelijke uurkost. De uren omvatten werk rond de dienst — voorbereiding, schoonmaak en sluiting — maar geen verlof, ziekte, reistijd of maaltijdpauze.", "O mínimo útil: data, serviço, pessoas, horas da equipa, vendas e custo horário real. As horas incluem o trabalho ligado ao serviço — preparação, limpeza e fecho — mas não férias, doença, deslocações ou pausa de refeição."],
  "Somme des heures de toutes les personnes.":["Sum of everyone’s hours.", "Suma de las horas de todas las personas.", "Somma delle ore di tutte le persone.", "Summe der Stunden aller Personen.", "Som van de uren van alle personen.", "Soma das horas de todas as pessoas."],
  "L’audit a besoin de vos chiffres":["The audit needs your figures", "La auditoría necesita sus cifras", "L’audit ha bisogno dei tuoi dati", "Das Audit braucht Ihre Zahlen", "De audit heeft uw cijfers nodig", "A auditoria precisa dos seus números"],
  "Complétez votre référence économique, puis revenez : l’audit se construira tout seul.":["Complete your economic baseline, then come back: the audit will build itself.", "Complete su referencia económica y vuelva: la auditoría se construirá sola.", "Completa il tuo riferimento economico, poi torna: l’audit si costruirà da solo.", "Vervollständigen Sie Ihre Referenz und kommen Sie zurück: das Audit baut sich von selbst auf.", "Vul uw economische referentie aan en kom terug: de audit bouwt zichzelf op.", "Complete a sua referência económica e volte: a auditoria constrói-se sozinha."],
  "Le Conseil a besoin de vos chiffres — remplissez d’abord la Saisie.":["The Advice needs your figures — complete the Setup first.", "El Consejo necesita sus cifras — complete primero los Datos.", "Il Consiglio ha bisogno dei tuoi dati — completa prima l’Inserimento.", "Der Rat braucht Ihre Zahlen — füllen Sie zuerst die Eingabe aus.", "Het Advies heeft uw cijfers nodig — vul eerst de Invoer in.", "O Conselho precisa dos seus números — preencha primeiro a Introdução."],
  "Un établissement réel est inclus : 69 € HT/mois ou 690 € HT/an en Pilotage, 129 € HT/mois ou 1 290 € HT/an en Pro. Chaque établissement réel supplémentaire coûte 39 € HT/mois en Pilotage ou 69 € HT/mois en Pro. Les modèles fictifs de démonstration sont gratuits et ne créent jamais un établissement facturé.":["One real business is included: €69/month or €690/year excl. VAT on Pilotage, €129/month or €1,290/year on Pro. Each additional real business costs €39/month on Pilotage or €69/month on Pro, excl. VAT. Fictional demo models are free and never create a billed business.", "Un establecimiento real está incluido: 69 € sin IVA/mes o 690 €/año en Pilotage, 129 €/mes o 1290 €/año en Pro. Cada establecimiento real adicional cuesta 39 €/mes en Pilotage o 69 €/mes en Pro, sin IVA. Los modelos ficticios de demostración son gratuitos y nunca crean un establecimiento facturado.", "Un’attività reale è inclusa: 69 € IVA esclusa/mese o 690 €/anno in Pilotage, 129 €/mese o 1.290 €/anno in Pro. Ogni attività reale aggiuntiva costa 39 €/mese in Pilotage o 69 €/mese in Pro, IVA esclusa. I modelli fittizi di dimostrazione sono gratuiti e non creano mai un’attività fatturata.", "Ein realer Betrieb ist enthalten: 69 €/Monat oder 690 €/Jahr zzgl. MwSt. mit Pilotage, 129 €/Monat oder 1.290 €/Jahr mit Pro. Jeder weitere reale Betrieb kostet 39 €/Monat mit Pilotage oder 69 €/Monat mit Pro, zzgl. MwSt.. Fiktive Demo-Modelle sind kostenlos und erzeugen nie einen abgerechneten Betrieb.", "Eén echte zaak is inbegrepen: € 69/maand of € 690/jaar excl. btw met Pilotage, € 129/maand of € 1.290/jaar met Pro. Elke extra echte zaak kost € 39/maand met Pilotage of € 69/maand met Pro, excl. btw. Fictieve demomodellen zijn gratis en maken nooit een gefactureerde zaak aan.", "Um estabelecimento real está incluído: 69 € s/IVA/mês ou 690 €/ano no Pilotage, 129 €/mês ou 1290 €/ano no Pro. Cada estabelecimento real adicional custa 39 €/mês no Pilotage ou 69 €/mês no Pro, s/IVA. Os modelos fictícios de demonstração são gratuitos e nunca criam um estabelecimento faturado."],
  "Ce qui change votre diagnostic":["What changes your diagnosis", "Lo que cambia su diagnóstico", "Ciò che cambia la tua diagnosi", "Was Ihre Diagnose verändert", "Wat uw diagnose verandert", "O que muda o seu diagnóstico"],
  "Ces réponses adaptent les conseils de Verdict. Aucun chiffre n’est inventé.":["These answers adapt Verdict advice. No figure is invented.", "Estas respuestas adaptan los consejos de Verdict. No se inventa ninguna cifra.", "Queste risposte adattano i consigli di Verdict. Nessun dato è inventato.", "Diese Antworten passen Verdicts Rat an. Keine Zahl wird erfunden.", "Deze antwoorden passen het advies van Verdict aan. Geen cijfer wordt verzonnen.", "Estas respostas adaptam os conselhos do Verdict. Nenhum número é inventado."],
  "Intégré à un hôtel":["Part of a hotel", "Integrado en un hotel", "Integrato in un hotel", "Teil eines Hotels", "Onderdeel van een hotel", "Integrado num hotel"],
  "La productivité mesure un résultat rapporté au travail utilisé. Pour les heures réellement travaillées, Verdict suit le périmètre statistique Eurostat : travail, préparation, maintenance, nettoyage et clôture ; congés, maladie, trajet et pause repas sont exclus. Les décisions d’organisation restent à valider avec les contrats, votre convention collective et vos contraintes terrain.":["Productivity measures a result against the work used. For hours actually worked, Verdict follows the Eurostat statistical scope: work, preparation, maintenance, cleaning and closing; leave, sickness, commute and meal breaks are excluded. Organisational decisions remain to be validated against contracts, your collective agreement and your field constraints.", "La productividad mide un resultado en relación con el trabajo empleado. Para las horas realmente trabajadas, Verdict sigue el perímetro estadístico de Eurostat: trabajo, preparación, mantenimiento, limpieza y cierre; se excluyen vacaciones, bajas, trayectos y pausas de comida. Las decisiones organizativas deben validarse con los contratos, su convenio colectivo y sus limitaciones de campo.", "La produttività misura un risultato rapportato al lavoro impiegato. Per le ore effettivamente lavorate, Verdict segue il perimetro statistico Eurostat: lavoro, preparazione, manutenzione, pulizia e chiusura; ferie, malattia, tragitti e pausa pasto sono esclusi. Le decisioni organizzative restano da validare con i contratti, il contratto collettivo e i vincoli sul campo.", "Produktivität misst ein Ergebnis im Verhältnis zur eingesetzten Arbeit. Für tatsächlich geleistete Stunden folgt Verdict dem statistischen Rahmen von Eurostat: Arbeit, Vorbereitung, Wartung, Reinigung und Abschluss; Urlaub, Krankheit, Anfahrt und Pausen sind ausgeschlossen. Organisatorische Entscheidungen sind mit Verträgen, Tarifvertrag und Praxisbedingungen abzustimmen.", "Productiviteit meet een resultaat tegenover het gebruikte werk. Voor werkelijk gewerkte uren volgt Verdict het statistische kader van Eurostat: werk, voorbereiding, onderhoud, schoonmaak en sluiting; verlof, ziekte, reistijd en maaltijdpauze zijn uitgesloten. Organisatorische beslissingen moeten worden getoetst aan contracten, uw cao en uw praktijkbeperkingen.", "A produtividade mede um resultado face ao trabalho utilizado. Para as horas efetivamente trabalhadas, o Verdict segue o perímetro estatístico do Eurostat: trabalho, preparação, manutenção, limpeza e fecho; férias, doença, deslocações e pausa de refeição são excluídas. As decisões de organização ficam por validar com os contratos, a sua convenção coletiva e as suas restrições no terreno."],
  "Objectif du jour":["Daily target", "Objetivo del día", "Obiettivo del giorno", "Tagesziel", "Dagdoel", "Objetivo do dia"],
  "Modèle de présentation fictif":["Fictional presentation model", "Modelo de presentación ficticio", "Modello di presentazione fittizio", "Fiktives Präsentationsmodell", "Fictief presentatiemodel", "Modelo de apresentação fictício"],
  "Verdict n’a besoin que du résultat du comptage, pas de vos 250 références. Compter, c’est le travail de la cuisine ; piloter, c’est le vôtre.":["Verdict only needs the result of the count, not all 250 items. Counting is the kitchen’s job; steering the business is yours.", "Verdict solo necesita el resultado del recuento, no sus 250 referencias. Contar es trabajo de la cocina; pilotar es el suyo.", "Verdict ha bisogno solo del risultato della conta, non delle tue 250 referenze. Contare è il lavoro della cucina; pilotare è il tuo.", "Verdict braucht nur das Ergebnis der Zählung, nicht Ihre 250 Artikel. Zählen ist Aufgabe der Küche; Steuern ist Ihre.", "Verdict heeft alleen het resultaat van de telling nodig, niet uw 250 artikelen. Tellen is het werk van de keuken; sturen is het uwe.", "O Verdict só precisa do resultado da contagem, não das suas 250 referências. Contar é trabalho da cozinha; pilotar é o seu."],
  "Quel parcours choisir ?":["Which path should I choose?","¿Qué recorrido debo elegir?","Quale percorso devo scegliere?","Welchen Weg soll ich wählen?","Welk traject kies ik?","Que percurso devo escolher?"],
  "Vous avez un exercice comptable clôturé et son compte de résultat : choisissez « J’ai un exercice clôturé » — ou, plus simple, « J’ai mon fichier comptable (FEC) » pour ne rien saisir. Vous êtes déjà ouvert sans premier exercice clôturé : choisissez « J’ai ouvert récemment » pour séparer les faits observés de la projection de travail, sans score annuel. Vous préparez une ouverture ou une reprise : choisissez « Je crée ou reprends ». Pour explorer sans vos chiffres, choisissez la démonstration fictive.":["If you have a closed financial year and its income statement, choose ‘Analyse my restaurant’. If you are already open without a first closed financial year, choose ‘I opened recently’ to keep observed facts separate from the working projection, without an annual score. If you are preparing an opening or takeover, choose ‘Create my project’. To explore without your figures, use the fictional demo.","Si tiene un ejercicio contable cerrado y su cuenta de resultados, elija «Analizar mi restaurante». Si ya está abierto sin un primer ejercicio cerrado, elija «He abierto recientemente» para separar los hechos observados de la proyección de trabajo, sin puntuación anual. Si prepara una apertura o adquisición, elija «Crear mi proyecto». Para explorar sin sus cifras, use la demo ficticia.","Se hai un esercizio contabile chiuso e il relativo conto economico, scegli «Analizza il mio ristorante». Se sei già aperto senza un primo esercizio chiuso, scegli «Ho aperto da poco» per separare i fatti osservati dalla proiezione di lavoro, senza punteggio annuale. Se prepari un’apertura o un subentro, scegli «Crea il mio progetto». Per esplorare senza i tuoi dati, usa la demo fittizia.","Bei einem abgeschlossenen Geschäftsjahr mit GuV wählen Sie „Mein Restaurant analysieren“. Sind Sie bereits geöffnet, aber ohne ersten Jahresabschluss, wählen Sie „Ich habe kürzlich eröffnet“, damit beobachtete Fakten und Arbeitsprojektion getrennt bleiben — ohne Jahresscore. Für Eröffnung oder Übernahme wählen Sie „Mein Projekt erstellen“. Zum Erkunden ohne eigene Zahlen nutzen Sie die fiktive Demo.","Hebt u een afgesloten boekjaar en de resultatenrekening, kies dan ‘Mijn restaurant analyseren’. Bent u al open zonder eerste afgesloten boekjaar, kies dan ‘Ik ben onlangs geopend’ om waargenomen feiten en werkprojectie gescheiden te houden, zonder jaarscore. Voor een opening of overname kiest u ‘Mijn project maken’. Gebruik de fictieve demo om zonder eigen cijfers te verkennen.","Se tem um exercício contabilístico encerrado e a demonstração de resultados, escolha «Analisar o meu restaurante». Se já abriu sem um primeiro exercício encerrado, escolha «Abri recentemente» para separar os factos observados da projeção de trabalho, sem pontuação anual. Para uma abertura ou aquisição, escolha «Criar o meu projeto». Para explorar sem os seus números, use a demonstração fictícia."],
  "Au démarrage, après le choix de la langue.":["At startup, after choosing the language.","Al iniciar, después de elegir el idioma.","All’avvio, dopo la scelta della lingua.","Beim Start, nach der Sprachauswahl.","Bij het starten, na de taalkeuze.","No arranque, depois de escolher o idioma."],

  "J’ai terminé la démonstration. Et maintenant ?":["I finished the demo. What next?","He terminado la demo. ¿Y ahora?","Ho finito la demo. E adesso?","Die Demo ist beendet. Wie geht es weiter?","Ik heb de demo afgerond. Wat nu?","Terminei a demonstração. E agora?"],
  "La visite guidée ne tourne qu’une fois. Ensuite vous pouvez explorer librement le modèle. À tout moment, passez à vos propres chiffres ou créez un projet ; vous n’avez pas à refaire la visite.":["The guided tour runs only once. You can then explore the model freely. At any time, switch to your own figures or create a project; you never have to repeat the tour.","La visita guiada solo se muestra una vez. Después puede explorar el modelo libremente. En cualquier momento puede pasar a sus cifras o crear un proyecto sin repetir la visita.","La visita guidata parte una sola volta. Poi puoi esplorare liberamente il modello. In qualsiasi momento puoi usare i tuoi dati o creare un progetto senza ripetere la visita.","Die Führung läuft nur einmal. Danach können Sie das Modell frei erkunden und jederzeit eigene Zahlen eingeben oder ein Projekt erstellen, ohne die Führung zu wiederholen.","De rondleiding loopt maar één keer. Daarna kunt u het model vrij verkennen en op elk moment uw eigen cijfers gebruiken of een project maken, zonder de rondleiding opnieuw te doen.","A visita guiada acontece apenas uma vez. Depois pode explorar o modelo livremente e, a qualquer momento, usar os seus números ou criar um projeto sem repetir a visita."],
  "Bandeau bleu « Et ensuite ? » dans la démonstration, ou Centre d’aide → Mes chiffres.":["Blue ‘What next?’ banner in the demo, or Help centre → My figures.","Banda azul «¿Y ahora?» en la demo, o Centro de ayuda → Mis cifras.","Banner blu «E adesso?» nella demo, oppure Centro assistenza → I miei dati.","Blauer Banner „Wie weiter?“ in der Demo oder Hilfe → Meine Zahlen.","Blauwe balk ‘Wat nu?’ in de demo, of Helpcentrum → Mijn cijfers.","Faixa azul «E agora?» na demonstração, ou Centro de ajuda → Os meus números."],

  "0 ou case vide : ce n’est pas la même chose":["0 and an empty field are not the same","0 y un campo vacío no son lo mismo","0 e un campo vuoto non sono la stessa cosa","0 und ein leeres Feld sind nicht dasselbe","0 en een leeg veld zijn niet hetzelfde","0 e um campo vazio não são a mesma coisa"],
  "Saisissez 0 uniquement si le poste est réellement nul. Une case vide signifie « je ne sais pas / pas encore renseigné ». Si une donnée indispensable manque, Verdict vous dit laquelle au lieu de fabriquer un score.":["Enter 0 only when the item is genuinely zero. An empty field means ‘unknown / not entered yet’. If required data is missing, Verdict names it instead of inventing a score.","Introduzca 0 solo si la partida es realmente nula. Un campo vacío significa «no lo sé / aún no informado». Si falta un dato obligatorio, Verdict lo indica en vez de inventar una puntuación.","Inserisci 0 solo se la voce è davvero nulla. Un campo vuoto significa «non lo so / non ancora inserito». Se manca un dato necessario, Verdict lo indica invece di inventare un punteggio.","Geben Sie 0 nur ein, wenn der Posten wirklich null ist. Ein leeres Feld bedeutet „unbekannt / noch nicht erfasst“. Fehlt eine Pflichtangabe, nennt Verdict sie, statt einen Score zu erfinden.","Vul 0 alleen in als de post echt nul is. Een leeg veld betekent ‘onbekend / nog niet ingevuld’. Ontbreekt verplichte informatie, dan noemt Verdict die in plaats van een score te verzinnen.","Introduza 0 apenas quando o item for realmente nulo. Um campo vazio significa «não sei / ainda não preenchido». Se faltar um dado obrigatório, o Verdict identifica-o em vez de inventar uma pontuação."],
  "Paramètres → vos chiffres.":["Settings → your figures.","Ajustes → sus cifras.","Impostazioni → i tuoi dati.","Einstellungen → Ihre Zahlen.","Instellingen → uw cijfers.","Definições → os seus números."],

  "CA HT, TVA et période : quoi recopier ?":["Revenue excl. tax, VAT and period: what should I copy?","Ventas sin IVA, IVA y período: ¿qué debo copiar?","Ricavi netti, IVA e periodo: cosa devo riportare?","Nettoumsatz, MwSt. und Zeitraum: Was übernehme ich?","Omzet excl. btw, btw en periode: wat neem ik over?","Receita sem IVA, IVA e período: o que devo copiar?"],
  "Pour un exercice terminé, recopiez le chiffre d’affaires HT de votre compte de résultat sur la même période que vos charges. Utilisez votre TVA moyenne réellement constatée si le calcul en a besoin : Verdict n’impose jamais 10 % à tous les restaurants.":["For a closed year, copy revenue excluding tax from your income statement for the same period as your costs. Use your actual average VAT rate when needed: Verdict never forces 10% on every restaurant.","Para un ejercicio cerrado, copie la facturación sin IVA de su cuenta de resultados para el mismo período que los gastos. Use su IVA medio real cuando sea necesario: Verdict no impone un 10 % a todos los restaurantes.","Per un esercizio chiuso, riporta i ricavi netti dal conto economico per lo stesso periodo dei costi. Usa l’aliquota IVA media effettiva quando serve: Verdict non impone il 10% a tutti.","Für ein abgeschlossenes Jahr übernehmen Sie den Nettoumsatz aus der GuV für denselben Zeitraum wie die Kosten. Verwenden Sie bei Bedarf Ihren tatsächlichen durchschnittlichen MwSt.-Satz; Verdict setzt nicht pauschal 10 % an.","Voor een afgesloten jaar neemt u de omzet excl. btw uit de resultatenrekening over voor dezelfde periode als de kosten. Gebruik waar nodig uw werkelijke gemiddelde btw; Verdict legt niet standaard 10% op.","Num exercício encerrado, copie a receita sem IVA da demonstração de resultados para o mesmo período dos custos. Use a taxa média de IVA realmente observada quando necessário: o Verdict não impõe 10% a todos."],
  "Votre compte de résultat / export comptable ; en cas de doute, validez la base avec votre comptable.":["Your income statement/accounting export; if in doubt, confirm the basis with your accountant.","Su cuenta de resultados/exportación contable; si duda, confirme la base con su contable.","Conto economico/esportazione contabile; in caso di dubbio, verifica la base con il commercialista.","Ihre GuV/Ihr Buchhaltungsexport; im Zweifel die Basis mit der Buchhaltung klären.","Uw resultatenrekening/boekhoudexport; bevestig bij twijfel de basis met uw boekhouder.","A sua demonstração de resultados/exportação contabilística; em caso de dúvida, valide a base com o contabilista."],

  "Salaires, charges sociales et ETP":["Payroll, employer costs and FTE","Salarios, cotizaciones y ETP","Salari, contributi e FTE","Löhne, Sozialkosten und FTE","Lonen, werkgeverslasten en FTE","Salários, encargos sociais e FTE"],
  "Utilisez le coût employeur et les taux qui correspondent réellement à votre situation. Le nombre d’ETP est facultatif pour certains indicateurs : s’il n’est pas saisi, Verdict affiche « Non renseigné » au lieu de l’estimer à partir des salaires.":["Use the employer cost and rates that actually apply to you. FTE count is optional for some indicators: if it is not entered, Verdict shows ‘Not provided’ instead of estimating it from payroll.","Use el coste empresarial y los tipos que realmente correspondan a su situación. El número de ETP es opcional para algunos indicadores: si no se introduce, Verdict muestra «No informado» en vez de estimarlo a partir de los salarios.","Usa il costo aziendale e le aliquote realmente applicabili. Il numero di FTE è facoltativo per alcuni indicatori: se manca, Verdict mostra «Non inserito» invece di stimarlo dai salari.","Verwenden Sie die Arbeitgeberkosten und Sätze, die tatsächlich für Sie gelten. Die FTE-Zahl ist für einige Kennzahlen optional: Fehlt sie, zeigt Verdict „Nicht angegeben“, statt sie aus der Lohnsumme zu schätzen.","Gebruik de werkgeverskosten en percentages die werkelijk op uw situatie van toepassing zijn. FTE is voor sommige indicatoren optioneel: zonder invoer toont Verdict ‘Niet opgegeven’ in plaats van een schatting op basis van de lonen.","Use o custo do empregador e as taxas que realmente se aplicam. O número de FTE é opcional em alguns indicadores: se não for indicado, o Verdict mostra «Não informado» em vez de o estimar a partir dos salários."],
  "Journal de paie, DSN ou données validées par votre paie/comptable.":["Payroll records or figures validated by payroll/accounting.","Nóminas o datos validados por su gestoría/contable.","Libro paga o dati validati dal consulente paghe/commercialista.","Lohnunterlagen oder von Lohnbuchhaltung/Buchhaltung bestätigte Daten.","Loonadministratie of door salarisadministratie/boekhouder bevestigde gegevens.","Registos de salários ou dados validados pelo processamento salarial/contabilista."],

  "Achats, loyer et autres charges":["Purchases, rent and other costs","Compras, alquiler y otros gastos","Acquisti, affitto e altri costi","Einkäufe, Miete und sonstige Kosten","Inkopen, huur en andere kosten","Compras, renda e outros custos"],
  "Saisissez les achats annuels HT réellement facturés et les charges sur leur vraie période. Pour une charge qui court toute l’année, indiquez 12 mois ; sinon indiquez le nombre de mois réellement concernés. Aucun pourcentage de marché n’est ajouté en secret.":["Enter actual annual purchases excluding tax and costs for their real period. Use 12 months for a cost that runs all year; otherwise use the months actually concerned. No market percentage is secretly added.","Introduzca las compras anuales reales sin IVA y los gastos en su período real. Use 12 meses si el gasto corre todo el año; en caso contrario, los meses realmente afectados. No se añade ningún porcentaje de mercado oculto.","Inserisci gli acquisti annui reali al netto dell’IVA e i costi per il loro periodo effettivo. Usa 12 mesi per un costo annuale; altrimenti i mesi realmente interessati. Non viene aggiunta alcuna percentuale di mercato nascosta.","Erfassen Sie die tatsächlichen jährlichen Nettoeinkäufe und Kosten für ihren realen Zeitraum. Bei ganzjährigen Kosten 12 Monate, sonst die tatsächlich betroffenen Monate. Es wird kein versteckter Branchenprozentsatz addiert.","Vul de werkelijke jaarlijkse inkopen excl. btw en kosten voor hun echte periode in. Gebruik 12 maanden voor een jaarronde kost, anders het werkelijke aantal maanden. Er wordt geen verborgen marktpercentage toegevoegd.","Introduza as compras anuais reais sem IVA e os custos no seu período real. Use 12 meses para custos anuais; caso contrário, os meses efetivamente abrangidos. Nenhuma percentagem de mercado é adicionada em segredo."],
  "Grand livre, compte de résultat, factures et contrats.":["General ledger, income statement, invoices and contracts.","Libro mayor, cuenta de resultados, facturas y contratos.","Libro mastro, conto economico, fatture e contratti.","Hauptbuch, GuV, Rechnungen und Verträge.","Grootboek, resultatenrekening, facturen en contracten.","Razão, demonstração de resultados, faturas e contratos."],

  "Verdict détecte une incohérence : suis-je bloqué ?":["Verdict detects an inconsistency: am I blocked?","Verdict detecta una incoherencia: ¿me bloquea?","Verdict rileva un’incoerenza: sono bloccato?","Verdict erkennt eine Unstimmigkeit: Bin ich blockiert?","Verdict detecteert een inconsistentie: zit ik vast?","O Verdict deteta uma incoerência: fico bloqueado?"],
  "Une donnée impossible ou indispensable manquante bloque le calcul et indique quoi corriger. Une donnée seulement improbable déclenche un avertissement : vous pouvez la corriger ou confirmer qu’elle est exacte. La confirmation est liée aux valeurs précises ; si elles changent, Verdict vérifie à nouveau.":["Impossible data or missing required data stops the calculation and tells you what to fix. Merely unusual data triggers a warning: correct it or confirm it is accurate. Confirmation is tied to the exact values; if they change, Verdict checks again.","Un dato imposible o la falta de un dato obligatorio detiene el cálculo e indica qué corregir. Un dato solo improbable genera una advertencia: puede corregirlo o confirmar que es exacto. La confirmación queda ligada a esos valores; si cambian, Verdict vuelve a comprobar.","Un dato impossibile o un dato obbligatorio mancante ferma il calcolo e indica cosa correggere. Un dato solo improbabile genera un avviso: puoi correggerlo o confermarlo. La conferma è legata ai valori esatti; se cambiano, Verdict controlla di nuovo.","Unmögliche oder fehlende Pflichtdaten stoppen die Berechnung und nennen die Korrektur. Nur ungewöhnliche Werte lösen eine Warnung aus: korrigieren oder bestätigen. Die Bestätigung gilt genau für diese Werte; ändern sie sich, prüft Verdict erneut.","Onmogelijke of ontbrekende verplichte gegevens stoppen de berekening en tonen wat u moet corrigeren. Alleen onwaarschijnlijke waarden geven een waarschuwing: corrigeren of bevestigen. De bevestiging hoort bij de exacte waarden; veranderen ze, dan controleert Verdict opnieuw.","Dados impossíveis ou obrigatórios em falta param o cálculo e indicam o que corrigir. Um valor apenas improvável gera um aviso: pode corrigi-lo ou confirmá-lo. A confirmação fica ligada aos valores exatos; se mudarem, o Verdict verifica novamente."],
  "La donnée concernée est nommée dans le message, jamais seulement colorée en rouge.":["The affected data is named in the message, never only shown in red.","El dato afectado se nombra en el mensaje, nunca se muestra solo en rojo.","Il dato interessato è indicato nel messaggio, non soltanto colorato in rosso.","Die betroffene Angabe wird im Hinweis genannt und nicht nur rot markiert.","Het betrokken gegeven wordt in het bericht genoemd en niet alleen rood gemarkeerd.","O dado em causa é identificado na mensagem, nunca apenas assinalado a vermelho."],

  "Que signifie le score Verdict de 0 à 100 ?":["What does the Verdict score from 0 to 100 mean?","¿Qué significa la puntuación Verdict de 0 a 100?","Cosa significa il punteggio Verdict da 0 a 100?","Was bedeutet der Verdict-Score von 0 bis 100?","Wat betekent de Verdict-score van 0 tot 100?","O que significa a pontuação Verdict de 0 a 100?"],
  "C’est un indice de pilotage interne à Verdict qui résume plusieurs dimensions de votre structure. Ce n’est ni une note comptable, ni une notation bancaire, ni un percentile national. Les repères Verdict et les statistiques publiques FIBEN sont affichés séparément.":["It is Verdict’s internal management index combining several dimensions of your structure. It is not an accounting grade, bank rating or national percentile. Verdict benchmarks and public FIBEN statistics are shown separately.","Es un índice interno de gestión de Verdict que resume varias dimensiones de su estructura. No es una nota contable, una calificación bancaria ni un percentil nacional. Las referencias Verdict y las estadísticas públicas FIBEN se muestran por separado.","È un indice gestionale interno di Verdict che riassume più dimensioni della struttura. Non è un voto contabile, un rating bancario né un percentile nazionale. I riferimenti Verdict e le statistiche pubbliche FIBEN restano separati.","Es ist ein interner Verdict-Steuerungsindex aus mehreren Dimensionen Ihrer Struktur. Er ist weder Buchhaltungsnote noch Bankrating oder nationales Perzentil. Verdict-Richtwerte und öffentliche FIBEN-Statistiken werden getrennt gezeigt.","Het is een interne Verdict-stuurindex die meerdere dimensies van uw structuur samenvat. Het is geen boekhoudcijfer, bankrating of nationaal percentiel. Verdict-richtwaarden en openbare FIBEN-statistieken worden apart getoond.","É um índice interno de gestão do Verdict que reúne várias dimensões da estrutura. Não é uma nota contabilística, classificação bancária nem percentil nacional. As referências Verdict e as estatísticas públicas FIBEN são mostradas separadamente."],
  "Accueil et Diagnostic → Score / Repères & secteur.":["Home and Diagnostic → Score / Benchmarks & sector.","Inicio y Diagnóstico → Puntuación / Referencias y sector.","Home e Diagnosi → Punteggio / Riferimenti e settore.","Start und Diagnose → Score / Richtwerte & Branche.","Home en Diagnose → Score / Richtwaarden & sector.","Início e Diagnóstico → Pontuação / Referências e setor."],

  "Résultat avant impôt, point mort et coûts matière":["Pre-tax result, break-even and food costs","Resultado antes de impuestos, punto de equilibrio y coste de materia","Risultato ante imposte, pareggio e costo materia","Ergebnis vor Steuern, Break-even und Wareneinsatz","Resultaat vóór belasting, break-even en materiaalkosten","Resultado antes de impostos, ponto de equilíbrio e custo de matéria"],
  "Le résultat avant impôt est ce qui reste dans le modèle après les coûts saisis, avant fiscalité. Le point mort est le niveau de CA nécessaire pour couvrir les coûts modélisés. Le food cost lit les achats nourriture ; le coût matière global ajoute les boissons et autres matières selon la vue.":["Pre-tax result is what remains in the model after entered costs, before tax. Break-even is the revenue needed to cover modelled costs. Food cost reads food purchases; total material cost adds drinks and other materials depending on the view.","El resultado antes de impuestos es lo que queda en el modelo después de los costes introducidos, antes de impuestos. El punto de equilibrio es la facturación necesaria para cubrir los costes modelizados. Food cost usa las compras de alimentos; el coste total de materia añade bebidas y otras materias según la vista.","Il risultato ante imposte è ciò che resta nel modello dopo i costi inseriti, prima della fiscalità. Il pareggio è il fatturato necessario a coprire i costi modellati. Il food cost legge gli acquisti alimentari; il costo materia totale aggiunge bevande e altre materie secondo la vista.","Das Ergebnis vor Steuern bleibt im Modell nach den erfassten Kosten vor Steuern übrig. Der Break-even ist der nötige Umsatz zur Deckung der modellierten Kosten. Food Cost nutzt Lebensmitteleinkäufe; der gesamte Wareneinsatz ergänzt Getränke und sonstige Waren je nach Ansicht.","Het resultaat vóór belasting is wat in het model overblijft na de ingevoerde kosten, vóór belasting. Break-even is de omzet die nodig is om de gemodelleerde kosten te dekken. Foodcost gebruikt voedingsinkopen; totale materiaalkosten voegen drank en andere materialen toe naargelang de weergave.","O resultado antes de impostos é o que resta no modelo após os custos inseridos, antes da fiscalidade. O ponto de equilíbrio é a receita necessária para cobrir os custos modelados. O food cost usa as compras de alimentos; o custo total de matéria acrescenta bebidas e outros materiais conforme a vista."],
  "Diagnostic. Les définitions utilisées sont rappelées à côté des indicateurs.":["Diagnostic. Definitions are shown next to the indicators.","Diagnóstico. Las definiciones aparecen junto a los indicadores.","Diagnosi. Le definizioni sono riportate accanto agli indicatori.","Diagnose. Die Definitionen stehen bei den Kennzahlen.","Diagnose. De definities staan naast de indicatoren.","Diagnóstico. As definições aparecem junto aos indicadores."],

  "Que dois-je faire au quotidien ?":["What should I do every day?","¿Qué debo hacer cada día?","Cosa devo fare ogni giorno?","Was soll ich täglich tun?","Wat doe ik dagelijks?","O que devo fazer diariamente?"],
  "Sur l’Accueil, deux chiffres suffisent pour votre point du jour : le CA TTC encaissé et les tickets. Verdict recalcule le rythme à tenir à partir de votre structure. Une fermeture ou une saison particulière doit être renseignée ; elle n’est pas devinée.":["On Home, your daily check uses gross revenue collected and ticket count. Verdict recalculates the pace from your structure. Closures or special seasons must be entered; they are never guessed.","En Inicio, el punto del día usa la facturación con impuestos cobrada y los tickets. Verdict recalcula el ritmo a partir de su estructura. Los cierres o temporadas especiales deben indicarse; no se adivinan.","In Home, il punto giornaliero usa l’incasso lordo e il numero di scontrini. Verdict ricalcola il ritmo dalla struttura. Chiusure o stagioni particolari vanno indicate; non vengono indovinate.","Auf Start nutzt der Tagescheck den Bruttoumsatz und die Bonzahl. Verdict berechnet daraus den nötigen Rhythmus. Schließtage oder besondere Saisons müssen erfasst werden; sie werden nicht erraten.","Op Home gebruikt de dagcheck de ontvangen omzet incl. btw en het aantal tickets. Verdict herberekent het tempo vanuit uw structuur. Sluitingen of bijzondere seizoenen moet u invoeren; ze worden niet gegokt.","No Início, o ponto diário usa a receita com IVA recebida e o número de tickets. O Verdict recalcula o ritmo a partir da estrutura. Fechos ou épocas especiais devem ser indicados; não são adivinhados."],
  "Accueil → Votre journée.":["Home → Your day.","Inicio → Su día.","Home → La tua giornata.","Start → Ihr Tag.","Home → Uw dag.","Início → O seu dia."],

  "Carte, stock et performance des services":["Menu, stock and service performance","Carta, stock y rendimiento de servicios","Menu, stock e performance dei servizi","Karte, Bestand und Service-Performance","Kaart, voorraad en serviceprestaties","Cardápio, stock e desempenho dos serviços"],
  "La Carte relie recettes, prix et volumes. Le Stock s’appuie sur vos comptages. Performance des services utilise vos heures équipe totales, votre CA du service et votre coût horaire chargé réel : si vous ne les donnez pas, Verdict ne les invente pas.":["Menu links recipes, prices and volumes. Stock uses your counts. Service performance uses total team hours, service revenue and your actual loaded hourly cost: if you do not provide them, Verdict does not invent them.","Carta relaciona recetas, precios y volúmenes. Stock usa sus recuentos. Rendimiento de servicios usa las horas totales del equipo, la facturación del servicio y su coste horario real: si no los indica, Verdict no los inventa.","Menu collega ricette, prezzi e volumi. Stock usa i tuoi conteggi. Performance dei servizi usa le ore totali del team, il fatturato del servizio e il costo orario caricato reale: se non li inserisci, Verdict non li inventa.","Karte verbindet Rezepte, Preise und Mengen. Bestand nutzt Ihre Zählungen. Service-Performance nutzt gesamte Teamstunden, Serviceumsatz und tatsächliche belastete Stundenkosten: Ohne Eingabe erfindet Verdict nichts.","Kaart koppelt recepten, prijzen en volumes. Voorraad gebruikt uw tellingen. Serviceprestaties gebruiken totale teamuren, serviceomzet en uw werkelijke belaste uurkost: zonder invoer verzint Verdict niets.","Cardápio liga receitas, preços e volumes. Stock usa as suas contagens. Desempenho dos serviços usa horas totais da equipa, receita do serviço e custo horário carregado real: sem esses dados, o Verdict não os inventa."],
  "Carte ; Plus → Achats/Stock ; Plus → Performance des services.":["Menu; More → Purchases/Stock; More → Service performance.","Carta; Más → Compras/Stock; Más → Rendimiento de servicios.","Menu; Altro → Acquisti/Stock; Altro → Performance dei servizi.","Karte; Mehr → Einkäufe/Bestand; Mehr → Service-Performance.","Kaart; Meer → Inkopen/Voorraad; Meer → Serviceprestaties.","Cardápio; Mais → Compras/Stock; Mais → Desempenho dos serviços."],

  "J’ai plusieurs restaurants : comment comparer ?":["I have several restaurants: how do I compare them?","Tengo varios restaurantes: ¿cómo los comparo?","Ho più ristoranti: come li confronto?","Ich habe mehrere Restaurants: Wie vergleiche ich sie?","Ik heb meerdere restaurants: hoe vergelijk ik ze?","Tenho vários restaurantes: como os comparo?"],
  "Ouvrez « Mes établissements » : Verdict compare les ratios sur 100 € HT, jamais la taille brute. Une conclusion n’est donnée que si les données sont complètes, de même nature et sur la même période ; un profil différent est signalé. Les sociétés ne sont jamais fusionnées ni consolidées. Ensuite, changez d’établissement : Verdict conserve exactement la page où vous étiez.":["Open ‘My businesses’: Verdict compares ratios per €100 excl. tax, never raw size. It concludes only with complete data of the same nature and period; a different profile is flagged. Companies are never merged or consolidated. Then switch location: Verdict keeps the exact page you were on.","Abra «Mis establecimientos»: Verdict compara ratios por 100 € sin IVA, nunca el tamaño bruto. Solo concluye con datos completos, de la misma naturaleza y período; señala un perfil distinto. Las sociedades nunca se fusionan ni consolidan. Al cambiar de establecimiento, Verdict conserva la página exacta.","Apri «I miei locali»: Verdict confronta i rapporti su 100 € netti, mai la dimensione assoluta. Conclude solo con dati completi, della stessa natura e periodo; segnala un profilo diverso. Le società non vengono unite né consolidate. Cambiando locale, Verdict mantiene la pagina esatta.","Öffnen Sie „Meine Betriebe“: Verdict vergleicht Kennzahlen je 100 € Nettoumsatz, nie die absolute Größe. Ein Schluss folgt nur bei vollständigen Daten gleicher Art und Periode; abweichende Profile werden markiert. Gesellschaften werden nie zusammengeführt oder konsolidiert. Beim Wechsel bleibt die genaue Seite erhalten.","Open ‘Mijn zaken’: Verdict vergelijkt ratio’s per €100 excl. btw, nooit ruwe omvang. Het concludeert alleen met volledige gegevens van dezelfde aard en periode; een ander profiel wordt gemeld. Vennootschappen worden nooit samengevoegd of geconsolideerd. Bij het wisselen blijft exact dezelfde pagina open.","Abra «Os meus estabelecimentos»: o Verdict compara rácios por 100 € sem imposto, nunca o tamanho bruto. Só conclui com dados completos, da mesma natureza e período; assinala um perfil diferente. As sociedades nunca são fundidas nem consolidadas. Ao mudar de estabelecimento, mantém exatamente a mesma página."],
  "Barre des établissements en haut → roue dentée → Comparer, ou Centre d’aide → Mes établissements.":["Business bar at the top → gear → Compare, or Help centre → My businesses.","Barra de establecimientos → rueda dentada → Comparar, o Centro de ayuda → Mis establecimientos.","Barra dei locali → ingranaggio → Confronta, oppure Centro assistenza → I miei locali.","Betriebsleiste oben → Zahnrad → Vergleichen oder Hilfe → Meine Betriebe.","Vestigingenbalk bovenaan → tandwiel → Vergelijken, of Helpcentrum → Mijn zaken.","Barra de estabelecimentos → roda dentada → Comparar, ou Centro de ajuda → Os meus estabelecimentos."],

  "Que contient l’Audit Premium ?":["What is included in the Premium Audit?","¿Qué incluye la Auditoría Premium?","Cosa contiene l’Audit Premium?","Was enthält das Premium-Audit?","Wat bevat de Premium-audit?","O que inclui a Auditoria Premium?"],
  "L’audit reprend la même source de calcul en 20 chapitres, ajoute votre modèle CHR et vos réponses terrain, puis construit un plan pilotable sur 90 jours. Ses quatre sorties — Premium complet, comptable, banque/associé et rapport exécutif — ne recalculent rien. Il reste une lecture de pilotage avant impôt et ne remplace ni les comptes annuels ni l’avis de votre comptable ou de votre banque.":["The audit uses one calculation source across 20 chapters, adds your hospitality model and field answers, then builds an actionable 90-day plan. Its four outputs — complete Premium Audit, accountant file, bank/partner file and executive report — never recalculate. It remains a pre-tax management reading and does not replace statutory accounts or advice from your accountant or bank.","La auditoría usa una única fuente de cálculo en 20 capítulos, añade su modelo hostelero y sus respuestas de campo y crea un plan gestionable de 90 días. Sus cuatro salidas — Auditoría Premium completa, expediente contable, expediente banco/socio e informe ejecutivo — no recalculan nada. Sigue siendo una lectura de gestión antes de impuestos y no sustituye las cuentas ni el asesoramiento profesional.","L’audit usa un’unica fonte di calcolo in 20 capitoli, aggiunge il modello dell’attività e le risposte sul campo, poi crea un piano operativo di 90 giorni. Le quattro uscite — Audit Premium completo, dossier commercialista, dossier banca/socio e rapporto esecutivo — non ricalcolano nulla. Resta una lettura gestionale ante imposte e non sostituisce bilancio o consulenza professionale.","Das Audit nutzt eine einzige Berechnungsquelle in 20 Kapiteln, ergänzt Ihr Gastronomiemodell und Ihre Praxisantworten und erstellt einen steuerbaren 90-Tage-Plan. Die vier Ausgaben – vollständiges Premium-Audit, Steuerberater-Dossier, Bank-/Partner-Dossier und Managementbericht – rechnen nichts neu. Es bleibt eine Steuerungslesart vor Steuern und ersetzt weder Abschluss noch professionelle Beratung.","De audit gebruikt één berekeningsbron in 20 hoofdstukken, voegt uw horecamodel en praktijkantwoorden toe en bouwt een stuurbaar 90-dagenplan. De vier uitvoerformaten — volledige Premium Audit, accountantdossier, bank-/partnerdossier en managementrapport — rekenen niets opnieuw. Het blijft een stuurlezing vóór belasting en vervangt jaarrekening of professioneel advies niet.","A auditoria usa uma única fonte de cálculo em 20 capítulos, acrescenta o seu modelo CHR e respostas de terreno e cria um plano gerível de 90 dias. As quatro saídas — Auditoria Premium completa, dossier contabilístico, dossier banco/sócio e relatório executivo — não recalculam nada. Continua a ser uma leitura de gestão antes de impostos e não substitui contas anuais ou aconselhamento profissional."],
  "Plus → Audit, puis choisissez le format d’export.":["More → Audit, then choose the export format.","Más → Auditoría y elija el formato de exportación.","Altro → Audit, poi scegli il formato di esportazione.","Mehr → Audit, dann das Exportformat wählen.","Meer → Audit en kies daarna het exportformaat.","Mais → Auditoria e depois escolha o formato de exportação."],

  "Où sont mes données ? Que se passe-t-il avec l’abonnement ?":["Where is my data? What happens with the subscription?","¿Dónde están mis datos? ¿Qué ocurre con la suscripción?","Dove sono i miei dati? Cosa succede con l’abbonamento?","Wo liegen meine Daten? Was passiert mit dem Abo?","Waar staan mijn gegevens? Wat gebeurt er met het abonnement?","Onde estão os meus dados? O que acontece com a subscrição?"],
  "Votre dossier reste enregistré sur cet appareil, avec une copie locale de secours et un export JSON. Lorsque le coffre de compte est réellement activé sur le serveur pour Verdict Pro, une copie chiffrée côté serveur permet aussi la synchronisation et la restauration sur un autre appareil. Verdict indique toujours l’état réel de cette protection ; ce coffre n’est pas un chiffrement de bout en bout. L’essai commercial de 14 jours est prévu après activation du serveur ; aucun paiement n’est actif dans cette livraison. Inventaire Cuisine & Bar reste gratuit.":["Your file remains stored on this device, with a local fallback copy and JSON export. When the account vault is actually enabled on the server for Verdict Pro, an encrypted server-side copy also enables syncing and restoring on another device. Verdict always shows the real protection status; this vault is not end-to-end encryption. The 14-day commercial trial is planned after server activation; no payment is active in this delivery. Kitchen & Bar Inventory remains free.","Su expediente permanece guardado en este dispositivo, con una copia local de respaldo y una exportación JSON. Cuando el servidor activa realmente la bóveda de cuenta para Verdict Pro, una copia cifrada en el servidor también permite sincronizar y restaurar en otro dispositivo. Verdict muestra siempre el estado real de la protección; no es cifrado de extremo a extremo. La prueba comercial de 14 días está prevista tras activar el servidor; no hay ningún pago activo en esta entrega. Inventario Cocina & Bar sigue siendo gratuito.","Il fascicolo resta salvato su questo dispositivo, con una copia locale di sicurezza e un'esportazione JSON. Quando il server attiva realmente il caveau dell'account per Verdict Pro, una copia cifrata lato server consente anche sincronizzazione e ripristino su un altro dispositivo. Verdict mostra sempre lo stato reale della protezione; non è crittografia end-to-end. La prova commerciale di 14 giorni è prevista dopo l’attivazione del server; nessun pagamento è attivo in questa versione. Inventario Cucina & Bar resta gratuito.","Ihre Akte bleibt auf diesem Gerät gespeichert, mit lokaler Sicherheitskopie und JSON-Export. Sobald der Konto-Tresor für Verdict Pro tatsächlich auf dem Server aktiviert ist, ermöglicht eine serverseitig verschlüsselte Kopie auch Synchronisierung und Wiederherstellung auf einem anderen Gerät. Verdict zeigt stets den tatsächlichen Schutzstatus; dies ist keine Ende-zu-Ende-Verschlüsselung. Der 14-tägige Test ist nach der Serveraktivierung vorgesehen; in dieser Version ist keine Zahlung aktiv. Küche-&-Bar-Inventar bleibt kostenlos.","Uw dossier blijft op dit apparaat opgeslagen, met een lokale reservekopie en JSON-export. Zodra de accountkluis voor Verdict Pro echt op de server is geactiveerd, maakt een versleutelde serverkopie ook synchronisatie en herstel op een ander apparaat mogelijk. Verdict toont altijd de werkelijke beschermingsstatus; dit is geen end-to-endversleuteling. De commerciële proef van 14 dagen is gepland na serveractivering; in deze versie is geen betaling actief. Inventaris Keuken & Bar blijft gratis.","O seu dossiê permanece guardado neste dispositivo, com uma cópia local de segurança e exportação JSON. Quando o cofre da conta for realmente ativado no servidor para o Verdict Pro, uma cópia cifrada no servidor também permite sincronizar e restaurar noutro dispositivo. O Verdict mostra sempre o estado real da proteção; não se trata de cifragem ponta a ponta. O teste comercial de 14 dias está previsto após a ativação do servidor; nenhum pagamento está ativo nesta versão. O Inventário Cozinha & Bar continua gratuito."],
  "Paramètres → Sauvegarder/Restaurer ; Plus → Mon abonnement.":["Settings → Backup/Restore; More → My subscription.","Ajustes → Guardar/Restaurar; Más → Mi suscripción.","Impostazioni → Backup/Ripristino; Altro → Il mio abbonamento.","Einstellungen → Sichern/Wiederherstellen; Mehr → Mein Abo.","Instellingen → Back-up/Herstellen; Meer → Mijn abonnement.","Definições → Guardar/Restaurar; Mais → A minha subscrição."],

  "Ce que Verdict ne décide pas à votre place":["What Verdict does not decide for you","Lo que Verdict no decide por usted","Cosa Verdict non decide al posto tuo","Was Verdict nicht für Sie entscheidet","Wat Verdict niet voor u beslist","O que o Verdict não decide por si"],
  "Verdict ne remplace pas la comptabilité, la fiscalité, le droit social, la paie, un planning contractuel ou un conseil bancaire. Il ne se connecte pas automatiquement à votre banque ou à votre caisse dans cette version. Il chiffre, recoupe, alerte et simule ; vous validez la décision et les données sources.":["Verdict does not replace accounting, tax, employment law, payroll, contractual scheduling or banking advice. This version does not connect automatically to your bank or POS. It calculates, cross-checks, warns and simulates; you validate decisions and source data.","Verdict no sustituye la contabilidad, fiscalidad, derecho laboral, nóminas, planificación contractual ni asesoramiento bancario. Esta versión no se conecta automáticamente al banco o caja. Calcula, cruza, avisa y simula; usted valida decisiones y datos fuente.","Verdict non sostituisce contabilità, fiscalità, diritto del lavoro, paghe, turnistica contrattuale o consulenza bancaria. Questa versione non si collega automaticamente a banca o cassa. Calcola, incrocia, avvisa e simula; tu convalidi decisioni e dati fonte.","Verdict ersetzt weder Buchhaltung, Steuern, Arbeitsrecht, Lohnabrechnung, vertragliche Einsatzplanung noch Bankberatung. Diese Version verbindet sich nicht automatisch mit Bank oder Kasse. Sie rechnet, gleicht ab, warnt und simuliert; Sie bestätigen Entscheidung und Quelldaten.","Verdict vervangt geen boekhouding, belastingadvies, arbeidsrecht, loonadministratie, contractplanning of bankadvies. Deze versie koppelt niet automatisch met bank of kassa. Ze rekent, kruist, waarschuwt en simuleert; u bevestigt beslissingen en brongegevens.","O Verdict não substitui contabilidade, fiscalidade, direito laboral, salários, planeamento contratual ou aconselhamento bancário. Esta versão não se liga automaticamente ao banco ou POS. Calcula, cruza, alerta e simula; o utilizador valida decisões e dados de origem."],
  "Quand une décision engage un contrat, un salarié, un impôt ou un financement, faites valider le point par le professionnel concerné.":["When a decision affects a contract, employee, tax or financing, have the point validated by the relevant professional.","Cuando una decisión afecte a un contrato, empleado, impuesto o financiación, valide el punto con el profesional correspondiente.","Quando una decisione riguarda contratto, dipendente, imposta o finanziamento, falla verificare dal professionista competente.","Bei Entscheidungen zu Vertrag, Mitarbeiter, Steuer oder Finanzierung den Punkt durch die zuständige Fachperson prüfen lassen.","Laat een beslissing over contract, werknemer, belasting of financiering door de juiste professional toetsen.","Quando uma decisão envolver contrato, trabalhador, imposto ou financiamento, valide o ponto com o profissional competente."]
});
Object.assign(TR,{
  "Pourquoi cette action est-elle première ?":["Why is this action first?","¿Por qué esta acción es la primera?","Perché questa azione viene prima?","Warum steht diese Maßnahme an erster Stelle?","Waarom staat deze actie op één?","Porque é que esta ação vem primeiro?"],
  "Verdict classe les écarts avec la même source dans Actions, l’Accueil, l’Audit et Vera. Il regarde l’urgence, le montant réellement observable, la fiabilité des données et la possibilité d’agir. Il affiche une seule action principale, explique pourquoi elle passe devant les autres et donne la mesure à vérifier. Un manque de trésorerie ou une perte constatée reste un écart à couvrir ; seul un changement futur testé est présenté comme une simulation. Une donnée ancienne passe d’abord en priorité et suspend les conseils financiers trop précis.":["Verdict ranks gaps from the same source in Actions, Home, Audit and Vera. It considers urgency, the amount that can actually be observed, data reliability and feasibility. It shows one main action, explains why it comes before the others and gives the metric to check. A cash shortfall or recorded loss remains a gap to cover; only a tested future change is presented as a simulation. Stale data becomes the first priority and suspends overly precise financial advice.","Verdict clasifica las desviaciones con la misma fuente en Acciones, Inicio, Auditoría y Vera. Considera la urgencia, el importe realmente observable, la fiabilidad de los datos y la posibilidad de actuar. Muestra una sola acción principal, explica por qué va antes que las demás e indica la medida que debe comprobarse. Una falta de tesorería o una pérdida constatada sigue siendo una desviación que cubrir; solo un cambio futuro probado se presenta como simulación. Un dato antiguo pasa primero y suspende los consejos financieros demasiado precisos.","Verdict ordina gli scostamenti con la stessa fonte in Azioni, Home, Audit e Vera. Considera urgenza, importo realmente osservabile, affidabilità dei dati e possibilità di agire. Mostra una sola azione principale, spiega perché viene prima delle altre e indica la misura da verificare. Una carenza di cassa o una perdita rilevata resta uno scostamento da coprire; solo un cambiamento futuro testato viene presentato come simulazione. Un dato vecchio passa al primo posto e sospende i consigli finanziari troppo precisi.","Verdict priorisiert Abweichungen aus derselben Quelle in Maßnahmen, Start, Audit und Vera. Berücksichtigt werden Dringlichkeit, tatsächlich beobachtbarer Betrag, Datenzuverlässigkeit und Umsetzbarkeit. Es zeigt eine Hauptmaßnahme, erklärt ihre Vorrangigkeit und nennt die zu prüfende Kennzahl. Eine Liquiditätslücke oder ein festgestellter Verlust bleibt eine zu schließende Lücke; nur eine getestete künftige Änderung wird als Simulation bezeichnet. Veraltete Daten werden zuerst behandelt und setzen zu genaue Finanztipps aus.","Verdict rangschikt afwijkingen vanuit dezelfde bron in Acties, Start, Audit en Vera. Het kijkt naar urgentie, het werkelijk waarneembare bedrag, betrouwbaarheid van gegevens en uitvoerbaarheid. Het toont één hoofdactie, legt uit waarom die vóór de andere komt en noemt de te controleren maatstaf. Een kastekort of vastgesteld verlies blijft een te dichten verschil; alleen een geteste toekomstige wijziging heet een simulatie. Verouderde gegevens krijgen voorrang en schorten te precieze financiële adviezen op.","O Verdict ordena os desvios com a mesma fonte em Ações, Início, Auditoria e Vera. Considera a urgência, o valor realmente observável, a fiabilidade dos dados e a possibilidade de agir. Mostra uma única ação principal, explica porque vem antes das outras e indica a medida a verificar. Uma falta de tesouraria ou uma perda apurada continua a ser um desvio a cobrir; só uma mudança futura testada é apresentada como simulação. Um dado antigo passa primeiro e suspende conselhos financeiros demasiado precisos."],
  "Actions → Commencer et suivre. Verdict enregistre le point de départ, la date de contrôle et l’établissement actif sans modifier le score.":["Actions → Start and track. Verdict records the baseline, review date and active business without changing the score.","Acciones → Empezar y seguir. Verdict registra el punto de partida, la fecha de control y el establecimiento activo sin cambiar la puntuación.","Azioni → Inizia e monitora. Verdict registra il punto di partenza, la data di controllo e il locale attivo senza modificare il punteggio.","Maßnahmen → Starten und verfolgen. Verdict speichert Ausgangswert, Prüftermin und aktiven Betrieb, ohne den Score zu verändern.","Acties → Starten en volgen. Verdict bewaart de nulmeting, controledatum en actieve zaak zonder de score te wijzigen.","Ações → Começar e acompanhar. O Verdict regista o ponto de partida, a data de controlo e o estabelecimento ativo sem alterar a pontuação."],
  "Comment commencer et mesurer le résultat ?":["How do I start and measure the result?","¿Cómo empiezo y mido el resultado?","Come inizio e misuro il risultato?","Wie starte ich und messe das Ergebnis?","Hoe start en meet ik het resultaat?","Como começo e meço o resultado?"],
  "Le montant affiché est-il un gain ?":["Is the amount shown a gain?","¿El importe mostrado es una ganancia?","L’importo mostrato è un guadagno?","Ist der angezeigte Betrag ein Gewinn?","Is het getoonde bedrag een winst?","O valor apresentado é um ganho?"]
});
function aideNorm(s){
  s=String(s==null?'':s).toLowerCase();
  try{s=s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');}catch(e){}
  return s.replace(/[’']/g,"'").replace(/\s+/g,' ').trim();
}
function aideEsc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
