function vAideTexte(s,n){return String(s||'').replace('{n}',String(n==null?'':n));}
function vAideContexte(){
  var t=V_AIDE_LANG[LOCALE]||V_AIDE_LANG.fr, r=null, man=[], inc=[];
  try{r=moteur();man=r.manquants||[];inc=r.incoherences||[];}catch(e){}
  var message='';
  if(VERDICT_DEMO_SESSION)message=t.demo;
  else if(inc.length)message=vAideTexte(t.invalid,inc.length);
  else if(man.length||!r||!r.ready)message=vAideTexte(t.missing,man.length||1);
  else message=t.ready;
  var nom=(DB&&DB.etab)||'—', vue=(VIEW||'pil');
  if(vue==='audit'&&r&&r.ready&&t.audit){
    var ce=auCtxEtat(),pe=au90Etat(); message=String(t.audit).replace('{ctx}',ce.n).replace('{plan}',pe.fait);
  }
  var box=document.getElementById('aideContext');
  if(box)box.innerHTML='<span class="k">'+aideEsc(t.local)+'</span><b>'+aideEsc(t.place)+' : '+aideEsc(nom)+'</b><br>'+aideEsc(t.screen)+' : '+aideEsc(vue)+'<br>'+aideEsc(message);
  var sug=document.getElementById('aideSuggestions'), Q=V_AIDE_VUES[vue]||V_AIDE_VUES.pil;
  if(sug){sug.innerHTML='<span class="v-help-name">'+aideEsc(t.ask)+'</span>'+Q.map(function(q){return '<button type="button" data-search="'+aideEsc(q[1])+'" onclick="vAideQuestion(this)">'+aideEsc(trText(q[0]))+'</button>';}).join('');}
}
function vAideQuestion(btn){
  var q=document.getElementById('aideQ'); if(!q)return;
  q.value=btn.textContent.replace(/\s*→\s*$/,'').trim()||btn.getAttribute('data-search')||'';
  aideDessiner();veraDemander(null);
  try{q.scrollIntoView({behavior:'smooth',block:'center'});}catch(e){}
}
function aideTrouver(brut){ /* R217 : PORTÉ depuis la lignée GPT (R200) — voir 04-TESTS/R201/R217 */
  var q=aideNorm(brut||''),eq=AIDE_EQUIV[veraAppLocale()]||{},qs=[q];
  if(q&&eq[q])qs=[aideNorm(eq[q])];
  if(!q)return AIDE_V104.slice();
  /* Search meaningful words, never arbitrary substrings inside unrelated words.
     Question words and connecting words are ignored in all seven UI languages. */
  var stop=('le la les un une des du de d et ou a au aux en sur pour par je tu vous votre vos mon ma mes ce cette ces est il elle ils elles que quoi comment pourquoi quel quelle quels quelles qui se sont fait faire '+
    'the a an of to is are was were my your our how why what which where when and or on in at for from with do does did i we you it this that these those about can could should '+
    'el la los las un una unos unas del es son mi mis su sus nuestro nuestra que cual cuales como donde cuando por para con al se hace hacer '+
    'il lo gli le uno una di della dello degli delle e ed che cosa quale quali come dove quando per da dal su sul sui mia mio miei mie suo sua sono si fa fare '+
    'der die das den dem des ein eine einer einem eines und oder ist sind war waren ich mein meine meinen ihr ihre ihren wie was welche welcher welches wo wann warum auf im am an zu zum zur mit von fur aus hoch kann soll '+
    'de het een en of is zijn was waren ik mijn jouw uw je wat welke hoe waar wanneer waarom op in aan bij voor van naar over kan moet '+
    'o a os as um uma uns umas do da dos das e ou eu meu meus minha minhas seu sua seus suas qual quais como onde quando porque por que em no na nos nas ao aos para com sobre esta sao fazer faz').split(' ');
  var short=['ca','ht','ttc','tva','fec','api','mfa','pdf','csv'];
  function words(s){return aideNorm(s).match(/[\p{L}\p{N}]+/gu)||[];}
  var termes=[];qs.forEach(function(x){words(x).forEach(function(w){if((w.length>2||short.indexOf(w)>=0)&&stop.indexOf(w)<0&&termes.indexOf(w)<0)termes.push(w);});});
  return AIDE_V104.map(function(a,idx){
    var src=a.c+' '+a.t+' '+a.d+' '+a.o,loc=src,titres=[a.t];
    if(veraAppLocale()!=='fr'){try{loc=[a.c,a.t,a.d,a.o].map(function(x){return trText(x);}).join(' ');titres.push(trText(a.t));}catch(e){}}
    var tokens=words(src+' '+loc),index=' '+tokens.join(' ')+' ',titreTokens=words(titres.join(' ')),score=0;
    qs.forEach(function(x){var phr=words(x).join(' ');if(phr&&titres.some(function(t){return words(t).join(' ')===phr;}))score+=200;else if(termes.length&&phr.length>2&&index.indexOf(' '+phr+' ')>=0)score+=100;});
    termes.forEach(function(w){if(tokens.indexOf(w)>=0)score+=(w.length>5?8:4)+(titreTokens.indexOf(w)>=0?8:0);});
    return {a:a,score:score,idx:idx};
  }).filter(function(x){return x.score>0;}).sort(function(a,b){return b.score-a.score||a.idx-b.idx;}).map(function(x){return x.a;});
}
function aideDessiner(){
  var el=document.getElementById('aideBody'); if(!el)return;
  var brut=(document.getElementById('aideQ')||{}).value||'',q=aideNorm(brut),liste=aideTrouver(brut);
  if(!liste.length){
    el.innerHTML='<div class="card help-empty">Aucune réponse pour « '+aideEsc(q)+' ». Essayez « score », « TVA », « salaires », « audit » ou « établissement ».</div>';
    try{if(window.translateDOM)translateDOM(el);}catch(e){} return;
  }
  var ordre=['Démarrer','Saisir sans erreur','Comprendre','Piloter','Confiance & données'],cat='',h='';
  liste=liste.slice().sort(function(a,b){return ordre.indexOf(a.c)-ordre.indexOf(b.c);});
  liste.forEach(function(a){
    if(a.c!==cat){cat=a.c;h+='<div class="help-cat">'+aideEsc(cat)+'</div>';}
    h+='<div class="card help-card"><h3>'+aideEsc(a.t)+'</h3><p>'+aideEsc(a.d)+'</p>'+
      '<div class="where"><b>Où agir :</b> '+aideEsc(a.o)+'</div></div>';
  });
  el.innerHTML=h;
  try{if(window.translateDOM)translateDOM(el);}catch(e){}
}
