function veraIntention(question){var q=String(question||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/’/g,"'");for(var i=0;i<VINT_RULES.length;i++)if(VINT_RULES[i].re.test(q))return VINT_RULES[i];return null;}
function veraReponseRentabilite(){var R=moteur();if(!R||!R.ready){var n=0;try{n=donneesManquantes().length+((R&&R.anomalies)||[]).length;}catch(e){}return {lignes:[vintT('rAbst',{n:Math.max(1,n)})]};}
  var d=R.d,v=R.v,ca=Number(d.ca)||0,res=Number(d.res),L=[],pc1=function(x){return pc(Math.abs(x),1);};
  if(ca>0&&isFinite(res))L.push(vintT(res>=0?'rRes':'rPerte',{v:eur(Math.abs(res)),p:(res<0?'−':'')+pc1(res/ca*100)}));
  var pmE=Number(v.pmEur);if(ca>0&&pmE>0){var m=(ca-pmE)/ca*100;L.push(vintT(m>=0?'rPm':'rPmSous',{v:eur(pmE),m:pc1(m)}));}
  try{var S=piloteMoisEtat(R);if(S&&S.economique&&S.economique.seuilMois>0){/* R236 : absent ≠ zéro — sans journée saisie, Vera ne dit pas « 0 € encaissés » */if(!(Number(S.donnees&&S.donnees.saisis)>0))L.push(vintT('rMoisVide',{s:eur(S.economique.seuilMois)}));else L.push(vintT('rMois',{c:eur(S.donnees.cumul),s:eur(S.economique.seuilMois),p:pc(S.donnees.cumul/S.economique.seuilMois*100,0)}));
    if(S.projection&&S.projection.disponible)L.push(vintT('rProj',{v:eur(S.projection.ca),f:(typeof pilPoint1T==='function'?pilPoint1T(S.confiance.niveau):S.confiance.niveau)}));}}catch(e){}
  L.push(vintT('rNature'));try{if(typeof VERDICT_DEMO_SESSION!=='undefined'&&VERDICT_DEMO_SESSION)L.push(vintT('rDemo'));}catch(e){}return {lignes:L};}
