  if(_vi&&_vi.k==='rentabilite'){var _rt=veraReponseRentabilite();if(_rt){box.innerHTML='<span class="v-answer-k">Vera · réponse fondée sur Verdict</span>'+_rt.lignes.map(function(l,i){return i?'<div class="v-answer-row">'+aideEsc(l)+'</div>':'<b>'+aideEsc(l)+'</b>';}).join('');try{if(window.translateDOM)translateDOM(box);}catch(e){}return;}}
