function veraConsentement(){try{return verdictClientReadAux('vera-online-consent','', 'verdict_vera_consent')==='1';}catch(e){return false;}}
function veraEnregistrerConsentement(){try{lsSet(verdictClientAuxKey('vera-online-consent',''),'1');return true;}catch(e){return false;}}
function veraDemander(ev,reprise){
  if(ev&&ev.preventDefault)ev.preventDefault();
  var q=document.getElementById('aideQ'),question=String(q&&q.value||'').trim(),box=document.getElementById('veraReponse');
  if(!question){if(q)q.focus();return false;}
  aideDessiner();veraReponseLocale(question);
  var c=window.VERDICT_V_CLIENT||{};
  if(c.mode!=='server'||!c.aiEnabled||!c.customerContextAllowed||!VERDICT_ACCOUNT_STATE.auth)return false;
  if(!veraConsentement()&&!reprise){
    try{ask('Activer Vera en ligne ?','Seuls votre question, l’établissement actif et quelques résultats déjà calculés seront envoyés au serveur. Aucun autre établissement ni dossier complet.','J’accepte',function(){veraEnregistrerConsentement();veraDemander(null,true);});}catch(e){}
    return false;
  }
  if(box){box.className='v-answer on loading';box.innerHTML='<span class="v-answer-k">Vera · analyse en cours</span>Je vérifie la réponse avec le contexte autorisé de cet établissement…';}
  fetch(c.apiEndpoint,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'ask',surface:'app',question:question,context:veraSafeContext(),consent:true,csrf:VERDICT_ACCOUNT_STATE.csrf||''})})
    .then(function(r){return r.json().then(function(j){if(!r.ok||!j.ok)throw new Error(j.error||'Vera distante indisponible');return j;});})
    .then(function(j){if(box){box.className='v-answer on';box.innerHTML='<span class="v-answer-k">Vera · réponse contextualisée</span>'+aideEsc(j.reply||'');}})
    .catch(function(){veraReponseLocale(question);try{toast('Vera en ligne est indisponible — réponse locale affichée');}catch(e){}});
  return false;
}
