var MODULES_AVEC_RETOUR=['x','hist','dec','ca','sal','achats','obj','alertes','sante','in','stock','planning','audit'];
var VERDICT_RETOURS_POSES=false;
function poseRetours(){
  if(VERDICT_RETOURS_POSES)return;
  MODULES_AVEC_RETOUR.forEach(function(v){
    var sec=document.getElementById('v-'+v);
    if(!sec||sec.querySelector('.btn-retour'))return;
    var b=document.createElement('button');
    b.className='btn sec btn-retour';
    b.style.marginTop='6px';
    b.textContent=(typeof t==='function')?t('abo.backModules'):'\u2190 Retour aux modules';
    b.onclick=function(){ go('plus'); };
    sec.appendChild(b);
  });
  VERDICT_RETOURS_POSES=true;
}
