var IND_KEYS=["rn","mc","cv","ms","acf","tc","pm","sen","fc","pc","com","prod"];
var IND_SUB={rn:'ind.rn.s',mc:'ind.mc.s',cv:'pctCA',ms:'pctCA',acf:'pctCA',tc:'pctCA',
  pm:'ind.pm.s',sen:'ind.sen.s',fc:'ind.fc.s',pc:'ind.pc.s',com:'pctCA',prod:'ind.prod.s'};
function indList(){ return IND_KEYS.map(function(k){ return [k,t('ind.'+k),t(IND_SUB[k])]; }); }
