  DB.ing.slice().sort(function(a,b){ return a.nom.localeCompare(b.nom,"fr"); }).forEach(function(g){
    var used=DB.plats.filter(function(p){ return (p.rec||[]).some(function(l){ return l[0]===g.nom; }); }).length;
    var alerte=cuOf(g)>0.02&&g.type!=="UNITE"?'<span style="color:var(--orange)"> \u00b7 co\u00fbt \u00e9lev\u00e9</span>':'';
    gh+='<div class="ind" role="button" tabindex="0" onclick="openIng(\''+g.id+'\')" style="cursor:pointer"><div class="n"><b>'+esc(g.nom)+'</b>'+
      '<span>'+g.type+' \u00b7 '+eur2(g.prix)+' HT \u00b7 perte '+fr(g.perte,0)+' %'+alerte+'</span></div>'+
      '<div class="v">'+(g.type==="UNITE"?eur2(cuOf(g))+"/u":fr(cuOf(g)*1000,2)+" \u20ac/kg utile")+'</div>'+
      '<div class="s" style="width:auto;font-size:12.5px;color:var(--mut2)">'+used+' plat'+(used>1?"s":"")+'</div></div>';
  });
  gh+='</div><p class="note">Le co\u00fbt utile int\u00e8gre la perte (\u00e9pluchage, cuisson, parage) : c\u2019est lui qui entre dans les recettes.</p>';
