    var cout=base*(s.qte||0), taux=(s.tva==null?verdictNumberOrDefault(DB.reg.tvac,10):Number(s.tva)), ht=(s.ttc||0)/(1+taux/100);
    var m=ht-cout, mp=ht>0?m/ht*100:0; if(ht>0){mTot+=mp;mN++;}
