  var severity=x.level==='critical'?100:(x.level==='warning'?65:40);
  var _trendEtat=x.trend&&(x.trend.state||x.trend.etat),_trendAdj=(_trendEtat&&W.trend[_trendEtat]!=null)?W.trend[_trendEtat]:1;
  var u=p11UrgencyScore(x.urgency),im=p11ImpactScore(amount,ca),cf=(x.confidence||.7)*100;
  var score=Math.round(_trendAdj*(u*W.urgency+im*W.impact+cf*W.confidence+ease*W.ease+severity*W.severity));
  x.rankFactors={urgence:u,impact:Math.round(im),fiabilite:Math.round(cf),facilite:ease,gravite:severity,tendance:_trendEtat||'inconnu',ajustementTendance:_trendAdj,score:score,version:W.version};
  return Number.isFinite(score)?score:0;
