/* Libellé client (5.18) : jamais un score, une catégorie compréhensible. */
function p11ChangementsPriorite(){
  var A=(DB.audits||[]).filter(function(a){return a&&Array.isArray(a.priorites);});
  if(A.length<2)return [];
  var prev=A[A.length-2],cur=A[A.length-1],pm={},cm={},out=[];
  prev.priorites.forEach(function(x){pm[x.id]=x;});cur.priorites.forEach(function(x){cm[x.id]=x;});
  var fmtE=function(n){return n==null?'non chiffré':eur(n);},jour=function(s){return String(s||'').split('-').reverse().join('/');};
  var methode=(prev.engineVersion&&cur.engineVersion&&prev.engineVersion!==cur.engineVersion)?' (méthode de classement différente : '+prev.engineVersion+' → '+cur.engineVersion+')':'';
  Object.keys(cm).forEach(function(id){var a=pm[id],b=cm[id];
    if(!a){out.push({id:id,type:'apparue',avant:null,apres:b,raison:'Nouvelle priorité : '+b.diag+(b.cat?' ('+b.cat+')':'')+'.'+methode});return;}
    var r=[];
    if(a.cat!==b.cat)r.push('Priorité : '+(a.cat||a.niveau)+' → '+(b.cat||b.niveau));
    if(a.impact!=null&&b.impact!=null&&Math.abs(b.impact-a.impact)>Math.max(1,Math.abs(a.impact))*0.1)r.push('Impact estimé : '+fmtE(a.impact)+' → '+fmtE(b.impact));
    else if((a.impact==null)!==(b.impact==null))r.push('Impact : '+fmtE(a.impact)+' → '+fmtE(b.impact));
    if(a.rangPos!==b.rangPos)r.push('Rang : n°'+a.rangPos+' → n°'+b.rangPos);
    if(r.length)out.push({id:id,type:'modifiee',avant:a,apres:b,raison:r.join(' · ')+methode});
  });
  Object.keys(pm).forEach(function(id){if(!cm[id])out.push({id:id,type:'disparue',avant:pm[id],apres:null,raison:'Ne remonte plus au '+jour(cur.date)+' : « '+pm[id].diag+' » n’est plus au-dessus du repère avec les données actuelles, ou a été traité.'+methode});});
  return out.map(function(o){o.dateAvant=prev.date;o.dateApres=cur.date;o.versionAvant=prev.engineVersion||null;o.versionApres=cur.engineVersion||null;return o;});
}
