      op({id:'STAFF_COST_HIGH',base:'salaires',level:v.ms>ms[2]?'critical':'warning',urgency:v.ms>ms[2]?'today':'week',difficulty:'medium',groups:['activite','salaires'],baseConfidence:.94,trend:_trMs,
        diagnosis:'Le coût humain pèse '+p11Pct(v.ms)+' du chiffre d’affaires',
        detail:'Repère de pilotage Verdict adapté à '+(type||'votre format')+' : vigilance au-dessus de '+p11Pct(ms[1])+'. '+_trMs.detail,
        action:p11StaffAction(type),metric:'Masse salariale / CA et contribution par heure, comparées sur quatre semaines.',
        whyFirst:'L’écart mesuré est de '+p11Pct(exMs)+' au-dessus du repère de votre format.',
        impact:{kind:'scenario_gain',annual:gMs,monthly:Math.round(gMs/12),amount:gMs,assumption:'Simulation Verdict : un tiers de l’écart avec le repère interne de '+p11Pct(ms[1])+' est récupéré par l’organisation. Ce n’est ni une suppression de poste automatique ni un gain garanti.'}});
