      var mcPct=ca>0?d.mc/ca:0,caTarget=mcPct>0?d.cf/(pm[1]/100*mcPct):ca,extra=Math.max(0,caTarget-ca),contrib=Math.round(extra*mcPct),_trPm=p11Trend('pm',pm[1],v.pm);
      op({id:'POINT_MORT_HIGH',base:'resilience',level:v.pm>pm[2]?'critical':'warning',urgency:'week',difficulty:'hard',groups:['activite','achats','salaires','fixes'],baseConfidence:.86,trend:_trPm,causeCertitude:p11CauseCertitude('manquante'),
        diagnosis:'Votre chiffre minimum arrive à '+p11Pct(v.pm)+' du chiffre d’affaires',detail:'Information manquante — Repère de vigilance adapté au format : '+p11Pct(pm[1])+'. '+_trPm.detail,
        action:(type==='Food truck'?'Comparez contribution par emplacement et créneau, puis allégez le premier coût fixe qui ne produit pas de ventes.':'Identifiez le premier poste fixe ou variable qui repousse ce seuil, puis testez une seule correction dans Décisions.'),
        metric:'Point mort / CA et nombre de jours nécessaires pour couvrir les charges.',whyFirst:'Aucun poste isolé ne domine ; c’est leur combinaison qui repousse le seuil de sécurité.',
        impact:{kind:'threshold_gap',annual:0,monthly:0,amount:contrib,assumption:'Montant de contribution supplémentaire nécessaire pour ramener le point mort au repère interne de '+p11Pct(pm[1])+', à taux de contribution inchangé. Ce n’est pas un gain prévu.'}});
