function actBarHTML(cur){
  var T=[['priorities','\u00c0 faire'],['alertes','Alertes'],['dec','Simuler'],['org','Équipe']];
  return '<div class="chips" style="margin-bottom:4px">'+
    T.map(function(x){
      return '<button class="'+(x[0]===cur?'on':'')+'" onclick="go(\''+x[0]+'\')">'+orgTr(x[1])+'</button>';
    }).join('')+'</div>';
}
function actBarInject(v){
  try{
    var sec=document.getElementById('v-'+v); if(!sec)return;
    var old=sec.querySelector('.actbar'); if(old)old.remove();
    var d=document.createElement('div'); d.className='actbar'; d.innerHTML=actBarHTML(v);
    var h1=sec.querySelector('h1'), sub=sec.querySelector('.sub');
    var apres=sub||h1;
    if(apres&&apres.parentNode)apres.parentNode.insertBefore(d, apres.nextSibling);
    else sec.insertBefore(d, sec.firstChild);
  }catch(e){}
}

