function xzone(pts){
  if(pts<4)return {t:"\u00c9cart faible \u2014 carte et comptes concordent",c:"var(--green)"};
  if(pts<8)return {t:"\u00c9cart mod\u00e9r\u00e9 \u2014 \u00e0 expliquer",c:"var(--yellow)"};
  if(pts<12)return {t:"\u00c9cart notable \u2014 investigation recommand\u00e9e",c:"var(--orange)"};
  return {t:"\u00c9cart large \u2014 investigation n\u00e9cessaire avant conclusion",c:"var(--red)"};
}

/* ═══ LE FOOD COST DIT SUR QUOI IL REPOSE (V4.61, étape 6) ═══
   Trois niveaux, jamais mélangés : théorique (fiches) · estimé (achats) ·
   réel (consommation). L'écart carte ↔ comptes ne s'interprète vraiment qu'au
   niveau A. Aucune valeur recalculée ici : tout vient du moteur et de DB.inv. */
function invFoodReel(){
  var N=invNiveau(); if(N.n!=='A'||!N.inv)return null;
  var R=moteur(); if(!R||!R.ready)return null;
  var i=N.inv,A=invAnalyse(i,R);if(!A.ready||!(A.ca.eur>0))return null;
  return {pct:A.fc, conso:A.conso, mois:i.m,ca:A.ca};
}
function fcNiveauHTML(){
  var N=invNiveau(), F=invFoodReel(), R=moteur();
  var h='<div class="card"><div style="display:flex;align-items:center;gap:10px">'+invBarres(N.barres)+
    '<b style="font-size:16.5px">Niveau '+N.n+' \u2014 '+N.lib+'</b></div>'+
    '<p class="au-p" style="margin:8px 0 0">'+N.d+'</p>'+invEchelleHTML()+'';
  if(F&&R&&R.ready){
    var est=R.v.fc, d=F.pct-est;
    h+='<div class="au-card" style="margin-top:12px">'+
      '<div class="autoline"><span class="k">Sur votre consommation</span><b>'+pct(F.pct)+'</b></div>'+
      '<div class="autoline"><span class="k">Sur vos achats</span><b>'+pct(est)+'</b></div>'+
      '<p class="au-p" style="margin:8px 0 0;font-size:14px">'+(Math.abs(d)<1
        ? 'Les deux lectures concordent : vos achats du mois correspondent \u00e0 votre consommation.'
        : (d<0 ? 'Vous avez achet\u00e9 plus que consomm\u00e9 : une partie est partie en stock, pas en assiette.'
               : 'Vous avez consomm\u00e9 plus qu\u2019achet\u00e9 : vous avez puis\u00e9 dans vos r\u00e9serves.'))+'</p></div>';
  } else if(N.n!=='A'){
    h+='<p class="au-p" style="margin:10px 0 0;color:var(--txt)"><b>\u2192</b> Un premier comptage fixe la base ; ensuite, un comptage par mois suffit.</p>'+
       '<button class="btn sec" style="margin-top:10px" onclick="go(\'stock\')">Faire mon comptage</button>';
  }
  return h+'</div>';
}

