function drawX(){
  var R=moteur(), st=carteStats();
  var el=document.getElementById("x-now");
  if(!R.ready||!DB.plats.length){
    el.innerHTML='<div class="warn on">L\&#39;\u00e9cart food cost a besoin de vos chiffres (Saisie) ET de votre carte (plats). '+(R.ready?"Ajoutez vos plats.":"Remplissez la saisie.")+'</div>';
  } else {
    var reel=R.v.fc, theo=st.theoR, pts=reel-theo, xz=xzone(Math.abs(pts));
    var eurAn=Math.round((reel-theo)/100*R.d.ca);
    var h="";

    /* ═══ 1. LE DIAGNOSTIC — la conclusion arrive en premier ═══ */
    var titre, sousTitre, coul;
    if(pts<0){ coul="var(--orange)";
      titre="Vos comptes co\u00fbtent moins cher que votre carte";
      sousTitre="Ce sens d\u2019\u00e9cart peut venir d\u2019une donn\u00e9e manquante, d\u2019un p\u00e9rim\u00e8tre diff\u00e9rent ou d\u2019un stock \u00e0 reprendre. V\u00e9rifiez avant de conclure.";
    } else if(pts<4){ coul="var(--green)";
      titre="Votre carte et vos comptes se rejoignent";
      sousTitre="Ce que vos plats devraient co\u00fbter correspond \u00e0 ce que vous achetez r\u00e9ellement.";
    } else if(pts<8){ coul="var(--yellow)";
      titre="Un \u00e9cart mod\u00e9r\u00e9 entre votre carte et vos comptes";
      sousTitre="Rien d\u2019alarmant, mais une partie de vos achats n\u2019est pas expliqu\u00e9e par vos fiches.";
    } else if(pts<12){ coul="var(--orange)";
      titre="Un \u00e9cart notable entre votre carte et vos comptes";
      sousTitre="Vos achats d\u00e9passent nettement ce que votre carte pr\u00e9voit. Une v\u00e9rification s\u2019impose.";
    } else { coul="var(--red)";
      titre="\u00c9cart majeur entre votre carte et vos comptes";
      sousTitre="Vos achats d\u00e9passent tr\u00e8s largement ce que votre carte pr\u00e9voit. C\u2019est le premier point \u00e0 traiter.";
    }
    h+='<div class="card" style="border-color:'+coul+'55;background:linear-gradient(160deg,'+
      (pts<4&&pts>=0?"rgba(34,197,94,.07)":"rgba(239,68,68,.06)")+',rgba(18,21,25,.9) 62%)">'+
      '<div style="font-family:var(--mono);font-size:12px;letter-spacing:.09em;text-transform:uppercase;color:var(--mut2)">Le diagnostic</div>'+
      '<h3 style="margin-top:7px;font-size:17.5px;line-height:1.3;color:'+coul+'">'+titre+'</h3>'+
      '<p class="sub" style="margin-top:8px">'+sousTitre+'</p>'+
      '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:14px;font-family:var(--mono);font-size:13px">'+
        '<span style="color:var(--mut)">Votre carte pr\u00e9voit</span><b style="color:var(--blue);font-size:19px">'+pc(theo,1)+'</b>'+
        '<span style="color:var(--mut2)">\u2192</span>'+
        '<span style="color:var(--mut)">vos comptes constatent</span><b style="font-size:19px">'+pc(reel,1)+'</b></div>'+
      '<div style="margin-top:9px;font-family:var(--mono);font-size:14px;color:'+coul+'">\u00c9cart : '+
        (pts>=0?"+":"\u2212")+fr(Math.abs(pts),1)+' points de votre chiffre d\u2019affaires</div></div>';

    /* ═══ 2. L'IMPACT — expliqué, jamais présenté comme une perte ═══ */
    if(pts>0){
      h+='<div class="card"><h3>Ce que cela repr\u00e9sente</h3>'+
        '<div style="text-align:center;margin:14px 0 6px"><div style="font-family:var(--mono);font-size:34px;font-weight:800;color:'+coul+'">'+eur(eurAn)+'</div>'+
        '<div style="font-size:12px;color:var(--mut);margin-top:4px">d\u2019achats sur l\u2019ann\u00e9e que votre carte n\u2019explique pas</div></div>'+
        '<div class="warn on" style="margin-top:12px">Ce montant n\u2019est <b>pas une perte constat\u00e9e</b>. C\u2019est la part de vos achats que vos fiches techniques ne justifient pas \u2014 elle demande une v\u00e9rification avant toute conclusion.</div></div>';
    }

    /* ═══ 3. LES CAUSES — ordonnées à partir de ses propres données ═══ */
    var boiPct=R.d.ca>0?R.d.boi/R.d.ca*100:0;
    var causes=[];
    var concorde=(pts>=0 && pts<4);
    if(concorde){
      causes.push(["Ce que montrent vos données","L’écart calculé entre vos fiches et vos achats est faible sur le périmètre actuellement renseigné."]);
      causes.push(["Ce qui mérite de rester à jour","Un changement de fournisseur, un prix d’achat modifié ou une nouvelle carte non saisie peut déplacer cet écart."]);
    }
    else if(pts>=0){
      if(pts>=8) causes.push(["Portions diff\u00e9rentes de vos fiches",
        "Hypoth\u00e8se \u00e0 v\u00e9rifier : un \u00e9cart r\u00e9p\u00e9t\u00e9 entre le grammage r\u00e9el et la fiche peut modifier le co\u00fbt th\u00e9orique."]);
      else causes.push(["Portions l\u00e9g\u00e8rement au-dessus de vos fiches",
        "Hypoth\u00e8se \u00e0 v\u00e9rifier : pesez quelques productions r\u00e9elles et comparez-les aux grammages enregistr\u00e9s."]);
      causes.push(["Pertes, casse et invendus",
        "Tout ce qui est achet\u00e9 puis jet\u00e9 sort des comptes sans jamais passer par une fiche."]);
      causes.push(["Offerts et repas du personnel",
        "Les gestes commerciaux et les repas d\u2019\u00e9quipe consomment de la mati\u00e8re sans g\u00e9n\u00e9rer de vente."]);
      if(boiPct>0) causes.push(["Achats hors carte",
        "Vos boissons repr\u00e9sentent "+pc(boiPct,1)+" du chiffre d\u2019affaires et sont d\u00e9j\u00e0 neutralis\u00e9es dans ce calcul. Restent les achats d\u2019\u00e9picerie, d\u2019entretien ou de mat\u00e9riel s\u2019ils sont pass\u00e9s en mati\u00e8re."]);
      else causes.push(["Achats hors carte",
        "\u00c9picerie, entretien, mat\u00e9riel : s\u2019ils sont compt\u00e9s en mati\u00e8re, ils gonflent le r\u00e9el sans appara\u00eetre dans la carte."]);
      causes.push(["Inventaire imprécis",
        "Un stock de d\u00e9but ou de fin approximatif d\u00e9place l\u2019\u00e9cart d\u2019un mois sur l\u2019autre."]);
      if(DB.plats.length<12) causes.push(["Carte incompl\u00e8te dans Verdict",
        "Vous avez saisi "+DB.plats.length+" plats. Si votre carte en compte davantage, le th\u00e9orique est calcul\u00e9 sur une partie seulement de vos ventes."]);
    } else {
      causes.push(["Achats non saisis ou sous-\u00e9valu\u00e9s","Une facture oubli\u00e9e ou saisie TTC au lieu de HT suffit \u00e0 inverser l\u2019\u00e9cart."]);
      causes.push(["Variation de stock non prise en compte","Un stock de d\u00e9but plus \u00e9lev\u00e9 que le stock de fin r\u00e9duit artificiellement le r\u00e9el."]);
      causes.push(["Fiches techniques trop g\u00e9n\u00e9reuses","Si vos fiches surestiment les quantit\u00e9s, le th\u00e9orique passe au-dessus du r\u00e9el."]);
    }
    h+='<div class="card"><h3>'+(concorde?"Pourquoi \u00e7a tient":"D\u2019o\u00f9 cela peut venir")+'</h3>'+
      '<p class="sub" style="margin:2px 0 12px">'+(concorde?
        "L\u2019\u00e9cart est faible avec les donn\u00e9es actuelles. Voici ce que vous pouvez conserver et surveiller.":
        "Liste de v\u00e9rification pratique, pas classement statistique : Verdict propose o\u00f9 regarder sans attribuer la cause.")+'</p>'+
      causes.map(function(c,i){
        return '<div class="ind" style="align-items:flex-start"><div class="n" style="flex:1"><b>'+(i+1)+'. '+c[0]+'</b><span style="display:block;margin-top:4px;line-height:1.5">'+c[1]+'</span></div></div>';
      }).join("")+'</div>';

    /* ═══ 4. LES PRIORITÉS — il repart avec une action ═══ */
    var actions = concorde ? [
      "Refaites ce contr\u00f4le chaque mois : c\u2019est un \u00e9quilibre qui se perd vite.",
      "Mettez \u00e0 jour vos fiches d\u00e8s qu\u2019un prix fournisseur bouge.",
      "Ajoutez vos nouveaux plats dans Verdict avant de les mettre \u00e0 la carte.",
      "Gardez le m\u00eame rythme d\u2019inventaire : c\u2019est lui qui rend ce chiffre fiable."
    ] : pts>=0 ? [
      "Repesez les 5 plats que vous vendez le plus, en plein service.",
      "Comparez vos achats d\u2019\u00e9picerie et d\u2019entretien : v\u00e9rifiez qu\u2019ils ne sont pas compt\u00e9s en mati\u00e8re.",
      "Notez les pertes et la casse pendant une semaine compl\u00e8te.",
      "Comptez les offerts et les repas du personnel sur le m\u00eame mois.",
      "Refaites un inventaire propre en d\u00e9but et en fin de mois."
    ] : [
      "V\u00e9rifiez qu\u2019aucune facture d\u2019achat ne manque sur la p\u00e9riode.",
      "Contr\u00f4lez que vos achats sont saisis hors taxes, pas TTC.",
      "Reprenez vos stocks de d\u00e9but et de fin de p\u00e9riode.",
      "Relisez les quantit\u00e9s de vos fiches techniques les plus vendues."
    ];
    h+='<div class="card" style="border-color:rgba(34,197,94,.28)"><h3>'+(concorde?"Pour que \u00e7a dure":"Commencez par l\u00e0")+'</h3>'+
      '<p class="sub" style="margin:2px 0 12px">'+(concorde?
        "Aucune anomalie n\u2019est d\u00e9duite de cet \u00e9cart seul. Ces contr\u00f4les vous aident \u00e0 garder des donn\u00e9es comparables.":
        "Commencez par les contr\u00f4les les plus simples ; si l\u2019\u00e9cart reste, poursuivez la liste.")+'</p>'+
      actions.map(function(a,i){
        return '<div style="display:flex;gap:11px;align-items:flex-start;padding:9px 0;border-bottom:1px solid var(--line)">'+
          '<b style="font-family:var(--mono);color:var(--green);font-size:14px;min-width:18px">'+(i+1)+'</b>'+
          '<span style="font-size:13.5px;line-height:1.5">'+a+'</span></div>';
      }).join("")+
      '<p class="note" style="margin-top:12px">'+(concorde?
        "Le suivi mensuel, juste \u00e0 c\u00f4t\u00e9, vous dira imm\u00e9diatement si cet \u00e9quilibre se d\u00e9grade.":
        "Une fois ces points v\u00e9rifi\u00e9s, reprenez cet \u00e9cran : si l\u2019\u00e9cart n\u2019a pas boug\u00e9, c\u2019est que la cause est ailleurs.")+'</p></div>';

    /* ═══ 5. CE QUI A SERVI AU DIAGNOSTIC — pas de score de confiance inventé ═══ */
    h+='<div class="card"><h3>Ce que Verdict a utilis\u00e9</h3>'+
      '<div class="autoline"><span class="k">Vos fiches techniques</span><b>'+DB.plats.length+' plats</b></div>'+
      '<div class="autoline"><span class="k">Vos achats mati\u00e8re</span><b>'+eur(R.d.nour)+' / an</b></div>'+
      '<div class="autoline"><span class="k">Votre chiffre d\u2019affaires</span><b>'+eur(R.d.ca)+' / an</b></div>'+
      '<div class="autoline"><span class="k">Vos boissons</span><b>'+eur(R.d.boi)+' \u2014 neutralis\u00e9es</b></div>'+
      '<p class="note" style="margin-top:10px">Les boissons sont retir\u00e9es des deux c\u00f4t\u00e9s du calcul : elles ne peuvent pas cr\u00e9er d\u2019\u00e9cart artificiel. '+
      (DB.plats.length<12?'Votre carte compte '+DB.plats.length+' plats dans Verdict : plus elle est compl\u00e8te, plus le th\u00e9orique est fiable.':'Plus votre carte est \u00e0 jour, plus le th\u00e9orique est fiable.')+'</p></div>';

    /* ═══ 6. LA PHRASE QUI PROTÈGE ═══ */
    h+='<p class="note" style="margin-top:14px;padding:11px 13px;border-left:2px solid var(--line)">Verdict ne conclut jamais \u00e0 une perte, \u00e0 une erreur ni \u00e0 une fraude. Il mesure un \u00e9cart entre deux lectures et vous indique o\u00f9 chercher. L\u2019explication vous appartient.</p>';

    el.innerHTML=h;
  }
  /* ─ Suivi mensuel ─ */
  var m=document.getElementById("x-mois");
  var theoRef=DB.plats.length?carteStats().theoR:null;
  var mh='<div class="card"><h3>\ud83d\udcc5 Suivi mensuel du food cost <span class="r">r\u00e9f. carte '+(theoRef!=null?pc(theoRef,1):"\u2014")+'</span></h3>'+
    '<p class="sub" style="margin-bottom:10px">Chaque mois : CA HT, achats mati\u00e8re, stock d\u00e9but, stock fin. Le food cost r\u00e9el du mois = (achats + stock d\u00e9but \u2212 stock fin) \u00f7 CA.</p>'+
    '<div class="tscroll"><table class="tt"><tr><th>Mois</th><th>CA HT</th><th>Achats</th><th>Stock d.</th><th>Stock f.</th><th>FC r\u00e9el</th><th>\u00c9cart</th><th></th></tr>';
  var cumEur=0,nMois=0,sumFc=0;
  DB.suivi.forEach(function(r,i){
    var fcm=null,ec=null,sig="\u23f3";
    if(r.ca>0&&r.ach!=null){
      var conso=r.ach+(r.sd||0)-(r.sf||0);
      fcm=conso/r.ca*100;
      if(theoRef!=null){ ec=fcm-theoRef; cumEur+=ec/100*r.ca;
        sig=ec<2?"\ud83d\udfe2":(ec<5?"\ud83d\udfe1":(ec<8?"\ud83d\udfe0":"\ud83d\udd34")); }
      nMois++; sumFc+=fcm;
    }
    function inp(k,v){ return '<input inputmode="decimal" value="'+(v!=null?String(v).replace(".",","):"")+'" onchange="suiviSet('+i+',\''+k+'\',this)">'; }
    mh+='<tr><td>'+r.m+'</td><td>'+inp("ca",r.ca)+'</td><td>'+inp("ach",r.ach)+'</td><td>'+inp("sd",r.sd)+'</td><td>'+inp("sf",r.sf)+'</td>'+
      '<td>'+(fcm!=null?pc(fcm,1):"\u2014")+'</td><td>'+(ec!=null?(ec>=0?"+":"")+fr(ec,1)+" pt":"\u2014")+'</td><td>'+sig+'</td></tr>';
  });
  mh+='</table></div>';
  if(nMois)mh+='<div class="autoline" style="margin-top:8px"><span class="k">Moyenne des mois saisissez</span><b>'+pc(sumFc/nMois,1)+'</b></div>'+
    '<div class="autoline"><span class="k">\u00c9cart cumul\u00e9 estim\u00e9 vs carte</span><b style="color:'+(cumEur>0?"var(--orange)":"var(--green)")+'">'+eur(cumEur)+'</b></div>';
  mh+='<p class="note">Stock d\u00e9but / fin : vos inventaires. Un mois vide ne casse rien \u2014 saisissez quand vous pouvez.</p></div>';
  m.innerHTML=mh;
}
function suiviSet(i,k,el){
  var v=num(el.value);
  if(el.value!==""&&(v==null||v<0)){ el.style.borderColor="var(--red)"; toast("Nombre positif attendu"); return; }
  el.style.borderColor="";
  DB.suivi[i][k]=(el.value===""?null:v);
  save();
  clearTimeout(suiviSet._t);
  suiviSet._t=setTimeout(function(){ if(VIEW==="x")drawX(); },250);
}
/* ═══ PILOTE QUOTIDIEN → ACCUEIL ═══ */
/* ═══ RAPPELS ═══
   1. Dans l'application : à l'ouverture, ce qui n'est pas fait.
   2. Dans le calendrier du client : un rendez-vous récurrent sur SON téléphone,
      qui fonctionne même s'il n'ouvre pas Verdict pendant deux mois.
   Une vraie notification poussée exige un serveur et l'application installée
   sur l'écran d'accueil : tant que le serveur n'existe pas, on ne promet rien. */
/* Première année où le client a utilisé Verdict : on la déduit de ses données,
   jamais d'une supposition. Sert à ne pas lui réclamer une année qu'il n'a pas
   vécue dans l'application. */
/* Nom du mois dans la langue de l'application. On s'appuie sur le navigateur :
   pas de liste à maintenir dans sept langues. */
function moisTraduit(i){
  try{
    var d=new Date(2000, i, 1);
    var n=d.toLocaleDateString((typeof LOCALE!=='undefined'?LOCALE:'fr'), {month:'long'});
    return n.charAt(0).toUpperCase()+n.slice(1);
  }catch(e){ return (typeof MOIS_N!=='undefined'&&MOIS_N[i])?MOIS_N[i]:String(i+1); }
}
function anneeDebut(){
  var an=new Date().getFullYear(), mini=an;
  try{
    if(DB.debutAn) mini=Math.min(mini, DB.debutAn);
    (DB.carnet||[]).forEach(function(r){ if(r.an<mini) mini=r.an; });
    (DB.histJour||[]).forEach(function(x){
      var d=x.d||x.date; if(d){ var y=parseInt(String(d).slice(0,4),10); if(y&&y<mini) mini=y; }
    });
  }catch(e){}
  return mini;
}
function rappels(){
  var out=[], au=new Date(), an=au.getFullYear(), mois=au.getMonth(), jour=au.getDate();
  var R=null; try{ R=moteur(); }catch(e){}
  if(!R || !R.ready){
    return [{cle:"saisie",urg:2,vue:"in",titre:t("rap.saisie.t"),txt:t("rap.saisie.d"),btn:t("rap.saisie.b")}];
  }
  /* Figer une année n'a de sens qu'à la fin de cet exercice, et seulement si
     le client utilisait déjà Verdict pendant cette année-là. On ne demande
     jamais de figer une année non terminée, ni une année d'avant l'inscription. */
  var fige={}; (DB.carnet||[]).forEach(function(r){ fige[r.an]=1; });
  var debut=anneeDebut();
  if(mois===11 && !fige[an] && debut<=an){
    /* décembre : l'exercice se termine, c'est le moment de le figer */
    out.push({cle:"carnet",urg:1,vue:"data",titre:t("rap.carnet.t").replace("{an}",an),
              txt:t("rap.carnet.d").replace("{an}",an),btn:t("rap.carnet.b")});
  } else if(mois<=2 && !fige[an-1] && debut<=an-1){
    /* janvier à mars : l'exercice précédent est clos et pas encore figé */
    out.push({cle:"carnet",urg:1,vue:"data",titre:t("rap.carnetClos.t").replace("{an}",an-1),
              txt:t("rap.carnetClos.d").replace("{an}",an-1),btn:t("rap.carnet.b")});
  }
  /* Le mois précédent n'est pas renseigné dans le Suivi mensuel du food cost.
     C'est le rappel le plus utile : c'est lui qui construit l'historique et
     alimente le croisement carte / comptes. */
  try{
    var mp = mois===0 ? 11 : mois-1;          /* le mois qui vient de s'écouler */
    var sv = (DB.suivi||[])[mp];
    if(sv && (sv.ca==null || sv.ach==null) && jour>=3){
      var nomMois=moisTraduit(mp);
      out.push({cle:"mois",urg:1,vue:"x",titre:t("rap.mois.t").replace("{m}",nomMois),
                txt:t("rap.mois.d").replace("{m}",nomMois.toLowerCase()),btn:t("rap.mois.b")});
    }
  }catch(e){}
  var hj=DB.histJour||[], dj=au.toISOString().slice(0,10);
  var moisActif=true,jourOuvert=true;
  try{var a4=point4MonthActivity(R,joursMois());moisActif=a4.active===true;jourOuvert=!estFerme(jour);}catch(e){}
  var exploitation=!(typeof projetOuvert==='function')||projetOuvert();
  if(exploitation&&moisActif&&jourOuvert&&!hj.some(function(x){ return (x.d||x.date)===dj; })){
    out.push({cle:"pilote",urg:0,vue:"pil",titre:t("rap.pilote.t"),txt:t("rap.pilote.d"),btn:t("rap.pilote.b")});
  }
  if(!DB.plats || DB.plats.length<3){
    out.push({cle:"carte",urg:1,vue:"carte",titre:t("rap.carte.t"),txt:t("rap.carte.d"),btn:t("rap.carte.b")});
  }
  /* Une fois l'exercice suivant clos, la référence mérite d'être refaite :
     c'est le moment où le comptable transmet les comptes annuels. */
  try{
    if(DB.ref&&DB.ref.date){
      var dRef=new Date(DB.ref.date), moisEcoules=(au.getFullYear()-dRef.getFullYear())*12+(au.getMonth()-dRef.getMonth());
      if(moisEcoules>=13){
        out.push({cle:"ref",urg:1,vue:"in",titre:"Votre r\u00e9f\u00e9rence date de plus d\u2019un an",
          txt:"Un nouvel exercice est clos. Reprenez les postes du dernier compte de r\u00e9sultat : tout se recalcule ensuite \u2014 objectifs, point mort, projections.",
          btn:"Mettre \u00e0 jour ma r\u00e9f\u00e9rence"});
      }
    }
  }catch(e){}
  out.sort(function(a,b){ return b.urg-a.urg; });
  return out;
}
function focusGuide(el){
  if(!el)return;
  el.scrollIntoView({behavior:'smooth',block:'center'});
  /* C33 : go() replace la page en haut juste après ; si la cible n'est plus à l'écran une fois la vue posée, on la recentre. */
  var _fgReplacer=function(){try{var r=el.getBoundingClientRect();if(r.top<0||r.bottom>window.innerHeight)el.scrollIntoView({behavior:'auto',block:'center'});}catch(e){}};
  setTimeout(_fgReplacer,360);setTimeout(_fgReplacer,900);
  try{ el.focus({preventScroll:true}); }catch(e){ try{el.focus();}catch(_){} }
  el.classList.remove('gpulse'); void el.offsetWidth; el.classList.add('gpulse');
  setTimeout(function(){ el.classList.remove('gpulse'); },2200);
}
function goIn(id){
  go('in');
  focusGuide(document.getElementById(id));
}
function goRap(cle,vue){
  if(cle==='ref'){ go('in'); openRef(); return; }
  go(vue);
  if(cle==='pilote'){ focusGuide(document.getElementById('point4-month')||document.getElementById('pl-ca')); }
  else if(cle==='saisie'){ focusGuide(document.getElementById('i-panier')); }
  else if(cle==='carnet'){
    var bc=document.querySelector('[onclick*="dsub(\'carnet\'"]'); if(bc)bc.click();
    focusGuide(document.getElementById('d-carnet'));
  }
  else if(cle==='mois'){
    var bx=document.querySelector('[onclick*="xsub(\'mois\'"]'); if(bx)bx.click();
    var au=new Date(),mp=au.getMonth()===0?11:au.getMonth()-1;
    focusGuide(document.querySelector('input[onchange="suiviSet('+mp+',\'ca\',this)"]'));
  }
  else if(cle==='carte'){
    if(!DB.plats||!DB.plats.length){ try{ openPlat(); }catch(e){} }
    else{ focusGuide(document.querySelector('#v-carte .btn[onclick="openPlat()"]')); }
  }
}
function blocRappels(){
  var L=rappels(); if(!L.length) return "";
  var r=L[0], c=r.urg>=2?"var(--orange)":(r.urg===1?"var(--yellow)":"var(--green)");
  return '<div class="card" style="border-left:3px solid '+c+'">'+
    '<div style="font-family:var(--mono);font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:var(--mut2)">'+t("rap.eyebrow")+'</div>'+
    '<b style="display:block;margin-top:7px;font-size:15.5px">'+r.titre+'</b>'+
    '<p class="sub" style="margin:7px 0 12px;line-height:1.55">'+r.txt+'</p>'+
    '<button type="button" class="btn sec" onclick="goRap(\''+r.cle+'\',\''+r.vue+'\')">'+r.btn+'</button>'+
    (L.length>1?'<p class="note" style="margin-top:10px">'+t("rap.autres").replace("{n}",L.length-1)+'</p>':'')+'</div>';
}
function icsEch(x){ return String(x).replace(/([,;\\])/g,'\\$1').replace(/\n/g,'\\n'); }
function icsD(d){
  return d.getUTCFullYear()+String(d.getUTCMonth()+1).padStart(2,'0')+String(d.getUTCDate()).padStart(2,'0')+
    'T'+String(d.getUTCHours()).padStart(2,'0')+String(d.getUTCMinutes()).padStart(2,'0')+'00Z';
}
function creerRappelCalendrier(type){
  var au=new Date(), deb, titre, desc, regle;
  if(type==='mois'){
    deb=new Date(au.getFullYear(),au.getMonth()+1,5,9,0,0);
    titre=t("cal.mois.t"); desc=t("cal.mois.d"); regle='RRULE:FREQ=MONTHLY;BYMONTHDAY=5';
  } else if(type==='semaine'){
    var j=au.getDay(), delta=(1-j+7)%7||7;
    deb=new Date(au.getFullYear(),au.getMonth(),au.getDate()+delta,9,0,0);
    titre=t("cal.semaine.t"); desc=t("cal.semaine.d"); regle='RRULE:FREQ=WEEKLY;BYDAY=MO';
  } else {
    deb=new Date(au.getFullYear()+1,0,15,9,0,0);
    titre=t("cal.annee.t"); desc=t("cal.annee.d"); regle='RRULE:FREQ=YEARLY;BYMONTH=1;BYMONTHDAY=15';
  }
  var fin=new Date(deb.getTime()+30*60000);
  var ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Verdict//FR','CALSCALE:GREGORIAN','METHOD:PUBLISH',
    'BEGIN:VEVENT','UID:verdict-'+type+'-'+Date.now()+'@verdictchr.fr','DTSTAMP:'+icsD(new Date()),
    'DTSTART:'+icsD(deb),'DTEND:'+icsD(fin),regle,'SUMMARY:'+icsEch(titre),'DESCRIPTION:'+icsEch(desc),
    'BEGIN:VALARM','TRIGGER:-PT15M','ACTION:DISPLAY','DESCRIPTION:'+icsEch(titre),'END:VALARM',
    'END:VEVENT','END:VCALENDAR'].join('\r\n');
  try{
    var b=new Blob([ics],{type:'text/calendar;charset=utf-8'});
    var u=URL.createObjectURL(b), a=document.createElement('a');
    a.href=u; a.download='verdict-rappel-'+type+'.ics';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(u); },4000);
    toast(t("cal.ok"));
  }catch(e){ toast(t("cal.ko")); }
}
function blocCalendrier(){
  return '<div class="card"><h3>\uD83D\uDD14 '+t("cal.t")+'</h3>'+
    '<p class="sub" style="margin:2px 0 12px;line-height:1.55">'+t("cal.d")+'</p>'+
    '<div style="display:flex;gap:8px;flex-wrap:wrap">'+
      '<button type="button" class="btn sec" onclick="creerRappelCalendrier(\'semaine\')">'+t("cal.b.semaine")+'</button>'+
      '<button type="button" class="btn sec" onclick="creerRappelCalendrier(\'mois\')">'+t("cal.b.mois")+'</button>'+
      '<button type="button" class="btn sec" onclick="creerRappelCalendrier(\'annee\')">'+t("cal.b.annee")+'</button>'+
    '</div><p class="note" style="margin-top:11px">'+t("cal.note")+'</p></div>';
}


/* ═══ PROGRESSION DU MOIS — l'écran d'accueil se lit en 2 secondes (V4.28) ═══
   Une barre par jour du mois, une ligne d'objectif, une phrase. Rien d'autre.
   Les points du jour sont stockés en CUMUL depuis le 1er : la barre d'un jour
   est donc l'écart entre deux relevés. Si des jours séparent deux saisies,
   l'écart est réparti sur les jours couverts et la barre est marquée estimée. */
function progObjJour(R){var op=verdictOperationalClock(),open=0;for(var j=1;j<=new Date(op.year,op.monthIndex+1,0).getDate();j++)if(!estFerme(j))open++;return VerdictFinance.monthlyTargets(R.d,open);}
function progJours(){
  var op=verdictOperationalClock(),pref=op.key.slice(0,7);
  var cum={};
  (DB.histJour||[]).forEach(function(r){
    if(!r||!r.date||r.ca==null)return;
    if(String(r.date).indexOf(pref)!==0||!window.VerdictServiceDay.observed(r,op))return;
    cum[parseInt(String(r.date).slice(8),10)]=r.ca;
  });
  // Le récapitulatif pil n'est pas daté : seuls les relevés datés font foi.
  var exact=joursMois();
  var ks=Object.keys(cum).map(Number).sort(function(a,b){return a-b;});
  var jours={}, prevJ=0, prevC=0;
  ks.forEach(function(j){
    var span=Math.max(1,j-prevJ), delta=cum[j]-prevC;
    if(delta<0)delta=0;
    for(var k=prevJ+1;k<=j;k++)jours[k]=(exact[k]?{v:exact[k].ca,est:exact[k].est}:{v:delta/span,est:span>1});
    prevJ=j; prevC=cum[j];
  });
  return {jours:jours, dernierJour:prevJ, cumul:prevC};
}
function blocProgression(R){
  var o=progObjJour(R); if(!o)return '';
  var P=progJours(),S=piloteMoisEtat(R),op=verdictOperationalClock(),nbJ=new Date(op.year,op.month,0).getDate(),auj=op.day;
  var seuilJour=S&&S.economique?S.economique.seuilJour:o.obj;
  var vals=[]; for(var k in P.jours)vals.push(P.jours[k].v);
  var mx=Math.max(seuilJour, vals.length?Math.max.apply(null,vals):0)*1.18||1;
  var W=nbJ*10, H=100, base=H-14, hUtile=base-10;
  var yObj=base-(seuilJour/mx)*hUtile;
  var s='<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" style="width:100%;height:104px;display:block">';
  for(var j=1;j<=nbJ;j++){
    var x=(j-1)*10+2.2, bw=5.6, e=P.jours[j];
    if(e&&e.v!=null){
      var hb=Math.max(2,(e.v/mx)*hUtile), objectifJour=null, apiCouleur=window.VerdictPerformanceIntegrated;
      try{ objectifJour=typeof verdictPerformanceDayTarget==='function'?verdictPerformanceDayTarget(j):null; }catch(_){ objectifJour=null; }
      var statutJour=apiCouleur&&typeof apiCouleur.statusFor==='function'?apiCouleur.statusFor(e.v,objectifJour):'neutral';
      var col=apiCouleur&&typeof apiCouleur.statusColor==='function'?apiCouleur.statusColor(statutJour):'#64748b';
      s+='<rect x="'+x+'" y="'+(base-hb)+'" width="'+bw+'" height="'+hb+'" rx="1.6" fill="'+col+'" opacity="'+(e.est?0.55:1)+'"/>';
    } else {
      var gris=(j<=auj)?'#232830':'#171b21';
      s+='<rect x="'+x+'" y="'+(base-3)+'" width="'+bw+'" height="3" rx="1.4" fill="'+gris+'"/>';
    }
  }
  s+='<line x1="0" y1="'+yObj+'" x2="'+W+'" y2="'+yObj+'" stroke="#8a93a0" stroke-width="0.8" stroke-dasharray="3 3" opacity=".85"/>';
  s+='<line x1="0" y1="'+base+'" x2="'+W+'" y2="'+base+'" stroke="#1d232b" stroke-width="1"/>';
  s+='</svg>';
  /* repères de jours, en dehors du SVG pour rester lisibles */
  var rep='<div style="display:flex;justify-content:space-between;font-family:var(--mono);font-size:11px;color:var(--mut2);margin-top:3px">'+
    '<span>1</span><span>'+Math.round(nbJ/4)+'</span><span>'+Math.round(nbJ/2)+'</span><span>'+Math.round(nbJ*3/4)+'</span><span>'+nbJ+'</span></div>';
  /* la phrase : avance ou retard, sur le cumul réel face au cumul attendu */
  var phrase, coul='#8a93a0';
  if(S&&S.projection.disponible){var etatProjection=projectionEtatVisuel(S);coul=etatProjection.color;
    phrase='Projection '+eur(S.projection.ca)+' · '+etatProjection.summary;}
  else if(S&&S.donnees.saisis>=3&&!S.calendrier.exact)phrase=pilPoint1T('waitSchedule');
  else if(S&&S.donnees.saisis>=3&&S.donnees.manquants>0)phrase=pilPoint1T('waitMissing');
  else phrase=pilPoint1T('needDays');
  return '<div class="card prog" role="button" tabindex="0" onclick="goRap(\'pilote\',\'pil\')" style="cursor:pointer">'+
    '<h3 style="margin-bottom:2px">Progression du mois</h3>'+
    '<p class="note" style="margin:0 0 10px">Couleur de chaque barre = chiffre encaiss\u00e9 face \u00e0 l\u2019objectif propre du jour \u00b7 ligne pointill\u00e9e neutre = moyenne structurelle ('+eur(seuilJour)+'/jour ouvert). Le rythme restant est recalcul\u00e9 dans « Piloter mon mois ».</p>'+
    s+rep+
    '<div style="display:flex;align-items:center;gap:8px;margin-top:12px">'+
      '<i style="width:9px;height:9px;border-radius:50%;background:'+coul+';flex:none;box-shadow:0 0 8px '+coul+'"></i>'+
      '<b style="font-size:14px;color:'+coul+'">'+phrase+'</b></div>'+
    '</div>';
}


/* ═══════════ SAISIE DU JOUR — modèle « CA de la journée » (V4.29) ═══════════
   Avant : le client saisissait le CA CUMULÉ depuis le 1er. Deux défauts —
   il devait faire une addition de tête, et un jour sauté rendait les barres
   approximatives. Désormais il saisit le CA DE LA JOURNÉE ; le cumul (dont
   dépendent le Pilote et tout l'historique) est recalculé par l'application.
   Les relevés déjà enregistrés en cumul restent lisibles : leur valeur
   journalière est déduite par écart, et signalée comme estimée. */
/* Horloge d'exploitation unique : avant l'heure de fin de service, la journée
   appartient encore à la veille. Toute la saisie, le calendrier et les courbes
   lisent cette même source afin d'éviter une bascule incohérente à minuit. */
function verdictOperationalClock(value){
  return window.VerdictServiceDay.clock(value,typeof DB==='object'?DB:null);
}
window.verdictOperationalClock=verdictOperationalClock;
/* R130 → R131 · Couleur intelligente d'une rupture signalée (Accueil + notification du gérant).
   Une seule règle, lue partout. Date CIVILE du fuseau de l'établissement (la journée finit à minuit).
   Elle croise la date de besoin et l'état du réapprovisionnement :
                    | livraison confirmée | commande passée | rien / préparée
     date passée    |        rouge        |      rouge      |     rouge
     aujourd'hui    |        orange       |      orange     |     rouge
     demain         |        jaune        |      jaune      |     orange
     dans 2 jours   |        vert         |      vert       |     orange
     3 jours et +   |        vert         |      vert       |     jaune
   Livraison prévue après le besoin, ou heure limite passée sans commande : rouge si besoin
   aujourd'hui ou demain, orange sinon. Sans date de besoin : « Date à préciser », orange si rien
   n'est commandé, jaune sinon ; aucune date n'est inventée. */
function verdictCleCivile(d,tz){try{return new Intl.DateTimeFormat('en-CA',{timeZone:tz||undefined,year:'numeric',month:'2-digit',day:'2-digit'}).format(d);}catch(e){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}}
function verdictUrgenceRupture(info,now){
  info=info||{};now=now instanceof Date?now:new Date(now==null?Date.now():now);
  var tz=info.tz||(function(){try{return verdictOperationalClock().timeZone;}catch(e){return undefined;}})();
  function inst(v){if(!v)return null;var t=Date.parse(String(v));return isFinite(t)?new Date(t):null;}
  var jour=verdictCleCivile(now,tz),besoin=String(info.besoin||'').slice(0,10),liv=inst(info.livraison),lim=inst(info.limite),cmd=String(info.etatCommande||'').toLowerCase();
  var dateOk=/^\d{4}-\d{2}-\d{2}$/.test(besoin)&&isFinite(Date.parse(besoin+'T12:00:00Z'));
  var tardive=!!(liv&&dateOk&&verdictCleCivile(liv,tz)>besoin);
  var appro=tardive?'rien':((liv&&info.verifie)||/^(confirmed|confirmee|partial|received)$/.test(cmd))?'confirmee':(liv||/^(sent|envoyee|planned|ordered)$/.test(cmd))?'envoyee':'rien';
  var limPassee=!!(lim&&appro==='rien'&&!tardive&&now.getTime()>lim.getTime());
  var r={etat:'orange',cause:'sansDate',appro:appro,jours:null,aujourdhui:jour,besoin:null,livraison:liv?liv.toISOString():null,limite:lim&&appro==='rien'?lim.toISOString():null,tz:tz};
  if(!dateOk){r.etat=appro==='rien'?'orange':'jaune';return r;}
  r.besoin=besoin;r.jours=Math.round((Date.parse(besoin+'T12:00:00Z')-Date.parse(jour+'T12:00:00Z'))/864e5);
  if(r.jours<0){r.etat='rouge';r.cause='depassee';return r;}
  if(tardive||limPassee){r.etat=r.jours<=1?'rouge':'orange';r.cause=tardive?'livraisonTardive':'limitePassee';return r;}
  r.cause=r.jours===0?'aujourdhui':r.jours===1?'demain':'dans';
  if(appro==='rien')r.etat=r.jours===0?'rouge':r.jours<=2?'orange':'jaune';
  else r.etat=r.jours===0?'orange':r.jours===1?'jaune':'vert';
  return r;
}
