function verdictUrgenceRuptureTexte(u,info,loc){
  u=u||verdictUrgenceRupture(info);info=info||{};
  loc=String(loc||(typeof LOCALE!=='undefined'&&LOCALE)||'fr').slice(0,2).toLowerCase();
  var T=VERDICT_RUPTURE_TX[loc]||VERDICT_RUPTURE_TX.fr,tag=T._tag;
  function f(s,v){return String(s||'').replace(/\{(\w+)\}/g,function(m,k){return v[k]!=null?v[k]:'';});}
  function jourTxt(k){try{return new Date(k+'T12:00:00Z').toLocaleDateString(tag,{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'});}catch(e){return k;}}
  function instTxt(iso){try{return new Date(iso).toLocaleString(tag,{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:u.tz||undefined});}catch(e){return iso;}}
  var v={n:u.jours,d:u.besoin?jourTxt(u.besoin):'',l:u.livraison?instTxt(u.livraison):'',c:u.limite?instTxt(u.limite):'',a:String(info.acteur||'')};
  var phrase=[];if(v.a)phrase.push(f(T.signale,v));phrase.push(f(T['p_'+u.cause],v));
  if(u.cause!=='livraisonTardive'&&u.cause!=='limitePassee'){
    if(u.appro==='confirmee')phrase.push(f(v.l?T.a_confirmeeL:T.a_confirmee,v));
    else if(u.appro==='envoyee')phrase.push(f(v.l?T.a_envoyeeL:T.a_envoyee,v));
    else{phrase.push(f(T.a_rien,v));if(u.limite)phrase.push(f(T.limiteAvant,v));}
  }
  return {chip:f(T['c_'+u.cause],v),phrase:phrase.join(' ')};
}
window.verdictUrgenceRupture=verdictUrgenceRupture;window.verdictUrgenceRuptureTexte=verdictUrgenceRuptureTexte;window.verdictCleCivile=verdictCleCivile;
function verdictTrackingStartKey(){
  var configured=String(DB&&DB.performanceTrackingStartedAt||'').slice(0,10);if(/^\d{4}-\d{2}-\d{2}$/.test(configured))return configured;
  var dates=(DB&&DB.histJour||[]).map(function(row){return row&&String(row.date||'').slice(0,10);}).filter(function(key){return /^\d{4}-\d{2}-\d{2}$/.test(key);}).sort();
  return dates[0]||verdictOperationalClock().key;
}
function jourCle(j){var op=verdictOperationalClock();return op.key.slice(0,8)+String(j).padStart(2,'0');}
function moisPrefixe(){return verdictOperationalClock().key.slice(0,7);}
/* Carte des jours du mois en cours : valeur du jour, tickets, et si elle est
   déduite d'un ancien relevé cumulé. Source unique pour tout l'écran. */
function joursMois(){
  var op=verdictOperationalClock(),pref=op.key.slice(0,7),lignes=[];
  (DB.histJour||[]).forEach(function(r){
    if(r&&r.date&&String(r.date).indexOf(pref)===0&&window.VerdictServiceDay.observed(r,op))lignes.push(r);
  });
  lignes.sort(function(a,b){ return a.date<b.date?-1:1; });
  var out={}, prevJ=0, prevCum=0, prevTk=0;
  lignes.forEach(function(r){
    var j=parseInt(String(r.date).slice(8),10);
    if(r.caJ!=null){
      out[j]={ca:r.caJ, tk:(r.tkJ!=null?r.tkJ:null), est:false};
      prevCum=(r.ca!=null?r.ca:prevCum+r.caJ);
    } else if(r.ca!=null){
      var span=Math.max(1,j-prevJ), delta=Math.max(0,r.ca-prevCum);
      var dtk=(r.tickets!=null)?Math.max(0,r.tickets-(prevTk||0)):null;
      for(var k=prevJ+1;k<=j;k++)out[k]={ca:delta/span, tk:(dtk!=null?dtk/span:null), est:span>1};
      if(r.tickets!=null)prevTk=r.tickets;
      prevCum=r.ca;
    }
    prevJ=j;
  });
  return out;
}
function cumulJusqua(j,jours){
  var J=jours||joursMois(), s=0;
  for(var k in J){ if(Number(k)<=j && J[k].ca)s+=J[k].ca; }
  return s;
}
function cumulTkJusqua(j,jours){
  var J=jours||joursMois(), s=0, vu=false;
  for(var k in J){ if(Number(k)<=j && J[k].tk!=null){ s+=J[k].tk; vu=true; } }
  return vu?s:null;
}
