function point4T(k){var l=(typeof LOCALE==='string'?LOCALE:'fr'),D=PIL_POINT4_TEXT[l]||PIL_POINT4_TEXT.fr,E=PIL_POINT4_EDGE[l]||PIL_POINT4_EDGE.fr;return D[k]||E[k]||PIL_POINT4_TEXT.fr[k]||PIL_POINT4_EDGE.fr[k]||k;}
