function v10140Text(){return V10140_TEXT[typeof LOCALE==='string'?LOCALE:'fr']||V10140_TEXT.fr;}
function v10140Fill(text,values){return String(text||'').replace(/\{([a-z]+)\}/g,function(_,key){return values&&values[key]!=null?values[key]:'';});}
/* V44.42 — porte FEC : le client qui possède son fichier comptable ne saisit rien.
   La feuille se ferme, Mes chiffres s'ouvre sur le bloc FEC, le consentement
   reçoit le focus. L'onboarding est marqué fait par l'import lui-même. */
function choisirFEC(){
  verdictEntrySelected();
  try{ verdictDemoResumeWrite(false); }catch(e){}
  try{ setMode('existing'); }catch(e){}
  try{ if(DB){ DB.onboardingDone=false; save(); } }catch(e){}
  try{ refClose(); }catch(e){}
  try{ go('in'); }catch(e){}
  setTimeout(function(){
    try{
      var card=document.getElementById('v44-fec'),consent=document.getElementById('v44-fec-consent');
      if(card){ card.classList.add('v44-deep-target','v44-focus'); card.scrollIntoView({block:'start',behavior:'auto'}); setTimeout(function(){try{card.classList.remove('v44-focus');}catch(e){}},1600); }
      if(consent){ consent.focus({preventScroll:true}); }
    }catch(e){}
  },140);
  return true;
}
window.choisirFEC=choisirFEC;
function choisirMode(m){
  /* La démo est un bac à sable, pas un mode à écrire dans le dossier réel. */
  verdictEntrySelected();
  if(m==='fec'){ return choisirFEC(); }
  if(m==='demo'){ VERDICT_DEMO_EXPLICIT_ENTRY=true; verdictDemoResumeWrite(true); demoEntrerSession(); refExemple(); return; }
  verdictDemoResumeWrite(false);
  setMode(m);
  try{ if(DB){ DB.onboardingDone=false; save(); } }catch(e){}
  /* V10.14 — aucune création de compte avant la première preuve. Le prospect
     obtient d'abord une lecture locale, explicite et partielle. Le compte ne
     sert ensuite qu'à sauvegarder/synchroniser : il ne conditionne jamais la
     compréhension de la valeur du produit. */
  if(m==='existing'){ refLectureRapide(); return; }
  if(m==='recent'){ recentFormulaire(true); return; }
  /* V9.2 — création / reprise : son propre assistant guidé, au futur. */
  pjFormulaire(true);
}

/* ═══ PREMIÈRE LECTURE AVANT COMPTE ET AVANT SCORE (V10.14) ═══
   Six nombres présents sur la plupart des comptes de résultat suffisent à
   rendre une première réponse. Cette lecture n'écrit rien dans le moteur et
   n'affiche aucun score : elle reste donc honnête quand TVA, rythme et volume
   d'activité ne sont pas encore connus. */
var QR_IDS=['qr-ca','qr-mat','qr-ms','qr-loy','qr-cf','qr-com'];
function qrCle(){var id='0';try{id=(STORE&&STORE.actif)||'0';}catch(e){}return verdictClientAuxKey('quick-reading',id);}
function qrCleLegacy(){var id='0';try{id=(STORE&&STORE.actif)||'0';}catch(e){}return 'verdict:lecture-rapide:v1:'+id;}
function qrLire(){
  function v(id){return num((document.getElementById(id)||{}).value);}
  return {ca:v('qr-ca'),mat:v('qr-mat'),ms:v('qr-ms'),loy:v('qr-loy'),cf:v('qr-cf'),com:v('qr-com')};
}
function qrSauver(){
  try{var r={};QR_IDS.forEach(function(id){r[id]=(document.getElementById(id)||{}).value||'';});lsSet(qrCle(),JSON.stringify(r));}catch(e){}
}
function qrCharger(){try{var site=(STORE&&STORE.actif)||'0',r=JSON.parse(verdictClientReadAux('quick-reading',site,qrCleLegacy())||'{}');QR_IDS.forEach(function(id){var e=document.getElementById(id);if(e&&r[id]!=null)e.value=r[id];});}catch(e){}}
function qrCalcul(r){
  var cv=r.mat+r.com,fixes=r.ms+r.loy+r.cf,res=r.ca-cv-fixes,taux=r.ca>0?cv/r.ca:1;
  return {res:res,mat:r.mat/r.ca*100,ms:r.ms/r.ca*100,marge:res/r.ca*100,
    seuil:(taux>=0&&taux<1)?fixes/(1-taux):null};
}
function qrApercu(){
  qrSauver();var box=document.getElementById('qr-apercu'),z=v10140Text();if(!box)return;
  var r=qrLire(),manq=[];QR_IDS.forEach(function(id){var v=num((document.getElementById(id)||{}).value);if(v==null||v<0)manq.push(id);});
  if(!(r.ca>0)||manq.length){
    box.innerHTML='<b>'+z.qrEmptyTitle+'</b>'+z.qrEmpty.replace('0','<b>0</b>');
    return;
  }
  var x=qrCalcul(r);
  box.innerHTML='<div class="ux-kicker">'+z.qrPartial+'</div><h3 style="margin:5px 0 10px">'+z.qrShows+'</h3>'+
    '<div class="autoline"><span class="k">'+z.qrResult+'</span><b style="color:'+(x.res>=0?'#22c55e':'#ef4444')+'">'+eur(x.res)+'</b></div>'+
    '<div class="autoline"><span class="k">'+z.qrMaterial+'</span><b>'+fr(x.mat,1)+' %</b></div>'+
    '<div class="autoline"><span class="k">'+z.qrPayroll+'</span><b>'+fr(x.ms,1)+' %</b></div>'+
    '<div class="autoline"><span class="k">'+z.qrMargin+'</span><b>'+fr(x.marge,1)+' %</b></div>'+
    '<div class="autoline"><span class="k">'+z.qrThreshold+'</span><b>'+(x.seuil==null?z.qrImpossible:eur(x.seuil))+'</b></div>'+
    '<p class="note" style="margin:10px 0 0">'+z.qrNote+'</p>';
  try{if(typeof window.verdictTrackMilestone==='function')window.verdictTrackMilestone('first_reading_visible',{mode:'existing',partial:true},'existing');}catch(e){}
}
function qrValide(){
  var z=v10140Text();
  var champs=[
    {id:'qr-ca',nom:z.qrFields[0][0],ok:function(v){return v!=null&&v>0;}},
    {id:'qr-mat',nom:z.qrFields[1][0],ok:function(v){return v!=null&&v>=0;}},
    {id:'qr-ms',nom:z.qrFields[2][0],ok:function(v){return v!=null&&v>=0;}},
    {id:'qr-loy',nom:z.qrFields[3][0],ok:function(v){return v!=null&&v>=0;}},
    {id:'qr-cf',nom:z.qrFields[4][0],ok:function(v){return v!=null&&v>=0;}},
    {id:'qr-com',nom:z.qrFields[5][0],ok:function(v){return v!=null&&v>=0;}}
  ];
  return valider(champs,'qr-ca');
}
function qrVersCompte(){
  if(!qrValide())return;qrSauver();
  try{if(typeof window.verdictTrackMilestone==='function')window.verdictTrackMilestone('account_start_after_value',{mode:'existing'},'existing');}catch(e){}
  verdictGoAccount('register','./?resume=1');
}
function qrContinuer(){
  if(!qrValide())return;var r=qrLire(),z=v10140Text();qrSauver();refFormulaire();
  setTimeout(function(){
    var vals={'rf-ca':r.ca,'rf-ms':r.ms,'rf-loy':r.loy,'rf-cf':r.cf,'rf-com':r.com};
    Object.keys(vals).forEach(function(id){var e=document.getElementById(id);if(e)e.value=String(vals[id]).replace('.',',');});
    var p=document.querySelector('#refP .ux-step[data-step="2"] .note');
    if(p)p.insertAdjacentHTML('afterend','<div class="ux-zero">'+v10140Fill(z.qrSplit,{amount:'<b>'+eur(r.mat)+'</b>'})+'</div>');
    try{sauverBrouillon('existing',1);}catch(e){}
  },0);
  try{if(typeof window.verdictTrack==='function')window.verdictTrack('full_diagnostic_start',{source:'quick_reading'});}catch(e){}
}
function refLectureRapide(){
  var el=refSheet(),p=document.getElementById('refP'),z=v10140Text(),f=z.qrFields;
  p.innerHTML='<div class="grab"></div><div class="ux-kicker">'+z.qrKicker+'</div>'+
    '<h3>'+z.qrTitle+'</h3>'+
    '<p class="note">'+z.qrIntro+'</p>'+
    '<button type="button" class="btn sec" style="margin:0 0 12px" onclick="choisirFEC()">'+entryT('fecInstead')+'</button>'+
    uxNum('qr-ca',f[0][0],f[0][1])+uxNum('qr-mat',f[1][0],f[1][1])+uxNum('qr-ms',f[2][0],f[2][1])+
    uxNum('qr-loy',f[3][0],f[3][1])+uxNum('qr-cf',f[4][0],f[4][1])+uxNum('qr-com',f[5][0],f[5][1])+
    '<div class="rsum" id="qr-apercu"><b>'+z.qrEmptyTitle+'</b>'+z.qrEmpty+'</div>'+
    '<div class="ux-actions"><button type="button" class="btn sec" onclick="openRef(true)">'+z.qrBack+'</button><button type="button" class="btn primary" onclick="qrContinuer()">'+z.qrComplete+'</button></div>'+
    (!VERDICT_ACCOUNT_STATE.auth&&location.protocol.indexOf('http')===0?'<button type="button" class="btn sec" style="margin-top:10px" onclick="qrVersCompte()">'+z.qrSave+'</button>':'')+
    '<button type="button" class="btn ghost mini" style="margin-top:8px" onclick="refClose()">'+z.qrClose+'</button>';
  qrCharger();QR_IDS.forEach(function(id){var e=document.getElementById(id);if(e)e.addEventListener('input',qrApercu);});qrApercu();
  try{if(typeof translateDOM==='function')translateDOM(p);}catch(e){}el.classList.add('on');
  setTimeout(function(){var e=document.getElementById('qr-ca');if(e)try{e.focus({preventScroll:true});}catch(x){}},120);
}

/* ═══ LES TROIS PARCOURS MÈNENT QUELQUE PART (V10) ═══
   Steven : « j'ai testé Plus tard, j'attendais d'être guidé, rien ».
   Verdict informe UNE FOIS, puis le client gère. */
function refSuite(mode){
  try{
    var vu='verdict_suite_'+mode;
    if(lsGet(vu)==='1')return;
    lsSet(vu,'1');
    var T={
      demo:{t:'Vous \u00eates en d\u00e9monstration',
        m:'Les chiffres affich\u00e9s sont ceux d\u2019une brasserie fictive : explorez librement, rien n\u2019est \u00e0 vous. Quand vous voudrez vos propres chiffres, allez dans Plus puis Mes chiffres. Verdict ne vous le redemandera plus.'},
      tard:{t:'C\u2019est not\u00e9, on reprendra plus tard',
        m:'Verdict ne vous relancera pas. Quand vous serez pr\u00eat, tout part de Plus puis Mes chiffres : l\u2019assistant vous guide poste par poste, puis le diagnostic complet s\u2019ouvre.'}
    }[mode];
    if(!T)return;
    setTimeout(function(){ try{ ask(T.t,T.m,'J\u2019ai compris',function(){}); }catch(e){ toast(T.t); } },700);
  }catch(e){}
}


