var VERDICT_DEMO_INTENT_RUNTIME='';
function demoIntentId(){return VERDICT_DEMO_INTENT_RUNTIME||VERDICT_ENTRY_CONTEXT.intent||'global';}
function demoIntentCourant(){return DEMO_INTENTS[demoIntentId()]||DEMO_INTENTS.global;}
function demoIntentResume(x){
  var R=null,st=null; try{R=moteur();}catch(e){}
  if(!R||!R.ready)return 'La brasserie fictive montre la méthode. Avec vos chiffres, Verdict vérifiera d’abord leur cohérence avant de produire une réponse.';
  try{st=carteStats();}catch(e){}
  switch(demoIntentId()){
    case 'situation': return 'Sur cette brasserie fictive, le résultat avant impôt est de '+eur(R.d.res)+' et la marge de '+pc(R.v.rn)+'. Vous pouvez modifier les hypothèses du bac à sable et voir le moteur recalculer la situation.';
    case 'action':
      try{var a=auImpactPrioritaire(),pr=a&&a.priority,nom=pr&&(pr.diagnosis||pr.title||pr.titre)||'';return (nom?'L’action classée en premier : « '+nom+' »':'Verdict classe une action prioritaire')+(a&&a.value&&a.value!=='—'?' — '+a.title.toLowerCase()+' : '+a.value:'')+'. Verdict affiche sa raison, sa preuve et la mesure à revoir ensuite.';}catch(e){return 'Verdict classe une action prioritaire, puis affiche sa raison, sa preuve et la mesure à revoir ensuite.';}
    case 'controle': return 'La trajectoire fictive conserve '+((DB.decisions||[]).length)+' décision(s) datée(s) et '+((DB.audits||[]).length)+' audit(s). Verdict exige une nouvelle mesure comparable avant de parler de progrès et ne prétend jamais prouver seul une causalité.';
    case 'rentabilite': return 'Sur cette brasserie fictive, le résultat avant impôt est de '+eur(R.d.res)+' ('+pc(R.v.rn)+'). Verdict montre ensuite les postes qui expliquent ce résultat et le premier levier à tester.';
    case 'food-cost': return 'Les achats nourriture représentent '+pc(R.v.fc)+' du chiffre d’affaires HT. La carte théorique'+(st&&st.actifs?' ressort à '+pc(st.theoR):' sera calculée dès que les plats seront renseignés')+' : l’écart devient une enquête, jamais une accusation.';
    case 'masse-salariale': return 'Le coût humain chargé représente '+pc(R.v.ms)+' du chiffre d’affaires HT. Verdict le relie au volume, aux heures et au point mort avant de recommander une action.';
    case 'point-mort':
      var p3=point3Calc(R),p3Label=p3.delta>=0?'Sa marge de sécurité est de ':'Son écart à combler est de ';
      return 'Cette brasserie doit réaliser environ '+eur(p3.breakEven)+' HT pour couvrir sa structure. '+p3Label+eur(Math.abs(p3.delta))+' : Verdict vous montre le calcul et sa résistance.';
    case 'carte': return (st&&st.actifs?st.actifs+' plats actifs sont lus par marge et volume. '+st.perte+' plat(s) vendus ont une marge négative.':'Verdict attend les prix, ingrédients et volumes avant de classer un plat.')+' La décision reste traçable plat par plat.';
    case 'prix': return 'Le panier moyen de l’exemple est de '+eur2(R.d.panierTTC)+' TTC. Verdict peut rejouer +1 € ou +2 € dans le moteur complet et mesurer l’effet annuel, sans promettre que le volume restera identique.';
    case 'plateformes': return 'Les commissions saisies représentent '+pc(R.v.com)+' du chiffre d’affaires HT. Verdict les relit avec la matière, l’emballage, la TVA et le prix de chaque plat livré.';
    case 'inventaire': return 'Le comptage ne reste pas une liste : Verdict rapproche stock initial, stock final et achats pour établir une consommation réelle et expliquer l’écart matière.';
    case 'organisation': return 'La contribution calculée est de '+eur(R.v.prod)+' par heure d’ouverture. Verdict la confronte au point mort et aux coûts de service avant de tester une autre organisation.';
    case 'multi-etablissements': return 'Chaque modèle conserve son propre score, ses chiffres et son audit. Verdict compare les ratios sur 100 € HT, nomme les périodes non équivalentes et reste sur la même page quand vous changez d’établissement.';
    case 'audit': return 'L’audit de l’exemple reprend le résultat de '+eur(R.d.res)+', les preuves disponibles et le contexte terrain, puis transforme les priorités en plan 90 jours suivi dans l’application.';
    case 'fiabilite': return 'Le score n’est affiché que lorsque les données indispensables sont présentes, cohérentes et les valeurs improbables confirmées. La confirmation reste liée aux chiffres exacts.';
  }
  return 'Verdict a calculé cette brasserie fictive. Vous pouvez voir la réponse courte, examiner ses conséquences, puis accéder à l’ensemble du produit sans formulaire.';
}
function fermerSurcouche(id){var m=document.getElementById(id);if(m&&m.parentNode)m.parentNode.removeChild(m);}
/* Bascule atomique fenêtre → contenu. Le contenu inférieur est préparé tant
   que la fenêtre reste visible, puis la fenêtre est retirée dans la même
   tâche. Si la préparation échoue, la fenêtre reste ouverte. */
function verdictCommitUnderOverlay(id,prepare){
  var m=document.getElementById(id),from=(typeof VIEW==='string'?VIEW:'');
  try{
    if(typeof prepare==='function'&&prepare()===false)return false;
  }catch(err){
    window.__verdictOverlayError=String(err&&err.stack||err||'erreur de transition');
    try{toast('Impossible d\u2019ouvrir cet écran');}catch(e){}
    return false;
  }
  if(m&&m.parentNode)m.parentNode.removeChild(m);
  window.__verdictOverlayTrace={id:id,from:from,to:(typeof VIEW==='string'?VIEW:''),prepared:true,closed:true};
  return true;
}
function toutVerdictFermer(){fermerSurcouche('mToutVerdict');}
function demoSousVueImmediate(v,subName){
  if(!subName)return false;
  var prefix=v==='data'?'dsub':(v==='carte'?'csub':(v==='x'?'xsub':''));
  if(!prefix)return false;
  var bs=document.querySelectorAll('#v-'+v+' button'),b=null;
  for(var j=0;j<bs.length;j++)if((bs[j].getAttribute('onclick')||'').indexOf(prefix+"('"+subName+"'")>=0){b=bs[j];break;}
  if(!b)return false;
  try{
    if(prefix==='dsub')return dsub(subName,b)!==false;
    if(prefix==='csub')return csub(subName,b)!==false;
    return xsub(subName,b)!==false;
  }catch(e){
    window.__verdictDemoSubError=String(e&&e.stack||e||'sous-vue indisponible');
    return false;
  }
}
function toutVerdictAller(i){
  var c=TV_CAPACITES[i]; if(!c)return false;
  return verdictCommitUnderOverlay('mToutVerdict',function(){
    if(c.special==='etabs'){openEtabs();return true;}
    if(go(c.v||'pil')===false)return false;
    if(c.sub)demoSousVueImmediate(c.v,c.sub);
    if(c.a){var e=document.querySelector(c.a);if(e)try{e.scrollIntoView({behavior:'auto',block:'start'});}catch(x){}}
    return true;
  });
}
function tvCapAffichee(c,i){
  if(i!==0||typeof projetOuvert!=='function'||projetOuvert())return c;
  return Object.assign({},c,{t:'Préparer ma situation avant l’ouverture',q:'Quel chiffre mon projet devra-t-il atteindre ?',
    d:'Verdict affiche la prévision annuelle, le seuil du projet et les hypothèses à compléter. La projection du mois commencera après l’ouverture et trois journées réelles.'});
}
function ouvrirToutVerdict(){
  fermerSurcouche('mToutVerdict'); var x=demoIntentCourant(),m=document.createElement('div');
  m.id='mToutVerdict';m.className='modal on tv-modal';m.setAttribute('role','dialog');m.setAttribute('aria-modal','true');m.setAttribute('aria-labelledby','tvTitle');
  var cards=TV_CAPACITES.map(function(c,i){var a=tvCapAffichee(c,i);return '<button type="button" class="tv-card" onclick="toutVerdictAller('+i+')"><span class="tv-ic">'+a.ic+'</span><span class="tv-copy"><b>'+esc(a.t)+'</b><small><strong>'+esc(a.q)+'</strong><br>'+esc(a.d)+'</small>'+(a.status?'<em>'+esc(a.status)+'</em>':'')+'</span></button>';}).join('');
  m.innerHTML='<div class="tv-sheet"><div class="tv-scroll"><div class="tv-head"><div class="tv-head-copy"><div class="tv-kicker">Carte complète · 15 besoins</div><h2 id="tvTitle">Toute la puissance de Verdict.<br>Une réponse claire à la fois.</h2><p class="tv-lead">Cette carte est un raccourci facultatif. La démonstration principale montre d’abord une décision complète : situation, diagnostic, cause, action et contrôle.</p></div><button type="button" class="tv-close" onclick="toutVerdictFermer()" aria-label="Fermer">✕</button></div>'+
    (demoIntentId()!=='global'?'<div class="tv-context"><strong>Votre question reste active</strong>'+esc(x.question)+' — ouvrez une capacité : Verdict conserve le même établissement et le même contexte.</div>':'')+
    '<div class="tv-grid">'+cards+'</div><div class="tv-foot"><button type="button" class="btn sec" onclick="toutVerdictFermer()">Continuer à explorer</button><button type="button" class="btn" onclick="toutVerdictFermer();demoFinVisite()">Essayer 14 jours avec mes chiffres</button></div></div></div>';
  m.addEventListener('click',function(e){if(e.target===m)toutVerdictFermer();});document.body.appendChild(m);
}
function demoIntentFermer(){fermerSurcouche('mDemoIntent');}
function demoIntentAller(){var x=demoIntentCourant();return verdictCommitUnderOverlay('mDemoIntent',function(){
  if(go(x.route||'pil')===false)return false;
  if(x.sub)demoSousVueImmediate(x.route,x.sub);
  if(x.special==='etabs')openEtabs();
  return true;
});}
function demoIntentVera(){var x=demoIntentCourant();return verdictCommitUnderOverlay('mDemoIntent',function(){
  if(go('aide')===false)return false;var q=document.getElementById('aideQ');
  if(q){q.value=x.question;var f=q.form;if(f)f.dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));}
  return true;
});}
function demoChoisirIntent(id){
  if(id==='all'||id==='decision'){
    try{if(typeof window.verdictTrack==='function')window.verdictTrack('demo_intent_selected',{intent:'decision_loop'});}catch(e){}
    demoDemarrerDecision();return;
  }
  if(id==='questions'){demoQuestionsOuvrir();return;}
  if(id==='explore'){
    try{if(typeof window.verdictTrack==='function')window.verdictTrack('demo_intent_selected',{intent:'free_explore'});}catch(e){}
    /* Depuis la porte d'entrée, « explorer librement » signifie toujours
       ouvrir l'Accueil au début. La feuille pouvait sinon rendre à Safari
       l'ancien ancrage situé sous les cartes du mois. */
    demoIntentFermer();demoMarquerVisite();demoNotifierFin('free');demoFin();demoStabiliserModeLibre('pil');return;
  }
  if(!DEMO_INTENTS[id]||id==='global')return;
  VERDICT_DEMO_INTENT_RUNTIME=id;
  demoPremierDeclicCommencer(id);
  try{sessionStorage.setItem('verdict:demo:runtime-intent',id);}catch(e){}
  try{if(typeof window.verdictTrack==='function')window.verdictTrack('demo_intent_selected',{intent:id});}catch(e){}
  demoIntentFermer();demoIntentOuvrir();
}
