/* R17.2 — machine à états observable de la présentation 1→30.
   Elle ne remplace pas les calculs métier : elle interdit les redémarrages
   implicites, conserve le passage Inventaire et rend chaque transition
   vérifiable sans minuterie arbitraire. */
var VERDICT_DEMO_MACHINE=(function(){
  var state={phase:'idle',session:0,currentStep:0,total:30,module:'pilotage',chapter:'',introPlayed:false,introRuns:0,completed:false,reason:'',updatedAt:0};
  function now(){try{return Date.now();}catch(e){return 0;}}
  function snapshot(){return Object.freeze(Object.assign({},state));}
  function touch(){state.updatedAt=now();return snapshot();}
  function start(reason,force){
    if(state.phase==='running'||state.phase==='inventory')return true;
    if(state.completed&&!force)return false;
    state.session++;state.phase='running';state.currentStep=0;state.module='pilotage';state.chapter='';state.completed=false;state.reason=String(reason||'start');
    if(!state.introPlayed||force){state.introPlayed=true;state.introRuns++;}
    touch();return true;
  }
  function visit(step,total,chapter,module){
    step=Math.max(1,Math.floor(Number(step)||1));total=Math.max(step,Math.floor(Number(total)||30));
    if(state.completed)return false;if(state.phase==='idle'||state.phase==='free')start('resume',false);
    state.phase='running';state.currentStep=step;state.total=total;state.chapter=String(chapter||'');state.module=module==='carte'?'carte':'pilotage';state.reason='step';touch();return true;
  }
  function inventory(step,total){
    if(state.completed)return false;if(state.phase==='idle'||state.phase==='free')start('inventory',false);
    state.phase='inventory';state.currentStep=Math.max(1,Math.floor(Number(step)||1));state.total=Math.max(state.currentStep,Math.floor(Number(total)||30));state.module='inventory';state.chapter='inventaire';state.reason='handoff';touch();return true;
  }
  function returnToPilotage(module){if(state.completed)return false;state.phase='running';state.module=module==='carte'?'carte':'pilotage';state.reason='return';touch();return true;}
  function complete(total){state.total=Math.max(1,Math.floor(Number(total)||state.total||30));state.currentStep=state.total;state.phase='completed';state.module='pilotage';state.completed=true;state.reason='completed';touch();return true;}
  function exit(reason){state.phase='free';state.reason=String(reason||'free');touch();return true;}
  function replay(reason){state.phase='idle';state.currentStep=0;state.completed=false;state.reason=String(reason||'replay');return start(state.reason,true);}
  return Object.freeze({start:start,visit:visit,inventory:inventory,returnToPilotage:returnToPilotage,complete:complete,exit:exit,replay:replay,inspect:snapshot});
})();
