    '<button type="button" class="di-close" onclick="demoTapStop();demoExplorerLibre()" aria-label="Quitter la démonstration">✕</button></div>';
  var pos=demoInlineBefore(DEMO_TARGET);pos.host.insertBefore(inline,pos.before||null);
  var marker=null;if(DEMO_TARGET&&DEMO_TARGET.parentNode){var powerCopy=demoScoreGuideCopy(c,(function(){try{return moteur();}catch(e){return null;}})());marker=document.createElement('div');marker.className='demo-target-banner is-power';marker.innerHTML='<span>'+esc((powerCopy&&powerCopy.open)||'Écran ouvert')+'</span><b>'+esc(c.t)+'</b>';DEMO_TARGET.parentNode.insertBefore(marker,DEMO_TARGET);}
  try{if(typeof translateDOM==='function'){translateDOM(inline);if(marker)translateDOM(marker);}}catch(e){}
