window.Verdict=window.Verdict||{};
window.Verdict.demo=function(n){ DEMO_AUTO=false;VERDICT_DEMO_MACHINE.start('api',false);demoPremierDeclicCommencer('api');return demoJouer(n||0); };
/* lancement automatique retiré : la démo ne part que sur demande explicite */


/* ═══ TROIS CHEMINS, PAS QUATRE (V5.11) ═══
   Steven : « Plus tard n'est pas un quatrième cas, c'est un piège ».
   Le troisième chemin charge un exemple pour de bon : le client n'atterrit
   jamais devant un écran vide, et il sait que ces chiffres ne sont pas les siens. */
function refExemple(){
  /* Un toucher iPhone peut être rejoué par la couche d'aperçu pendant que la
     feuille se ferme. Une seconde initialisation remettait alors le compteur à
     zéro et, surtout, pouvait exécuter la suite avant la fin de l'animation. */
  if(window.__verdictDemoEntryBusy===true)return false;
  window.__verdictDemoEntryBusy=true;
  try{
    var entreeExplicite=VERDICT_DEMO_EXPLICIT_ENTRY===true;
    VERDICT_DEMO_EXPLICIT_ENTRY=false;
    demoEntrerSession();
    /* V10.14.4 — une démo déjà chargée est bien la démo démarrée.
       Sans ce verrou, la fin de l'introduction ?demo=1 pouvait rappeler
       refFirstRun() plusieurs secondes plus tard et renvoyer toute seule à
       l'Accueil pendant que le client lisait une autre page. */
    VERDICT_DEMO_STARTED=true;
    /* Cette installation remplace entièrement le STORE actif par un seul
       établissement fictif non facturable. Le portefeuille réel, s'il existe,
       reste hors de l'univers manipulable jusqu'à la sortie. */
    var d=demoInstallerBrasserieCanonique();
    verdictModelMarkStarted(STORE.actif);
    /* V7.0 — la démo est un univers clos : aucun assistant ne doit pouvoir
       s'y inviter, ni maintenant ni à la réouverture. */
    try{ guideMarquer(); }catch(e){}
    try{ if(typeof guideFermer==='function')guideFermer(false); }catch(e){}
    try{ fillInputs(); readInputs(); }catch(e){}
    try{ refreshAll(); }catch(e){}
    try{ refClose(); }catch(e){}
    try{ go('pil'); }catch(e){}
    verdictScrollHomeTop();
    /* Le modèle ne doit jamais apparaître brutalement déjà calculé. Comme lors
       d'un changement de modèle, Verdict repart de zéro, anime le score de la
       brasserie, puis seulement ouvre la découverte. */
    var R=null;try{R=moteur();}catch(e){}
    var introLancee=replayIntro('Brasserie — score '+(R&&R.ready?Math.round(R.score):'—')+'/100',function(){
      window.__verdictDemoEntryBusy=false;
      verdictScrollHomeTop();
      /* Depuis une page SEO, la vraie question du prospect passe avant la visite
         générique — même s'il a déjà exploré Verdict. Sans question précise, la
         découverte express se joue une fois puis laisse l'exploration libre. */
      clearTimeout(window.VERDICT_DEMO_ENTRY_TIMER);
      if(demoIntentId()!=='global')window.VERDICT_DEMO_ENTRY_TIMER=setTimeout(function(){try{demoIntentOuvrir();}catch(e){}},180);
      else if(entreeExplicite||!demoVisiteDejaVue())window.VERDICT_DEMO_ENTRY_TIMER=setTimeout(function(){ try{ demoIntentOuvrir(); }catch(e){} },180);
      else demoFin();
    },'discovery');
    if(introLancee===false)window.__verdictDemoEntryBusy=false;
    return introLancee!==false;
  }catch(e){
    window.__verdictDemoEntryBusy=false;
    VERDICT_DEMO_EXPLICIT_ENTRY=false;
    try{demoRestaurerSessionReelle();}catch(_e){}
    try{openRef(true);toast('La démonstration n’a pas pu démarrer. Touchez de nouveau « Découvrir Verdict ».');}catch(_e){}
    try{console.error('Verdict demo start',e);}catch(_e){}
  }
}

/* Restaure exactement le portefeuille qui existait avant une démo marketing.
   Le paramètre ?demo=1 est retiré afin qu'un CTA « À mon tour » ne relance pas
   immédiatement l'exemple. Les démos choisies depuis le premier écran ne
   passent pas ici et conservent leur fonctionnement normal. */
function demoRestaurerSessionReelle(){
  if(!VERDICT_DEMO_SESSION)return false;
  verdictDemoResumeWrite(false);
  var retour=VERDICT_DEMO_RETURN||{};VERDICT_DEMO_RESTORE_ACTIVE=true;
  try{
    var u=new URL(location.href), q;
    u.searchParams.delete('demo'); q=u.searchParams.toString();
    history.replaceState(null,'',u.pathname+(q?'?'+q:'')+u.hash);
  }catch(e){}
  /* Le bac à sable est désactivé avant toute lecture réelle. Son stockage
     mémoire est ensuite jeté en bloc : rien n'est fusionné champ par champ. */
  VERDICT_DEMO_SESSION=false;VERDICT_DEMO_REQUESTED=false;VERDICT_DEMO_STARTED=false;
  verdictDemoStorageReset();
  try{
    if(retour.skey)SKEY=retour.skey;
    VERDICT_STORAGE_SCOPE=retour.storageScope||'guest';
    VERDICT_LOCAL_FOUND=!!retour.localFound;
    VERDICT_SAFETY_READY=!!retour.safetyReady;
    if(retour.accountState)VERDICT_ACCOUNT_STATE=verdictDemoClone(retour.accountState);
    if(retour.cloud)VERDICT_CLOUD=verdictDemoClone(retour.cloud);
    TIER=retour.tier||'verdict';
    if(retour.store){
      STORE=verdictDemoClone(retour.store);
      if(STORE.actif&&STORE.etabs&&STORE.etabs[STORE.actif])setActif(STORE.actif);
      else if(STORE.ordre&&STORE.ordre.length)setActif(STORE.ordre[0]);
    }else load();
    verdictModeWrite(retour.mode==null?'':retour.mode);
  }catch(e){ try{load();}catch(x){} }
  try{if(retour.runtimeIntent==null)sessionStorage.removeItem('verdict:demo:runtime-intent');else sessionStorage.setItem('verdict:demo:runtime-intent',retour.runtimeIntent);}catch(e){}
  VERDICT_DEMO_RETURN=null;
  VERDICT_DEMO_FROM_PORTFOLIO=false;
  VERDICT_DEMO_PORTFOLIO_MODEL_ACTIVE=false;
  try{ fillInputs(); readInputs(); refreshAll(); drawEtabs(); }catch(e){}
  try{ majBandeauDemo(); }catch(e){}
  VERDICT_DEMO_RESTORE_ACTIVE=false;
  /* Les services réels ne reprennent qu'après la restauration intégrale. */
  try{ verdictAccountRefresh().then(function(){return verdictCloudInit();}); }catch(e){}
  return true;
}

/* ═══════════════════════════════════════════════════════════════════
   ASSISTANT « ANALYSER MON RESTAURANT » EN 3 ÉTAPES (V9.0)
   Steven : « le style GPT est meilleur — clair, précis, guidé — mais il
   demande le nom de l'établissement avant de savoir ce que veut le client ».
   D'où ce portage : la maquette guidée est reprise, mais elle n'arrive
   qu'APRÈS le choix du profil, et chaque étape est verrouillée par les
   contrôles métier (recoupement, postes indispensables, plausibilité).
   Une étape ne s'ouvre que si la précédente tient debout.
   ═══════════════════════════════════════════════════════════════════ */
