/* Sortie de démo directement vers un parcours choisi. */
function quitterDemoVers(mode){
  PLUS_DEMO_HANDOFF=false; verdictDemoResumeWrite(false); demoMarquerVisite(); demoFin();
  try{
    var marketing=demoRestaurerSessionReelle();
    if(!marketing){
      var d=freshDB(false);
      if(typeof STORE!=='undefined' && STORE.actif){ STORE.etabs[STORE.actif]=d; }
      DB=d; save();
    }
    try{ verdictGuideClear(); }catch(e){}
    try{ fillInputs(); readInputs(); refreshAll(); }catch(e){}
    setMode(mode);
    /* En sortie de la démo marketing, le choix du prospect devient son vrai
       parcours. On ne réutilise jamais onboardingDone du portefeuille restauré
       pour court-circuiter l'assistant qu'il vient explicitement de demander. */
    try{ DB.onboardingDone=false; save(); }catch(e){}
    try{ majBandeauDemo(); }catch(e){}
  }catch(e){}
  if(mode==='creation')pjFormulaire(true);else if(mode==='recent')recentFormulaire(true);else refLectureRapide();
}

/* ═══════════════════════════════════════════════════════════════════
   UNE SORTIE TOUJOURS VISIBLE (V9.3)
   Steven : « impossible de faire retour ». Vérifié : la fiche « Nouveau plat »
   n'avait aucune fermeture dans son en-tête, et son bouton Annuler tombait à
   1050 px sur un écran de 844 — hors de portée sans deviner qu'il faut faire
   défiler. La croix que croyait voir mon premier audit était en réalité le
   bouton de suppression d'un ingrédient.
   Règle : toute fiche qui s'ouvre porte une fermeture visible, en haut, qui ne
   défile pas. Elle est posée automatiquement — aucune fiche ne peut l'oublier.
   Exception assumée : le choix de langue et le choix du parcours au tout
   premier lancement, où il n'y a rien derrière à retrouver.
   ═══════════════════════════════════════════════════════════════════ */
var SANS_FERMETURE={mLang:1};
function poserFermeture(el){
  try{
    if(!el||!el.classList||!el.classList.contains('on'))return;
    var id=el.id||'';
    if(SANS_FERMETURE[id])return;
    if(id==='refSh' && !document.querySelector('#refP .ux-step') &&
       !(typeof onboardingFait==='function' && onboardingFait()))return;  /* écran de choix initial */
    /* R320 : une autre surcouche « on » sans .sheet posait sa croix DANS la
       feuille d'entrée (#refP), malgré l'exception ci-dessus. Seule #refSh
       peut se rabattre sur #refP. */
    var sheet=el.querySelector('.sheet')||(id==='refSh'?document.getElementById('refP'):null);
    if(!sheet||sheet.querySelector('.sh-fermer'))return;
    var b=document.createElement('button');
    b.type='button'; b.className='sh-fermer'; b.setAttribute('aria-label','Fermer');
    b.innerHTML='\u2715';
    b.onclick=function(ev){
      ev.stopPropagation();
      if(id==='refSh'){ try{ refRetourSecurise(); }catch(e){try{refClose();}catch(_){}} return; }
      try{ closeM(id); }catch(e){ el.classList.remove('on'); }
    };
    sheet.insertBefore(b, sheet.firstChild);
  }catch(e){}
}
try{
  var _obsFerm=new MutationObserver(function(muts){
    muts.forEach(function(m){
      if(m.type==='attributes'&&m.attributeName==='class')poserFermeture(m.target);
      if(m.type==='childList')Array.prototype.forEach.call(m.addedNodes||[],function(n){
        if(n.nodeType===1&&n.classList&&(n.classList.contains('modal')))poserFermeture(n);
      });
    });
  });
  document.addEventListener('DOMContentLoaded',function(){
    _obsFerm.observe(document.body,{attributes:true,attributeFilter:['class'],subtree:true,childList:true});
  });
}catch(e){}

function projetOuvert(){
  try{ if(getMode()!=='creation')return true; }catch(e){ return true; }
  try{ return DB && DB.projetOuvert===true; }catch(e){ return true; }
}
var PJ_ETAPE=1;
function pjEtape(n){
  if(n>PJ_ETAPE && PJ_ETAPE===1 && !validateEstablishmentContext('pj'))return;
  if(n>PJ_ETAPE && PJ_ETAPE===2 && !pjValiderActivite())return;
  PJ_ETAPE=n;
  try{ sauverBrouillon('creation',n); }catch(e){}
  document.querySelectorAll('#refP .ux-step').forEach(function(x){ x.hidden=(Number(x.getAttribute('data-step'))!==n); });
  var pr=document.getElementById('refProgress'); if(pr)pr.innerHTML=uxProgress(n,3);
  try{ if(pr&&typeof translateDOM==='function')translateDOM(pr); }catch(e){}
  if(n===3){ try{ pjApercu(); }catch(e){} }
  uxHaut();
}
function pjValiderActivite(){
  var ok=valider([
    {id:'pj-panier',nom:'Panier moyen pr\u00e9vu',ok:function(v){ return v!=null&&v>0; }},
    {id:'pj-tva',nom:'TVA moyenne',ok:function(v){ return v!=null&&v>=0&&v<=30; }},
    {id:'pj-cmdj',nom:'Couverts pr\u00e9vus par jour',ok:function(v){ return v!=null&&v>0; }},
    {id:'pj-jsem',nom:'Jours ouverts par semaine',ok:function(v){ return v!=null&&v>=1&&v<=7; }},
    {id:'pj-mois',nom:'Mois d\u2019activit\u00e9 par an',ok:function(v){ return v!=null&&v>=1&&v<=12; }}
  ],'pj-panier');
  if(!ok)return false;
  var p=num((document.getElementById('pj-panier')||{}).value), c=num((document.getElementById('pj-cmdj')||{}).value);
  var j=num((document.getElementById('pj-jsem')||{}).value), m=num((document.getElementById('pj-mois')||{}).value);
  var tva=num((document.getElementById('pj-tva')||{}).value), alertes=[];
  var ca=p*c*j*4.33*m/(1+tva/100);
  if(p<5)alertes.push('Le panier prévu est inférieur à 5 € TTC. Possible sur certains formats, mais vérifiez qu\u2019il s\u2019agit bien d\u2019une addition moyenne.');
  if(p>300)alertes.push('Le panier prévu dépasse 300 € TTC. Vérifiez qu\u2019il s\u2019agit bien d\u2019une addition moyenne.');
  if(c<1)alertes.push('Vous prévoyez moins d\u2019un couvert par jour d\u2019ouverture.');
  if(c>500)alertes.push('Vous prévoyez plus de 500 couverts par jour d\u2019ouverture.');
  if(ca>0&&ca<1000)alertes.push('Le chiffre d\u2019affaires annuel prévisionnel est inférieur à 1 000 €. Vérifiez vos hypothèses et unités.');
  if(!uxAlerte('creation','activite','Verdict a détecté une hypothèse inhabituelle',alertes,[p,tva,c,j,m],function(){ pjEtape(3); }))return false;
  return true;
}
function pjLire(){
  function v(id){ return num((document.getElementById(id)||{}).value); }
  var tva=v('pj-tva');
  return {panier:v('pj-panier'), tva:tva, cmdj:v('pj-cmdj'),
    jsem:v('pj-jsem'), mois:v('pj-mois'),
    nour:v('pj-nour'), boi:v('pj-boi'), emb:v('pj-emb'), com:v('pj-com'),
    dirb:v('pj-dirb'), salb:v('pj-salb'), etp:v('pj-etp'), loy:v('pj-loy'), cf:v('pj-cf')};
}
function pjApercu(){
  var box=document.getElementById('pj-apercu'); if(!box)return;
  var r=pjLire();
  if(!(r.panier>0)||!(r.cmdj>0)){ box.innerHTML='<b>Votre pr\u00e9vision</b>Renseignez le panier moyen et les couverts par jour : la pr\u00e9vision se calcule ici.'; return; }
  var jAn=r.jsem*4.33*r.mois, caTTC=r.panier*r.cmdj*jAn, ca=caTTC/(1+r.tva/100);
  function n(x){ return x==null?0:x; }
  var abs=[];
  [['nour','achats nourriture'],['boi','achats boissons'],['salb','salaires'],['dirb','votre r\u00e9mun\u00e9ration'],['loy','loyer']]
    .forEach(function(p){ if(r[p[0]]==null)abs.push(p[1]); });
  var cv=n(r.nour)+n(r.boi)+n(r.emb)+n(r.com);
  var fixe=(n(r.dirb)+n(r.salb)+n(r.loy)+n(r.cf))*12;
  var res=ca-cv-fixe, mn=ca>0?res/ca*100:0;
  box.innerHTML='<b>Votre pr\u00e9vision</b>'+
    (abs.length?'<span style="color:#f87171">Pas encore renseign\u00e9 : '+abs.join(', ')+'. Cette pr\u00e9vision les ignore \u2014 elle est donc trop optimiste.</span><br>':'')+
    'Chiffre d\u2019affaires pr\u00e9visionnel : <b>'+eur(ca)+'</b> HT par an<br>'+
    'R\u00e9sultat estim\u00e9 : <b style="color:'+(res>=0?'#22c55e':'#ef4444')+'">'+eur(res)+'</b> \u00b7 marge '+fr(mn,1)+'&nbsp;%<br>'+
    '<span style="opacity:.85">Calcul : '+fr(r.cmdj,1)+' couverts \u00d7 '+eur2(r.panier)+' \u00d7 '+fr(jAn,0)+' jours d\u2019ouverture. '+
    'Charges mensuelles \u00d7 12. Ce sont vos hypoth\u00e8ses, pas une promesse.</span>';
}
function pjApercuActivite(){
  var box=document.getElementById('pj-activite-apercu'),z=v10140Text();if(!box)return;
  var r=pjLire();
  if(!(r.panier>0)||r.tva==null||r.tva<0||r.tva>30||!(r.cmdj>0)||!(r.jsem>0)||!(r.mois>0)){
    box.innerHTML='<b>'+z.pjFirst+'</b>'+z.pjMissing;return;
  }
  var jours=r.jsem*4.33*r.mois,caTTC=r.panier*r.cmdj*jours,ca=caTTC/(1+r.tva/100);
  box.innerHTML='<div class="ux-kicker">'+z.pjKicker+'</div><h3 style="margin:5px 0 8px">'+eur(ca)+' '+z.pjAnnual+'</h3>'+
    '<p class="note" style="margin:0">'+v10140Fill(z.pjNote,{covers:fr(r.cmdj,1),basket:eur2(r.panier),days:fr(jours,0)})+'</p>'+
    (!VERDICT_ACCOUNT_STATE.auth&&location.protocol.indexOf('http')===0?'<button type="button" class="btn sec" style="margin-top:10px" onclick="sauverBrouillon(\'creation\',2);verdictGoAccount(\'register\',\'./?resume=1\')">'+z.pjSave+'</button>':'');
  try{if(typeof window.verdictTrackMilestone==='function')window.verdictTrackMilestone('first_reading_visible',{mode:'creation',partial:true},'creation');}catch(e){}
}
function pjValiderCharges(continuer){
  var champs=[
    {id:'pj-nour',nom:'Achats nourriture',ok:function(v){ return v!=null&&v>=0; }},
    {id:'pj-boi',nom:'Achats boissons',ok:function(v){ return v!=null&&v>=0; }},
    {id:'pj-dirb',nom:'Coût dirigeant chargé',ok:function(v){ return v!=null&&v>=0; }},
    {id:'pj-salb',nom:'Masse salariale chargée',ok:function(v){ return v!=null&&v>=0; }},
    {id:'pj-etp',nom:'Effectif actif (ETP)',ok:function(v){ return v==null||v>=0; }},
    {id:'pj-loy',nom:'Loyer',ok:function(v){ return v!=null&&v>=0; }},
    {id:'pj-emb',nom:'Emballages',ok:function(v){ return v==null||v>=0; }},
    {id:'pj-com',nom:'Commissions plateformes',ok:function(v){ return v==null||v>=0; }},
    {id:'pj-cf',nom:'Autres charges fixes',ok:function(v){ return v==null||v>=0; }}
  ];
  if(!valider(champs,'pj-nour'))return false;
  var r=pjLire(), n=function(x){ return x==null?0:x; };
  var jours=r.jsem*4.33*r.mois, ca=r.panier*r.cmdj*jours/(1+r.tva/100);
  var mat=n(r.nour)+n(r.boi)+n(r.emb), cv=mat+n(r.com);
  var humain=(n(r.dirb)+n(r.salb))*12, fixes=(n(r.loy)+n(r.cf))*12;
  var res=ca-cv-humain-fixes, alertes=[];
  if(mat===0)alertes.push('Vous prévoyez 0 € d\u2019achats de matière. Si c\u2019est volontaire, confirmez-le.');
  if(humain===0)alertes.push('Vous prévoyez 0 € de coût humain. Si personne ne sera rémunéré au démarrage, confirmez-le.');
  if(fixes===0)alertes.push('Vous prévoyez 0 € de loyer et d\u2019autres charges fixes. Vérifiez qu\u2019aucun poste n\u2019a été oublié.');
  if(ca>0&&r.nour>0&&r.nour/ca<.10)alertes.push('Les achats nourriture représentent moins de 10 % du CA prévisionnel. Vérifiez que l\u2019année est complète.');
  if(ca>0&&r.nour/ca>.80)alertes.push('Les achats nourriture dépassent 80 % du CA prévisionnel. Vérifiez les hypothèses et les périodes.');
  if(ca>0&&mat>ca)alertes.push('Les achats de matière dépassent le chiffre d\u2019affaires prévisionnel. C\u2019est possible, mais très inhabituel.');
  if(ca>0&&humain>ca)alertes.push('Le coût humain annuel dépasse le chiffre d\u2019affaires prévisionnel. Vérifiez notamment mensuel contre annuel.');
  if(ca>0&&n(r.loy)*12/ca>.20)alertes.push('Le loyer dépasse 20 % du CA prévisionnel. Vérifiez qu\u2019il est bien saisi par mois.');
  if(ca>0&&res/ca>.30)alertes.push('La marge prévisionnelle dépasse 30 %. Vérifiez qu\u2019aucune charge importante n\u2019a été oubliée.');
  if(ca>0&&res/ca<-.50)alertes.push('La perte prévisionnelle dépasse 50 % du CA. Verdict peut l\u2019analyser, mais vérifiez d\u2019abord les unités.');
  var vals=[r.nour,r.boi,r.emb,r.com,r.dirb,r.salb,r.etp,r.loy,r.cf,ca];
  return uxAlerte('creation','charges','Verdict a détecté des hypothèses inhabituelles',alertes,vals,continuer);
}
