function pjValider(){
  if(!validateEstablishmentContext('pj')){pjEtape(1);return;}
  if(!pjValiderActivite()){ pjEtape(2); return; }
  if(!pjValiderCharges(function(){ pjValider(); }))return;
  var r=pjLire();
  try{
    var _n=(document.getElementById('pj-nom')||{}).value;
    var _t=(document.getElementById('pj-type')||{}).value;
    var _v=(document.getElementById('pj-ville')||{}).value;
    if(_n&&_n.trim())DB.etab=_n.trim();
    if(_t)DB.etabType=_t;
    if(_v!=null)DB.etabVille=(_v||'').trim();
  }catch(e){}
  DB.in=DB.in||{};
  DB.in.panier=r.panier; DB.in.tva=r.tva; DB.in.cmdj=r.cmdj;
  DB.reg=DB.reg||{}; DB.reg.tvac=r.tva;
  DB.in.jsem=r.jsem; DB.in.mois=r.mois; DB.in.moisch=12;
  DB.in.nour=r.nour; DB.in.boi=r.boi; DB.in.emb=r.emb; DB.in.com=r.com; DB.in.autv=0;
  DB.in.dirb=r.dirb; DB.in.dirn=0; DB.in.dirt=0;
  DB.in.salb=r.salb; DB.in.saln=(r.etp!=null&&r.etp>=0)?r.etp:0; DB.in.salt=0;
  DB.in.f1=r.loy; for(var i=2;i<=9;i++)DB.in['f'+i]=0; DB.in.f10=r.cf;
  DB.exempleCharge=false; DB.userMode='creation'; DB.projetOuvert=false; DB.onboardingDone=false;
  DB.dataProvenance={nature:'client_hypothesis',source:'business-plan-manual',period:'forecast',confidence:'client-declared',verificationLevel:'hypothesis',documentVerified:false,finalScoreAllowed:false};
  try{ setMode('creation'); }catch(e){}
  save(); fillInputs(); readInputs(); refreshAll();
  confirmerAnomaliesAssistant();
  var manq=[]; try{ manq=donneesManquantes(); }catch(e){}
  if(manq.length){
    pjEtape(3);
    champsMsg('pj-nour','<b>Il manque encore des informations</b>'+manquantsParSection(manq).join('<br>')+'. Corrigez-les ici : Verdict conserve tout le reste.');
    return;
  }
  var R=moteur();
  if(!R.ready){
    pjEtape(3);
    var inc=(R.incoherences||[]).concat((R.anomalies||[]).map(function(a){return a.lb;}));
    champsMsg('pj-nour','<b>Verdict doit encore vérifier vos chiffres</b>'+(inc.length?inc.slice(0,4).join('<br>'):'Relisez les champs signalés avant de continuer.'));
    return;
  }
  try{
    var wv=document.getElementById('wVerdict'); if(wv){ wv.innerHTML=''; wv.classList.remove('on'); }
    document.querySelectorAll('.err-champ').forEach(function(e){ e.remove(); });
    document.querySelectorAll('input.manque').forEach(function(e){ e.classList.remove('manque'); });
  }catch(e){}
  onboardingTerminer('creation');
  try{window.verdictTrackMilestone('full_diagnostic_ready',{mode:'creation',source:'project'},'creation');}catch(e){}
  refClose();
  toast('Pr\u00e9vision calcul\u00e9e \u2014 score '+Math.round(R.score));
  go('data');
}
/* ═══════════════════════════════════════════════════════════════════
   ÉTABLISSEMENT RÉCEMMENT OUVERT — PAS DE FAUX EXERCICE ANNUEL
   Les faits de la période sont conservés séparément. Une projection de travail
   alimente uniquement le seuil quotidien ; elle ne devient jamais un exercice
   clos, un score annuel, une comparaison sectorielle ou un audit bancaire.
   ═══════════════════════════════════════════════════════════════════ */
var RC_ETAPE=1;
function recentToday(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function recentDateInput(id,label,value,help){return '<label class="f"><span>'+label+' <b class="ux-required">*</b></span><input id="'+id+'" type="date" value="'+esc(value||'')+'">'+(help?'<small>'+help+'</small>':'')+'</label>';}
function recentDays(a,b){var x=new Date(String(a||'')+'T12:00:00'),y=new Date(String(b||'')+'T12:00:00');if(isNaN(x.getTime())||isNaN(y.getTime())||y<x)return 0;return Math.floor((y-x)/86400000)+1;}
function recentStored(){return DB&&DB.recent&&DB.recent.raw?DB.recent.raw:{};}
function recentLire(){
  function s(id){return ((document.getElementById(id)||{}).value||'').trim();}
  function n(id){return num((document.getElementById(id)||{}).value);}
  return {name:s('rc-nom'),type:s('rc-type'),city:s('rc-ville'),opened:s('rc-open'),start:s('rc-start'),end:s('rc-end'),
    ca:n('rc-ca'),food:n('rc-nour'),drinks:n('rc-boi'),pack:n('rc-emb'),commission:n('rc-com'),tickets:n('rc-tickets'),
    vat:n('rc-tva'),daysWeek:n('rc-jsem'),months:n('rc-mois'),ticket:n('rc-panier'),payroll:n('rc-ms'),fte:n('rc-etp'),rent:n('rc-loy'),fixed:n('rc-cf')};
}
function recentCalc(r){
  var days=recentDays(r.start,r.end),openDays=Math.max(1,Math.round(days*Math.max(1,r.daysWeek||1)/7));
  var observedVariable=(r.food||0)+(r.drinks||0)+(r.pack||0)+(r.commission||0),variableRate=r.ca>0?observedVariable/r.ca:1;
  var activeDays=Math.max(1,(r.daysWeek||1)*4.33*(r.months||1)),caAnnual=r.ca>0?r.ca/openDays*activeDays:0;
  var ratio=function(v){return r.ca>0?Math.max(0,v||0)/r.ca:0;};
  var fixedMonthly=(r.payroll||0)+(r.rent||0)+(r.fixed||0),fixedAnnual=fixedMonthly*12;
  var thresholdAnnual=variableRate>=0&&variableRate<1?fixedAnnual/(1-variableRate):null;
  var periodFixed=fixedMonthly*(days/30.4375),partial=r.ca-observedVariable-periodFixed;
  var observedTicket=(r.tickets>0&&r.ca>0)?r.ca*(1+(r.vat||0)/100)/r.tickets:null;
  var ordersDay=(r.tickets>0)?r.tickets/openDays:(r.ticket>0?r.ca*(1+(r.vat||0)/100)/r.ticket/openDays:0);
  return {days:days,openDays:openDays,activeDays:activeDays,caAnnual:caAnnual,variableRate:variableRate,
    foodAnnual:caAnnual*ratio(r.food),drinksAnnual:caAnnual*ratio(r.drinks),packAnnual:caAnnual*ratio(r.pack),commissionAnnual:caAnnual*ratio(r.commission),
    fixedMonthly:fixedMonthly,fixedAnnual:fixedAnnual,thresholdAnnual:thresholdAnnual,thresholdMonth:thresholdAnnual==null?null:thresholdAnnual/Math.max(1,r.months),
    thresholdDay:thresholdAnnual==null?null:thresholdAnnual/activeDays,periodFixed:periodFixed,partial:partial,observedTicket:observedTicket,ordersDay:ordersDay};
}
function recentValidateIdentity(){
  if(!validateEstablishmentContext('rc'))return false;
  if(!valider([{id:'rc-open',nom:recentT('openingDate'),texte:true,ok:function(v){return /^\d{4}-\d{2}-\d{2}$/.test(v);}}],'rc-open'))return false;
  var r=recentLire();
  if(r.opened>recentToday()){
    champErr('rc-open',true);champsMsg('rc-open','<b>'+recentT('openingDate')+'</b> · '+recentT('identityNote'));toast(recentT('openingDate'));return false;
  }
  return true;
}
function recentValidateFacts(){
  var fields=[
    {id:'rc-start',nom:recentT('periodStart'),texte:true,ok:function(v){return /^\d{4}-\d{2}-\d{2}$/.test(v);}},
    {id:'rc-end',nom:recentT('periodEnd'),texte:true,ok:function(v){return /^\d{4}-\d{2}-\d{2}$/.test(v);}},
    {id:'rc-ca',nom:recentT('revenue'),ok:function(v){return v!=null&&v>0;}},
    {id:'rc-nour',nom:recentT('food'),ok:function(v){return v!=null&&v>=0;}},
    {id:'rc-boi',nom:recentT('drinks'),ok:function(v){return v!=null&&v>=0;}},
    {id:'rc-emb',nom:recentT('packaging'),ok:function(v){return v!=null&&v>=0;}},
    {id:'rc-com',nom:recentT('commissions'),ok:function(v){return v!=null&&v>=0;}}
  ];
  if(!valider(fields,'rc-start'))return false;
  var r=recentLire(),bad='';
  if(r.start<r.opened)bad='rc-start';else if(r.end<r.start||r.end>recentToday())bad='rc-end';
  if(bad){champErr(bad,true);champsMsg(bad,'<b>'+recentT(bad==='rc-start'?'periodStart':'periodEnd')+'</b> · '+recentT('samePeriod'));return false;}
  var raw=((document.getElementById('rc-tickets')||{}).value||'').trim();
  if(raw&&(r.tickets==null||r.tickets<0||Math.floor(r.tickets)!==r.tickets)){
    champErr('rc-tickets',true);champsMsg('rc-tickets','<b>'+recentT('tickets')+'</b> · '+recentT('ticketsHelp'));return false;
  }
  return true;
}
function recentValidateStructure(continuation){
  var fields=[
    {id:'rc-tva',nom:recentT('vat'),ok:function(v){return v!=null&&v>=0&&v<=30;}},
    {id:'rc-jsem',nom:recentT('daysWeek'),ok:function(v){return v!=null&&v>=1&&v<=7;}},
    {id:'rc-mois',nom:recentT('monthsYear'),ok:function(v){return v!=null&&v>=1&&v<=12;}},
    {id:'rc-panier',nom:recentT('averageTicket'),ok:function(v){return v!=null&&v>0;}},
    {id:'rc-ms',nom:recentT('payroll'),ok:function(v){return v!=null&&v>=0;}},
    {id:'rc-loy',nom:recentT('rent'),ok:function(v){return v!=null&&v>=0;}},
    {id:'rc-cf',nom:recentT('fixed'),ok:function(v){return v!=null&&v>=0;}}
  ];
  if(!valider(fields,'rc-tva'))return false;
  var r=recentLire(),raw=((document.getElementById('rc-etp')||{}).value||'').trim();
  if(raw&&(r.fte==null||r.fte<0)){champErr('rc-etp',true);champsMsg('rc-etp','<b>'+recentT('fte')+'</b>');return false;}
  var c=recentCalc(r),alerts=[];
  if(c.days<3)alerts.push(recentT('anomalyShort'));
  if((r.food+r.drinks+r.pack)===0)alerts.push(recentT('anomalyZeroMaterial'));
  if(r.payroll===0&&r.rent===0&&r.fixed===0)alerts.push(recentT('anomalyZeroFixed'));
  if(c.variableRate>=1)alerts.push(recentT('anomalyVariable'));
  if(c.observedTicket&&Math.abs(c.observedTicket-r.ticket)/r.ticket>.35)alerts.push(recentT('anomalyTicket'));
  var mat=(r.food||0)+(r.drinks||0)+(r.pack||0),annualResult=c.caAnnual-(c.variableRate*c.caAnnual)-c.fixedAnnual;
  var annualizedUnusual=c.caAnnual>0&&(
    c.caAnnual<1000||r.ticket>300||(c.ordersDay>0&&c.ordersDay<1)||c.ordersDay>500||
    (r.food>0&&r.food/r.ca>.80)||(r.rent*12/c.caAnnual>.20)||(r.payroll*12>c.caAnnual)||
    (mat/r.ca*c.caAnnual+r.payroll*12>c.caAnnual)||(annualResult/c.caAnnual>.30)||(annualResult/c.caAnnual<-.50)
  );
  if(annualizedUnusual)alerts.push(recentT('anomalyAnnualized'));
  var vals=[r.start,r.end,r.ca,r.food,r.drinks,r.pack,r.commission,r.tickets,r.vat,r.daysWeek,r.months,r.ticket,r.payroll,r.rent,r.fixed];
  return uxAlerte('recent','structure',recentT('anomalyTitle'),alerts,vals,continuation);
}
function recentEtape(n){
  if(n>RC_ETAPE&&RC_ETAPE===1&&!recentValidateIdentity())return;
  if(n>RC_ETAPE&&RC_ETAPE===2&&!recentValidateFacts())return;
  RC_ETAPE=n;try{sauverBrouillon('recent',n);}catch(e){}
  document.querySelectorAll('#refP .ux-step').forEach(function(x){x.hidden=(Number(x.getAttribute('data-step'))!==n);});
  var pr=document.getElementById('refProgress');if(pr)pr.innerHTML=uxProgress(n,3);
  if(n>=2)try{recentApercu();}catch(e){}uxHaut();
}
function recentApercu(){
  var boxes=document.querySelectorAll('#rc-preview-2,#rc-preview-3');if(!boxes.length)return;var r=recentLire();
  if(!(r.ca>0)||!r.start||!r.end){boxes.forEach(function(box){box.innerHTML='<b>'+recentT('partial')+'</b>'+recentT('samePeriod');});return;}
  var c=recentCalc(r),mat=(r.food||0)+(r.drinks||0)+(r.pack||0),ready=r.vat!=null&&r.daysWeek>0&&r.months>0&&r.ticket>0&&r.payroll!=null&&r.rent!=null&&r.fixed!=null;
  var html='<div class="ux-kicker">'+recentT('partial')+'</div><div class="autoline"><span class="k">'+recentT('revenue')+'</span><b>'+eur(r.ca)+'</b></div>'+
    '<div class="autoline"><span class="k">'+recentT('materialRatio')+'</span><b>'+(r.ca>0?fr(mat/r.ca*100,1)+' %':'—')+'</b></div>'+
    (ready?'<div class="autoline"><span class="k">'+recentT('partialBalance')+'</span><b style="color:'+(c.partial>=0?'#22c55e':'#ef4444')+'">'+eur(c.partial)+'</b></div>'+
      '<div class="autoline"><span class="k">'+recentT('monthThreshold')+'</span><b>'+(c.thresholdMonth==null?'—':eur(c.thresholdMonth))+'</b></div>':'')+
    '<p class="note" style="margin:9px 0 0">'+recentT('limit')+'</p>';
  boxes.forEach(function(box){box.innerHTML=html;});
  try{if(typeof window.verdictTrackMilestone==='function')window.verdictTrackMilestone('first_reading_visible',{mode:'recent',partial:true},'recent');}catch(e){}
}
function recentApply(){
  if(!recentValidateIdentity()){recentEtape(1);return;}
  if(!recentValidateFacts()){recentEtape(2);return;}
  if(!recentValidateStructure(function(){recentApply();}))return;
  var r=recentLire(),c=recentCalc(r);DB.in=DB.in||{};DB.reg=DB.reg||{};
  if(r.name)DB.etab=r.name;if(r.type)DB.etabType=r.type;DB.etabVille=r.city||'';DB.establishmentProfile=readPassport('rc');
  DB.in.panier=Math.round(r.ticket*100)/100;DB.in.tva=r.vat;DB.reg.tvac=r.vat;
  DB.in.cmdj=Math.round(c.ordersDay*1000)/1000;DB.in.jsem=r.daysWeek;DB.in.mois=r.months;DB.in.moisch=12;DB.in.obj=0;
  DB.in.nour=Math.round(c.foodAnnual*100)/100;DB.in.boi=Math.round(c.drinksAnnual*100)/100;DB.in.emb=Math.round(c.packAnnual*100)/100;
  DB.in.com=Math.round(c.commissionAnnual*100)/100;DB.in.autv=0;DB.in.dirb=0;DB.in.dirn=0;DB.in.dirt=0;
  DB.in.salb=r.payroll;DB.in.saln=(r.fte!=null&&r.fte>=0)?r.fte:0;DB.in.salt=0;DB.in.f1=r.rent;
  for(var i=2;i<=9;i++)DB.in['f'+i]=0;DB.in.f10=r.fixed;DB.in.annee=null;
  DB.recent={schema:1,raw:r,calculated:c,updatedAt:new Date().toISOString(),nature:'current-management-period',closed:false};
  DB.ref=null;DB.refSource={nature:'current-management-period',start:r.start,end:r.end,observed:true,projectedForDaily:true,documentVerified:false};DB.exerciseYear=null;
  DB.auditEvidence={period:'current',source:'management',docs:{}};DB.exempleCharge=false;DB.projetOuvert=true;DB.userMode='recent';DB.onboardingDone=false;
  DB.dataProvenance={nature:'client_observed_current_period',source:'management-manual',period:r.start+'/'+r.end,confidence:'provisional',verificationLevel:'provisional-manual',documentVerified:false,finalScoreAllowed:false};
  try{setMode('recent');}catch(e){}save();fillInputs();readInputs();confirmerAnomaliesAssistant();
  var R=moteur();if(!R||!R.ready){recentEtape(3);champsMsg('rc-tva','<b>'+recentT('engineCheck')+'</b>');return;}
  onboardingTerminer('recent');try{window.verdictTrackMilestone('recent_period_ready',{days:c.days,open_days:c.openDays,no_annual_score:true},'recent');}catch(e){}
  refClose();refreshAll();go('pil');toast(recentT('partial'));
}
