function estModeRecent(){try{return getMode()==='recent'&&DB&&DB.recent&&DB.recent.closed!==true;}catch(e){return false;}}
function recentRecordedDays(){
  try{return (DB.histJour||[]).filter(function(x){return x&&x.date&&x.est!==true&&x.caJ!=null;}).length;}catch(e){return 0;}
}
function recentAgeDays(){
  try{return Math.max(0,Math.floor((Date.now()-new Date(DB.recent.updatedAt).getTime())/86400000));}catch(e){return 999;}
}
function recentReliability(){
  var n=recentRecordedDays(),key=n<3?'insuffisante':(n<7?'faible':'moyenne');
  return {days:n,key:key,label:(typeof pilPoint1T==='function'?pilPoint1T(key):key)};
}
