/* La visite demande une preuve à la fois. Injecter les vingt chapitres du
   rapport derrière son guide bloquait Safari plusieurs secondes sans rien
   montrer de plus. Ces trois rendus sont des extraits du même moteur ; la vue
   Audit complète reste intacte et sera construite dès son ouverture libre. */
function auDemoAuditPartialHTML(R,hint){
  if(hint==='money'){
    var premium=auditPremiumCalc(R),quality=auDonnees();
    return '<div class="au-wrap">'+auMoney100HTML(R,premium,quality)+'</div>';
  }
  var impact=auImpactPrioritaire(),z=zone(R.score),name=esc((DB&&DB.etab)||'Mon établissement');
  if(hint==='audit'){
    var data=auDonnees(),actions=auActions();
    return '<div class="au-wrap"><div class="au-sc vu" id="auDemoSummary" style="--zc:'+z.h+'">'+
      '<div class="au-tag">Audit Premium Verdict® · aperçu guidé</div><h1 class="au-h">'+name+' · '+Math.round(R.score)+'/100</h1>'+
      '<p class="au-p">Le rapport complet relie les chiffres, les preuves, les limites et un plan de 90 jours en 20 chapitres. Cet aperçu utilise exactement le même moteur.</p>'+
      '<div class="au-card"><span class="au-k">Résultat avant impôt</span><div class="au-eur">'+eur(R.d.res)+'</div><p class="au-p">'+pct(R.v.rn)+' du chiffre d’affaires HT sur les postes saisis.</p></div>'+
      '<div class="au-card"><span class="au-k">Première décision</span><b>'+esc(impact.priority&&impact.priority.diagnosis||impact.title)+'</b><p class="au-p">'+esc(impact.explanation)+'</p></div>'+
      '<div class="au-card"><span class="au-k">Contrat de preuve</span><b>'+data.pct+' % des données économiques présentes · '+actions.length+' action'+(actions.length>1?'s':'')+' maximum dans le plan actif</b><p class="note">Une étape ne devient mesurée qu’après une nouvelle donnée datée et comparable.</p></div></div></div>';
  }
  if(hint==='exports'){
    return '<div class="au-wrap"><div class="au-sc vu" id="auExports" style="--zc:'+z.h+'"><div class="au-tag">Transmettre le Verdict</div>'+
      '<h1 class="au-h">Quatre sorties, sans recalcul différent</h1><p class="au-p">Chaque document conserve les mêmes chiffres et adapte uniquement la profondeur au destinataire.</p>'+
      '<div class="au-card"><div class="au-ok"><span>Audit Premium complet</span><b>20 chapitres</b></div><div class="au-ok"><span>Dossier comptable</span><b>Rapprochement</b></div><div class="au-ok"><span>Banque / associé</span><b>Pièces et limites</b></div><div class="au-ok"><span>Rapport exécutif</span><b>1 page</b></div></div>'+
      '<button class="btn" onclick="auExporter()">Choisir mon export</button><p class="note">Les exports restent des aides au pilotage : ils ne certifient ni les comptes, ni une capacité de remboursement.</p></div></div>';
  }
  return '';
}

function drawAudit(){
  var el=document.getElementById('auditBody'); if(!el)return;
  if(typeof estModeRecent==='function'&&estModeRecent()){el.innerHTML='<div class="au-wrap">'+recentGateHTML()+'</div>';return;}
  var _auditUiLocale=String(typeof LOCALE==='string'?LOCALE:'fr');
  if(_auditUiLocale!=='fr')LOCALE='fr';
  var R=moteur();
  if(!R||!R.ready){ el.innerHTML='<div class="au-wrap"><div class="au-sc"><h1 class="au-h">L\u2019audit a besoin de vos chiffres</h1>'+
    '<p class="au-p">Compl\u00e9tez votre r\u00e9f\u00e9rence \u00e9conomique, puis revenez : l\u2019audit se construira tout seul.</p>'+
    '<button class="btn" onclick="go(\'in\')">Compl\u00e9ter mes chiffres</button></div></div>'; LOCALE=_auditUiLocale;return; }
  var _demoAuditHint=typeof VERDICT_DEMO_RENDER_HINT==='string'?VERDICT_DEMO_RENDER_HINT:'';
  if(_demoAuditHint==='money'||_demoAuditHint==='audit'||_demoAuditHint==='exports'){
    var _demoAuditHTML=auDemoAuditPartialHTML(R,_demoAuditHint);
    if(_demoAuditHTML){VERDICT_PARTIAL_VIEW_RENDER=true;el.setAttribute('data-verdict-demo-partial',_demoAuditHint);el.innerHTML=_demoAuditHTML;LOCALE=_auditUiLocale;return;}
  }
  el.removeAttribute('data-verdict-demo-partial');
  var d=R.d,v=R.v,z=zone(R.score),h='',lim=auFaible(R),impact=auImpactPrioritaire(),dq=auDonnees(),P=auditPremiumCalc(R),dm=auDossierMode(),sim=verdictScoreIsSimulation(R),truth=verdictScoreTruth(R);

  /* ── 1. Le verdict immédiat ─────────────────────────────── */
  var phrase;
  if(!truth.final){
    var _lectureSujet=sim?'Cette simulation':('Cette lecture '+verdictScoreText('short',R).toLowerCase());
    if(v.rn<0) phrase=_lectureSujet+' décrit une structure déficitaire.';
    else if(v.rn<5) phrase=_lectureSujet+' décrit une structure positive, mais trop fragile pour encaisser un coup dur.';
    else if(v.rn<8) phrase=_lectureSujet+' décrit une structure rentable, mais encore fragile.';
    else phrase=_lectureSujet+' décrit une structure rentable et solide.';
  }else if(v.rn<0) phrase='Votre \u00e9tablissement perd de l\u2019argent.';
  else if(v.rn<5) phrase='Votre \u00e9tablissement gagne de l\u2019argent, mais trop peu pour encaisser un coup dur.';
  else if(v.rn<8) phrase='Votre \u00e9tablissement est rentable, mais il reste fragile.';
  else phrase='Votre \u00e9tablissement est rentable et tient debout.';
  var _ap=auProfil(), _ac=auCtxEtat(), _an=esc((DB&&DB.etab)||'Mon établissement');
  /* La couverture nomme déjà explicitement simulation, période et source :
     ne pas ajouter un second avertissement avant elle. Sur mobile, ce doublon
     consommait une grande partie du premier écran sans information nouvelle. */
  h+='<div class="au-sc" style="--zc:'+z.h+'"><div class="au-cover">'+
    '<div class="au-tag">'+(!truth.final?esc(verdictScoreText('label',R))+' · ':'')+'Audit Premium Verdict\u00ae \u00b7 '+new Date().toLocaleDateString(localeTag())+'</div>'+
    '<div class="au-big" style="color:'+z.h+'">'+Math.round(R.score)+'<small> /100'+(!truth.final?' · '+esc(verdictScoreText('short',R)).toLowerCase():'')+'</small></div>'+
    '<h1 class="au-h" style="margin-top:16px">'+phrase+'</h1>'+
    '<p class="au-p">'+(!truth.final?(sim?'Un scénario illustratif construit à partir d’estimations sectorielles. Il ne décrit pas un dossier client réel.':'Une lecture de pilotage non finale construite pour <b>'+_an+'</b>. Sa période, sa source ou sa clôture doivent encore être confirmées.'):'Un dossier construit pour <b>'+_an+'</b>, à partir de ses données, de son modèle déclaré et de ses réponses terrain.')+'</p>'+
    '<div class="au-cover-grid">'+
      '<div class="au-cover-chip"><b>Modèle</b>'+esc(_ap.format)+'</div>'+
      '<div class="au-cover-chip"><b>Profondeur</b>20 chapitres · 4 exports</div>'+
      '<div class="au-cover-chip"><b>Dossier</b>'+esc(dm.lib)+'</div>'+
      '<div class="au-cover-chip"><b>Statut</b>Audit calculé</div>'+
    '</div></div>'+auAuditLanguageNoteHTML(_auditUiLocale)+
    '<div class="au-direct-ready" role="status"><span class="au-direct-badge">AUDIT DISPONIBLE</span><b>Vous avez déjà le verdict, son explication et la première décision.</b>'+
      '<p>Les questions terrain apparaissent plus loin, après les preuves. Elles sont facultatives et servent uniquement à départager les causes possibles.</p>'+
      '<div class="au-direct-steps"><span><i>1</i>Verdict</span><span><i>2</i>Pourquoi</span><span><i>3</i>Action</span></div></div>'+
    '<div class="au-card"><span class="au-k">'+esc(impact.title)+'</span>'+
      '<div style="margin-bottom:5px">'+auBadge(impact.kind==='scenario'?'scenario':(impact.kind==='data_refresh'||impact.kind==='none'?'missing':'calc'),impact.kind==='scenario'?'Scénario':(impact.kind==='data_refresh'||impact.kind==='none'?'Donnée / décision':'Calcul moteur'))+'</div>'+
      '<div class="au-eur" style="color:'+(impact.kind==='scenario'?'#b45309':'var(--txt)')+'">'+esc(impact.value)+'</div>'+
      '<p class="au-p" style="margin:8px 0 0;font-size:14px">'+esc(impact.explanation)+'</p></div>'+
    '<div class="au-card"><span class="au-k">Ce qui vous freine le plus</span>'+
      '<b style="font-size:19px">'+AU_LIB[lim].charAt(0).toUpperCase()+AU_LIB[lim].slice(1)+'</b>'+
      '<p class="au-p" style="margin:6px 0 0">'+auVal(v,lim)+' \u00b7 not\u00e9 '+R.s[lim]+'/100</p></div></div>';

  /* Offre : le verdict est pour tous, le détail appartient à l'abonnement. */
  if(typeof isPro==='function' && !isPro()){
    el.innerHTML='<div class="au-wrap">'+h+auMur()+'</div>';
    var _s=el.querySelectorAll('.au-sc');
    for(var _i=0;_i<_s.length;_i++)_s[_i].classList.add('vu');
    LOCALE=_auditUiLocale;
    return;
  }

  /* ── 2. Pourquoi Verdict dit cela ───────────────────────── */
  var ch=[];
  ch.push('Votre r\u00e9sultat avant imp\u00f4t repr\u00e9sente <b>'+pct(v.rn)+'</b> du chiffre d\u2019affaires.');
  ch.push('Il vous faut atteindre <b>'+pct(v.pm)+'</b> de votre chiffre d\u2019affaires avant de gagner le premier euro.');
  ch.push('Apr\u00e8s les co\u00fbts variables, il vous reste <b>'+pct(v.mc)+'</b> pour payer le reste.');
  if(v.ms>=35) ch.push('Vos salaires p\u00e8sent <b>'+pct(v.ms)+'</b> du chiffre d\u2019affaires.');
  if(v.fc>=30) ch.push('Votre co\u00fbt mati\u00e8re p\u00e8se <b>'+pct(v.fc)+'</b> du chiffre d\u2019affaires.');
  if(v.com>0) ch.push('Les commissions plateformes p\u00e8sent <b>'+pct(v.com)+'</b> du chiffre d\u2019affaires.');
  ch.push('<b>Conclusion : '+AU_LIB[lim]+' est ce qui commande votre r\u00e9sultat aujourd\u2019hui.</b>');
  h+='<div class="au-sc" style="--zc:'+z.h+'"><div class="au-tag">Le raisonnement</div>'+
    '<h2 class="au-h">Pourquoi Verdict dit cela</h2><ul class="au-chain">'+
    ch.map(function(x,i){ return '<li'+(i===ch.length-1?' class="fin"':'')+'>'+x+'</li>'; }).join('')+'</ul></div>';

  /* ── 3. Autopsie financière en montants absolus ── */
  h+=auStructurePremiumHTML(R,P);

  /* ── 4. Où part l'argent (sur 100 €) ────────────────────── */
  h+=auMoney100HTML(R,P,dq);

  /* ── 5. Le problème principal ───────────────────────────── */
  /* Profondeur Premium : seuil, productivité, secteur, carte, canaux et prix.
     Chaque chapitre reste présent même si une donnée facultative manque. */
  h+=auSeuilPremiumHTML(R,P)+auProductivitePremiumHTML(R,P)+auSecteurPremiumHTML(R,P)+
     auCartePremiumHTML(R,P)+auCanauxPremiumHTML(R,P)+auPrixPremiumHTML(R,P);

  var cons, quoi;
  if(lim==='pm'||lim==='sen'){ cons='Une mauvaise semaine suffit \u00e0 effacer le r\u00e9sultat du mois.'; quoi='Faire baisser les charges fixes ou remonter la marge par ticket \u2014 le volume seul ne suffira pas.'; }
  else if(lim==='ms'||lim==='pc'){ cons='Chaque heure travaill\u00e9e co\u00fbte plus que ce qu\u2019elle rapporte sur les créneaux ou services creux.'; quoi='Construire l’organisation sur les ventes r\u00e9elles, créneau par créneau.'; }
  else if(lim==='fc'){ cons='Chaque vente part avec une marge plus faible que celle annoncée par la fiche ou la carte.'; quoi='V\u00e9rifier les portions, les prix d\u2019achat et les fiches techniques.'; }
  else if(lim==='com'){ cons='Une part de chaque commande part avant m\u00eame de payer la mati\u00e8re.'; quoi='Ramener une partie du volume en direct, et v\u00e9rifier les prix pratiqu\u00e9s en livraison.'; }
  else { cons='Le r\u00e9sultat reste sous le rep\u00e8re de pilotage utilis\u00e9 par Verdict.'; quoi='Travailler la structure : c\u2019est elle qui d\u00e9cide, pas le volume.'; }
  var risque=(v.rn<8)?Math.round((8-v.rn)/100*d.ca):0;
  h+='<div class="au-sc" style="--zc:'+z.h+'"><div class="au-tag">Le probl\u00e8me principal</div>'+
    '<h2 class="au-h">'+AU_LIB[lim].charAt(0).toUpperCase()+AU_LIB[lim].slice(1)+'</h2>'+
    '<div class="au-card"><span class="au-k">Aujourd\u2019hui</span><b style="font-size:22px">'+auVal(v,lim)+'</b></div>'+
    '<div class="au-card"><span class="au-k">Ce que \u00e7a entra\u00eene</span><p class="au-p" style="margin:0">'+cons+'</p></div>'+
    (risque>0?'<div class="au-card"><span class="au-k">Écart au repère interne</span><p class="au-p" style="margin:0">Le calcul isole <b style="color:'+z.h+'">'+eur(risque)+'</b> entre le résultat actuel et le repère de pilotage Verdict de 8 %. Ce n’est ni une moyenne sectorielle ni un gain attendu.</p></div>':'')+
    '<div class="au-card" style="border-left:3px solid #22c55e"><span class="au-k">Ce qu\u2019il faut faire</span><p class="au-p" style="margin:0;color:var(--txt)">'+quoi+'</p></div></div>';

  h+=diagHTML();   /* les règles déclenchées, leurs causes, leurs questions */

  /* ── 6. Les preuves ─────────────────────────────────────── */
  var pr=[];
  pr.push('R\u00e9sultat avant imp\u00f4t / CA : '+pct(v.rn)+' \u2014 rep\u00e8re de pilotage Verdict : 8\u00a0%');
  pr.push('Chiffre minimum \u00e0 r\u00e9aliser : '+pct(v.pm)+' de votre chiffre d\u2019affaires');
  pr.push('Ce qui reste apr\u00e8s les co\u00fbts variables : '+pct(v.mc));
  pr.push('Co\u00fbt mati\u00e8re : '+pct(v.fc)+' \u00b7 cuisine + salaires : '+pct(v.pc));
  pr.push('R\u00e9sistance \u00e0 un coup dur : not\u00e9e '+R.s.sen+'/100');
  pr.push('Banque de France FIBEN, secteur 56 (2024) : taux d\u2019exc\u00e9dent brut global / CA HT m\u00e9dian 8,8\u00a0% \u2014 indicateur diff\u00e9rent du r\u00e9sultat Verdict');
  h+='<div class="au-sc"><div class="au-tag">Les preuves</div><h2 class="au-h">Sur quoi Verdict s\u2019appuie</h2>'+
    '<div class="au-card">'+pr.map(function(x){ return '<div class="au-ok"><span class="p" style="color:var(--mut2)">\u2022</span><span>'+x+'</span></div>'; }).join('')+'</div></div>';

  /* L'affinage terrain vient après le verdict et ses preuves. Il reste
     facultatif et n'est plus présenté comme une condition d'accès à l'audit. */
  h+=auCtxHTML(R);

  /* ── 9. Ce qui fonctionne déjà ──────────────────────────── */
  var bons=[]; for(var k in R.s){ if(R.s[k]>=75)bons.push(k); }
  bons.sort(function(a,b){ return R.s[b]-R.s[a]; });
  h+='<div class="au-sc"><div class="au-tag">Ce qui fonctionne d\u00e9j\u00e0</div><h2 class="au-h">'+
    (bons.length?'Ce que vous tenez bien':'Aucun indicateur en zone verte pour l\u2019instant')+'</h2>'+
    (bons.length?'<div class="au-card">'+bons.slice(0,5).map(function(k){
      return '<div class="au-ok"><span class="p">\u2713</span><span><b>'+AU_LIB[k].charAt(0).toUpperCase()+AU_LIB[k].slice(1)+'</b><br>'+
        '<span style="color:var(--mut)">'+auVal(v,k)+' \u00b7 not\u00e9 '+R.s[k]+'/100</span></span></div>'; }).join('')+'</div>'
      :'<p class="au-p">C\u2019est rare, et \u00e7a se corrige : commencez par le probl\u00e8me principal ci-dessus, les autres suivent souvent.</p>')+
    (bons.length?'<p class="au-p">Ces points-l\u00e0, on n\u2019y touche pas.</p>':'')+'</div>';

  /* ── 17. La qualité des données ─────────────────────────── */
  h+='<div class="au-sc"><div class="au-tag">Qualit\u00e9 des donn\u00e9es</div>'+
    '<h2 class="au-h">Complétude économique : '+dq.pct+' % · dossier '+esc(dq.level.toLowerCase())+'</h2>'+
    '<div class="au-jauge"><i style="width:'+dq.pct+'%"></i></div>'+
    (dq.manque.length?'<p class="au-p">Il manque : <b>'+dq.manque.join(', ')+'</b>. Chaque information ajout\u00e9e resserre l\u2019analyse.</p>'
      :'<p class="au-p">Toutes les informations \u00e9conomiques attendues sont renseign\u00e9es.</p>')+
    '<p class="au-p" style="font-size:14px">Journ\u00e9es enregistr\u00e9es ce mois-ci : '+dq.jours+'. Carte renseign\u00e9e : '+(dq.carte?'oui':'non')+'.</p>'+
    '<p class="note">Le pourcentage mesure uniquement les champs économiques présents. Il ne mesure ni exactitude, ni qualité des pièces, ni probabilité de réussite.</p>'+auEvidenceHTML(dq)+auCtxSummaryHTML(R)+'</div>';

  /* ── 18. Ce que Verdict ne sait pas ─────────────────────── */
  var ign=auLimitesReelles(R,dq);
  h+='<div class="au-sc"><div class="au-tag">Honn\u00eatet\u00e9</div><h2 class="au-h">Ce que Verdict ne sait pas</h2>'+
    '<p class="au-p">Un audit qui n\u2019a pas de zone d\u2019ombre est un audit qui ment. Voici les n\u00f4tres.</p>'+
    '<div class="au-card">'+ign.map(function(x){ return '<div class="au-ok"><span class="p" style="color:var(--mut2)">\u2014</span><span>'+x+'</span></div>'; }).join('')+'</div></div>';

  h+=auRisquesHTML(R)+auPlanHTML(R)+auRepriseHTML(R);

  /* ── Fin ────────────────────────────────────────────────── */
  h+='<div class="au-sc" id="auExports" style="--zc:'+z.h+'"><div class="au-tag">Verdict final</div>'+
    '<h2 class="au-h" style="font-size:26px">'+(impact.priority
      ? 'Une seule décision démarre maintenant : <span style="color:#168f43">'+esc(impact.priority.diagnosis||impact.priority.title||'la priorité n°1')+'</span>.'
      : 'Votre structure ne présente aucune urgence chiffrée aujourd’hui.')+'</h2>'+
    '<p class="au-p">'+esc(impact.title)+' : <b>'+esc(impact.value)+'</b>. '+esc(impact.explanation)+'</p>'+
    '<div class="au-cta"><button class="btn" onclick="go(\'priorities\')">Voir mes actions, une par une</button>'+
      '<button class="btn sec" style="margin-top:8px" onclick="auExporter()">Exporter ce rapport</button>'+
      '<p class="note" style="margin:8px 0 0;text-align:center">Quatre exports : Audit Premium complet, dossier comptable, dossier banque / associé et rapport exécutif d’une page.</p></div>'+
    '<p class="au-p" style="font-size:13px;text-align:center;margin-top:10px">Audit g\u00e9n\u00e9r\u00e9 le '+new Date().toLocaleDateString(localeTag())+
    ' \u00b7 statistiques de contexte Banque de France et INSEE, s\u00e9par\u00e9es des rep\u00e8res Verdict</p></div>';

  el.innerHTML='<div class="au-wrap">'+h+'</div>';
  auAuditClientOrder(el);auAnnoterSections();LOCALE=_auditUiLocale;
  /* Révélation lente au défilement — statique si le JS ou le mouvement est coupé. */
  var secs=el.querySelectorAll('.au-sc');
  var iosSansRaccord=!!(window.CSS&&CSS.supports&&CSS.supports('-webkit-touch-callout','none'));
  if(iosSansRaccord||!('IntersectionObserver' in window)||scReduced()){ for(var i=0;i<secs.length;i++)secs[i].classList.add('vu'); return; }
  var o=new IntersectionObserver(function(e){ e.forEach(function(x){ if(x.isIntersecting)x.target.classList.add('vu'); }); },{threshold:0.12});
  for(var j=0;j<secs.length;j++)o.observe(secs[j]);
  if(secs[0])secs[0].classList.add('vu');
  /* Filet : un défilement rapide ne doit jamais laisser un écran vide. */
  setTimeout(function(){ for(var k=0;k<secs.length;k++)secs[k].classList.add('vu'); },3000);
}

/* ═══ IMPORT CAISSE UNIVERSEL — CONTRAT MINIMAL ═══
   Une ligne par journée, trois données : date, CA TTC, tickets. Le détail
   article reste un import distinct et facultatif pour Carte/Inventaire. */
var DAILY_CSV_LOT=null;
function dailyCsvDate(v){
  var s=String(v==null?'':v).trim(),m,d;if(!s)return '';
  if(/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}/.test(s)){m=s.match(/^(\d{4})[-\/](\d{1,2})[-\/](\d{1,2})/);}
  else if(/^\d{1,2}[-\/.]\d{1,2}[-\/.]\d{4}/.test(s)){m=s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/);m=[m[0],m[3],m[2],m[1]];}
  else if(/^\d{5}(?:\.\d+)?$/.test(s)){d=new Date(Date.UTC(1899,11,30)+Number(s)*86400000);return isNaN(d.getTime())?'':d.toISOString().slice(0,10);}
  if(!m)return '';d=new Date(Number(m[1]),Number(m[2])-1,Number(m[3]));if(d.getFullYear()!=Number(m[1])||d.getMonth()!=Number(m[2])-1||d.getDate()!=Number(m[3]))return '';
  return String(m[1]).padStart(4,'0')+'-'+String(m[2]).padStart(2,'0')+'-'+String(m[3]).padStart(2,'0');
}
function dailyCsvColumns(head){
  var c={date:-1,ca:-1,tickets:-1};head.forEach(function(x,i){var h=point5Norm(x).replace(/ /g,'');
    if(c.date<0&&/^(date|jour|day|businessdate|closedate|datedecloture|journee)$/.test(h))c.date=i;
    else if(c.tickets<0&&/(nombredetickets|tickets|ticketcount|transactions|transactioncount|receipts|orders|commandes|nbtickets|nbcommandes)/.test(h))c.tickets=i;
    else if(c.ca<0&&/(cattc|chiffredaffairesttc|chiffredaffaires|ventesttc|totalttc|grosssales|netsales|salesincltax|turnover|recettetotale)/.test(h))c.ca=i;
  });return c;
}
function dailyCsvAnalyse(txt){
  var lines=String(txt||'').split(/\r?\n/).filter(function(x){return x.trim();}),out={ok:false,rows:[],errors:[],warnings:[],newRows:[],same:[],conflicts:[],fingerprint:''};
  if(lines.length<2){out.errors.push('Fichier vide ou sans données.');return out;}
  var sep=point5CsvSep(lines[0]),head=point5CsvRow(lines[0],sep),c=dailyCsvColumns(head);if(c.date<0||c.ca<0||c.tickets<0){out.errors.push('Colonnes requises introuvables : Date, CA TTC, Nombre de tickets.');return out;}
  var seen={},today=typeof point12Today==='function'?point12Today():new Date().toISOString().slice(0,10);
  lines.slice(1).forEach(function(line,n){var p=point5CsvRow(line,sep),date=dailyCsvDate(p[c.date]),ca=point5Number(p[c.ca]),tk=point5Number(p[c.tickets]),_num=function(x){/* R313 : même lecteur que le calcul ; milliers acceptés, ambigu refusé. */return point5Number(x)!==null;};
    if(!_num(p[c.ca])){out.errors.push('Ligne '+(n+2)+' : CA TTC vide ou illisible (jamais lu comme 0).');return;}if(!_num(p[c.tickets])){out.errors.push('Ligne '+(n+2)+' : nombre de tickets vide ou illisible (jamais lu comme 0).');return;}
    if(!date){out.errors.push('Ligne '+(n+2)+' : date illisible.');return;}if(date>today){out.errors.push('Ligne '+(n+2)+' : date future.');return;}if(seen[date]){out.errors.push('Ligne '+(n+2)+' : la date '+date+' apparaît deux fois dans le fichier.');return;}seen[date]=1;
    if(!(ca>=0)){out.errors.push('Ligne '+(n+2)+' : CA TTC invalide.');return;}if(!(tk>=0)||Math.floor(tk)!==tk){out.errors.push('Ligne '+(n+2)+' : tickets invalides.');return;}
    var row={date:date,jour:Number(date.slice(8)),caJ:Math.round(ca*100)/100,tkJ:tk,ca:null,tickets:null,source:'pos-csv',importedAt:new Date().toISOString()};out.rows.push(row);
    if(ca>0&&tk===0)out.warnings.push(date+' : CA positif avec 0 ticket.');if(ca===0&&tk>0)out.warnings.push(date+' : tickets positifs avec 0 € de CA.');
  });
  var vals=out.rows.map(function(x){return x.caJ;}).filter(function(x){return x>0;}).sort(function(a,b){return a-b;});if(vals.length>=5){var med=vals.length%2?vals[(vals.length-1)/2]:(vals[vals.length/2-1]+vals[vals.length/2])/2;out.rows.forEach(function(x){if(x.caJ>med*3)out.warnings.push(x.date+' : CA supérieur à 3× la médiane du fichier.');else if(x.caJ>0&&x.caJ<med*.25)out.warnings.push(x.date+' : CA inférieur au quart de la médiane du fichier.');});}
  out.rows.forEach(function(x){var old=(DB.histJour||[]).filter(function(y){return y&&y.date===x.date;})[0];if(!old)out.newRows.push(x);else if(Math.abs(Number(old.caJ)-x.caJ)<.01&&Number(old.tkJ)===x.tkJ)out.same.push(x);else out.conflicts.push({incoming:x,existing:old});});
  out.fingerprint=point5Hash(JSON.stringify(out.rows.map(function(x){return [x.date,x.caJ,x.tkJ];})));out.duplicate=(DB.dailyImports||[]).some(function(x){return x.fingerprint===out.fingerprint;});
  if(out.duplicate)out.errors.push('Ce fichier a déjà été importé.');out.ok=out.rows.length>0&&!out.errors.length;return out;
}
function dailyCsvPreview(){var t=document.getElementById('daily-csv-text'),e=document.getElementById('daily-csv-result'),b=document.getElementById('daily-csv-apply');if(!t||!e)return;DAILY_CSV_LOT=dailyCsvAnalyse(t.value);var r=DAILY_CSV_LOT,col=r.ok?'#22c55e':'#f97316',h='<b style="color:'+col+'">'+r.rows.length+' journée(s) lue(s)</b> · '+r.newRows.length+' nouvelle(s) · '+r.same.length+' déjà identique(s) · '+r.conflicts.length+' conflit(s)';if(r.ok)h+='<br><b style="color:#22c55e">Prêt à importer après votre validation.</b>';if(r.errors.length)h+='<br><b>À corriger :</b> '+r.errors.slice(0,4).map(esc).join(' · ');if(r.warnings.length)h+='<br><b style="color:#f97316">À vérifier sans blocage :</b> '+r.warnings.slice(0,4).map(esc).join(' · ');e.innerHTML='<p class="note" style="margin:9px 0">'+h+'</p>';if(b)b.disabled=!r.ok;}
function dailyCsvFile(inp){var f=inp.files&&inp.files[0];if(!f)return;var rd=new FileReader();rd.onload=function(){var t=document.getElementById('daily-csv-text');if(t){t.value=rd.result;dailyCsvPreview();}};rd.readAsText(f);}
var DAILY_GUIDED_ID=0,DAILY_PREVIEW_TIMER=null;
function dailyGuidedRowHTML(){DAILY_GUIDED_ID++;return '<div class="daily-guided-row g2" style="align-items:end;padding:9px 0;border-top:1px solid var(--line)"><label class="f"><span>Date de clôture</span><input class="daily-guided-date" type="date" max="'+new Date().toISOString().slice(0,10)+'" onchange="dailyGuidedChanged()"></label><label class="f"><span>CA TTC (€)</span><input class="daily-guided-ca" type="text" inputmode="decimal" autocomplete="off" placeholder="ex. 1250,50" oninput="dailyGuidedChanged()"></label><label class="f"><span>Nombre de tickets</span><input class="daily-guided-tickets" type="text" inputmode="numeric" autocomplete="off" placeholder="ex. 47" oninput="dailyGuidedChanged()"></label><button type="button" class="btn2" aria-label="Supprimer cette journée" onclick="dailyGuidedRemove(this)">Retirer</button></div>';}
function dailyGuidedAdd(){var e=document.getElementById('daily-guided-rows');if(e)e.insertAdjacentHTML('beforeend',dailyGuidedRowHTML());}
function dailyGuidedRemove(b){var r=b&&b.closest('.daily-guided-row');if(r)r.remove();dailyGuidedChanged();}
