function matNom(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
function matInventaireFrame(){try{var P=window.parent;if(!P)return null;for(var i=0;i<P.frames.length;i++){try{var f=P.frames[i];if(f!==window&&typeof f.inventaireDonneesMatiere==='function')return f;}catch(e){}}}catch(e){}return null;}
function matIsoJour(d){return new Date(d).toISOString().slice(0,10);}
/* Construit l'entrée du moteur depuis les données Inventaire (D) + fiches et volumes Verdict. Rien n'est écrit. */
/* ═══ R253 — VENTES PAR PLAT DATÉES (base du théorique matière) ═══════════════════
   Le théorique matière doit venir des ventes RÉELLES de la période, plat par plat et jour par jour.
   Source : export « ventes par article » de la caisse (CSV), puis connexion caisse quand elle existera.
   Règles : une vente non reliée à une fiche est signalée, jamais devinée ; absent ≠ zéro ; ré-import idempotent. */
function vdsNorm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();}
function vdsNum(v){ /* R313 : import ventes par article, lecture stricte. */ return verdictReadNumber(v,true); }
function vdsDate(v){var s=String(v||'').trim();var m=s.match(/^(\d{4})-(\d{2})-(\d{2})/);if(m)return m[1]+'-'+m[2]+'-'+m[3];
  m=s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})/);if(m){var y=m[3].length===2?'20'+m[3]:m[3],mo=('0'+m[2]).slice(-2),d=('0'+m[1]).slice(-2);
    var t=Date.parse(y+'-'+mo+'-'+d+'T12:00:00Z');if(!isFinite(t)||new Date(t).getUTCDate()!==+d)return null;return y+'-'+mo+'-'+d;}return null;}
/* Lecture d'un export caisse « ventes par article ». Colonnes reconnues par leur en-tête. Pur : aucune écriture. */
function vdsParse(text){
  var out={ok:false,lignes:[],ignorees:0,raisons:{},colonnes:null};
  var raw=String(text||'').replace(/^\ufeff/,'').split(/\r\n|\n|\r/).filter(function(l){return l.trim().length;});
  if(raw.length<2){out.raison='fichier-vide';return out;}
  var head=raw[0],sep=[';','\t',','].map(function(c){return [c,head.split(c).length];}).sort(function(a,b){return b[1]-a[1];})[0][0];
  function cells(l){var r=[],cur='',q=false;for(var i=0;i<l.length;i++){var ch=l[i];if(ch==='"'){if(q&&l[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(ch===sep&&!q){r.push(cur);cur='';}else cur+=ch;}r.push(cur);return r.map(function(x){return x.trim();});}
  var H=cells(head).map(vdsNorm),col={date:-1,article:-1,qte:-1,ca:-1};
  H.forEach(function(h,i){
    if(col.date<0&&/^(date|jour|day|fecha|data|datum)\b/.test(h))col.date=i;
    else if(col.article<0&&/(article|produit|plat|libelle|designation|item|product|nom)/.test(h))col.article=i;
    else if(col.qte<0&&/^(quantite|qte|qty|quantity|nombre|nb|vendus|ventes)\b/.test(h))col.qte=i;
    else if(col.ca<0&&/(^ca\b|montant|total|chiffre|ttc|\bht\b|amount|revenue)/.test(h))col.ca=i;});
  out.colonnes=col;
  if(col.date<0||col.article<0||col.qte<0){out.raison='colonnes-manquantes';return out;}
  for(var k=1;k<raw.length;k++){var c=cells(raw[k]),d=vdsDate(c[col.date]),a=c[col.article],q=vdsNum(c[col.qte]),ca=col.ca>=0?vdsNum(c[col.ca]):null;
    var why=!d?'date':!a?'article':(q==null||q<0)?'quantite':null;
    if(why){out.ignorees++;out.raisons[why]=(out.raisons[why]||0)+1;continue;}
    out.lignes.push({date:d,article:a,qte:q,ca:ca});}
  out.ok=out.lignes.length>0;if(!out.ok)out.raison='aucune-ligne-valide';
  return out;
}
/* Fusion idempotente : une même (date, article) remplace la précédente ; rien n'est additionné deux fois. */
function vdsMerge(existing,lignes,source){
  var map={},order=[];(existing||[]).forEach(function(s){var k=s.date+'|'+vdsNorm(s.article);if(!map[k])order.push(k);map[k]=s;});
  var added=0,replaced=0;(lignes||[]).forEach(function(l){var k=l.date+'|'+vdsNorm(l.article);if(map[k])replaced++;else{order.push(k);added++;}map[k]={date:l.date,article:l.article,qte:l.qte,ca:l.ca,source:source||'csv'};});
  return {ventes:order.map(function(k){return map[k];}),ajoutees:added,remplacees:replaced};
}
/* Relie une vente à un plat de la carte : identifiant, puis nom normalisé exact. Jamais d'approximation. */
function vdsResolve(article,plats){var n=vdsNorm(article);for(var i=0;i<(plats||[]).length;i++){var p=plats[i];if(p&&(p.id===article||vdsNorm(p.nom)===n))return p;}return null;}
/* Ventes de la période [debut, fin] et couverture face aux journées de CA connues. */
function vdsPeriode(debutISO,finISO,ventes,histJour){
  var a=String(debutISO).slice(0,10),b=String(finISO).slice(0,10),inP=function(d){return d>=a&&d<=b;};
  var vs=(ventes||[]).filter(function(s){return s&&inP(s.date)&&s.qte>=0;});
  var jVentes={},jCA={},caCaisse=0,caVentes=0,caVentesConnu=true;
  vs.forEach(function(s){jVentes[s.date]=1;if(typeof s.ca==='number')caVentes+=s.ca;else caVentesConnu=false;});
  (histJour||[]).forEach(function(r){var d=String(r&&r.date||'').slice(0,10);if(inP(d)&&typeof r.caJ==='number'&&r.caJ>0){jCA[d]=1;caCaisse+=r.caJ;}});
  var nCA=Object.keys(jCA).length,both=Object.keys(jCA).filter(function(d){return jVentes[d];}).length,nV=Object.keys(jVentes).length;
  var couv=nCA>0?both/nCA:null;
  return {ventes:vs,joursVentes:nV,joursCA:nCA,couvertureJours:couv,utilisable:vs.length>0&&(couv==null?nV>0:couv>=0.9),
    caVentes:caVentesConnu&&vs.length?caVentes:null,caCaisse:nCA?caCaisse:null,partCA:(caVentesConnu&&nCA&&caCaisse>0)?caVentes/caCaisse:null};
}
/* Démonstration uniquement : ventes FICTIVES jour par jour autour des volumes déclarés (jamais pour un vrai client). */
function vdsDemo(debutISO,finISO,plats,joursOuverts){
  var out=[],t0=Date.parse(String(debutISO).slice(0,10)+'T12:00:00Z'),t1=Date.parse(String(finISO).slice(0,10)+'T12:00:00Z');
  for(var t=t0;t<=t1;t+=864e5){var d=new Date(t).toISOString().slice(0,10);if(joursOuverts&&!joursOuverts[d])continue;
    (plats||[]).forEach(function(p,ix){var vol=Number(p.vol);if(!(vol>0))return;var h=0,key=d+'|'+(p.id||p.nom);for(var i=0;i<key.length;i++){h=(h*31+key.charCodeAt(i))>>>0;}
      var f=0.7+(h%600)/1000,q=Math.max(0,Math.round(vol/30.4375*f));if(q>0)out.push({date:d,article:p.nom,plat:p.id||null,qte:q,ca:null,source:'demo',fictif:true});});}
  return out;
}
/* Construit les ventes du moteur depuis les ventes datées. */
function vdsVersMoteur(E,ventes,plats){
  var nonRelies={};
  (ventes||[]).forEach(function(s){var p=s.plat?(plats||[]).filter(function(x){return x&&x.id===s.plat;})[0]:null;p=p||vdsResolve(s.article,plats);
    var art=p?'plat:'+(p.id||p.nom):'non-relie:'+s.article;if(!p)nonRelies[s.article]=(nonRelies[s.article]||0)+s.qte;
    E.ventes.push({article:art,qte:s.qte,date:s.date,ca:typeof s.ca==='number'?s.ca:(p&&typeof platHT==='function'?s.qte*platHT(p):0),source:s.source||'ventes-reelles'});});
  E.theoriqueSource='ventes-reelles';E.ventesNonReliees=nonRelies;
  return E;
}
/* Import depuis un fichier choisi dans l'Inventaire (appelé par la carte d'écart). */
function verdictDishSalesImport(text){
  var P=vdsParse(text);if(!P.ok)return {ok:false,raison:P.raison,ignorees:P.ignorees};
  var plats=(DB.plats||[]),nr={};P.lignes.forEach(function(l){if(!vdsResolve(l.article,plats))nr[l.article]=(nr[l.article]||0)+l.qte;});
  var M=vdsMerge(DB.dishSales||[],P.lignes,'csv');DB.dishSales=M.ventes;try{save('dish-sales-import');}catch(e){}
  var ds=P.lignes.map(function(l){return l.date;}).sort();
  return {ok:true,lignes:P.lignes.length,ajoutees:M.ajoutees,remplacees:M.remplacees,ignorees:P.ignorees,debut:ds[0],fin:ds[ds.length-1],nonRelies:Object.keys(nr)};
}
window.verdictDishSalesImport=verdictDishSalesImport;
window.VerdictDishSales={parse:vdsParse,merge:vdsMerge,resolve:vdsResolve,periode:vdsPeriode,demo:vdsDemo,versMoteur:vdsVersMoteur,norm:vdsNorm,num:vdsNum,date:vdsDate};
/* ═══ fin R253 ═══ */

/* ═══ P1 — JOURNAL DES PERTES (Pro) ═══════════════════════════════════════════
   Déclarer une perte en quelques secondes : produit, quantité, raison. Chaque perte entre dans l'écart
   EXPLIQUÉ du moteur matière (elle est déjà dans le réel : le stock a baissé), jamais retirée deux fois.
   Absent ≠ zéro : sans prix, la valeur est « inconnue », pas 0 €. Aucune accusation : une raison, pas un coupable. */
var VP_RAISONS=['gaspillage','casse','perime','erreur','retour','offert','repas','surproduction','autre'];
/* raison du restaurateur -> type compris par le moteur (EXPLIQUE = perte, casse, interne, repas-personnel, degustation) */
var VP_TYPE={gaspillage:'perte',casse:'casse',perime:'perte',erreur:'perte',retour:'perte',offert:'interne',repas:'repas-personnel',surproduction:'perte',autre:'perte'};
function vpNum(v){ /* R313 : lecture unique. */ return verdictReadNumber(v,false); }
function vpJour(d){var s=String(d||'').slice(0,10);if(!/^\d{4}-\d{2}-\d{2}$/.test(s))return null;var t=Date.parse(s+'T12:00:00Z');return isFinite(t)&&new Date(t).toISOString().slice(0,10)===s?s:null;}
/* Validation d'une déclaration (pur). */
function vpValider(x,produits){
  var e=[],p=null;(produits||[]).forEach(function(q){if(q&&q.id===x.produitId)p=q;});
  if(!p)e.push('produit');var q=vpNum(x.qte);if(q==null||q<=0)e.push('quantite');
  if(VP_RAISONS.indexOf(x.raison)<0)e.push('raison');if(!vpJour(x.date))e.push('date');
  return {ok:!e.length,erreurs:e,produit:p,qte:q};
}
/* Retrouve un produit depuis le texte saisi (nom exact ou « Nom (unité) »), jamais approché. */
function vpResoudre(texte,produits){var t=String(texte||'').replace(/\s*\([^)]*\)\s*$/,'').trim().toLowerCase();if(!t)return null;
  var r=null;(produits||[]).forEach(function(p){if(p&&String(p.name||'').trim().toLowerCase()===t)r=p;});return r;}
/* Mouvements du moteur pour une période (pur) : uniquement les pertes datées dans [debut, fin]. */
function vpMouvements(journal,debutISO,finISO,produits){
  var a=String(debutISO).slice(0,10),b=String(finISO).slice(0,10),ids={};(produits||[]).forEach(function(p){if(p)ids[p.id]=p;});
  return (journal||[]).filter(function(x){return x&&ids[x.produitId]&&x.date>=a&&x.date<=b&&vpNum(x.qte)>0;}).map(function(x){
    /* quantité saisie dans l'unité du produit : on laisse le moteur utiliser l'unité normalisée du produit */
    return {produit:x.produitId,type:VP_TYPE[x.raison]||'perte',qte:vpNum(x.qte),date:x.date,source:'journal-pertes',raison:x.raison};});
}
/* Synthèse d'une période par raison (pur) : valeur au prix connu du produit ; prix absent = valeur inconnue. */
function vpSynthese(journal,debutISO,finISO,produits){
  var a=String(debutISO).slice(0,10),b=String(finISO).slice(0,10),ids={};(produits||[]).forEach(function(p){if(p)ids[p.id]=p;});
  var par={},total=0,sansPrix=0,n=0;VP_RAISONS.forEach(function(r){par[r]={eur:0,n:0,sansPrix:0};});
  (journal||[]).forEach(function(x){if(!x||!ids[x.produitId]||x.date<a||x.date>b||!(vpNum(x.qte)>0))return;var p=ids[x.produitId],pr=p&&vpNum(p.price),r=par[x.raison]||par.autre;n++;r.n++;
    if(pr!=null&&pr>0&&(!x.unite||!p.unit||String(x.unite).toLowerCase()===String(p.unit).toLowerCase())){var v=vpNum(x.qte)*pr;r.eur+=v;total+=v;}else{r.sansPrix++;sansPrix++;}});
  var parts=VP_RAISONS.map(function(k){return {raison:k,eur:par[k].eur,n:par[k].n,sansPrix:par[k].sansPrix,part:total>0?par[k].eur/total:null};}).filter(function(x){return x.n>0;}).sort(function(x,y){return y.eur-x.eur;});
  return {total:total,declarations:n,sansPrix:sansPrix,parRaison:parts};
}
/* ---------- données réelles (Verdict) ---------- */
function vpProduits(){try{var F=matInventaireFrame();var D=F?F.inventaireDonneesMatiere():null;return (D&&D.produits)||[];}catch(e){return [];}}
function vpAujourdhui(){try{var k=verdictOperationalClock().key;if(vpJour(k))return k;}catch(e){}return new Date().toISOString().slice(0,10);}
function verdictPerteEnregistrer(x){
  var P=vpProduits(),v=vpValider(x,P);if(!v.ok)return {ok:false,erreurs:v.erreurs};
  DB.lossJournal=DB.lossJournal||[];var id='perte-'+Date.now().toString(36)+'-'+Math.floor(Math.random()*1e6).toString(36);
  DB.lossJournal.push({id:id,date:vpJour(x.date),produitId:v.produit.id,produitNom:v.produit.name,unite:v.produit.unit||null,qte:v.qte,raison:x.raison,creeLe:new Date().toISOString()});
  try{save('loss-journal');}catch(e){}
  return {ok:true,id:id};
}
function verdictPerteSupprimer(id){var L=DB.lossJournal||[],n=L.length;DB.lossJournal=L.filter(function(x){return x&&x.id!==id;});if(DB.lossJournal.length!==n){try{save('loss-journal-delete');}catch(e){}return true;}return false;}
/* Lecture du formulaire affiché dans l'Inventaire (document de l'Inventaire). */
function verdictPerteDepuisFormulaire(doc){
  var P=vpProduits(),txt=(doc.getElementById('vpProduit')||{}).value,p=vpResoudre(txt,P),zone=doc.getElementById('vpRaisons'),r=zone?zone.getAttribute('data-r'):'';
  var res=verdictPerteEnregistrer({produitId:p?p.id:null,qte:(doc.getElementById('vpQte')||{}).value,raison:r,date:(doc.getElementById('vpDate')||{}).value||vpAujourdhui()});
  if(!res.ok)return matT('vpErreur',{e:res.erreurs.map(function(k){return matT('vpE_'+k);}).join(', ')});
  return matT('vpOk',{q:String((doc.getElementById('vpQte')||{}).value),u:p.unit||'',p:p.name,r:matT('vpR_'+r)});
}
function vpEurTxt(v){var d=Math.abs(v)<100?2:0;try{return new Intl.NumberFormat(localeTag(),{style:'currency',currency:'EUR',minimumFractionDigits:d,maximumFractionDigits:d}).format(v);}catch(e){return v.toFixed(d)+' €';}}
/* Carte « Journal des pertes » insérée dans Inventaire > Analyse (sous l'écart matière). */
