  h+='<div style="display:flex;gap:6px;margin:0 0 6px"><input id="vpQte" inputmode="decimal" placeholder="'+aideEsc(matT('vpQtePh'))+'" style="flex:1;min-width:0;padding:10px;border-radius:10px"><input id="vpDate" type="date" value="'+today+'" max="'+today+'" style="flex:1;min-width:0;padding:10px;border-radius:10px"></div>';
