  h+='<button type="button" class="btn" id="vpEnregistrer" onclick="(function(){var F=typeof matiereVerdictFrame===\'function\'?matiereVerdictFrame():window;var m=F&&F.verdictPerteDepuisFormulaire?(typeof verdictEnFrancais===\'function\'?verdictEnFrancais(F,function(){return F.verdictPerteDepuisFormulaire(document);}):F.verdictPerteDepuisFormulaire(document)):\'\';try{if(m)F.toast(m);}catch(e){}try{drawStats();}catch(e){}})()">'+aideEsc(matT('vpEnregistrer'))+'</button>';
  h+='<p class="note" style="margin:10px 0 4px"><b>'+aideEsc(matT('vpPeriode',{a:matJourTxt(deb),b:matJourTxt(fin)}))+'</b> · '+aideEsc(S.declarations?matT('vpTotal',{v:vpEurTxt(S.total),n:S.declarations}):matT('vpAucune'))+(S.sansPrix?' · '+aideEsc(matT('vpSansPrix',{n:S.sansPrix})):'')+'</p>';
  S.parRaison.forEach(function(x){h+='<div class="note" style="display:flex;justify-content:space-between;gap:8px;padding:3px 0"><span>'+aideEsc(matT('vpR_'+x.raison))+' · '+x.n+'</span><b>'+(x.eur>0?aideEsc(vpEurTxt(x.eur))+(x.part!=null?' · '+Math.round(x.part*100)+'\u00a0%':''):aideEsc(matT('vpInconnue')))+'</b></div>';});
  var recentes=(DB.lossJournal||[]).slice(-8).reverse();
