  Object.keys(mensuel).sort().forEach(function(k){if(k<a||k>b)return;var m=mensuel[k]||{},v=(m.food||0)+(m.beverage||0)+(m.packaging||0);mois.push({mois:k,achats:v});tot+=v;});
  return mois.length?{mois:mois,total:tot,exact:a===b?false:false}:null;
