/* Démonstration uniquement : sans deux comptages détaillés, comptages FICTIFS simulés pour montrer le calcul (jamais pour un vrai client). */
function matSimulerDemo(D){
  var B=new Date(),A=new Date(B.getTime()-28*864e5),base={statut:'ok',site:D.site,debut:A.toISOString(),fin:B.toISOString(),produits:D.produits||[],lignesA:[],lignesB:[],receptions:[],fictif:true};
  var vdsJO={},vdsN=0;(DB.histJour||[]).forEach(function(r){if(r&&typeof r.caJ==='number'&&r.caJ>0){vdsJO[String(r.date).slice(0,10)]=1;}});Object.keys(vdsJO).forEach(function(d){if(d>=String(base.debut).slice(0,10)&&d<=String(base.fin).slice(0,10))vdsN++;});base.ventesPlats=vdsDemo(base.debut,base.fin,DB.plats||[],vdsN>=5?vdsJO:null);
  var E0=verdictMatiereEntreeInventaire(base),R0=VerdictMatiere.analyser(E0),dev=[0.09,-0.03,0.015,0.2,0.004],n=0;
  (D.produits||[]).forEach(function(p){var r=R0.produits[p.id],th=r&&r.theorique&&r.theorique.valeur;if(!(th>0)||E0.produits[p.id].horsPerimetre)return;
    var b=VerdictMatiere.versBase(1,E0.produits[p.id].unite,E0.produits[p.id]);if(!b.ok)return;var fin=th*0.3,deb=fin+th*(1+dev[n%dev.length]);
    var vdsR=E0.produits[p.id].unite==='piece'?function(x){return Math.round(x);}:function(x){return Math.round(x*1000)/1000;};base.lignesA.push({id:p.id,qty:vdsR(deb/b.valeur)});base.lignesB.push({id:p.id,qty:vdsR(fin/b.valeur)});n++;});
  return base;
}
