  if(R.achatsRecoupement&&R.achatsRecoupement.nonVerifie){R.verificationState='non_verifie';Object.keys(R.produits).forEach(function(k){var r=R.produits[k];if(r.statut==='hors-perimetre')return;r.confiance='faible';r.raisons.push('rapprochement-facture-reception-non-confirme');if(r.statut==='calcule')r.statut='non-interpretable-avec-confiance';r.decision={type:'verifier',motif:'reception-non-confirmee',controle:'recompter-le-stock',conclusion:'ecart-non-interpretable'};});}
