function matJourTxt(iso){try{return new Date(iso).toLocaleDateString(localeTag(),{day:'numeric',month:'long'});}catch(e){return String(iso).slice(0,10);}}
function matPct(v){return v==null?'—':Math.round(v*100)+'\u00a0%';}
function matCtrl(r){var c=r.decision&&r.decision.controle||'';return /conversion/.test(c)?matT('k_conv'):/fiche/.test(c)?matT('k_fiche'):/ventes/.test(c)?matT('k_ventes'):/recompter-le-stock/.test(c)?matT('k_recompter'):matT('k_portions');}
function matRaison(r){var x=r.raisons.join(' ');return /stock-(initial|final)/.test(x)?matT('r_stock'):/conversion/.test(x)?matT('r_conv'):matT('r_theo');}
/* Carte HTML (localisée) — insérée telle quelle dans l'Analyse de l'Inventaire */
function verdictMatiereCarteHTML(R){
  if(!R||R.statut==='indisponible')return '';
  var h='<div class="card" id="matiereEcart" style="margin-top:14px"><h3 style="margin:0 0 6px">'+aideEsc(matT('titre',{m:''}).replace(/\s*·\s*$/,''))+'</h3>';
  if(R.statut&&R.statut!=='ok'&&!R.statutGlobal)return vcCarteHTML(R)+h+'<p class="note">'+aideEsc(matT(R.statut==='courte'?'courte':'attente'))+'</p></div>'+vpCarteHTML(R);
  h+='<p class="note" style="margin:0 0 4px">'+aideEsc(matT('periodeInv',{a:matJourTxt(R.debutISO),b:matJourTxt(R.finISO),j:(Math.round(R.jours*10)/10).toLocaleString(localeTag())}))+'</p>';
  h+='<p class="note" style="margin:0 0 4px">'+aideEsc(matT('couv',{v:matPct(R.couverture.ventes.taux),s:matPct(R.couverture.stock.taux)}))+'</p>'+vdsSourceHTML(R);
  if(R.fictif)h+='<p class="note" style="margin:0 0 6px;color:#7DA2F5">'+aideEsc(matT('fictif'))+'</p>';
  function bloc(r){var e=r.ecart,s='<div class="mat-l" data-prod="'+aideEsc(r.id)+'" data-decision="'+aideEsc(r.decisionId||'')+'" style="padding:9px 0;border-top:1px solid rgba(255,255,255,.07)"><div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline"><b>'+aideEsc(r.nom)+'</b><span class="chip" style="white-space:nowrap">'+aideEsc(matT('d_'+(r.decision&&r.decision.type||'verifier')))+'</span></div>';
    if(e){s+='<p class="note" style="margin:3px 0 0">'+aideEsc(matT('ligne',{r:matQteAbs(r.reel.valeur,r.unite),t:matQteAbs(r.theorique.valeur,r.unite),e:matQte(e.brut,r.unite)}))+'</p>';
      if(e.valorisation)s+='<p class="note" style="margin:2px 0 0">'+aideEsc(matT('valeur',{v:eur(e.valorisation.residuel)}))+'</p>';
      if(!e.dansTolerance)s+='<p class="note" style="margin:2px 0 0">'+aideEsc(matT('cause'))+' '+aideEsc(matT('veraCtrl',{c:matCtrl(r)}))+'</p>';
      if(r.recurrence&&r.recurrence.memeSens>0)s+='<p class="note" style="margin:2px 0 0;color:#f59e0b">'+aideEsc(matT('recurrent',{n:r.recurrence.memeSens}))+'</p>';
      if(!e.dansTolerance&&!R.fictif){var dja=(DB.decisions||[]).some(function(x){return x&&x.id===r.decisionId&&(x.status==='testing'||x.status==='waiting');});s+=dja?'<p class="note" style="margin:4px 0 0;color:#22c55e">'+aideEsc(matT('suivie'))+'</p>':'<button type="button" class="btn ghost mat-suivre" style="margin-top:6px" onclick="(function(){var F=typeof matiereVerdictFrame===\'function\'?matiereVerdictFrame():window;if(F&&F.verdictMatiereSuivre)F.verdictMatiereSuivre(\''+aideEsc(r.id)+'\');try{drawStats();}catch(e){}})()">'+aideEsc(matT('suivre'))+'</button>';}
      var c=r.reel.composantes;s+='<details style="margin-top:4px"><summary class="note" style="cursor:pointer">'+aideEsc(matT('preuve'))+'</summary><p class="note" style="margin:4px 0 0">'+aideEsc(matT('pStock',{a:matQteAbs(c.stockInitial,r.unite),r:matQteAbs(c.entrees,r.unite),b:matQteAbs(c.stockFinal,r.unite),c:matQteAbs(r.reel.valeur,r.unite)}))+'</p><p class="note" style="margin:2px 0 0">'+aideEsc(matT(R.theoriqueSource==='ventes-reelles'?'pTheoReel':'pTheo',{t:matQteAbs(r.theorique.valeur,r.unite),j:(Math.round(R.jours*10)/10).toLocaleString(localeTag())}))+'</p><p class="note" style="margin:2px 0 0">'+aideEsc(matT('pMoteur',{m:R.version,e:String(R.empreinte).split(':').pop(),d:r.decisionId}))+'</p></details>';}
    else s+='<p class="note" style="margin:3px 0 0">'+aideEsc(matT('nonCalc',{raison:matRaison(r)}))+' '+aideEsc(matT('veraCtrl',{c:matCtrl(r)}))+'</p>';
    return s+'</div>';}
  var top=R.top.map(function(t){return R.produits[t.id];});top.forEach(function(r){h+=bloc(r);});
  var autres=Object.keys(R.produits).map(function(k){return R.produits[k];}).filter(function(r){return top.indexOf(r)<0&&r.statut!=='hors-perimetre';});
  if(autres.length)h+='<details style="margin-top:6px"><summary class="note" style="cursor:pointer">'+aideEsc(matT('tous',{n:autres.length+top.length}))+'</summary>'+autres.map(bloc).join('')+'</details>';
  if(R.horsFiche)h+='<p class="note" style="margin:8px 0 0">'+aideEsc(matT('horsFiche',{n:R.horsFiche}))+'</p>';
  return vcCarteHTML(R)+h+'</div>'+vpCarteHTML(R);
}
window.verdictMatiereDepuisInventaire=verdictMatiereDepuisInventaire;window.verdictMatiereCarteHTML=verdictMatiereCarteHTML;
/* Vera : « Où part ma matière ? » — le même calcul que l'écran Inventaire */
function veraReponseMatiere(question){
  var qq=String(question||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[’']/g,' ');
  if(!/(ou part ma matiere|ecart matiere|ecart de matiere|perte(s)? (de )?matiere|consommation theorique|theorique.*reel|material variance|where.*material|desviacion de materia|scostamento materia|materialabweichung|materiaalafwijking|desvio de materia)/.test(qq))return null;
  var R=verdictMatiereDepuisInventaire();if(!R||!R.statutGlobal){if(/(stock|inventaire|inventory|consommation|consumption|ecart matiere|ecart de stock|material gap)/.test(qq))return null;/* la réponse mensuelle en euros (R128) reprend la main */return {lignes:[matT(R&&R.statut==='courte'?'courte':'veraRienInv')]};}
  var ja=matJourTxt(R.debutISO),jb=matJourTxt(R.finISO),mt=ja+' – '+jb;
  var cal=R.top.map(function(t){return R.produits[t.id];}).filter(function(r){return r.ecart&&!r.ecart.dansTolerance;});
  if(!Object.keys(R.produits).some(function(k){return R.produits[k].ecart;}))return {lignes:[matT('veraRienInv')]};
  if(!cal.length){var bl=R.top.map(function(t){return R.produits[t.id];}).filter(function(r){return !r.ecart;});return {lignes:[matT('veraAucun',{m:mt})].concat(bl.length?[matT('veraCtrl',{c:matCtrl(bl[0])})]:[])};}
  var r=cal[0],e=r.ecart,out=[matT(e.brut>0?'veraConstatP':'veraSousP',{p:r.nom,e:matQteAbs(e.brut,r.unite),a:ja,b:jb})];
  if(e.valorisation)out.push(matT('valeur',{v:eur(e.valorisation.residuel)}));
  out.push(matT('veraQualite',{v:matPct(R.couverture.ventes.taux),c:matT('c_'+r.confiance)}));
  out.push(matT('cause'));out.push(matT('veraCtrl',{c:matCtrl(r)}));out.push(matT('estime'));if(R.fictif)out.push(matT('fictif'));
  return {lignes:out};
}

/* Décision matière dans le centre Décisions (même modèle que le suivi d'un plat ; identifiant = décision racine du moteur) */
function verdictMatiereSuivre(prodId){
  var R=verdictMatiereDepuisInventaire();if(!R||!R.statutGlobal||R.fictif)return null;var r=R.produits[prodId];if(!r||!r.ecart)return null;
  DB.decisions=DB.decisions||[];if(DB.decisions.some(function(x){return x&&x.id===r.decisionId&&(x.status==='testing'||x.status==='waiting');}))return null;
  var today=typeof point12Today==='function'?point12Today():new Date().toISOString().slice(0,10),review=typeof point12DateAdd==='function'?point12DateAdd(today,30):today;
  var rec={version:'12.3',trackingId:'D12_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),kind:'material',status:'testing',date:today,startedAt:new Date().toISOString(),reviewDate:review,
    id:r.decisionId,produitId:prodId,lib:'Matière — '+r.nom,action:matCtrl(r),metricKey:'material:'+prodId,
    baseline:{measure:{periode:{debut:R.periode.debut,fin:R.periode.fin},reel:r.reel.valeur,theorique:r.theorique.valeur,ecart:r.ecart.residuel,unite:r.unite,valeur:r.ecart.valorisation?r.ecart.valorisation.residuel:null,confiance:r.confiance,moteur:R.version,empreinte:R.empreinte}},
    expected:{kind:'material_variance',annual:0,amount:0,assumption:'Suivi de l’écart matière : vérification puis nouvelle mesure, pas un montant promis.'},
    est:0,profile:String(DB.etabType||''),establishmentId:typeof point12EstablishmentId==='function'?point12EstablishmentId():null,confidence:r.confiance,volume:null};
  DB.decisions.push(rec);try{save();}catch(e){}try{toast(matT('suivie'));}catch(e){}return rec;
}
