function fouT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=FOU_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,n){return v[n]!=null?v[n]:'';});}
function fouUnite(u){u=String(u||'').toLowerCase().trim();if(/^(kg|kilo)/.test(u))return 'kg';if(u==='g'||u==='gr')return 'g';if(/^(l|litre|liter)$/.test(u))return 'L';if(u==='cl')return 'cl';if(u==='ml')return 'ml';if(/^(u|unite|unité|pc|pce|piece|pièce|pieces)$/.test(u))return 'piece';if(/^(bouteille|btl)$/.test(u))return 'bouteille';return u;}
function fouNb(v,d){return (Math.round(v*Math.pow(10,d))/Math.pow(10,d)).toLocaleString(localeTag(),{minimumFractionDigits:d,maximumFractionDigits:d});}
function fouPrix(v,u){return fouNb(v,2)+'\u00a0€/'+u;}
function fouJour(d){try{return new Date(d+'T12:00:00Z').toLocaleDateString(localeTag(),{day:'numeric',month:'long',timeZone:'UTC'});}catch(e){return d;}}
function verdictFournisseursAnalyse(){
  if(!window.VerdictFournisseurs)return null;var FV=VerdictFournisseurs,op=verdictOperationalClock(),auj=op.civilKey,ilya=function(n){var d=new Date(Date.parse(auj+'T12:00:00Z')-n*864e5);return d.toISOString().slice(0,10);};
  var lignes=(typeof achLignes==='function'?achLignes():(DB.achats||[])).filter(function(l){return l&&l.d&&String(l.d).slice(0,10)>=ilya(365)&&String(l.d).slice(0,10)<=auj;});
  var docs={},noms={};lignes.forEach(function(l,i){var f=String(l.four||'—'),d=String(l.d).slice(0,10),k=f+'|'+d;var doc=docs[k]=docs[k]||{id:k,fournisseur:f,date:d,etablissementId:'etab',lignes:[]};var p=achCle(l.art);noms[p]=l.art;
    doc.lignes.push({id:'l'+i,produit:p,quantite:Number(l.qte),unite:fouUnite(l.unite),prixUnitaire:(l.pu===null||l.pu===undefined||l.pu==='')?null:Number(l.pu),conditionnement:l.cond||null});});
  var D=Object.keys(docs).map(function(k){return docs[k];}),paires={},bloques=0,n=0;
  try{var FI=typeof matInventaireFrame==='function'?matInventaireFrame():null,TI=FI&&FI.inventaireDonneesFournisseurs?FI.inventaireDonneesFournisseurs():null;
    (TI&&TI.historique||[]).forEach(function(h,i){if(!h||!h.fournisseur||h.avant==null||h.apres==null||!(String(h.date)>=ilya(365)&&String(h.date)<=auj))return;var pr=achCle(h.produitNom);noms[pr]=noms[pr]||h.produitNom;var veille=new Date(Date.parse(h.date+'T12:00:00Z')-864e5).toISOString().slice(0,10);
      [[veille,h.avant,'a'],[h.date,h.apres,'b']].forEach(function(x){D.push({id:'inv-tarif-'+i+x[2],fournisseur:h.fournisseur,date:x[0],type:'tarif',source:'inventaire-tarif',etablissementId:'etab',lignes:[{id:'t'+i+x[2],produit:pr,quantite:1,unite:fouUnite(h.unite),prixUnitaire:Number(x[1])}]});});});}catch(e){}
  D.forEach(function(doc){doc.lignes.forEach(function(l){if(doc.source!=='inventaire-tarif')n++;var r=FV.normaliser(l,doc);if(r.statut!=='ok'&&r.statut!=='avoir')bloques++;paires[l.produit+'||'+doc.fournisseur]=1;});});
  var sujets=[],offres={};
  Object.keys(paires).forEach(function(k){var p=k.split('||')[0],f=k.split('||')[1],h=FV.historique(D,p,f,'etab'),v=FV.variation(h,{aujourdhui:auj});
    var last=h.points[h.points.length-1];if(last)(offres[p]=offres[p]||[]).push({fournisseur:f,prixNormalise:last.prixNormalise,unite:last.unite,date:last.date});
    if(!v||!(v.statut==='confirmee'||v.statut==='ponctuelle-a-confirmer'||v.statut==='erreur-potentielle-a-verifier')||!v.absolue)return;
    var vol90=h.points.filter(function(x){return x.date>=ilya(90)&&x.source!=='inventaire-tarif';}).reduce(function(s,x){return s+x.quantiteBase/(x.unite==='pièce'?1:1000);},0),volM=vol90/3;
    var usages=[];(DB.plats||[]).forEach(function(pl){(pl.rec||[]).forEach(function(r){var lien=(DB.achatLiens||{})[noms[p]];if(achCle(r[0])!==p&&!(lien&&achCle(lien)===achCle(r[0])))return;var g=typeof ingByName==='function'?ingByName(r[0]):null;
      usages.push({recette:pl.nom,qte:Number(r[1]),unite:g&&g.type==='UNITE'?'piece':(v.unite==='L'?'ml':'g'),volumeFutur:Number(pl.vol)>0?Number(pl.vol):null});});});
    sujets.push({id:p,produit:noms[p],fournisseur:f,variation:v,variationUnitaire:v.absolue,volumeMensuel:volM,impact:FV.impact(v.absolue,v.unite==='pièce'?'piece':v.unite,usages),effectId:FV.idEffet('etab',p,v.dateEffet),decisionId:FV.idDecision('etab',p)});});
  var P=FV.prioriser(sujets),dep=FV.dependance(lignes.filter(function(l){return String(l.d).slice(0,10)>=ilya(90);}).map(function(l){return {fournisseur:String(l.four||'—'),montant:Number(l.qte)*Number(l.pu)};}));
  return {version:FV.version,lignes:n,bloques:bloques,sujets:sujets,top:P.top,nb:P.nb,dependance:dep,offres:offres,noms:noms};
}
