function fouRT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=FOU_RDT_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,x){return v[x]!=null?v[x]:'';});}
function fouPropre(x){return String(x||'').replace(/['\\"]/g,'').trim();}
function fouRdtCle(p,f){return fouPropre(p).toLowerCase()+'|'+fouPropre(f).toLowerCase();}
function fouRdFiche(prod){var g=typeof ingByName==='function'?ingByName(prod):null;return g?1-Math.min(95,Math.max(0,Number(g.perte)||0))/100:null;}
function fouRendement(p,f,rdFiche){var x=(DB.rendementsFournisseur||{})[fouRdtCle(p,f)];if(x&&x.pct>0&&x.pct<=100)return {valeur:x.pct/100,source:'fournisseur',at:x.at};return rdFiche?{valeur:rdFiche,source:'fiche'}:null;}
function verdictFournisseurRendement(p,f,val){DB.rendementsFournisseur=DB.rendementsFournisseur||{};var k=fouRdtCle(p,f),t=String(val==null?'':val).trim();if(t===''){if(DB.rendementsFournisseur[k]){delete DB.rendementsFournisseur[k];try{save();}catch(e){}}return 'efface';}
  var n=Number(t.replace(',','.'));if(!(n>0&&n<=100))return 'err';var prev=DB.rendementsFournisseur[k];if(prev&&prev.pct===n)return 'same';DB.rendementsFournisseur[k]={pct:n,at:new Date().toISOString(),precedent:prev?prev.pct:null};try{save();}catch(e){}return 'ok';}
function fouComparaison(s,R){var o=(R.offres[s.id]||[]).slice();if(!o.length)return null;var rd=fouRdFiche(s.produit),u=o[0].unite;o=o.filter(function(x){return x.unite===u;});
  var L=o.map(function(x){var r=fouRendement(s.produit,x.fournisseur,rd);return {fournisseur:x.fournisseur,prixNormalise:x.prixNormalise,rendement:r?r.valeur:null,source:r?r.source:null};});
  if(L.some(function(x){return x.rendement==null;}))return {sansRdt:true};var C=VerdictFournisseurs.comparer(L.map(function(x){return {fournisseur:x.fournisseur,prixNormalise:x.prixNormalise,rendement:x.rendement,unite:u};}),{unite:u}),by={};L.forEach(function(x){by[x.fournisseur]=x;});
  return {unite:u,comparables:C.comparables.map(function(c){var x=by[c.fournisseur]||{};return {fournisseur:c.fournisseur,prixUtilisable:c.prixUtilisable,rendement:x.rendement,source:x.source};})};}
function fouRdtHTML(s){var R=verdictFournisseursAnalyse();if(!R||!R.offres)return '';var K=fouComparaison(s,R);if(!K)return '';var h='<div class="fou-rdt-bloc" style="margin:6px 0 0">';
  if(K.sansRdt)h+='<p class="note" style="margin:2px 0">'+aideEsc(fouRT('rdtNo'))+'</p>';
  else{h+='<p class="note" style="margin:2px 0;font-weight:600">'+aideEsc(fouRT('rdtT'))+'</p>';K.comparables.forEach(function(c){h+='<p class="note" style="margin:1px 0">'+aideEsc(fouRT('rdtL',{f:c.fournisseur,u:fouPrix(c.prixUtilisable,K.unite),r:Math.round(c.rendement*1000)/10+'\u00a0%',src:fouRT(c.source==='fournisseur'?'src_f':'src_fi')}))+'</p>';});}
  var cur=(DB.rendementsFournisseur||{})[fouRdtCle(s.produit,s.fournisseur)];
  h+='<label style="display:block;font-size:12px;margin-top:4px">'+aideEsc(fouRT('rdtIn',{f:s.fournisseur}))+' <input class="fou-rdt" inputmode="decimal" value="'+(cur?cur.pct:'')+'" style="width:70px"></label>';
  h+='<button type="button" class="btn ghost fou-rdt-btn" style="margin-top:4px" onclick="(function(b){var F=typeof matiereVerdictFrame===\'function\'?matiereVerdictFrame():window;var i=b.parentNode.querySelector(\'.fou-rdt\');if(F&&F.verdictFournisseurRendement)F.verdictFournisseurRendement(\''+aideEsc(fouPropre(s.produit))+'\',\''+aideEsc(fouPropre(s.fournisseur))+'\',i.value);try{drawStats();}catch(e){}})(this)">'+aideEsc(fouRT('rdtBtn'))+'</button>';
  return h+'</div>';}
