    var _avM=JSON.parse(JSON.stringify(DB.factureMemoire||{}));DB.factureMemoire=VerdictFacturesXML.memoriser(DB.factureMemoire||{},f,validations);try{reglesJournaliser('facture',_avM,DB.factureMemoire);}catch(_j){}
