  function repartirService(coutGlobal,cleService,cleTotal,direct){var C=num(coutGlobal),s=num(cleService),t=num(cleTotal);if(C==null||s==null||t==null||t<=0)return {statut:'non-calculable'};
    return {statut:'calcule',coutDirect:num(direct),coutReparti:C*s/t,cle:'heures',coutAttribue:(num(direct)||0)+C*s/t,coutEvitable:null,note:'coût attribué ≠ coût évitable : l’évitable dépend des contrats, réaffectations et minimums.'};}
  /* 15.68, 15.72–15.74 : simulation d'heures (jamais une économie réalisée). */
  function simulerHeures(p){var h=num(p.heures),cph=num(p.coutHoraire),ret=num(p.retrait)||0,reaf=num(p.reaffectees)||0,min=num(p.minimumOperationnel),ev=num(p.partEvitable);
    if(h==null||cph==null)return {statut:'non-calculable'};if(min!=null&&h-ret<min-EPS)return {type:'simulation',statut:'bloquee',raison:'sous le minimum opérationnel connu ('+min+' h)'};
    return {type:'simulation',heuresActuelles:h,heuresSimulees:h-ret,heuresReellementRetirees:ret-reaf,economieTheorique:ev==null?null:(ret-reaf)*cph*ev,coutConcerne:(ret-reaf)*cph,hypotheses:ev==null?['part évitable non renseignée : économie non chiffrable']:['part évitable '+Math.round(ev*100)+' %'],message:'Simulation : aucune action ni économie réalisée.'};}
  /* 15.75–15.76 : simulations de CA et combinée. */
  function simuler(c,ca,dCaPct,dHeuresPct,heures){var C=num(c),A=num(ca);if(C==null||A==null||A<=0)return {statut:'non-calculable'};var H=num(heures),cph=H?C/H:null;
    var H2=H!=null?H*(1+(dHeuresPct||0)/100):null,C2=cph!=null&&H2!=null?cph*H2:C,A2=A*(1+(dCaPct||0)/100);
    return {type:'simulation',ratioActuel:C/A*100,ratioSimule:C2/A2*100,coutSimule:C2,caSimule:A2,caParHeureSimule:H2?A2/H2:null,hypotheses:['CA '+(dCaPct||0)+' %','heures '+(dHeuresPct||0)+' %','coût horaire stable']};}
  /* 15.78–15.80 : fermeture de service — scénarios explicites, jamais « fermez ». */
  function fermerService(p){var ca=num(p.caPerdu),mat=num(p.matiereEvitee),hum=num(p.coutHumainEvitable),fix=num(p.coutsFixesRestants);if(ca==null||mat==null)return {statut:'non-calculable'};
    var sc=(p.reports||[0]).map(function(t){var perte=ca*(1-t);return {tauxReport:t,caPerduNet:perte,effet:-perte+mat*(1-t)+(hum==null?0:hum)};});
    return {type:'simulation',coutHumainEvitable:hum,note:hum==null?'coût humain évitable inconnu : non compté':null,coutsFixesRestants:fix,scenarios:sc,message:'Plusieurs scénarios selon le report d’activité ; aucune recommandation automatique.'};}
  /* 15.86–15.90 : mesure après action, effet net, échec visible. */
  function mesurer(av,ap,attendu){var dC=ap.cout-av.cout,dCA=ap.ca-av.ca,rAv=av.cout/av.ca*100,rAp=ap.cout/ap.ca*100;
    var o={variationCoutHumain:dC,variationCA:dCA,ratioAvant:rAv,ratioApres:rAp,economieObservee:dC<0?-dC:0,effetNetObserve:-dC+dCA*(num(av.margeSurCA)||0),note:'résultat observé ≠ causalité démontrée'};
    o.conclusion=(attendu==='baisse-ratio'&&rAp>=rAv-EPS)?'echec-ou-sans-effet':(dCA<0&&-dCA*(num(av.margeSurCA)||0)>(-dC))?'effet-net-negatif':'a-confirmer';return o;}
  /* 15.83 : priorité de vérification quand les heures sont incomplètes. */
