function salT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=SAL_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,n){return v[n]!=null?v[n]:'';});}
function salSaisi(k){var x=DB&&DB.in?DB.in[k]:undefined;return !(x===undefined||x===null||x==='');}
function salChargesConnues(){var dirb=Number(DB.in&&DB.in.dirb)||0,salb=Number(DB.in&&DB.in.salb)||0;return (dirb<=0||salSaisi('dirt'))&&(salb<=0||salSaisi('salt'));}
function verdictCoutHumain(){if(!window.VerdictSalaires)return null;var R=moteur();if(!R||!R.ready)R=moteur();if(!R||!R.ready)return null;var d=R.d,dirb=Number(d.dirb)||0,salb=Number(d.salb)||0,manque=[];
  if(dirb>0&&!salSaisi('dirt'))manque.push('dir');if(salb>0&&!salSaisi('salt'))manque.push('sal');
  var ch=manque.length?null:dirb*(Number(d.dirt)||0)/100+salb*(Number(d.salt)||0)/100;
  var c=VerdictSalaires.coutHumain({brut:dirb+salb,chargesEmployeur:ch}),caM=Number(d.ca)>0?Number(d.ca)/12:null,r=c.valeur!=null?VerdictSalaires.ratio(c.valeur,caM,'HT'):{statut:'non-calculable'};
  var A=typeof salAnalyseMois==='function'?salAnalyseMois():null;var dec=manque.length?{type:'verifier-les-donnees',action:'a_taux'}:(A&&A.evol?{type:'analyser',action:'a_comparer'}:{type:'verifier-les-heures',action:'a_heures'});
  return {cout:c,manque:manque,ratio:r,decision:dec,decisionId:VerdictSalaires.idDecision(DB.etabId||DB.etab||'etab','cout-humain'),version:VerdictSalaires.version};}
function verdictCoutHumainCarteHTML(){var X=verdictCoutHumain();if(!X)return '';var c=X.cout,h='<div class="card" id="coutHumainCarte" data-decision="'+aideEsc(X.decisionId)+'"><h3>'+aideEsc(salT('titre'))+'</h3><p class="note" style="margin:0 0 6px">'+aideEsc(salT('def'))+'</p>';
  if(c.statut==='calcule')h+='<p style="margin:4px 0"><b>'+aideEsc(salT('cout',{v:eur(c.valeur)}))+'</b></p>';
  else{h+='<p style="margin:4px 0"><b>'+aideEsc(salT('bruts',{v:eur(c.metriqueConnue?c.metriqueConnue.valeur:0)}))+'</b></p><p class="note" style="margin:0 0 4px;color:#f59e0b">'+aideEsc(salT('incomplet',{q:X.manque.map(function(k){return salT('q_'+k);}).join(' / ')}))+'</p>';}
  h+=X.ratio.statut==='calcule'?'<p class="note" style="margin:4px 0 0">'+aideEsc(salT('ratio',{v:pc(X.ratio.valeur,1)}))+'</p><p class="note" style="margin:2px 0 0">'+aideEsc(salT('repere'))+'</p>':'<p class="note" style="margin:4px 0 0">'+aideEsc(salT('ratioNon'))+'</p>';
  var nm=(DB.laborMonths||[]).length;h+='<p class="note" style="margin:6px 0 0">'+aideEsc(salT('jour'))+'</p>'+(nm?'':'<p class="note" style="margin:2px 0 0">'+aideEsc(salT('heures'))+'</p><p class="note" style="margin:2px 0 0">'+aideEsc(salT('evol'))+'</p>');
  h+='<p style="margin:8px 0 0"><b>'+aideEsc(salT('action',{a:salT(X.decision.action)}))+'</b></p>';return h+'</div>';}
function veraReponseCoutHumain(question){var _sim=typeof salVeraSimulation==='function'?salVeraSimulation(question):null;if(_sim)return _sim;var q=String(question||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
  if(!/(cout humain|masse salariale|salaire|charges? (de )?personnel|labou?r cost|payroll|coste humano|costo del personale|personalkosten|personeelskosten|custo humano)/.test(q))return null;
  var X=verdictCoutHumain();if(!X){var ib=DB.in||{},db=Number(ib.dirb)||0,sb=Number(ib.salb)||0,mq=[];if(db>0&&!salSaisi('dirt'))mq.push('dir');if(sb>0&&!salSaisi('salt'))mq.push('sal');
    if(!mq.length)return null;return {lignes:[salT('bruts',{v:eur(db+sb)}),salT('incomplet',{q:mq.map(function(k){return salT('q_'+k);}).join(' / ')}),salT('ratioNon'),salT('action',{a:salT('a_taux')})]};}
  var c=X.cout,out=[];
  out.push(c.statut==='calcule'?salT('cout',{v:eur(c.valeur)}):salT('bruts',{v:eur(c.metriqueConnue?c.metriqueConnue.valeur:0)}));
  if(c.statut!=='calcule')out.push(salT('incomplet',{q:X.manque.map(function(k){return salT('q_'+k);}).join(' / ')}));
  out.push(X.ratio.statut==='calcule'?salT('ratio',{v:pc(X.ratio.valeur,1)}):salT('ratioNon'));var A=typeof salAnalyseMois==='function'?salAnalyseMois():null;if(A&&A.mois.length){salEvolLignes(A).forEach(function(l){out.push(l);});}else{out.push(salT('evol'));out.push(salT('heures'));}out.push(salT('action',{a:salT(X.decision.action)}));
  return {lignes:out};}
window.verdictCoutHumain=verdictCoutHumain;

