function salEvt(type,p,extra){DB.laborEvents=DB.laborEvents||[];var e={type:type,period:p||null,at:new Date().toISOString(),engine:VerdictSalaires.version};if(extra)for(var k in extra)e[k]=extra[k];DB.laborEvents.push(e);if(DB.laborEvents.length>300)DB.laborEvents=DB.laborEvents.slice(-300);}
function salBaseSim(){var A=salAnalyseMois(),c=A.mois.filter(function(x){return x.ca.ca!=null&&x.ca.ca>0&&!x.ca.enCours;});var b=c.length?c[c.length-1]:A.mois[A.mois.length-1];return b||null;}
function salSimuler(ret,reaf,ev,dca){var B=salBaseSim();if(!B)return {err:'s_vide'};var H=B.r.heures,dt=B.r.detail||{},C=B.r.cout-(dt.abC||0),CA=B.ca.ca;ret=salNum(ret);reaf=salNum(reaf)||0;ev=salNum(ev);dca=salNum(dca)||0;
  if(!(ret>0)||ret>=H||reaf<0||reaf>ret||(ev!=null&&(ev<0||ev>100)))return {err:'s_err'};var cph=C/H,net=ret-reaf,sh=VerdictSalaires.simulerHeures({heures:H,coutHoraire:cph,retrait:ret,reaffectees:reaf,partEvitable:ev==null?null:ev/100});
  var baisse=sh.economieTheorique!=null?sh.economieTheorique:net*cph,C2=B.r.cout-baisse,CA2=CA!=null?CA*(1+dca/100):null,H2=H-net;
  return {type:'simulation',base:B,h1:H,h2:H2,coutConcerne:sh.coutConcerne,eco:sh.economieTheorique,ev:ev,r1:CA?B.r.cout/CA*100:null,r2:CA2?C2/CA2*100:null,p1:CA?CA/H:null,p2:CA2?CA2/H2:null};}
function salSimTexte(S){if(S.err)return [salT(S.err)];var o=[salT('s_res',{h1:fr(S.h1,0),h2:fr(S.h2,0),cc:eur(S.coutConcerne),r1:S.r1!=null?pc(S.r1,1):'—',r2:S.r2!=null?pc(S.r2,1):'—',p1:S.p1!=null?eur(S.p1):'—',p2:S.p2!=null?eur(S.p2):'—'})];
  o.push(S.eco!=null?salT('s_eco',{e:eur(S.eco),p:fr(S.ev,0)}):salT('s_econon'));return o;}
function salSimClic(){var g=function(i){var e=document.getElementById(i);return e?e.value:'';},S=salSimuler(g('salSimRet'),g('salSimReaf'),g('salSimEv'),g('salSimCa')),el=document.getElementById('salSimRes');if(el)el.innerHTML=salSimTexte(S).map(function(l,i){return '<p class="note" style="margin:'+(i?2:6)+'px 0 0">'+(i?'':'<b>')+aideEsc(l)+(i?'':'</b>')+'</p>';}).join('');if(!S.err)salEvt('simulation.run',S.base.r.period,{retrait:salNum(g('salSimRet'))});}
function salSuivre(){var A=salAnalyseMois();if(!A.evol)return null;var e=A.evol,id=VerdictSalaires.idDecision(DB.etabId||DB.etab||'etab','cout-humain:'+e.b);DB.decisions=DB.decisions||[];
  if(DB.decisions.some(function(x){return x&&x.id===id&&(x.status==='testing'||x.status==='waiting');}))return 'deja';
  var today=typeof point12Today==='function'?point12Today():new Date().toISOString().slice(0,10),review=typeof point12DateAdd==='function'?point12DateAdd(today,30):today,R=e.ratio,C=e.cout;
  DB.decisions.push({version:'15.1',trackingId:'D15_'+Date.now()+'_'+Math.random().toString(36).slice(2,6),kind:'labor',status:'testing',date:today,startedAt:new Date().toISOString(),reviewDate:review,id:id,lib:'Coût humain — '+salMoisLabel(e.a)+' → '+salMoisLabel(e.b),action:'Comparer à l’objectif, vérifier les heures, décider (ajuster, observer ou ne rien changer)',metricKey:'labor-cost-ratio',
    baseline:{measure:{periodeAvant:e.a,periodeApres:e.b,ratioAvant:R.avant,ratioApres:R.apres,effetCout:R.effetCout,effetActivite:R.effetActivite,variationCout:C.variation,effetVolumeHeures:C.effetVolumeHeures,effetCoutHoraire:C.effetCoutHoraire,effetMix:e.mix?C.effetMix:null,partNonExpliquee:C.partNonExpliquee,absencesSeparees:!!e.absencesSeparees},engine:VerdictSalaires.version,certitude:'observation'}});
  salEvt('decision.created',e.b,{id:id});try{save();}catch(x){}return 'ok';}
function salSuivreClic(){var r=salSuivre(),m=document.getElementById('salDecMsg');if(m)m.textContent=r==='ok'?salT('dec_ok'):(r==='deja'?salT('dec_deja'):'');}
function salSuiteHTML(A){var h='';if(A.evol)h+='<button type="button" id="salDecBtn" onclick="salSuivreClic()" style="margin-top:8px;padding:10px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.3);background:transparent;color:inherit;font-weight:600">'+aideEsc(salT('dec_btn'))+'</button><p id="salDecMsg" class="note" role="status" aria-live="polite" style="margin:4px 0 0"></p>';
  var n=(DB.laborEvents||[]).length,t=(DB.laborMonths||[]).length,c=(DB.laborMonths||[]).filter(function(r){return (r.version||1)>1;}).length;if(t)h+='<p class="note" style="margin:6px 0 0">'+aideEsc(salT('j_line',{n:n,c:c,t:t,p:pc(c/t*100,0)}))+'</p>';
  var B=salBaseSim(),inp=function(id,lab){return '<label style="display:block;margin:6px 0 0;font-size:13px">'+aideEsc(lab)+'<input id="'+id+'" inputmode="decimal" style="display:block;width:100%;box-sizing:border-box;margin-top:3px;padding:8px;border-radius:8px;border:1px solid rgba(255,255,255,.25);background:transparent;color:inherit;font-size:16px"></label>';};
  h+='<details id="salSimBloc" style="margin:10px 0 0"><summary style="font-weight:700;cursor:pointer">'+aideEsc(salT('s_titre'))+'</summary>';
  if(!B)return h+'<p class="note">'+aideEsc(salT('s_vide'))+'</p></details>';
  h+='<p class="note" style="margin:4px 0 0">'+aideEsc(salT('s_base',{m:salMoisLabel(B.r.period),h:fr(B.r.heures,0),c:eur(B.r.cout),ca:B.ca.ca!=null?eur(B.ca.ca):'—'}))+'</p>'+inp('salSimRet',salT('s_ret'))+inp('salSimReaf',salT('s_reaf'))+inp('salSimEv',salT('s_ev'))+inp('salSimCa',salT('s_ca'));
  return h+'<button type="button" id="salSimBtn" onclick="salSimClic()" style="margin-top:8px;width:100%;padding:10px;border-radius:10px;border:0;font-weight:700">'+aideEsc(salT('s_btn'))+'</button><div id="salSimRes" role="status" aria-live="polite"></div></details>';}
function salVeraSimulation(question){var q=String(question||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(!/(que se passerait|si je (retire|enleve|supprime)|what if|if i (remove|cut)|que pasaria|cosa succede|was passiert|wat als|o que acontece)/.test(q))return null;
  var m=q.match(/(\d+(?:[.,]\d+)?)\s*(h\b|heure|hour|hora|ora|stunde|uur)/);if(!m)return null;var S=salSimuler(m[1].replace(',','.'),0,null,0);return {lignes:salSimTexte(S).concat(S.err?[]:[salT('m_warn')])};}
window.salSimClic=salSimClic;window.salSuivreClic=salSuivreClic;window.salSimuler=salSimuler;window.salSuivre=salSuivre;window.salVeraSimulation=salVeraSimulation;

function pilGo(force){
  var field=document.getElementById('pl-jour'),clock=verdictOperationalClock();
  if(field&&field.dataset.clockKey&&field.dataset.clockKey!==clock.key){toast(window.VerdictServiceDay.copy(LOCALE).stale);return;}
  var j=Math.round(num(document.getElementById("pl-jour").value)||pilJourActif());
  var caJ=num(document.getElementById("pl-ca").value);
  var tkJ=num(document.getElementById("pl-tk").value);
  var auj=verdictOperationalClock().day;
  if(!(j>=1&&j<=auj)){ toast("Jour du mois entre 1 et "+auj); return; }
  if(!valider([{id:'pl-ca',nom:'CA TTC de la journ\u00e9e',ok:function(v){ return v!=null&&v>=0; }}],'pl-ca'))return;
  if(tkJ!=null&&(tkJ<0||Math.floor(tkJ)!==tkJ)){
    champErr('pl-tk',true);champsMsg('pl-tk','<b>'+point4T('ticketInvalid')+'</b>');
    toast(point4T('ticketInvalid'));focusGuide(document.getElementById('pl-tk'));return;
  }
  champErr('pl-tk',false);
  var cle=jourCle(j),empreinte=point4DailyFingerprint(j,caJ,tkJ);
  var alertes=point4DailyWarnings(moteur(),j,caJ,tkJ);
  DB.confirmationsJour=DB.confirmationsJour||{};
  if(alertes.length&&!force&&DB.confirmationsJour[cle]!==empreinte){
    ask(point4T('dailyAnomalyTitle'),alertes.join(' '),point4T('dailyAnomalyLabel'),function(){
      DB.confirmationsJour[cle]=empreinte;save();pilGo(true);
    });return;
  }
  if(!alertes.length&&DB.confirmationsJour[cle])delete DB.confirmationsJour[cle];
  if(window.VerdictDailyValidation&&window.VerdictDailyValidation.shouldGate()){
    var capture=window.VerdictDailyValidation.capture({day:j,date:cle,caJ:caJ,tkJ:tkJ});
    if(capture&&capture.handled){
      if(capture.message)toast(capture.message);
      PIL_JOUR=null;PIL_EDIT_JOUR=null;drawPil();refreshAll();return;
    }
  }
  /* on écrit la journée, puis on recalcule le cumul du mois : c'est lui qui
     alimente le Pilote et l'historique. */
  var _dailyChange=typeof window.verdictDailyChangeBefore==='function'?window.verdictDailyChangeBefore('save',j):null;
  enregistrerJourCalcule(j,caJ,tkJ);
  save();
  PIL_JOUR=null;PIL_EDIT_JOUR=null;
  if(typeof window.verdictDailyChangeAfter==='function')window.verdictDailyChangeAfter(_dailyChange);
  toast(j===auj?"Journ\u00e9e enregistr\u00e9e":"Jour "+j+" enregistr\u00e9");
  drawPil();refreshAll();
}
/* ═══ HISTORIQUE — graphiques légers (SVG) ═══ */
function miniBars(labels,vals,color,fmt){
  var mx=Math.max.apply(null,vals.map(function(v){return Math.abs(v||0);}))||1;
  /* R213 : repère FIXE de 320 unités (l'ancien repère de 34 unités par barre était réduit à ~47 % sur 24 mois : étiquettes de ~4 px, illisibles). Police 10, gris >= 4,5:1 ; quand les colonnes sont serrées, une étiquette sur k. */
  var w=320, hgt=120, base=hgt-22, slot=w/labels.length, every=Math.max(1,Math.ceil(30/slot)); /* R225 : lisible aussi sous 360 px */
  var svg='<svg viewBox="0 0 '+w+' '+hgt+'" style="width:100%;height:120px;display:block" aria-hidden="true">';
  var bw=Math.max(3,Math.min(26,slot-4));
  labels.forEach(function(lb,i){
    var x=i*slot+(slot-bw)/2;
    if(vals[i]==null||!isFinite(vals[i])){ svg+='<line x1="'+x+'" y1="'+(base-1)+'" x2="'+(x+bw)+'" y2="'+(base-1)+'" stroke="#5f6873" stroke-width="1.5" stroke-dasharray="3 3"><title>—</title></line>'; }
    else { var v=Number(vals[i]), bh=Math.min(base-4,Math.abs(v)/mx*(base-8));
    var y=v>=0?base-bh:base;
    svg+='<rect x="'+x+'" y="'+y+'" width="'+bw+'" height="'+Math.max(1,bh)+'" rx="3" fill="'+(v<0?"#ef4444":color)+'"/>'; }
    if(i%every===0||i===labels.length-1&&(labels.length-1)%every>every/2)svg+='<text x="'+(x+bw/2)+'" y="'+(hgt-6)+'" font-size="12.5" fill="#98a2ad" text-anchor="middle">'+lb+'</text>';
  });
  svg+='</svg>';
  return svg;
}
function lineSVG(vals,color){
  var w=320,hgt=100,pad=8;
  var clean=vals.map(function(v){ return v==null?null:v; });
  var present=clean.filter(function(v){return v!=null;});
  if(!present.length)return '<p class="note">Pas encore de donn\u00e9es.</p>';
  var mn=Math.min.apply(null,present), mx=Math.max.apply(null,present);
  if(mx===mn){mx+=1;mn-=1;}
  var n=clean.length, step=(w-2*pad)/Math.max(1,n-1);
  var pts=[];
  clean.forEach(function(v,i){ if(v!=null)pts.push([pad+i*step,hgt-pad-(v-mn)/(mx-mn)*(hgt-2*pad)]); });
  var path=pts.map(function(p,i){ return (i===0?"M":"L")+p[0].toFixed(1)+","+p[1].toFixed(1); }).join(" ");
  var svg='<svg viewBox="0 0 '+w+' '+hgt+'" style="width:100%;height:100px;display:block">'+
    '<path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>';
  pts.forEach(function(p){ svg+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="2.6" fill="'+color+'"/>'; });
  svg+='</svg>';
  return svg;
}
function isoWeek(dstr){
  var d=new Date(dstr+"T00:00:00"); var day=(d.getDay()+6)%7;
  d.setDate(d.getDate()-day+3);
  var firstThu=new Date(d.getFullYear(),0,4);
  var wk=1+Math.round(((d-firstThu)/86400000-3+((firstThu.getDay()+6)%7))/7);
  return d.getFullYear()+"-S"+String(wk).length<2?wk:wk;
}

/* ═══════════════════════════════════════════════════════════════════
   TRAJECTOIRE — la mémoire économique de l'établissement (V4.53)
   Ni un historique de ventes (la caisse le fait), ni une courbe : une
   histoire. Où j'étais · ce que j'ai fait · ce qui a changé · ce qui marche.
   Aucune donnée nouvelle : audits archivés, décisions appliquées, carnet.
   Aucun calcul économique ici — couche narration.
   ═══════════════════════════════════════════════════════════════════ */

/* ═══ CE QUE « J'AI APPLIQUÉ » FAIT VRAIMENT (V4.57) ═══
   Retour Steven : « ça ne fait rien, je m'attendais à voir le score changer ».
   Il a raison sur le ressenti, et le score ne DOIT pas bouger : une décision
   appliquée ne change pas les chiffres tant que les chiffres n'ont pas changé.
   Ce qui manquait, c'est de le dire — et de montrer que c'est enregistré. */
