  inventoryNotComparable:['consommation non comparable — périmètre ou cohérence à vérifier','consumption not comparable — scope or consistency to check','consumo no comparable — perímetro o coherencia por verificar','consumo non confrontabile — perimetro o coerenza da verificare','Verbrauch nicht vergleichbar — Umfang oder Stimmigkeit prüfen','verbruik niet vergelijkbaar — reikwijdte of consistentie controleren','consumo não comparável — perímetro ou coerência a verificar'],
  actualConsumption:['consommation réelle {amount}','actual consumption {amount}','consumo real {amount}','consumo reale {amount}','Tatsächlicher Verbrauch {amount}','werkelijk verbruik {amount}','consumo real {amount}'],
