function p12t(k,vars){
  var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof veraAppLocale==='function'?veraAppLocale():(typeof LOCALE!=='undefined'?LOCALE:'fr'));
  if(i<0)i=0;var a=POINT12_TEXT[k]||[k],s=a[i]||a[0]||k;vars=vars||{};return s.replace(/\{([a-z]+)\}/gi,function(_,n){return vars[n]===undefined?_:String(vars[n]);});
}
function p12Reason(s){
  s=String(s||'');var exact={
    'Le suivi appartient à un autre établissement.':'reasonOtherEstablishment','Le modèle d’établissement a changé depuis le départ.':'reasonProfileChanged',
    'Les données actuelles ne permettent pas encore un calcul complet.':'reasonIncomplete','La mesure de départ n’est pas assez documentée.':'reasonBaseline',
    'Aucune nouvelle mesure comparable.':'reasonNoComparable','La source ou l’unité n’est plus la même qu’au départ.':'reasonSourceChanged',
    'Aucune donnée nouvelle depuis le départ.':'reasonNoNew','Une association dans le temps ne prouve pas que cette action a causé seule le mouvement.':'reasonCausal'
  };if(exact[s])return p12t(exact[s]);var m=s.match(/^(\d+) autre\(s\) test\(s\) ou décision\(s\) ont chevauché la période\.$/);return m?p12t('reasonOverlap',{n:m[1]}):s;
}
function p12Source(m){var x={daily_sales:m&&/fictives/.test(m.source)?'sourceDemo':'sourceDaily',inventory_food_cost:'sourceInventory',annual_structure:'sourceAccounting',cash_manual:'sourceCash'};return p12t(x[m&&m.sourceFamily]||'oldSource');}
function p12Period(m){var s=String(m&&m.period||'');if(/^Exercice /.test(s))return p12t('exercise',{year:s.replace(/^Exercice /,'')});if(/^Valeur au /.test(s))return (typeof LOCALE==='undefined'||LOCALE==='fr')?s:p12t('startReview',{start:s.replace(/^Valeur au /,''),review:''}).replace(/\s*·\s*[^·]*$/,'');return s||p12t('unknownPeriod');}
function point12Today(){/* R123 : le jour d'exploitation de l'établissement (son fuseau, coupure de service), jamais la date UTC. */try{var c=typeof verdictOperationalClock==='function'?verdictOperationalClock():null;if(c&&/^\d{4}-\d{2}-\d{2}$/.test(String(c.key)))return c.key;}catch(e){}var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
