  var missing=[],warnings=[],p=ORG_PRESETS[s.type]||ORG_PRESETS.custom,demand=s.revenueMode==="verdict"?orgEstimateDemand(s):null;
  if(s.occ==null||s.occ<=0)missing.push("nombre de services concernés");
  if(s.revenueMode==="verdict"&&(!demand||!demand.available))missing.push("historique permettant d’estimer le CA");
  if(s.revenueMode==="manual"&&s.manualCA==null)missing.push("hypothèse manuelle de CA TTC");
