  var grossCA=sourceCA==null?null:(p.mode==="remove"?-Math.abs(sourceCA):sourceCA);
  if(demand&&demand.proxy)warnings.push("le jour ciblé n’a jamais été observé ; l’estimation utilise les journées ouvertes de la même période");
  if(num(s.periodWeeks)>weeks)warnings.push("la période dépasse les semaines d’ouverture de l’établissement et a été limitée");
