  var effectiveOther=p.mode==="remove"?-Math.abs(other):other;
  var displacement=s.displacementPct==null?null:Math.max(0,Math.min(100,s.displacementPct)),ca=grossCA==null?null:grossCA*(1-(displacement==null?0:displacement)/100);
  var lowGross=demand&&demand.available?(p.mode==="remove"?-Math.abs(demand.low):demand.low):grossCA,highGross=demand&&demand.available?(p.mode==="remove"?-Math.abs(demand.high):demand.high):grossCA;
  var lowCA=lowGross==null?null:lowGross*(1-(displacement==null?0:displacement)/100),highCA=highGross==null?null:highGross*(1-(displacement==null?0:displacement)/100);
  var central=ca==null?null:orgPlanImpact(selected,ca,occ,periodWeeks,tva,mc,effectiveOther),low=lowCA==null?null:orgPlanImpact(selected,lowCA,occ,periodWeeks,tva,mc,effectiveOther),high=highCA==null?null:orgPlanImpact(selected,highCA,occ,periodWeeks,tva,mc,effectiveOther);
  var complete=missing.length===0&&central&&central.impact!=null,impact=complete?central.impact:null,netOcc=complete?central.netOccurrence:null,labour=selected&&selected.complete?selected.costOccurrence:0;
  var annualPlan=orgTeamPlans(s,occ*weeks,weeks)[selected.key];if(p.mode==="remove")annualPlan=Object.assign({},annualPlan,{costOccurrence:-Math.abs(annualPlan.costOccurrence||0),periodCost:-Math.abs(annualPlan.periodCost||0)});
  var annualCalc=ca==null?null:orgPlanImpact(annualPlan,ca,occ,weeks,tva,mc,effectiveOther),annual=complete&&annualCalc?annualCalc.impact:null;
  var costOcc=selected&&selected.complete?selected.costOccurrence+effectiveOther:0,breakEven=complete&&p.mode!=="remove"&&mc>0&&costOcc>0?costOcc/(mc/100)*(1+tva/100):null;
  var alternatives={};["extra","salary"].forEach(function(k){var pl=plans[k];if(p.mode==="remove")pl=Object.assign({},pl,{costOccurrence:-Math.abs(pl.costOccurrence||0),periodCost:-Math.abs(pl.periodCost||0)});alternatives[k]=ca==null?null:Object.assign({plan:pl},orgPlanImpact(pl,ca,occ,periodWeeks,tva,mc,effectiveOther));});
  var base=orgGroup(s.baselineKey)||s.baseline,n=base&&base.n?base.n:0,proven=base&&base.proven?base.proven:0,completeProof=base&&base.complete?base.complete:0;
  if(demand&&demand.available)n=demand.n;
