function orgVeraHTML(x){
  var level="yellow",title="Je ne peux pas encore conclure",body="Complétez "+x.missing.join(", ")+". Un vrai 0 est accepté ; une case vide reste inconnue.";
  if(x.complete&&!x.operationallyFeasible){level="red";title="L’équipe renseignée ne couvre pas le besoin";body="Le résultat économique reste visible pour comprendre l’écart, mais ce plan ne peut pas être testé tant que la capacité horaire par fonction n’est pas suffisante.";}
  else if(x.complete&&x.s.demoIllustrative){level="yellow";title="Estimation calculée depuis l’historique fictif";body="Verdict n’invente pas un gain de CA : il construit une fourchette depuis les journées de "+(x.demand?x.demand.seasonLabel:"la période")+", applique "+fr(x.displacementPct||0,1)+" % de déplacement des ventes, puis retire le coût de l’équipe choisie. Le résultat reste un scénario à tester, jamais un gain acquis."+(x.warnings.length?" Vigilance : "+x.warnings.join(". ")+".":"");}
  else if(x.complete&&x.warnings.length){level="orange";title="Vérifiez les limites avant de tester";body=x.warnings.join(". ")+". Le calcul reste visible, mais cette hypothèse mérite confirmation.";}
  else if(x.complete&&x.n<3){level="yellow";title="Testez avant de décider";body=(x.n?"Seulement "+x.n+" occurrence(s) comparable(s) sont liées.":"Aucune occurrence comparable n’est liée.")+" Le montant est une hypothèse, pas un résultat attendu.";}
  else if(x.complete&&x.impact<0){level="red";title="Ce scénario coûte plus qu’il ne rapporte";body="Selon les hypothèses saisies, il retire "+eur(Math.abs(x.impact))+" sur "+fr(x.periodWeeks,0)+" semaines. Ajustez l’organisation ou testez-la sur un petit périmètre.";}
  else if(x.complete&&x.impact>0){level="green";title="Ce scénario mérite un test terrain";body="Le moteur calcule "+("+"+eur(x.impact))+" sur "+fr(x.periodWeeks,0)+" semaines selon vos hypothèses. Vera le classe comme potentiel à mesurer, jamais comme gain acquis.";}
  else if(x.complete){level="yellow";title="Aucun écart économique calculé";body="Les gains et les coûts saisis s’annulent. Modifiez une hypothèse ou testez une autre organisation.";}
  /* Les champs manquants et avertissements sont utiles en français, mais ne
     doivent jamais réinjecter une phrase française dans les six autres
     langues. Les versions localisées gardent la même information économique
     sans masquer le caractère incomplet ou illustratif du scénario. */
  if(LOCALE!=="fr"){
    if(!x.complete)body=orgTr("Le moteur ne peut pas encore conclure. Complétez les données indiquées ; un zéro confirmé reste différent d’un champ vide.");
    else if(x.s.demoIllustrative)body=orgTr("Le modèle calcule une fourchette à partir de l’historique, applique le déplacement des ventes puis retire le coût réel de l’équipe choisie. Le résultat reste à tester.");
  }
  var colors={green:["#22c55e","rgba(34,197,94,.09)"],yellow:["#eab308","rgba(234,179,8,.09)"],orange:["#f97316","rgba(249,115,22,.09)"],red:["#ef4444","rgba(239,68,68,.09)"]},c=colors[level];
  return '<div class="dec-vd org-vera" data-level="'+level+'" style="background:'+c[1]+';border-color:'+c[0]+'"><b style="color:'+c[0]+'">'+esc(orgTr("Vera · {title}",{title:orgTr(title)}))+'</b>'+esc(orgTr(body))+'<small style="display:block;color:var(--mut);margin-top:6px">'+esc(orgTr("Vera explique ; le moteur Verdict calcule."))+'</small></div>';
}
function orgProofHTML(x){
  var b=x.baseline,d=x.demand;
  if(d&&d.available){
    var years=d.years.map(function(y){return '<div class="autoline"><span class="k">'+esc(orgTr("{year} · {n} journées · poids {weight} %",{year:y.year,n:y.n,weight:fr(y.weightPct,1)}))+'</span><b>'+esc(orgTr("{amount} TTC/jour",{amount:eur(y.average)}))+'</b></div>';}).join('');
    var parts=d.dayparts.length?'<div style="font-family:var(--mono);font-size:11px;color:var(--mut2);letter-spacing:.06em;margin-top:8px">'+esc(orgTr("COMPOSITION DES JOURNÉES COMPARABLES"))+'</div>'+d.dayparts.map(function(p){return '<div class="autoline"><span class="k">'+esc(orgTr(p.label))+' · '+pc(p.share*100,1)+'</span><b>'+eur(p.amount)+'</b></div>';}).join(''):'';
    var nature=x.s.demoIllustrative?'MODÈLE FICTIF CALIBRÉ':'HISTORIQUE DE VOTRE ÉTABLISSEMENT';
    var proxy=d.proxy?'<div class="warn on" style="margin:9px 0 0"><b>'+esc(orgTr("{day} jamais observé.",{day:orgTr(d.targetLabel)}))+'</b><br>'+esc(d.limitations.map(function(v){return orgTr(v);}).join(' '))+'</div>':'';
    return '<div class="dec-vd" style="background:rgba(96,165,250,.08);border-color:#60a5fa"><b style="color:#93c5fd">'+esc(orgTr("ESTIMATION VERDICT · {nature}",{nature:orgTr(nature)}))+'</b>'+esc(orgTr("{n} journées comparables du {from} au {to}. Méthode : {method}.",{n:d.n,from:String(d.from).split('-').reverse().join('/'),to:String(d.to).split('-').reverse().join('/'),method:orgTr(d.method)}))+
      '<div class="autoline" style="margin-top:8px"><span class="k">'+esc(orgTr("Jour ciblé"))+'</span><b>'+esc(orgTr(d.targetLabel))+'</b></div><div class="autoline"><span class="k">'+esc(orgTr("Période"))+'</span><b>'+esc(orgTr(d.seasonLabel))+'</b></div>'+years+
      '<div style="font-family:var(--mono);font-size:11px;color:var(--mut2);letter-spacing:.06em;margin-top:8px">'+esc(orgTr("FOURCHETTE DE CA TTC PAR JOUR"))+'</div><div class="autoline"><span class="k">'+esc(orgTr("Prudente · quartile bas"))+'</span><b>'+eur(d.low)+'</b></div><div class="autoline"><span class="k">'+esc(orgTr("Centrale · années récentes pondérées"))+'</span><b>'+eur(d.central)+'</b></div><div class="autoline"><span class="k">'+esc(orgTr("Haute · quartile haut"))+'</span><b>'+eur(d.high)+'</b></div>'+parts+proxy+
      '<p class="note" style="margin:9px 0 0">'+esc(orgTr("Ces journées contiennent les créneaux réellement présents dans le journal : petit déjeuner, midi, service continu et soir. Les ventes de boissons et d’alcool sont donc incluses lorsqu’elles figurent dans les tickets ; elles ne sont jamais ajoutées une seconde fois."))+'</p></div>';
  }
  if(x.s.revenueMode==="manual")return '<div class="dec-vd" style="background:rgba(234,179,8,.08);border-color:#eab308"><b style="color:#facc15">'+esc(orgTr("HYPOTHÈSE MANUELLE · PAS UNE OBSERVATION"))+'</b>'+esc(orgTr("Le CA de {amount} par occurrence vient de votre saisie. Verdict l’affiche séparément et ne le présente pas comme une estimation issue de l’historique.",{amount:eur(Math.abs(x.sourceCA||0))}))+'</div>';
  if(x.s.revenueMode==="zero")return '<div class="dec-vd" style="background:rgba(139,148,160,.07);border-color:var(--mut2)"><b>'+esc(orgTr("HYPOTHÈSE CONFIRMÉE · CA INCHANGÉ"))+'</b>'+esc(orgTr("Vous avez confirmé 0 € de variation. Cette valeur est volontaire ; elle n’est pas issue d’un champ vide."))+'</div>';
  if(!b)return '<div class="dec-vd" style="background:rgba(139,148,160,.07);border-color:var(--mut2)"><b>FAIT OBSERVÉ · aucune référence liée</b>Vous pouvez simuler, mais reliez ensuite au moins trois '+esc(orgUnitLabel())+' comparables depuis Performance des services.</div>';
  return '<div class="dec-vd" style="background:rgba(96,165,250,.08);border-color:#60a5fa"><b style="color:#93c5fd">FAIT OBSERVÉ · '+esc(b.label||"service comparable")+'</b>'+
    (b.n||0)+' occurrence(s) du '+esc(String(b.from||"").split("-").reverse().join("/"))+' au '+esc(String(b.to||"").split("-").reverse().join("/"))+'. Moyenne : '+eur(b.avgCA||0)+' TTC, '+fr(b.avgH||0,1)+' h réellement travaillées, '+eur(b.avgOther||0)+' d’autres coûts, soit '+(Number(b.avgNet||0)>=0?'+':'−')+eur(Math.abs(Number(b.avgNet||0)))+' après coûts variables et équipe. '+
    (b.proven||0)+' occurrence(s) proviennent d’un import ou d’une connexion.</div>';
}
