function orgTestById(id){return (DB.decisions||[]).filter(function(d){return d&&d.id===id&&d.kind==="organization";})[0]||null;}
function orgTestProgress(a,forcedToday){
  if(!a)return null;var today=forcedToday||recentToday(),base=a.baseline||null,key=base&&base.key?String(base.key):"";
  var scenario=a.scenario||{},fullDay=Number(scenario.schema)>=4&&scenario.scope==="full_day",targetDow=num(scenario.targetDow);
  if(fullDay&&typeof perfLignes==="function"){
    var dayGroups={},all=perfLignes().filter(function(x){return x&&x.d<=today&&x.d>=String(a.date||"")&&x.d<=String(a.reviewDate||today)&&(targetDow==null||new Date(String(x.d)+"T12:00:00").getDay()===targetDow);});
    all.forEach(function(x){var g=dayGroups[x.d]||(dayGroups[x.d]={date:x.d,net:0,rows:0,complete:false,usable:true});g.usable=g.usable&&!!x.usable&&typeof x.res==='number'&&Number.isFinite(x.res);g.net+=Number(x.res||0);g.rows++;if(x.completeDay==="yes")g.complete=true;});
    var days=Object.keys(dayGroups).sort().map(function(k){return dayGroups[k];}).filter(function(d){return d.complete&&d.usable;}),avgDay=days.length?days.reduce(function(n,d){return n+d.net;},0)/days.length:null;
    var activeWeeks=num(scenario.activeWeeks)||num(scenario.periodWeeks)||orgWeeks(),occ=num(scenario.occ)||0,projected=avgDay==null?null:avgDay*occ*activeWeeks,observedTotal=days.reduce(function(n,d){return n+d.net;},0);
    var endFull=new Date(String(a.reviewDate||today)+"T12:00:00"),nowFull=new Date(String(today)+"T12:00:00"),leftFull=Math.ceil((endFull-nowFull)/864e5);
    return {rows:all,days:days,n:days.length,avgNet:avgDay,deltaPerOccurrence:avgDay,observedTotal:days.length?observedTotal:null,observedDates:days.map(function(d){return d.date;}),annual:projected,periodImpact:projected,due:leftFull<=0,daysLeft:Math.max(0,leftFull),ready:leftFull<=0&&days.length>=3&&avgDay!=null,mode:(ORG_PRESETS[scenario.type]||ORG_PRESETS.custom).mode,fullDay:true,targetDow:targetDow};
  }
  /* Sans référence figée, Verdict ne mélange jamais tous les services pour
     fabriquer une observation. Le scénario reste testable, mais sa conclusion
     automatique demeure indisponible et cette limite est dite au client. */
  var rows=key&&typeof perfLignes==="function"?perfLignes().filter(function(x){
    return x.baseline&&x.index>=(num(a.serviceCountAtStart)||0)&&x.d>=String(a.date||"")&&x.d<=String(a.reviewDate||today)&&x.d<=today&&(perfDayIndex(x.d)+"|"+x.s)===key;
  }):[];
  var avg=rows.length?rows.reduce(function(n,x){return n+x.res;},0)/rows.length:null,mode=(ORG_PRESETS[a.scenario&&a.scenario.type]||ORG_PRESETS.custom).mode;
  var delta=null;if(avg!=null&&mode==="add")delta=avg;else if(avg!=null&&(mode==="transform"||mode==="custom")&&base&&Number.isFinite(Number(base.avgNet)))delta=avg-Number(base.avgNet);
  var activeWeeks=num(a.scenario&&a.scenario.activeWeeks)||orgWeeks(),occ=num(a.scenario&&a.scenario.occ)||0,annual=delta==null?null:delta*occ*activeWeeks;
  var end=new Date(String(a.reviewDate||today)+"T12:00:00"),now=new Date(String(today)+"T12:00:00"),days=Math.ceil((end-now)/864e5);
  return {rows:rows,n:rows.length,avgNet:avg,deltaPerOccurrence:delta,observedTotal:delta==null?null:delta*rows.length,observedDates:Array.from(new Set(rows.map(function(x){return x.d;}))).sort(),annual:annual,periodImpact:annual,due:days<=0,daysLeft:Math.max(0,days),ready:days<=0&&rows.length>=3&&delta!=null,mode:mode};
}
function orgActiveTestHTML(){
  var a=(DB.decisions||[]).filter(function(d){return d&&d.kind==="organization"&&d.status==="testing";}).slice(-1)[0];if(!a)return "";
  var p=orgTestProgress(a),hasBase=!!(a.baseline&&a.baseline.key),proof=p&&p.fullDay?(p.n?p.n+' journée(s) ciblée(s) complète(s) enregistrée(s) depuis le lancement.':'Aucune journée ciblée complète enregistrée depuis le lancement.'):(!hasBase?'Aucune référence comparable n’a été figée au lancement : Verdict ne mélangera pas vos autres services pour produire une fausse conclusion.':(p&&p.n?p.n+' service(s) comparable(s) enregistré(s) depuis le lancement.':'Aucun service comparable enregistré depuis le lancement.'));
  var observed=p&&p.periodImpact!=null?'<p class="note" style="margin:7px 0"><b>'+(orgEvidenceText(9)+' '+(p.ready?'à valider':'provisoire'))+' :</b> '+(p.periodImpact>=0?'+':'−')+eur(Math.abs(p.periodImpact))+' sur la période économique, à partir de '+p.n+' '+(p.fullDay?'journée(s)':'service(s)')+'.'+(p.fullDay?' Net réellement enregistré pendant le test : '+(p.observedTotal>=0?'+':'−')+eur(Math.abs(p.observedTotal))+'.':'')+'</p>':'';
  var action=p&&p.ready?'<button type="button" class="btn" onclick="orgCloseTest(\''+esc(a.id)+'\')">Comparer le prévu au réalisé</button>':(!hasBase&&!(p&&p.fullDay)?'<div class="warn on" style="margin:8px 0"><b>Suivi manuel uniquement.</b><br>Relancez un prochain test avec une référence observée pour obtenir une comparaison automatique fiable.</div>':(p&&p.due&&p.n<3?'<div class="warn on" style="margin:8px 0"><b>Test arrivé à échéance.</b><br>Ajoutez au moins '+Math.max(0,3-p.n)+' '+(p.fullDay?'journée(s) ciblée(s)':'service(s) comparable(s)')+', ou prolongez votre observation.</div>':''));
  var removal=p&&p.mode==="remove"?'<p class="note" style="color:#fbbf24">Un retrait ne crée plus de ligne de service. Verdict suivra le mouvement global entre deux audits, sans prétendre que le retrait en est l’unique cause.</p>':'';
  return '<div class="card" style="margin-top:12px;border-left:3px solid #60a5fa"><div style="font-family:var(--mono);font-size:11px;color:#93c5fd;letter-spacing:.08em">TEST TERRAIN EN COURS</div><h3 style="margin:7px 0 4px">'+esc(a.lib||"Nouvelle organisation")+'</h3><p class="note" style="margin:0 0 5px">Du '+esc(String(a.date||"").split("-").reverse().join("/"))+' au '+esc(String(a.reviewDate||"").split("-").reverse().join("/"))+'. Estimation figée : '+(a.est>=0?"+":"−")+eur(Math.abs(a.est||0))+' sur la période simulée.</p><p class="note" style="margin:0 0 7px">'+proof+(p&&!p.due?' · '+p.daysLeft+' jour(s) restant(s).':'')+'</p>'+observed+removal+'<button type="button" class="btn sec" onclick="go(\'planning\')">Enregistrer les services observés</button>'+action+'</div>';
}
/* R235: keep recorded occurrences separate from extrapolations; no historical record is rewritten. */
function decisionObservedImpact(d){
  function finite(x){return x!=null&&x!==''&&typeof x!=='boolean'&&Number.isFinite(Number(x))?Number(x):null;}
  if(!d)return null;
  if(d.kind!=='organization')return finite(d.observedPeriodImpact);
  if(d.observationMethod==='recorded-occurrences-r235')return finite(d.observedPeriodImpact);
  /* Older organization records stored an extrapolation as observedPeriodImpact.
     The original fields remain intact; only evidenced test totals are exposed. */
  if(d.scenario&&d.scenario.scope==='full_day')return finite(d.observedTestTotal);
  var n=finite(d.observedCount),per=finite(d.observedPerOccurrence);
  return n!=null&&Number.isInteger(n)&&n>0&&per!=null?Math.round(n*per*100)/100:null;
}
