function decRender(id,v,instant){
  var def=DEC_DEFS.filter(function(x){return x.id===id;})[0];
  var imp=decImpact(id,v); if(!imp)return;
  var box=document.getElementById("dr-"+id); if(!box)return;
  DEC_STATE[id]=v;
  var vd=decVerdictMsg(imp);
  var col=imp.delta>0?"var(--green)":(imp.delta<0?"var(--red)":"var(--mut)");
  /* structure une fois, ensuite on anime */
  if(!box.dataset.built){
    box.innerHTML=
      '<div class="dec-ba">'+
        '<div class="dec-col"><div class="h">Aujourd\u2019hui</div>'+
          '<div class="big">'+def.dispBase(imp.R0)+'</div>'+
          '<div class="li"><span>R\u00e9sultat</span><b>'+eur(imp.before)+'</b></div>'+
          '<div class="li"><span>Score</span><b>'+imp.score0+' /100</b></div>'+
          '<div class="li"><span>Rentabilit\u00e9</span><b>'+pc(imp.rn0,1)+'</b></div></div>'+
        '<div class="dec-arr">\u2192</div>'+
        '<div class="dec-col after"><div class="h">Apr\u00e8s simulation</div>'+
          '<div class="big" id="da-lev-'+id+'"></div>'+
          '<div class="li"><span>R\u00e9sultat</span><b id="da-res-'+id+'"></b></div>'+
          '<div class="li"><span>Score</span><b id="da-sc-'+id+'"></b></div>'+
          '<div class="li"><span>Rentabilit\u00e9</span><b id="da-rn-'+id+'"></b></div></div>'+
      '</div>'+
      '<div class="dec-gain" id="da-gain-'+id+'"></div>'+
      '<div class="dec-vd" id="da-vd-'+id+'"></div>';
    box.dataset.built="1";
  }
  var lab=document.getElementById("dval-"+id); if(lab){lab.textContent=def.fmt(v); lab.style.color=col;}
  var lev=document.getElementById("da-lev-"+id); if(lev)lev.textContent=def.dispAfter(imp.R0,v);
  var resEl=document.getElementById("da-res-"+id);
  var scEl=document.getElementById("da-sc-"+id);
  var rnEl=document.getElementById("da-rn-"+id);
  var gEl=document.getElementById("da-gain-"+id);
  if(instant){
    if(resEl){resEl.textContent=eur(imp.after);resEl.dataset.cur=imp.after;}
    if(scEl){scEl.textContent=imp.score1+" /100";scEl.dataset.cur=imp.score1;}
    if(rnEl){rnEl.textContent=pc(imp.rn1,1);rnEl.dataset.cur=imp.rn1;}
    if(gEl){gEl.textContent=(imp.delta>=0?"+":"\u2212")+eur(Math.abs(imp.delta))+" /an";gEl.dataset.cur=imp.delta;}
  }else{
    decAnim(resEl,imp.after,function(x){return eur(x);});
    decAnim(scEl,imp.score1,function(x){return Math.round(x)+" /100";});
    decAnim(rnEl,imp.rn1,function(x){return pc(x,1);});
    decAnim(gEl,imp.delta,function(x){return (x>=0?"+":"\u2212")+eur(Math.abs(x))+" /an";});
  }
  if(scEl)scEl.style.color=imp.score1>imp.score0?"var(--green)":(imp.score1<imp.score0?"var(--red)":"var(--txt)");
  if(rnEl)rnEl.style.color=imp.rn1>imp.rn0?"var(--green)":(imp.rn1<imp.rn0?"var(--red)":"var(--txt)");
  if(gEl)gEl.style.color=col;
  var vdEl=document.getElementById("da-vd-"+id);
  if(vdEl){vdEl.style.background=vd.bg;vdEl.style.borderColor=vd.c;
    vdEl.innerHTML='<b style="color:'+vd.c+'">'+vd.t+'</b>'+vd.m;}
}
function decMove(id,rangeEl){
  var v=num(rangeEl.value); if(v==null)return;
  DEC_SCENE_PLAYING=false;DEC_SCENE_LANDING=false;decSceneClearTimers();document.documentElement.classList.remove('dec-reveal-lock');var reveal=document.getElementById('decReveal');if(reveal)reveal.remove();
  decRender(id,v,true);decSceneUpdateInline();
  decDrawTotal(true);
}
/* ✨ Point de départ si les curseurs sont à zéro ; amélioration additive si
   le client a déjà construit une simulation. */
function decPayrollRecommendationAllowed(){
  return (DB.decisions||[]).some(function(d){
    return d&&d.kind==="organization"&&d.status==="reviewed"&&num(decisionObservedImpact(d))!=null;
  });
}
function decPotentialState(P){
  var state={},d=moteur().d,ent=DB.in;
  (P&&P.leviers||[]).forEach(function(x){
    var o=x.over;
    if(o.nour!=null){var ca=d.ca||1;state.fc=Math.round(((o.nour-(ent.nour||0))/ca*100)*2)/2;}
    if(o.salb!=null){state.sal=Math.round((o.salb-(ent.salb||0))/100)*100;}
    if(o.panier!=null){state.panier=Math.round(((o.panier-(ent.panier||0)))*2)/2;}
    if(o.cmdj!=null){state.cmd=Math.round(o.cmdj-(ent.cmdj||0));}
    if(o.com!=null&&(ent.com||0)>0){state.com=Math.round((o.com/(ent.com||1)-1)*100/5)*5;}
    if(o.emb!=null&&(ent.emb||0)>0){state.emb=Math.round((o.emb/(ent.emb||1)-1)*100/5)*5;}
    for(var k in o){if(/^f\d+$/.test(k)){var b=ent[k]||0;if(b>0)state.fix=Math.round((o[k]/b-1)*100/5)*5;}}
  });
  state.jour=0;return state;
}
function decBest(){
  var out=document.getElementById("dec-best-out");if(!out)return;
  var Rtoday=moteur();if(!Rtoday.ready)return;
  var U=decPremiumUI();
  var base={};DEC_DEFS.forEach(function(d){base[d.id]=(DEC_STATE[d.id]!=null)?DEC_STATE[d.id]:d.def;});
  var hadCurrent=decNbActifs(base)>0,R0=moteur(decOverAll(base));
  var payrollProven=decPayrollRecommendationAllowed();
  var paniers=[0,0.5,1,1.5,2],fcs=[0,-0.5,-1,-1.5,-2],sals=payrollProven?[0,-500,-1000]:[0];
  var _P=(typeof potentiel==="function")?potentiel():null,best=null;
  function borne(id,v){var d=DEC_DEFS.filter(function(x){return x.id===id;})[0];return d?Math.max(d.min,Math.min(d.max,v)):v;}
  paniers.forEach(function(pv){fcs.forEach(function(fv){sals.forEach(function(sv){
    if(pv===0&&fv===0&&sv===0)return;
    var state={};for(var key in base)state[key]=base[key];
    state.panier=borne('panier',(base.panier||0)+pv);
    state.fc=borne('fc',(base.fc||0)+fv);
    state.sal=borne('sal',(base.sal||0)+sv);
    var R1=moteur(decOverAll(state));
    var effort=Math.abs(pv)/2+Math.abs(fv)/2+Math.abs(sv)/1000;
    var cand={pv:pv,fv:fv,sv:sv,score:R1.score,res:R1.d.res,delta:R1.d.res-R0.d.res,
      totalDelta:R1.d.res-Rtoday.d.res,rn:R1.v.rn,effort:effort,state:state};
    if(cand.delta<=0)return;
    if(best===null){best=cand;return;}
    var candGreen=cand.score>=75,bestGreen=best.score>=75;
    if(candGreen&&!bestGreen){best=cand;return;}
    if(candGreen&&bestGreen){if(cand.effort<best.effort||(cand.effort===best.effort&&cand.delta>best.delta))best=cand;return;}
    if(!candGreen&&!bestGreen&&(cand.score>best.score||(cand.score===best.score&&cand.delta>best.delta)))best=cand;
  });});});
  /* Le paquet de Priorités n'est candidat que pour un point de départ. Une
     simulation déjà modifiée n'est jamais remplacée en silence. */
  var paquetPayroll=false;
  if(_P&&_P.leviers)paquetPayroll=_P.leviers.some(function(x){return x&&x.over&&(x.over.salb!=null||x.over.dirb!=null);});
  if(!hadCurrent&&_P&&_P.leviers.length&&(!paquetPayroll||payrollProven)){
    var paquetState=decPotentialState(_P),RT=moteur(decOverAll(paquetState));
    if(!best||RT.score>best.score+2||(RT.d.res-R0.d.res)>best.delta*1.5){
      best={paquet:true,score:RT.score,res:RT.d.res,delta:RT.d.res-R0.d.res,rn:RT.v.rn,
        pv:0,fv:0,sv:0,nb:_P.leviers.length,state:paquetState};
    }
  }
  if(!best){DEC_BEST_PENDING=null;out.innerHTML='<p class="note">'+U.none+'</p>';return;}
  var parts=[];
  if(best.paquet)parts.push(U.package.replace('{n}',"<b>"+best.nb+"</b>"));
  if(best.pv!==0)parts.push(U.basket+" <b>+"+best.pv.toFixed(2).replace(".",",")+" €</b>");
  if(best.fv!==0)parts.push(U.food+" <b>−"+Math.abs(best.fv).toFixed(1).replace(".",",")+" pt</b>");
  if(best.sv!==0)parts.push(decHumanLoadedText('short')+" <b>−"+eur(Math.abs(best.sv))+decHumanLoadedText('delta')+"</b>");
  /* Le libellé du bouton et son comportement restent liés au même état :
     « Utiliser comme point de départ » déclenche toujours la révélation. */
  best.starting=!hadCurrent;DEC_BEST_PENDING=best;
  out.innerHTML='<div style="background:rgba(0,0,0,0.25);border-radius:10px;padding:12px;margin:8px 0">'+
    '<div style="font-size:13px;margin-bottom:8px">'+(hadCurrent?U.added:U.calculated)+' : '+parts.join(" · ")+'</div>'+
    '<div class="autoline"><span class="k">'+U.impact+'</span><b style="color:var(--green)">+'+eur(best.delta)+' /an</b></div>'+
    '<div class="autoline"><span class="k">'+U.result+'</span><b>'+eur(best.res)+'</b></div>'+
    '<div class="autoline"><span class="k">'+U.score+'</span><b>'+best.score+' /100 ('+(best.score-R0.score>=0?"+":"")+(best.score-R0.score)+')</b></div>'+
    '<div class="autoline"><span class="k">'+U.profit+'</span><b>'+pc(best.rn,1)+'</b></div>'+
    '<div style="margin-top:9px;padding-top:9px;border-top:1px solid var(--line)"><div style="font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:#93c5fd">'+U.proof+'</div><p class="note" style="margin:4px 0 0">'+U.proofD+'</p></div>'+
    '<button class="btn sec" style="margin-top:10px" onclick="decApplyBest()">'+(hadCurrent?U.applyAdd:U.applyStart)+'</button></div>';
}

/* Le bouton « Tester ces leviers ensemble » ne renvoie plus vers un écran vide :
   il positionne réellement chaque curseur de Décisions sur le levier proposé.
   Les deux écrans donnent alors le même total — une seule lecture. */
function decDepuisPotentiel(sceneBefore,sceneLabel,playReveal){
  var P=potentiel(); if(!P||!P.leviers.length){ go('dec'); return; }
  var baseR=sceneBefore||moteur(decOverAll());
  DEC_STATE=decPotentialState(P);
  DEC_SCENE_LAST=decSceneSnapshot(baseR,sceneLabel||decPremiumUI().calculated);
  decScenarioPersist('decision-scenario-applied');
  /* Le bouton est une demande explicite de lecture : l'animation se rejoue.
     Une simple réouverture du module reste, elle, silencieuse. */
  if(playReveal==null)playReveal=true;
  DEC_SCENE_PLAYING=!!playReveal;DEC_SCENE_LANDING=!playReveal;
  go('dec');
  /* go() protège le haut de page pendant 700 ms sur Safari iOS. La scène
     démarre juste après, sinon cette protection annule son positionnement. */
  if(playReveal)setTimeout(decScenePlay,780);else setTimeout(function(){var scene=document.getElementById('decScene');if(scene){scene.classList.add('is-complete');decSceneScroll(scene);}},780);
  try{ toast("Les curseurs sont positionn\u00e9s sur les leviers propos\u00e9s"); }catch(e){}
}
function decApplyBest(pv,fv,sv){
  var beforeR=moteur(decOverAll()),U=decPremiumUI(),pending=DEC_BEST_PENDING,playReveal=false;
  /* Compatibilité avec les anciens appels de recette, puis contrat V10.14.4. */
  if(arguments.length){
    playReveal=true;
    if(pv==="paquet"){decDepuisPotentiel(beforeR,U.calculated,playReveal);return;}
    DEC_STATE.panier=pv;DEC_STATE.fc=fv;DEC_STATE.sal=sv;DEC_STATE.jour=0;
  }else{
    if(!DEC_BEST_PENDING){toast('Calculez d’abord un scénario');return;}
    /* Toute validation explicite d'un nouveau scénario mérite la lecture
       guidée. Elle n'est jamais imposée lors d'une simple réouverture. */
    playReveal=true;
    DEC_STATE={};for(var k in DEC_BEST_PENDING.state)DEC_STATE[k]=DEC_BEST_PENDING.state[k];
  }
  DEC_BEST_PENDING=null;
  DEC_SCENE_LAST=decSceneSnapshot(beforeR,pending&&pending.paquet?U.calculated:U.added);
  decScenarioPersist('decision-scenario-applied');
  DEC_SCENE_PLAYING=!!playReveal;DEC_SCENE_LANDING=!playReveal;
  drawDec();
  if(playReveal)setTimeout(decScenePlay,60);else setTimeout(function(){var scene=document.getElementById('decScene');if(scene){scene.classList.add('is-complete');decSceneScroll(scene);}},60);
}
