function plusTexte(){
  var locale=typeof LOCALE==='string'&&PLUS_UI[LOCALE]?LOCALE:'fr',base=PLUS_UI[locale],items=base.items.map(function(x){return x.slice();});
  if(typeof modeleDansDemonstration==='function'&&modeleDansDemonstration())items=items.map(function(x){return x[0]==='etabs'?DEMO_MODEL_MENU_UI[locale].slice():x;});
  items.splice(1,0,PLUS_RECO_UI[locale]);
  return {title:base.title,sub:base.sub,all:base.all,groups:base.groups,items:items};
}
function plusAller(id){
  if(id==='search'){go('aide');var q=document.getElementById('aideQ');if(q)q.focus();return;}
  if(id==='recommendations'){go('reco');return;}
  if(id==='data'||id==='import'){go('in');return;}
  if(id==='inventory'){go('achats');return;}
  if(id==='models'){openModeles();return;}
  if(id==='etabs'){openEtabs();return;}
  if(id==='account'){go('abo');return;}
  if(id==='language'){langModal();return;}
  if(id==='export'){go('audit');var e=document.getElementById('auExports');if(e)e.scrollIntoView({block:'start',behavior:'auto'});return;}
  if(id==='vera'){revoirVera();return;}
  if(id==='full'){ouvrirToutVerdict();}
}
function plusRaccourcisHTML(){
  var u=plusTexte();return '<div class="menuGrid plus-needs">'+u.items.map(function(x){return '<button type="button" class="mtile" data-plus-need="'+x[0]+'" onclick="plusAller(\''+x[0]+'\')"><span class="mi">'+x[1]+'</span><span class="mt">'+esc(x[2])+'</span><span class="md">'+esc(x[3])+'</span></button>';}).join('')+'</div>';
}

