  if(id==='reco')try{return chrCockpitText('recoTitle');}catch(e){return 'Recommandations';}
  var demoModel=id==='etabs'&&typeof modeleDansDemonstration==='function'&&modeleDansDemonstration();
  var n=plusNeedItem(demoModel?'models':id);return n?n[2]:id;
