function plusSearchSubmit(ev){
  if(ev&&ev.preventDefault)ev.preventDefault();
  var src=document.getElementById('plusSearchQ'),question=String(src&&src.value||'').trim();
  if(!question){if(src)src.focus();return false;}
  try{AIDE_RETOUR='plus';go('aide');var q=document.getElementById('aideQ');if(q){q.value=question;aideDessiner();veraDemander(null);q.focus();}}catch(e){}
  return false;
}
