/* ═══════════════════════════════════════════════════════════════════
   TROIS NIVEAUX, ET ON S'ARRÊTE QUAND ON VEUT (V4.84)
   La référence seule suffit à tout le diagnostic, mais
   rien ne le disait. On l'écrit, une fois, en tête du menu : ce qui est
   nécessaire, ce qui est optionnel, et ce que chaque étape apporte.
   ═══════════════════════════════════════════════════════════════════ */
function parcoursEtat(){
  var R=moteur();
  return [
    {t:'Vos chiffres', tps:t('journey.once'), fait:!!(R&&R.ready),
     d:'Suffit \u00e0 tout le diagnostic\u00a0: score, point mort, priorit\u00e9s, audit complet.', go:'in'},
    {t:'Vos dix plats', tps:t('journey.whenever'), fait:((DB.plats||[]).length>=10),
     d:'Ajoutez la marge plat par plat et le co\u00fbt mati\u00e8re th\u00e9orique.', go:'carte'},
    {t:'Vos achats et un comptage', tps:t('journey.monthlyCount'), fait:((DB.inv||[]).length>0),
     d:'Rend le co\u00fbt mati\u00e8re r\u00e9el et fait vivre la commande.', go:'achats'}
  ];
}
function parcoursHTML(){
  var P=parcoursEtat(), n=P.filter(function(x){ return x.fait; }).length;
  return '<div class="mgrp" style="margin-top:2px"><div class="card" style="border-left:3px solid var(--green)">'+
    '<div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2)">Ce qui est n\u00e9cessaire</div>'+
    '<b style="display:block;font-size:16.5px;margin:6px 0 8px">'+(n?'\u00c9tape '+n+' sur 3':'Commencez par vos chiffres')+'</b>'+
    P.map(function(x,i){
      return '<div class="au-ok" style="padding:8px 0"><span class="p" style="color:'+(x.fait?'#22c55e':'var(--mut2)')+'">'+(x.fait?'\u2713':(i+1))+'</span>'+
        '<span style="flex:1"><b>'+x.t+'</b> <span style="color:var(--mut2);font-size:12.5px">\u00b7 '+x.tps+'</span>'+
        '<br><span style="color:var(--mut);font-size:13.5px">'+x.d+'</span></span>'+
        (x.fait?'':'<button type="button" class="btn sec" style="width:auto;padding:6px 10px;font-size:12.5px;margin:0" onclick="go(\''+x.go+'\')">Y aller</button>')+
        '</div>';
    }).join('')+
    '<p class="note" style="margin:10px 0 0">La premi\u00e8re \u00e9tape suffit\u00a0: le reste s\u2019ajoute quand vous en avez besoin, jamais avant. Rien ne se bloque si vous vous arr\u00eatez l\u00e0.</p>'+
    '</div></div>';
}

