  el.innerHTML=plusDemoHandoffHTML(plusHubUI())+plusStartSearchHTML(u)+plusStartAuditHTML(u)+plusStartPriorityHTML(u)+plusInventoryAccessHTML()+plusAlertPreferencesHTML()+plusStartShortcutsHTML(u)+plusStartVeraHTML(u)+
    '<section class="plus-map-card plus-start-map"><span class="plus-start-icon" aria-hidden="true">🧭</span><div><span class="plus-eyebrow">'+esc(u.mapK)+'</span><h2>'+esc(u.mapT)+'</h2><p>'+esc(u.mapD)+'</p></div><button type="button" class="plus-primary" onclick="plusHubGo(\'full\')">'+esc(u.mapC)+' →</button></section>'+
    plusHubAdminHTML(plusHubUI());
