/* ═══ CHIFFRE D'AFFAIRES ═══ */
function verdictHistoryHTML(){
  var historyAll=(DB.monthlyHistory||[]),historyYears=Array.from(new Set(historyAll.map(function(r){return r.period.slice(0,4);}))).sort().reverse();
  var selectedHistoryYear=String(window.VERDICT_HISTORY_YEAR||historyYears[0]||'');if(historyYears.indexOf(selectedHistoryYear)<0)selectedHistoryYear=historyYears[0]||'';
  var histM=historyAll.filter(function(r){return r.period.slice(0,4)===selectedHistoryYear;}),moisVals=histM.length?histM.map(function(r){return r.caHT;}):DB.suivi.map(function(r){ return r.ca; });
  var moisLabels=histM.length?histM.map(function(r){var p=String(r.period||'');return p.slice(5,7)+'/'+p.slice(2,4);}):MOIS_N.map(function(m){return m.slice(0,3);});
  var hasM=moisVals.some(function(v){return v!=null;});
  var hM=(historyYears.length?'<div class="card"><label for="history-year">Année de l’historique</label><select id="history-year" onchange="window.VERDICT_HISTORY_YEAR=this.value;drawCA()">'+historyYears.map(function(y){return '<option value="'+y+'"'+(y===selectedHistoryYear?' selected':'')+'>'+y+'</option>';}).join('')+'</select><p class="note">'+(DB.demoHistory?'Démonstration fictive · cinq exercices complets et année en cours.':'Toutes les années enregistrées.')+'</p></div>':'')+'<div class="card"><h3>CA HT par mois <span class="r">'+(histM.length?histM.length+' mois datés'+(histM[histM.length-1].closed===false?' · dernier en cours':''):'saisie Food Cost &gt; Suivi mensuel')+'</span></h3>';
  if(hasM){
    hM+=miniBars(moisLabels,moisVals.map(function(v){return (v==null||!isFinite(v))?null:v;}),"#60a5fa");
  } else hM+='<p class="note">Renseignez le CA HT mensuel dans Food Cost \u2192 Suivi mensuel pour voir la courbe ici.</p>';
  hM+='</div>';
  if(DB.demoHistory&&histM.length)hM+='<div class="card"><h3>Chaque mois face à son point mort</h3><p class="note">Données fictives · CA HT, minimum comptable HT et résultat avant impôt. Charges fixes et salaires de la structure de démonstration, amortissements inclus ; consommation issue des inventaires. Le mois en cours reste partiel.</p>'+histM.map(function(x){var ratio=x.breakEvenRatio,col=ratio==null?'#9aa6b2':({green:'#22c55e',yellow:'#eab308',orange:'#f97316',red:'#ef4444'})[window.VerdictExact.zoneRatio(ratio)]||'#9aa6b2';return '<div style="padding:12px 0;border-top:1px solid #303740"><b>'+x.period+(x.closed?'':' · en cours')+'</b><div>CA HT : '+eur(x.caHT)+' · minimum : '+(x.breakEvenHT==null?'non atteignable':eur(x.breakEvenHT))+'</div><div style="color:'+col+'">'+(ratio==null?'Non calculable':fr(ratio*100,1)+' % du minimum')+'</div><div>Résultat avant impôt : '+eur(x.resultBeforeTax)+'</div></div>';}).join('')+'</div>';
  var fcVals=histM.length?histM.map(function(r){return r.foodCostPct;}):DB.suivi.map(function(r){
    if(r.ca>0&&r.ach!=null){ var conso=r.ach+(r.sd||0)-(r.sf||0); return conso/r.ca*100; }
    return null;
  });
  hM+='<div class="card"><h3>'+(histM.length&&histM[0].foodCostScope==='total-matter-ht'?'Co\u00fbt mati\u00e8re r\u00e9el (cuisine + boissons) par mois':'Food cost r\u00e9el par mois')+'</h3>'+lineSVG(fcVals,"#f97316")+
    '<p class="note">'+(histM.length&&histM[0].foodCostScope==='total-matter-ht'?'Consommation r\u00e9elle issue de l\u2019inventaire \u00f7 CA HT. Distincte des seuls achats nourriture.':'Trac\u00e9 depuis le Suivi mensuel du Food Cost.')+'</p></div>';
  return hM;
}
function drawCA(){
  var R=moteur(), el=document.getElementById("caBody");
  if(!R.ready){ needData(el); return; }
  var d=R.d;
  var h='<div class="kpis">'+
    '<div class="kpi"><div class="k">CA annuel HT</div><div class="v">'+eur(d.ca)+'</div><div class="d">'+fr(d.cmdAn)+' commandes/an</div></div>'+
    '<div class="kpi"><div class="k">CA mensuel moyen HT</div><div class="v">'+eur(d.ca/12)+'</div><div class="d">panier '+eur2(d.panierHT)+' HT</div></div>'+
    '<div class="kpi"><div class="k">CA / jour ouvr\u00e9</div><div class="v">'+(d.jAn>0?eur(d.ca/d.jAn):'\u2014')+'</div><div class="d">'+(d.jAn>0?d.jAn+' jours ouverts/an':'jours d\u2019ouverture non renseign\u00e9s')+'</div></div>'+
    '<div class="kpi"><div class="k">CA / ETP</div><div class="v">'+(d.caSalarie!=null?eur(d.caSalarie):'\u2014')+'</div><div class="d">'+(d.etp>0?fr(d.etp,1)+' ETP renseign\u00e9s':'effectif non renseign\u00e9')+'</div></div></div>';
  h+=verdictHistoryHTML();
  if(DB.pil.jour!=null&&DB.pil.ca!=null){
    h+='<div class="card"><h3>Ce mois-ci <span class="r">depuis l\u2019Accueil</span></h3>'+
      '<div class="autoline"><span class="k">CA TTC encaiss\u00e9 depuis le 1er</span><b>'+eur(DB.pil.ca)+'</b></div>'+
      '<div class="autoline"><span class="k">Jour du mois</span><b>'+DB.pil.jour+'</b></div></div>';
  }
  /* comparaison même jour du mois précédent */
  if(DB.histJour.length){
    var today=new Date(); var y=today.getFullYear(), mo=today.getMonth(), day=today.getDate();
    var prevMo=new Date(y,mo-1,day);
    var prevKey=prevMo.toISOString().slice(0,10);
    var prevEntry=DB.histJour.filter(function(r){ return r.date===prevKey; })[0];
    var todayEntry=DB.histJour.filter(function(r){ return r.jour===day; }).slice(-1)[0];
    if(prevEntry&&todayEntry&&todayEntry.date!==prevEntry.date){
      var delta2=todayEntry.ca-prevEntry.ca, pct2=prevEntry.ca>0?delta2/prevEntry.ca*100:0;
      h+='<div class="card"><h3>M\u00eame jour du mois pr\u00e9c\u00e9dent</h3>'+
        '<div class="autoline"><span class="k">Ce mois (jour '+day+')</span><b>'+eur(todayEntry.ca)+'</b></div>'+
        '<div class="autoline"><span class="k">Mois pr\u00e9c\u00e9dent (jour '+day+')</span><b>'+eur(prevEntry.ca)+'</b></div>'+
        '<div class="autoline"><span class="k">Variation</span><b style="color:'+(delta2>=0?"var(--green)":"var(--red)")+'">'+(delta2>=0?"+":"")+eur(delta2)+' ('+(pct2>=0?"+":"")+fr(pct2,0)+' %)</b></div></div>';
    }
  }
  /* tendances 7 / 30 jours */
  if(DB.histJour.length>=2){
    var sorted=DB.histJour.slice().sort(function(a,b){return a.date<b.date?-1:1;});
    function sumLast(n,offset){
      var arr=sorted.slice(Math.max(0,sorted.length-n-offset), sorted.length-offset);
      var start=Math.max(0,sorted.length-n-offset);
      return arr.reduce(function(a,r,i){return a+histJourValeur(sorted,start+i,'caJ','ca');},0);
    }
    var d7=sumLast(7,0), d7prev=sumLast(7,7), d30=sumLast(30,0), d30prev=sumLast(30,30);
    function trend(cur,prev){
      var delta=cur-prev, pct=prev>0?delta/prev*100:0;
      return '<div class="autoline"><span class="k">CA cumul\u00e9</span><b>'+eur(cur)+'</b></div>'+
        (prev>0?'<div class="autoline"><span class="k">P\u00e9riode pr\u00e9c\u00e9dente</span><b>'+eur(prev)+' &nbsp; <span style="color:'+(delta>=0?"var(--green)":"var(--red)")+'">'+(delta>=0?"+":"")+fr(pct,0)+' %</span></b></div>':'');
    }
    h+='<div class="card"><h3>&#128200; Tendance 7 jours</h3>'+trend(d7,d7prev)+'</div>'+
       '<div class="card"><h3>&#128200; Tendance 30 jours</h3>'+trend(d30,d30prev)+'</div>';
  }
  el.innerHTML=h;
}
/* ═══ SALAIRES ═══ */
function drawSal(){
  var R=moteur(), el=document.getElementById("salBody");
  if(!R.ready){ needData(el); return; }
  var d=R.d,v=R.v, iz=zone(R.s.ms);
  var h='<div class="kpis">'+
    '<div class="kpi"><div class="k">Masse salariale / an</div><div class="v">'+eur(d.sal)+'</div><div class="d">'+(typeof salChargesConnues==='function'&&!salChargesConnues()?aideEsc(salT('brutsSeuls')):'dirigeant(s) + salari\u00e9s, charges incluses')+'</div></div>'+
    '<div class="kpi"><div class="k">% du CA</div><div class="v" style="color:'+iz.h+'">'+pc(v.ms,1)+'</div><div class="d">rep\u00e8re sain \u2264 35 %</div></div>'+
    '<div class="kpi"><div class="k">&#128100; Co\u00fbt salarial du jour</div><div class="v">'+eur(d.jMois>0?d.salM/d.jMois:0)+'</div><div class="d">masse salariale mensuelle \u00f7 jours ouverts</div></div></div>';
  h+='<div class="jauge"><div class="jt"><span>Masse salariale % CA</span><b style="color:'+iz.h+'">'+pc(v.ms,1)+'</b></div>'+
    '<div class="jtrk"><i style="width:'+Math.min(100,v.ms/55*100)+'%;background:'+iz.h+'"></i></div></div>';
  h+='<div class="card"><h3>D\u00e9tail</h3>'+
    '<div class="autoline"><span class="k">Brut dirigeant(s) / mois</span><b>'+eur(DB.in.dirb||0)+'</b></div>'+
    '<div class="autoline"><span class="k">Bruts salari\u00e9s / mois</span><b>'+eur(DB.in.salb||0)+'</b></div>'+
    '<div class="autoline"><span class="k">Masse salariale / mois (charges incl.)</span><b>'+eur(d.salM)+'</b></div>'+
    '<div class="autoline"><span class="k">ETP renseign\u00e9s</span><b>'+(d.etp>0?fr(d.etp,1):'\u2014')+'</b></div>'+
    '<div class="autoline"><span class="k">CA par ETP</span><b>'+(d.caSalarie!=null?eur(d.caSalarie):'\u2014')+'</b></div></div>'+
    '<button class="btn sec" onclick="goIn(\'i-dirb\')">Modifier dans Param\u00e8tres</button>'+
    '<p class="note">Au-del\u00e0 de 38 % du CA, le seuil de vigilance interne Verdict est franchi. C\u2019est un signal de pilotage, jamais une prescription RH : les d\u00e9cisions d\u2019emploi restent celles du dirigeant avec ses professionnels.</p>';
  try{h+=verdictCoutHumainCarteHTML();}catch(e){}
  try{h+=salMoisHTML();}catch(e){}
  el.innerHTML=h;
}
/* ═══ ACHATS ═══ */

/* ═══════════════════════════════════════════════════════════════════
   ACHATS — l'observatoire des approvisionnements (V4.54, étape 1)
   Ce n'est pas un registre de factures : c'est la base de données commune
   (fournisseurs, articles, historique de prix) et la lecture de ce que les
   hausses coûtent réellement. Couche narration : aucun calcul du moteur ici,
   uniquement de l'arithmétique publique sur les lignes saisies.
   ═══════════════════════════════════════════════════════════════════ */

/* Un prix unitaire s'affiche au centime : arrondir 7,88 € en « 8 € » fait
   perdre exactement ce qu'on cherche à surveiller. */
function eurPrix(v){
  if(v==null||isNaN(v))return '\u2014';
  var s=(Math.round(v*100)/100).toFixed(2).replace('.',',');
  return s+'\u00a0\u20ac';
}


/* ═══════════════════════════════════════════════════════════════════
   MATIÈRES — un seul module (V4.81)
   Références, achats, fournisseurs et inventaires vivaient dans deux écrans
   séparés. C'est la même matière : une seule entrée, trois onglets, une seule
   base. Aucune donnée n'est saisie deux fois.
   ═══════════════════════════════════════════════════════════════════ */

/* ═══════════════════════════════════════════════════════════════════
   MATIÈRES — PRODUITS, COMPTAGE, COMMANDE (V4.83)
   Décision Steven : l'inventaire n'est pas une application, c'est une source
   de données de Verdict. Une seule saisie alimente le stock, le coût matière
   réel, les alertes et les commandes. Cuisine et bar, niveau d'activité,
   quatre statuts — et rien de plus : Verdict ne devient pas un logiciel
   de gestion de stock.
   ═══════════════════════════════════════════════════════════════════ */
var PROD_NIV={calme:{lib:'Calme',k:0.7},normale:{lib:'Normale',k:1},forte:{lib:'Forte',k:1.3},rush:{lib:'Rush',k:1.6}};
function prodNiv(){ return PROD_NIV[DB.prodNiv]?DB.prodNiv:'normale'; }
function prodEsp(){ return (DB.prodEsp==='bar')?'bar':'cuisine'; }
function prodListe(){ var e=prodEsp(); return (DB.prod||[]).filter(function(p){ return (p.esp||'cuisine')===e; }); }
function prodPrix(p){
  if(p.prix>0)return p.prix;
  var L=(typeof achDernier==='function')?achDernier(p.nom):null;   /* le prix vient d'Achats */
  return L?L.pu:0;
}
function prodCible(p){ return Math.max(0,(p.goal||0)*PROD_NIV[prodNiv()].k); }
/* Quatre statuts, une seule signification par couleur (doctrine zones). */
function prodStatut(p){
  var s=(p.stock==null)?null:p.stock, c=prodCible(p), mini=p.min||0;
  if(s==null)return {k:'?', lib:'\u00c0 compter', h:'#8b94a0'};
  if(s<=0)return {k:'rupture', lib:'Rupture', h:'#ef4444'};
  if(s<mini)return {k:'sousmini', lib:'Sous minimum', h:'#f97316'};
  if(s<c)return {k:'commander', lib:'\u00c0 commander', h:'#eab308'};
  return {k:'ok', lib:'OK', h:'#22c55e'};
}
function prodStep(p){
  var u=String(p.unit||'').toLowerCase().replace(/\s+/g,'');
  return /^(kg|g|l|lt|litre|litres|cl|ml)$/.test(u)?0.1:1;
}
function prodAjouter(){
  if(!valider([{id:'pr-nom',nom:'Nom du produit',texte:true,ok:function(v){ return !!v; }},
               {id:'pr-goal',nom:'Stock id\u00e9al',ok:function(v){ return v!=null&&v>0; }}],'pr-nom'))return;
  DB.prod=DB.prod||[];
  DB.prod.push({id:'pr'+Date.now().toString(36), esp:prodEsp(),
    nom:document.getElementById('pr-nom').value.trim(),
    four:(document.getElementById('pr-four').value||'').trim(),
    unit:(document.getElementById('pr-unit').value||'kg'),
    goal:num(document.getElementById('pr-goal').value),
    min:num(document.getElementById('pr-min').value)||0,
    prix:num(document.getElementById('pr-prix').value)||0, stock:null});
  save(); drawAchats(); toast('Produit ajout\u00e9');
}
function prodStock(id,v){
  var p=(DB.prod||[]).filter(function(x){ return x.id===id; })[0]; if(!p)return;
  p.stock=(String(v).trim()==='')?null:num(v); save();
  var b=document.getElementById('st-'+id), s=prodStatut(p);
  if(b){ b.textContent=s.lib; b.style.color=s.h; }
  var t=document.getElementById('prodTot'); if(t)t.innerHTML=prodTotalHTML();
}
function prodSetNiv(k){ DB.prodNiv=k; save(); drawAchats(); }
function prodSetEsp(e){ DB.prodEsp=e; save(); drawAchats(); }
function prodValeur(){
  var t=0,n=0,counted=0,P=prodListe();
  P.forEach(function(p){ var pr=prodPrix(p); if(p.stock!=null){ counted++; if(pr>0){ t+=(+p.stock||0)*pr; n++; } } });
  return {eur:t,n:n,counted:counted,total:P.length};
}
function prodTotalHTML(){
  var v=prodValeur();
  return v.n?('Valeur connue\u00a0: <b>'+eur(v.eur)+'</b> \u00b7 '+v.n+'/'+v.total+' produit'+(v.total>1?'s':'')+' compt\u00e9s et chiffr\u00e9s'+(v.n<v.total?' \u2014 partiel':'')):'Rien de valoris\u00e9 pour l\u2019instant.';
}
/* Le comptage devient l'inventaire du mois : aucune ressaisie ailleurs. */
function prodValiderInventaire(){
  var v=prodValeur();
  if(!v.n){ toast('Comptez au moins un produit'); return; }
  var commit=function(){
    var m=invMoisCle(1),keys=prodListe().filter(function(p){return p.stock!=null&&prodPrix(p)>0;}).map(function(p){return p.nom;}),espace=prodEsp(),scope=invScopeHash(keys,'PROD-'+espace),debut=invDebutRepris(m,scope);
    var r={version:3, date:m, stockInitial:(debut!=null?debut:null), stockFinal:Math.round(v.eur),
           achats:Math.round(invAchatsMois(m,keys)),scopedPurchases:true,scopeHash:scope,scopeSpace:espace,consommation:null,premierComptage:!(debut!=null), qualite:(v.n===v.total?'complet':'standard'),
           references:v.n,referencesTotal:v.total,couverture:(v.total?Math.round(v.n/v.total*100):null)};
    if(invImporter(r)){ toast(INV_IMPORT_STATUS.baseline?'Premier comptage enregistr\u00e9 \u2014 base cr\u00e9\u00e9e':'Comptage envoy\u00e9 au co\u00fbt mati\u00e8re'); matAller('stock'); }
  };
  if(v.n<v.total){
    ask('Comptage partiel',v.n+'/'+v.total+' produits sont compt\u00e9s avec un prix. Verdict peut continuer, mais gardera cette couverture visible.','Continuer',commit);
  }else commit();
}
function prodCommande(){
  var par={}, tot=0;
  prodListe().forEach(function(p){
    var s=prodStatut(p); if(s.k==='ok'||s.k==='?')return;
    var step=prodStep(p), manque=Math.ceil((prodCible(p)-(p.stock||0)-1e-9)/step)*step;
    manque=Math.round(manque*100)/100; if(manque<=0)return;
    var f=(p.four||'Sans fournisseur'), pr=prodPrix(p), m=manque*pr;
    (par[f]=par[f]||{nom:f,lignes:[],eur:0});
    par[f].lignes.push({nom:p.nom, q:manque, u:p.unit, eur:m, st:s});
    par[f].eur+=m; tot+=m;
  });
  var L=[]; for(var k in par)L.push(par[k]);
  return {four:L, tot:tot};
}
function prodHTML(sous){
  var esp=prodEsp(), niv=prodNiv(), P=prodListe();
  var h='<div class="card"><div style="display:flex;gap:7px;margin-bottom:10px">'+
    [['cuisine','\ud83c\udf73 Cuisine'],['bar','\ud83c\udf78 Bar']].map(function(x){
      var ici=(x[0]===esp);
      return '<button type="button" onclick="prodSetEsp(\''+x[0]+'\')" style="flex:1;padding:10px;border-radius:11px;cursor:pointer;'+
        'border:1px solid '+(ici?'rgba(255,255,255,.28)':'rgba(255,255,255,.09)')+';background:'+(ici?'rgba(255,255,255,.06)':'transparent')+
        ';color:'+(ici?'var(--txt)':'var(--mut)')+';font-weight:700;font-size:14px">'+x[1]+'</button>';
    }).join('')+'</div>'+
    '<div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2);margin-bottom:6px">Niveau d\u2019activit\u00e9</div>'+
    '<div style="display:flex;gap:6px">'+
    Object.keys(PROD_NIV).map(function(k){
      var ici=(k===niv);
      return '<button type="button" onclick="prodSetNiv(\''+k+'\')" style="flex:1;padding:8px 4px;border-radius:9px;cursor:pointer;'+
        'border:1px solid '+(ici?'rgba(255,255,255,.28)':'rgba(255,255,255,.09)')+';background:'+(ici?'rgba(255,255,255,.06)':'transparent')+
        ';color:'+(ici?'var(--txt)':'var(--mut2)')+';font-size:12.5px">'+PROD_NIV[k].lib+'</button>';
    }).join('')+'</div>'+
    '<p class="note" style="margin:8px 0 0">Les quantit\u00e9s cibles suivent ce niveau\u00a0: en rush, Verdict vous demande d\u2019en avoir plus. '+
    'C\u2019est le rythme <b>du moment</b>, pour vos commandes \u2014 \u00e0 ne pas confondre avec la saisonnalit\u00e9 du Diagnostic, qui lit votre ann\u00e9e.</p></div>';
  if(sous==='cmd'){
    var C=prodCommande();
    h+='<div class="card"><h3>\ud83d\uded2 Ma commande</h3>';
    if(!C.four.length) h+='<p class="au-p" style="margin:6px 0 0">Rien \u00e0 commander\u00a0: tout est au-dessus de votre cible. Comptez vos produits pour actualiser.</p>';
    else{
      C.four.forEach(function(g){
        h+='<div class="au-card"><b>'+esc(g.nom)+'</b>'+
          g.lignes.map(function(l){
            return '<div class="au-ok" style="padding:6px 0"><span class="p" style="color:'+l.st.h+'">\u00b7</span>'+
              '<span style="flex:1">'+esc(l.nom)+'<br><span style="color:var(--mut);font-size:13px">'+l.st.lib+'</span></span>'+
              '<b style="font-family:var(--mono)">'+l.q+' '+esc(l.u)+(l.eur>0?' \u00b7 '+eur(l.eur):'')+'</b></div>';
          }).join('')+
          (g.eur>0?'<div class="autoline"><span class="k">Total '+esc(g.nom)+'</span><b>'+eur(g.eur)+'</b></div>':'')+'</div>';
      });
      if(C.tot>0)h+='<div class="autoline"><span class="k">Commande compl\u00e8te</span><b>'+eur(C.tot)+'</b></div>';
    }
    return h+'</div>';
  }
  /* Produits et comptage : une seule liste, on tape ce qu'on a. */
  h+='<div class="card"><h3>\u25a3 Compter \u2014 '+(esp==='bar'?'Bar':'Cuisine')+'</h3>'+
    '<p class="note" style="margin:6px 0 10px">Combien il vous en reste. C\u2019est tout\u00a0: Verdict calcule la valeur, le manque et la commande.</p>'+
    (P.length?P.map(function(p){
      var s=prodStatut(p), pr=prodPrix(p);
      return '<div style="display:flex;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid rgba(255,255,255,.05)">'+
        '<span style="flex:1;font-size:14.5px">'+esc(p.nom)+
          '<br><span style="font-size:11.5px"><b id="st-'+p.id+'" style="color:'+s.h+'">'+s.lib+'</b>'+
          '<span style="color:var(--mut2)"> \u00b7 cible '+(Math.round(prodCible(p)*10)/10)+' '+esc(p.unit)+
          (pr>0?' \u00b7 '+eurPrix(pr):'')+'</span></span></span>'+
        '<input inputmode="decimal" value="'+(p.stock!=null?String(p.stock).replace('.',','):'')+'" '+
        'oninput="prodStock(\''+p.id+'\',this.value)" style="width:78px;text-align:center;padding:9px 4px;border-radius:9px;'+
        'border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.04);color:var(--txt);font-family:var(--mono);font-size:15px"></div>';
    }).join('')+'<p class="note" id="prodTot" style="margin:10px 0 0">'+prodTotalHTML()+'</p>'+
      '<button class="btn" style="margin-top:10px" onclick="prodValiderInventaire()">Valider comme inventaire du mois</button>'
     :'<p class="au-p" style="margin:0">Aucun produit dans cet espace. Ajoutez-en un ci-dessous\u00a0: nom, stock id\u00e9al, et c\u2019est parti.</p>')+
    '</div>';
  h+='<details class="card" style="padding:14px 16px"><summary style="cursor:pointer;font-size:14px;color:var(--mut)">Ajouter un produit</summary>'+
    '<div class="g2"><label class="f"><span>Nom</span><input id="pr-nom" type="text"></label>'+
    '<label class="f"><span>Fournisseur</span><input id="pr-four" type="text"></label></div>'+
    '<div class="g2"><label class="f"><span>Unit\u00e9</span><input id="pr-unit" type="text" value="kg"></label>'+
    '<label class="f"><span>Stock id\u00e9al</span><input id="pr-goal" inputmode="decimal"></label></div>'+
    '<div class="g2"><label class="f"><span>Alerte si moins de</span><input id="pr-min" inputmode="decimal"></label>'+
    '<label class="f"><span>Prix (optionnel)</span><input id="pr-prix" inputmode="decimal"></label></div>'+
    '<p class="note" style="margin:0 0 10px">Laissez le prix vide s\u2019il figure d\u00e9j\u00e0 dans vos achats\u00a0: Verdict le reprendra.</p>'+
    '<button class="btn sec" onclick="prodAjouter()">Ajouter</button></details>';
  return h;
}


/* ═══════════════════════════════════════════════════════════════════
   QUI COMPTE LE STOCK ? (V4.85)
   Steven : « un patron paie pour que son chef travaille ; Verdict l'aide à
   piloter ». Exact. Compter 250 références n'est pas du pilotage. Verdict
   n'a besoin QUE du résultat. Le comptage reste donc masqué par défaut :
   l'équipe compte dans l'appli Inventaire, le patron colle le résultat.
   Ceux qui font tout eux-mêmes l'activent en un geste.
   ═══════════════════════════════════════════════════════════════════ */
function matCompteActif(){ return DB.matCompte===true; }
function matCompteSet(v){ DB.matCompte=!!v; if(!v&&(DB.matSub==='prod'||DB.matSub==='cmd'))DB.matSub=null; save(); drawAchats(); }
function matQuiCompteHTML(){
  var a=matCompteActif();
  return '<div class="card"><div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2)">Qui compte le stock\u00a0?</div>'+
    '<p class="au-p" style="margin:7px 0 10px">Verdict n\u2019a besoin que du r\u00e9sultat du comptage, pas de vos 250 r\u00e9f\u00e9rences. Compter, c\u2019est le travail de la cuisine\u00a0; piloter, c\u2019est le v\u00f4tre.</p>'+
    '<div style="display:flex;gap:7px">'+
      '<button type="button" onclick="matCompteSet(false)" style="flex:1;padding:11px 8px;border-radius:11px;cursor:pointer;text-align:left;'+
        'border:1px solid '+(!a?'rgba(255,255,255,.28)':'rgba(255,255,255,.09)')+';background:'+(!a?'rgba(255,255,255,.06)':'transparent')+'">'+
        '<b style="font-size:14px;color:'+(!a?'var(--txt)':'var(--mut)')+'">Mon \u00e9quipe compte</b>'+
        '<div style="font-size:12px;color:var(--mut2);margin-top:3px">dans l\u2019appli Inventaire \u2014 vous collez le r\u00e9sultat</div></button>'+
      '<button type="button" onclick="matCompteSet(true)" style="flex:1;padding:11px 8px;border-radius:11px;cursor:pointer;text-align:left;'+
        'border:1px solid '+(a?'rgba(255,255,255,.28)':'rgba(255,255,255,.09)')+';background:'+(a?'rgba(255,255,255,.06)':'transparent')+'">'+
        '<b style="font-size:14px;color:'+(a?'var(--txt)':'var(--mut)')+'">Je compte moi-m\u00eame</b>'+
        '<div style="font-size:12px;color:var(--mut2);margin-top:3px">ajoute Compter et Commande ici</div></button>'+
    '</div></div>';
}

function matBarHTML(cur){
  var T=[['achats','R\u00e9f\u00e9rences & achats'],['four','Fournisseurs'],['stock','Co\u00fbt mati\u00e8re']];
  if(matCompteActif())T.splice(1,0,['prod','Compter'],['cmd','Commande']);
  return '<div class="chips" style="margin-bottom:4px">'+
    T.map(function(x){
      var ici=(x[0]===cur);
      return '<button class="'+(ici?'on':'')+'" onclick="matAller(\''+x[0]+'\')">'+x[1]+'</button>';
    }).join('')+'</div>';
}
function matAller(k){
  if(k==='stock'){ DB.matSub=null; save(); go('stock'); return; }
  DB.matSub=(k==='achats')?null:k; save();
  if(VIEW==='achats')drawAchats(); else go('achats');
  try{ window.scrollTo({top:0,behavior:'auto'}); }catch(e){}
}
/* Les fournisseurs : ce qu'ils p\u00e8sent, et depuis quand on ne les a pas revus. */
function matFournisseurs(){
  var par={}, tot=0;
  (DB.achats||[]).forEach(function(x){
    var f=(x.four||'Sans fournisseur').trim(), v=(x.qte||0)*(x.pu||0);
    var g=par[f]||(par[f]={nom:f, val:0, refs:{}, dern:''});
    g.val+=v; g.refs[achCle(x.art)]=1; if(x.d>g.dern)g.dern=x.d; tot+=v;
  });
  var L=[]; for(var k in par){ var g=par[k]; L.push({nom:g.nom, val:g.val, n:Object.keys(g.refs).length, dern:g.dern,
    part:(tot>0?g.val/tot:0)}); }
  L.sort(function(a,b){ return b.val-a.val; });
  return {liste:L, tot:tot};
}
function matFourHTML(){
  var F=matFournisseurs();
  if(!F.liste.length){
    return '<div class="card"><h3>\ud83d\ude9a Vos fournisseurs</h3>'+
      '<p class="au-p" style="margin:6px 0 0">Ils appara\u00eetront ici d\u00e8s vos premiers achats enregistr\u00e9s, avec ce qu\u2019ils p\u00e8sent dans votre budget mati\u00e8re.</p></div>';
  }
  var auj=new Date();
  return '<div class="card"><h3>\ud83d\ude9a Vos fournisseurs</h3>'+
    '<p class="note" style="margin:6px 0 10px">Class\u00e9s par ce qu\u2019ils repr\u00e9sentent dans vos achats.</p>'+
    F.liste.slice(0,10).map(function(g){
      var j=g.dern?Math.round((auj-new Date(g.dern))/864e5):null;
      return '<div class="au-ok" style="padding:9px 0"><span class="p" style="color:var(--mut2)">\u00b7</span>'+
        '<span style="flex:1"><b>'+esc(g.nom)+'</b><br><span style="color:var(--mut);font-size:13px">'+
        g.n+' r\u00e9f\u00e9rence'+(g.n>1?'s':'')+(j!=null?' \u00b7 dernier achat il y a '+j+' j':'')+'</span></span>'+
        '<b style="font-family:var(--mono)">'+Math.round(g.part*100)+'\u00a0%</b></div>';
    }).join('')+
    (F.liste.length>1?'<p class="au-p" style="margin:10px 0 0">Un fournisseur qui p\u00e8se plus de la moiti\u00e9 de vos achats vous expose\u00a0: une hausse chez lui se voit imm\u00e9diatement sur votre marge.</p>':'')+
    '</div>';
}

function achLignes(){ return (DB.achats||[]).slice().sort(function(a,b){ return a.d<b.d?-1:1; }); }
/* ===== R172 · point 25 — référentiel produit unique : identité canonique, alias, références fournisseurs, fusion / séparation tracées ===== */
var REF_TX={titre:['Référentiel produit','Product register','Referencial de productos','Anagrafica prodotti','Produktverzeichnis','Productregister','Referencial de produtos'],
 intro:['Un produit = une seule identité, même s’il porte plusieurs noms (facture, fournisseur, inventaire, recette). Rien n’est fusionné sans votre accord, sauf les noms identiques aux majuscules et accents près.','One product = one identity, even with several names (invoice, supplier, inventory, recipe). Nothing is merged without your consent, except names identical apart from case and accents.','Un producto = una sola identidad, aunque tenga varios nombres (factura, proveedor, inventario, receta). Nada se fusiona sin su acuerdo, salvo nombres idénticos salvo mayúsculas y acentos.','Un prodotto = una sola identità, anche con più nomi (fattura, fornitore, inventario, ricetta). Nulla viene unito senza il vostro consenso, salvo nomi identici a meno di maiuscole e accenti.','Ein Produkt = eine Identität, auch mit mehreren Namen (Rechnung, Lieferant, Inventur, Rezept). Nichts wird ohne Ihre Zustimmung zusammengeführt, außer Namen, die bis auf Groß-/Kleinschreibung und Akzente gleich sind.','Eén product = één identiteit, ook met meerdere namen (factuur, leverancier, inventaris, recept). Niets wordt samengevoegd zonder uw akkoord, behalve namen die gelijk zijn op hoofdletters en accenten na.','Um produto = uma só identidade, mesmo com vários nomes (fatura, fornecedor, inventário, receita). Nada é fundido sem o seu acordo, exceto nomes idênticos a menos de maiúsculas e acentos.'],
 compte:['{p} produit(s) · {a} alias · {r} référence(s) fournisseur · {x} doublon(s) possible(s)','{p} product(s) · {a} alias(es) · {r} supplier reference(s) · {x} possible duplicate(s)','{p} producto(s) · {a} alias · {r} referencia(s) de proveedor · {x} posible(s) duplicado(s)','{p} prodotto/i · {a} alias · {r} riferimento/i fornitore · {x} possibile/i doppione/i','{p} Produkt(e) · {a} Alias · {r} Lieferantenreferenz(en) · {x} mögliche Dublette(n)','{p} product(en) · {a} alias · {r} leveranciersreferentie(s) · {x} mogelijke dubbel(s)','{p} produto(s) · {a} alias · {r} referência(s) de fornecedor · {x} possível(eis) duplicado(s)'],
 prop:['« {a} » et « {b} » : même produit ? ({n})','“{a}” and “{b}”: same product? ({n})','«{a}» y «{b}»: ¿mismo producto? ({n})','«{a}» e «{b}»: stesso prodotto? ({n})','„{a}“ und „{b}“: dasselbe Produkt? ({n})','„{a}” en „{b}”: hetzelfde product? ({n})','«{a}» e «{b}»: mesmo produto? ({n})'],
 n_moyen:['même nom au pluriel près','same name apart from plural','mismo nombre salvo plural','stesso nome a meno del plurale','gleicher Name bis auf Plural','zelfde naam op meervoud na','mesmo nome a menos do plural'],n_faible:['mots en commun, à vérifier','words in common, to check','palabras en común, a verificar','parole in comune, da verificare','gemeinsame Wörter, zu prüfen','gemeenschappelijke woorden, te controleren','palavras em comum, a verificar'],
 fusion:['Fusionner','Merge','Fusionar','Unisci','Zusammenführen','Samenvoegen','Fundir'],diff:['Différents','Different','Diferentes','Diversi','Verschieden','Verschillend','Diferentes'],separer:['Séparer','Split','Separar','Separa','Trennen','Scheiden','Separar'],
 fus:['« {b} » est un alias de « {a} » ({d})','“{b}” is an alias of “{a}” ({d})','«{b}» es un alias de «{a}» ({d})','«{b}» è un alias di «{a}» ({d})','„{b}“ ist ein Alias von „{a}“ ({d})','„{b}” is een alias van „{a}” ({d})','«{b}» é um alias de «{a}» ({d})'],
 auto:['automatique : même nom','automatic: same name','automático: mismo nombre','automatico: stesso nome','automatisch: gleicher Name','automatisch: zelfde naam','automático: mesmo nome'],vous:['votre choix du {d}','your choice of {d}','su elección del {d}','vostra scelta del {d}','Ihre Wahl vom {d}','uw keuze van {d}','a sua escolha de {d}'],
 aucune:['Aucun doublon possible détecté.','No possible duplicate detected.','Ningún posible duplicado detectado.','Nessun possibile doppione rilevato.','Keine mögliche Dublette erkannt.','Geen mogelijke dubbel gevonden.','Nenhum possível duplicado detetado.']};
function refT(k,v){var i=['fr','en','es','it','de','nl','pt'].indexOf(typeof LOCALE!=='undefined'?LOCALE:'fr');if(i<0)i=0;var a=REF_TX[k]||[k],s=a[i]||a[0];v=v||{};return String(s).replace(/\{(\w+)\}/g,function(_,x){return v[x]!=null?v[x]:'';});}
function refNorm(s){return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim();}
function refSing(n){return n.split(' ').map(function(w){return w.length>3?w.replace(/(s|x)$/,''):w;}).join(' ');}
function refResoudreCle(k){try{var R=DB&&DB.referentiel;if(!R||!R.alias)return k;var c=R.alias[refNorm(k)];return c||k;}catch(e){return k;}}
function refBase(){DB.referentiel=DB.referentiel||{alias:{},historique:[],ecartes:{}};var R=DB.referentiel;R.alias=R.alias||{};R.historique=R.historique||[];R.ecartes=R.ecartes||{};return R;}
function refSourcesNoms(){var noms={},add=function(n,src,extra){n=String(n||'').trim();if(!n)return;var k=n.toLowerCase();(noms[k]=noms[k]||{nom:n,sources:{},fournisseurs:{},unites:{}});noms[k].sources[src]=1;if(extra&&extra.four)noms[k].fournisseurs[extra.four]=1;if(extra&&extra.unite)noms[k].unites[extra.unite]=1;};
  (DB.ing||[]).forEach(function(g){add(g.nom,'carte',{unite:g.type});});(DB.achats||[]).forEach(function(a){add(a.art,'achat',{four:a.four,unite:a.unite});});
  try{var F=typeof matInventaireFrame==='function'?matInventaireFrame():null,D=F&&F.inventaireDonneesMatiere?F.inventaireDonneesMatiere():null;(D&&D.produits||[]).forEach(function(p){add(p.name,'inventaire',{unite:p.unit});});}catch(e){}return noms;}
function refRafraichir(){var R=refBase(),N=refSourcesNoms(),par={};Object.keys(N).forEach(function(k){var n=refNorm(k);(par[n]=par[n]||[]).push(k);});
  Object.keys(par).forEach(function(n){var ks=par[n];if(ks.length<2)return;var canon=ks.slice().sort(function(a,b){return Object.keys(N[b].sources).length-Object.keys(N[a].sources).length||a.localeCompare(b);})[0];
    ks.forEach(function(k){if(k===canon)return;if(!R.alias[n]||R.alias[n]!==canon){R.alias[n]=canon;R.historique.push({type:'auto-fort',principal:canon,secondaire:k,at:new Date().toISOString()});}});});
  var refs=0;Object.keys(DB.factureMemoire||{}).forEach(function(){refs++;});return {noms:N,refs:refs};}
function refCanoniques(){var R=refBase(),S=refRafraichir(),can={};Object.keys(S.noms).forEach(function(k){var c=refResoudreCle(k);(can[c]=can[c]||{cle:c,nom:(S.noms[c]||S.noms[k]).nom,alias:[],sources:{},fournisseurs:{}});if(c!==k)can[c].alias.push(S.noms[k].nom);Object.keys(S.noms[k].sources).forEach(function(x){can[c].sources[x]=1;});Object.keys(S.noms[k].fournisseurs).forEach(function(x){can[c].fournisseurs[x]=1;});});return {produits:can,refs:S.refs};}
function refPropositions(){var R=refBase(),C=refCanoniques().produits,ks=Object.keys(C),out=[];for(var i=0;i<ks.length;i++)for(var j=i+1;j<ks.length;j++){var a=ks[i],b=ks[j],pk=[a,b].sort().join('||');if(R.ecartes[pk])continue;var na=refNorm(C[a].nom),nb=refNorm(C[b].nom);
    if(refSing(na)===refSing(nb)){out.push({a:a,b:b,niveau:'moyen'});continue;}var wa=refSing(na).split(' ').filter(function(w){return w.length>2;}),wb=refSing(nb).split(' ').filter(function(w){return w.length>2;});var inter=wa.filter(function(w){return wb.indexOf(w)>=0;}).length,uni=wa.length+wb.length-inter;
    if(inter>=2&&uni>0&&inter/uni>=0.6)out.push({a:a,b:b,niveau:'faible'});}
  out.sort(function(x,y){return (x.niveau==='moyen'?0:1)-(y.niveau==='moyen'?0:1);});return out;}
function refFusionner(principal,secondaire){var R=refBase();principal=refResoudreCle(principal);if(!principal||!secondaire||principal===secondaire)return false;R.alias[refNorm(secondaire)]=principal;Object.keys(R.alias).forEach(function(n){if(R.alias[n]===secondaire)R.alias[n]=principal;});
  R.historique.push({type:'fusion',principal:principal,secondaire:secondaire,at:new Date().toISOString()});try{save();}catch(e){}return true;}
function refSeparer(secondaire){var R=refBase(),n=refNorm(secondaire);if(!R.alias[n])return false;var p=R.alias[n];delete R.alias[n];R.ecartes[[p,secondaire].sort().join('||')]=true;R.historique.push({type:'separation',principal:p,secondaire:secondaire,at:new Date().toISOString()});try{save();}catch(e){}return true;}
function refEcarter(a,b){var R=refBase();R.ecartes[[a,b].sort().join('||')]=true;R.historique.push({type:'ecarte',a:a,b:b,at:new Date().toISOString()});try{save();}catch(e){}return true;}
function refClic(btn){var a=btn.getAttribute('data-a'),b=btn.getAttribute('data-b'),op=btn.getAttribute('data-op');if(op==='fusion')refFusionner(a,b);else if(op==='diff')refEcarter(a,b);else if(op==='separer')refSeparer(b);try{drawAchats();}catch(e){}}
function refHTML(){var C=refCanoniques(),P=refPropositions(),R=refBase(),nA=Object.keys(R.alias).length,jj=function(x){x=String(x||'').slice(0,10);return x?x.split('-').reverse().join('/'):'—';},q=function(x){return String(x).replace(/&/g,'&amp;').replace(/"/g,'&quot;');};
  var h='<div class="card" id="referentielProduit"><h3 style="margin:0 0 4px">'+aideEsc(refT('titre'))+'</h3><p class="note" style="margin:0 0 6px">'+aideEsc(refT('intro'))+'</p><p class="note" style="margin:0 0 6px;font-weight:600">'+aideEsc(refT('compte',{p:Object.keys(C.produits).length,a:nA,r:C.refs,x:P.length}))+'</p>';
  if(!P.length)h+='<p class="note">'+aideEsc(refT('aucune'))+'</p>';
  P.slice(0,8).forEach(function(x){var A=C.produits[x.a],B=C.produits[x.b];h+='<div class="ref-prop" data-niveau="'+x.niveau+'" style="padding:6px 0;border-top:1px solid rgba(255,255,255,.07)"><p class="note" style="margin:0 0 4px">'+aideEsc(refT('prop',{a:A.nom,b:B.nom,n:refT(x.niveau==='moyen'?'n_moyen':'n_faible')}))+'</p><button type="button" class="btn ghost" data-op="fusion" data-a="'+q(x.a)+'" data-b="'+q(x.b)+'" onclick="refClic(this)">'+aideEsc(refT('fusion'))+'</button> <button type="button" class="btn ghost" data-op="diff" data-a="'+q(x.a)+'" data-b="'+q(x.b)+'" onclick="refClic(this)">'+aideEsc(refT('diff'))+'</button></div>';});
  var H=R.historique.filter(function(e){return (e.type==='fusion'||e.type==='auto-fort')&&R.alias[refNorm(e.secondaire)]===e.principal;});
  H.slice(-8).reverse().forEach(function(e){var pn=(C.produits[e.principal]||{}).nom||e.principal;h+='<div class="ref-fus" style="padding:4px 0"><p class="note" style="margin:0">'+aideEsc(refT('fus',{a:pn,b:e.secondaire,d:e.type==='auto-fort'?refT('auto'):refT('vous',{d:jj(e.at)})}))+' <button type="button" class="btn ghost" data-op="separer" data-a="'+q(e.principal)+'" data-b="'+q(e.secondaire)+'" onclick="refClic(this)">'+aideEsc(refT('separer'))+'</button></p></div>';});
  return h+'</div>';}
window.refClic=refClic;window.refFusionner=refFusionner;window.refSeparer=refSeparer;window.refEcarter=refEcarter;window.refPropositions=refPropositions;window.refCanoniques=refCanoniques;window.refResoudreCle=refResoudreCle;window.refNorm=refNorm;

function achCle(art){ var k=String(art||'').trim().toLowerCase(); return typeof refResoudreCle==='function'?refResoudreCle(k):k; }
function achDernier(art){
  var L=achLignes().filter(function(x){ return achCle(x.art)===achCle(art); });
  return L.length?L[L.length-1]:null;
}
/* Un article = son historique de prix, son prix moyen pondéré, sa variation. */
function achArticles(){
  var par={};
  achLignes().forEach(function(x){
    var k=achCle(x.art); if(!k)return;
    (par[k]=par[k]||{art:x.art, four:x.four, unite:x.unite, lignes:[]}).lignes.push(x);
  });
  var out=[];
  for(var k in par){
    var a=par[k], L=a.lignes, qt=0, val=0;
    L.forEach(function(x){ qt+=(x.qte||0); val+=(x.qte||0)*(x.pu||0); });
    var prem=L[0], dern=L[L.length-1];
    var varPct=(prem.pu>0)?((dern.pu-prem.pu)/prem.pu*100):0;
    /* Impact annuel à consommation constante : écart de prix × quantité annualisée. */
    var jours=Math.max(1,(new Date(dern.d)-new Date(prem.d))/864e5);
    var qteAn=(jours>=28)?(qt/jours*365):(qt*12);
    out.push({art:a.art, four:dern.four, unite:a.unite, esp:dern.esp||'commun', n:L.length,
      premier:prem.pu, dernier:dern.pu, moyen:(qt>0?val/qt:0),
      varPct:varPct, qteAn:qteAn, impact:(dern.pu-prem.pu)*qteAn, lignes:L});
  }
  out.sort(function(x,y){ return Math.abs(y.impact)-Math.abs(x.impact); });
  return out;
}
function achAjouter(){
  var f=document.getElementById('ac-four'), a=document.getElementById('ac-art'),
      q=document.getElementById('ac-qte'), u=document.getElementById('ac-unite'), p=document.getElementById('ac-pu'),e=document.getElementById('ac-esp');
  if(!valider([
      {id:'ac-art',nom:'Article',texte:true,ok:function(v){ return !!v; }},
      {id:'ac-qte',nom:'Quantit\u00e9',ok:function(v){ return v!=null&&v>0; }},
      {id:'ac-pu',nom:'Prix unitaire HT',ok:function(v){ return v!=null&&v>0; }}
    ],'ac-art'))return;
  DB.achats=DB.achats||[];
  DB.achats.push({d:new Date().toISOString().slice(0,10), four:(f.value||'').trim(),
    art:a.value.trim(), qte:num(q.value), unite:(u.value||'kg'), pu:num(p.value),esp:(e&&e.value)||'commun'});
  save(); a.value=''; q.value=''; p.value=''; drawAchats();
  toast('Achat enregistr\u00e9');
}
/* Prix pré-rempli au dernier payé : on ne corrige que ce qui a changé. */
function achPrefill(){
  var a=document.getElementById('ac-art'), p=document.getElementById('ac-pu'),
      f=document.getElementById('ac-four'), u=document.getElementById('ac-unite'), e=document.getElementById('ac-esp'), n=document.getElementById('ac-hint');
  if(!a)return;
  var L=achDernier(a.value);
  if(L){ if(!p.value)p.value=String(L.pu).replace('.',','); if(!f.value)f.value=L.four||''; if(u)u.value=L.unite||'kg';if(e)e.value=L.esp||'commun';
    if(n)n.innerHTML='Dernier prix pay\u00e9 : <b>'+eur(L.pu)+'</b> / '+(L.unite||'kg')+' \u00b7 le '+L.d.split('-').reverse().join('/'); }
  else if(n)n.textContent='Nouvel article \u2014 il servira de r\u00e9f\u00e9rence pour les prochains achats.';
}

/* ═══ CE QUI EXPLIQUE LA DÉRIVE (V4.80) ═══
   Steven veut « une intelligence absolue, une vraie aide ». Pas une alerte de
   plus : la responsabilité chiffrée. Quels ingrédients font monter le coût,
   combien ça coûte à l'année, et lesquels valent qu'on décroche le téléphone.
   Arithmétique publique : hausse du prix × quantité annualisée achetée. */
function matDerive(){
  var A=(typeof achArticles==='function')?achArticles():[];
  var L=A.filter(function(a){ return a.n>1 && a.impact>0 && a.varPct>=2; })
         .map(function(a){ return {nom:a.art, four:a.four, pct:a.varPct, impact:a.impact, part:0}; });
  var tot=0; L.forEach(function(x){ tot+=x.impact; });
  L.forEach(function(x){ x.part=(tot>0?x.impact/tot*100:0); });
  L.sort(function(a,b){ return b.impact-a.impact; });
  /* Combien d'ingrédients suffisent à expliquer l'essentiel ? */
  var cum=0, n=0;
  for(var i=0;i<L.length;i++){ cum+=L[i].part; n++; if(cum>=70)break; }
  return {liste:L, total:tot, nExplique:n, partExplique:Math.round(cum)};
}
function matDeriveHTML(){
  var D=matDerive();
  if(!D.liste.length)return '';
  var R=moteur(), pctRes=(R&&R.ready&&R.d.res!==0)?Math.abs(D.total/R.d.res*100):0;
  var h='<div class="card" style="border-left:3px solid #f97316">'+
    '<div style="font-family:var(--mono);font-size:11.5px;letter-spacing:.07em;text-transform:uppercase;color:var(--mut2)">Ce qui fait monter vos co\u00fbts</div>';
  if(D.liste.length>1&&D.nExplique<=3){
    h+='<b style="display:block;font-size:16.5px;margin:7px 0 4px">'+D.nExplique+' ingr\u00e9dient'+(D.nExplique>1?'s':'')+
      ' expliquent '+D.partExplique+'\u00a0% de la hausse</b>';
  } else {
    h+='<b style="display:block;font-size:16.5px;margin:7px 0 4px">'+D.liste.length+' r\u00e9f\u00e9rence'+(D.liste.length>1?'s':'')+' en hausse</b>';
  }
  h+='<p class="au-p" style="margin:0 0 10px">\u00c0 consommation constante, ces hausses repr\u00e9sentent <b>'+eur(D.total)+'</b> par an'+
    (pctRes>3?' \u2014 soit '+Math.round(pctRes)+'\u00a0% de votre r\u00e9sultat actuel':'')+'.</p>'+
    D.liste.slice(0,4).map(function(x){
      return '<div class="au-ok" style="padding:8px 0"><span class="p" style="color:#f97316">\u00b7</span>'+
        '<span style="flex:1"><b>'+esc(x.nom)+'</b>'+(x.four?' <span style="color:var(--mut2)">\u00b7 '+esc(x.four)+'</span>':'')+
        '<br><span style="color:var(--mut);font-size:13px">+'+(Math.round(x.pct*10)/10).toString().replace('.',',')+'\u00a0% \u00b7 '+
        Math.round(x.part)+'\u00a0% de la hausse totale</span></span>'+
        '<b style="font-family:var(--mono);color:#f97316">'+eur(x.impact)+'/an</b></div>';
    }).join('')+
    '<p class="au-p" style="margin:10px 0 0;color:var(--txt)"><b>\u2192</b> '+
    (D.liste.length?'Commencez par <b>'+esc(D.liste[0].nom)+'</b>\u00a0: c\u2019est la ligne o\u00f9 un appel au fournisseur rapporte le plus.':'')+'</p>'+
    '<button class="btn sec" style="margin-top:10px" onclick="go(\'dec\')">Tester l\u2019effet sur mon r\u00e9sultat</button>'+
    '<p class="note" style="margin:8px 0 0">Calcul \u00e0 consommation constante\u00a0: si vous en achetez moins, l\u2019effet sera moindre. Une hausse ponctuelle n\u2019est pas une tendance.</p></div>';
  return h;
}

function achObservatoire(){
  var A=achArticles();
  if(!A.length){
    return '<div class="card"><h3>\ud83d\uded2 Vos achats, article par article</h3>'+
      '<p class="note" style="margin:8px 0 0">D\u00e8s le deuxi\u00e8me achat d\u2019un m\u00eame article, Verdict compare les prix et chiffre ce qu\u2019une hausse vous co\u00fbte sur l\u2019ann\u00e9e. Une ligne prend dix secondes.</p></div>';
  }
  var haut=A.filter(function(x){ return x.varPct>=3&&x.n>1; }),
      bas=A.filter(function(x){ return x.varPct<=-3&&x.n>1; });
  var h=matDeriveHTML();
  var h='<div class="card"><h3>\ud83d\udcc8 Ce que vos prix ont fait</h3>';
  if(!haut.length&&!bas.length) h+='<p class="note" style="margin:8px 0 0">Aucune variation notable pour l\u2019instant. Verdict surveille chaque article d\u00e8s qu\u2019il a deux prix \u00e0 comparer.</p>';
  haut.slice(0,4).forEach(function(x){
    h+='<div class="au-card" style="border-left:3px solid #f97316"><b>'+esc(x.art)+'</b>'+
      '<p class="au-p" style="margin:6px 0 0">Le prix est pass\u00e9 de <b>'+eurPrix(x.premier)+'</b> \u00e0 <b>'+eurPrix(x.dernier)+'</b> par '+esc(x.unite)+
      ' \u2014 <b style="color:#f97316">+'+(Math.round(x.varPct*10)/10).toString().replace('.',',')+'\u00a0%</b>.'+
      (x.impact>50?'<br>\u00c0 consommation constante, cela repr\u00e9sente environ <b>'+eur(x.impact)+'</b> par an.':'')+'</p>'+
      '<p class="au-p" style="margin:8px 0 0;color:var(--txt)"><b>\u2192</b> Ren\u00e9gocier, comparer un autre fournisseur, ou r\u00e9percuter sur les plats qui l\u2019utilisent.</p></div>';
  });
  bas.slice(0,2).forEach(function(x){
    h+='<div class="au-card" style="border-left:3px solid #22c55e"><b>'+esc(x.art)+'</b>'+
      '<p class="au-p" style="margin:6px 0 0">Le prix a baiss\u00e9 de <b>'+(Math.round(-x.varPct*10)/10).toString().replace('.',',')+'\u00a0%</b> \u2014 '+eurPrix(x.dernier)+' par '+esc(x.unite)+'.'+
      '<br>\u00c0 confirmer sur la prochaine facture : une baisse ponctuelle n\u2019est pas un nouveau tarif.</p></div>';
  });
  /* Le total, puis la décision — jamais un chiffre seul. */
  var tot=0; haut.forEach(function(x){ if(x.impact>0)tot+=x.impact; });
  if(tot>100) h+='<div class="au-card"><span class="au-k">Effet cumul\u00e9 des hausses</span>'+
    '<div class="au-eur" style="color:#f97316">'+eur(tot)+' /an</div>'+
    '<p class="au-p" style="margin:8px 0 0;font-size:14px">\u00c0 consommation constante, sur les articles suivis. Ce n\u2019est pas une perte constat\u00e9e : c\u2019est ce que la hausse repr\u00e9sente si rien ne change.</p>'+
    '<button class="btn sec" style="margin-top:10px" onclick="go(\'dec\')">Tester l\u2019effet sur mon r\u00e9sultat</button></div>';
  h+='</div>';
  /* La base : ce que les autres modules utiliseront. */
  h+='<div class="card"><h3>\ud83d\udcda Votre base d\u2019articles</h3>'+
    '<p class="note" style="margin:6px 0 10px">'+A.length+' article'+(A.length>1?'s':'')+' suivi'+(A.length>1?'s':'')+
    '. Ces prix alimenteront votre carte, votre co\u00fbt mati\u00e8re et vos simulations.</p>'+
    '<input type="search" placeholder="Rechercher une r\u00e9f\u00e9rence" oninput="achFiltre(this.value)" value="'+esc(DB._q||'')+'" '+
      'style="width:100%;margin:0 0 10px;padding:11px 12px;border-radius:10px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.04);color:var(--txt);font-size:15px">'+
    A.filter(function(x){ return !DB._q || x.art.toLowerCase().indexOf(DB._q)>=0 || (x.four||'').toLowerCase().indexOf(DB._q)>=0; })
     .slice(0,20).map(function(x){
      return '<div class="autoline"><span class="k">'+esc(x.art)+(x.four?' \u00b7 '+esc(x.four):'')+'</span>'+
        '<b>'+eurPrix(x.dernier)+' / '+esc(x.unite)+'</b>'+
        '<button type="button" onclick="achDupliquer(\''+esc(x.art).replace(/'/g,'')+'\')" '+
        'style="margin-left:8px;padding:5px 9px;border-radius:8px;border:1px solid rgba(255,255,255,.10);background:transparent;color:var(--mut2);font-size:12px;cursor:pointer">racheter</button></div>';
    }).join('')+'</div>';
  return h;
}

/* ═══════════════════════════════════════════════════════════════════
   REMPLIR LA BASE SANS Y PASSER LA SOIRÉE (V4.80)
   Steven : « le succès de cette architecture dépend du fait que la Base
   Matière soit simple à construire ». Trois portes : import d'un fichier ou
   d'un copier-coller, recherche instantanée, duplication d'une référence.
   Rien n'entre sans être montré d'abord.
   ═══════════════════════════════════════════════════════════════════ */
function csvSep(l){
  var c=[[';',(l.split(';').length)],[',',(l.split(',').length)],['\t',(l.split('\t').length)]];
  c.sort(function(a,b){ return b[1]-a[1]; });
  return c[0][1]>1?c[0][0]:';';
}
function csvNombre(s){
  if(s==null)return null;
  s=String(s).replace(/[^\d,.\-]/g,'').replace(/\s/g,'');
  if(s.indexOf(',')>=0 && s.indexOf('.')>=0) s=s.replace(/\./g,'');
  s=s.replace(',','.');
  var v=parseFloat(s); return isFinite(v)?v:null;
}
/* On devine les colonnes : les fichiers fournisseurs ne se ressemblent jamais. */
function csvColonnes(entete){
  var m={art:-1,pu:-1,unite:-1,four:-1,qte:-1,date:-1,esp:-1};
  entete.forEach(function(h,i){
    h=(h||'').toLowerCase().replace(/[^a-z]/g,'');
    if(m.art<0&&/(article|produit|designation|libelle|reference|nom)/.test(h))m.art=i;
    else if(m.pu<0&&/(prixunitaire|prixht|puht|pu|prix|tarif)/.test(h))m.pu=i;
    else if(m.unite<0&&/(unite|unit|conditionnement|cond)/.test(h))m.unite=i;
    else if(m.four<0&&/(fournisseur|four|supplier)/.test(h))m.four=i;
    else if(m.qte<0&&/(quantite|qte|qty|nombre)/.test(h))m.qte=i;
    else if(m.date<0&&/(date|jour)/.test(h))m.date=i;
    else if(m.esp<0&&/(espace|rayon|famille|cuisinebar)/.test(h))m.esp=i;
  });
  return m;
}
function csvAnalyser(txt){
  var lignes=String(txt||'').split(/\r?\n/).filter(function(l){ return l.trim(); });
  if(lignes.length<2)return {ok:[],ko:[],msg:'Il faut au moins une ligne d\u2019en-t\u00eate et une ligne de donn\u00e9es.'};
  var sep=csvSep(lignes[0]);
  var ent=lignes[0].split(sep).map(function(x){ return x.trim().replace(/^"|"$/g,''); });
  var col=csvColonnes(ent);
  if(col.art<0||col.pu<0) return {ok:[],ko:[],msg:'Colonnes introuvables\u00a0: il faut au minimum un nom d\u2019article et un prix.'};
  var ok=[], ko=[];
  lignes.slice(1).forEach(function(l,n){
    var p=l.split(sep).map(function(x){ return x.trim().replace(/^"|"$/g,''); });
    var art=p[col.art]||'', pu=csvNombre(p[col.pu]);
    if(!art||!(pu>0)){ ko.push({n:n+2, l:l.slice(0,44)}); return; }
    ok.push({d:(col.date>=0&&/^\d{4}-\d{2}-\d{2}$/.test(p[col.date]))?p[col.date]:new Date().toISOString().slice(0,10),
      art:art, pu:pu, unite:(col.unite>=0?(p[col.unite]||'kg'):'kg'),
      four:(col.four>=0?(p[col.four]||''):''), qte:(col.qte>=0?(csvNombre(p[col.qte])||1):1),
      esp:(col.esp>=0&&/bar/i.test(p[col.esp]||'')?'bar':(col.esp>=0&&/cuisine/i.test(p[col.esp]||'')?'cuisine':'commun'))});
  });
  return {ok:ok, ko:ko, msg:''};
}
var CSV_LOT=null;
function csvApercu(){
  var t=document.getElementById('csv-txt'); if(!t)return;
  var r=csvAnalyser(t.value); CSV_LOT=r.ok;
  var el=document.getElementById('csv-res'); if(!el)return;
  if(r.msg){ el.innerHTML='<p class="note" style="margin:8px 0 0;color:#f97316">'+r.msg+'</p>'; return; }
  el.innerHTML='<div class="au-card" style="margin-top:10px"><b>'+r.ok.length+' r\u00e9f\u00e9rence'+(r.ok.length>1?'s':'')+' lue'+(r.ok.length>1?'s':'')+'</b>'+
    (r.ko.length?'<br><span style="color:#f97316;font-size:13.5px">'+r.ko.length+' ligne'+(r.ko.length>1?'s':'')+' ignor\u00e9e'+(r.ko.length>1?'s':'')+' (nom ou prix manquant)\u00a0: '+
      r.ko.slice(0,2).map(function(x){ return 'ligne '+x.n; }).join(', ')+'</span>':'')+
    '<div style="margin-top:8px;font-size:13px;color:var(--mut)">'+
      r.ok.slice(0,4).map(function(x){ return esc(x.art)+' \u00b7 '+eurPrix(x.pu)+' / '+esc(x.unite)+(x.four?' \u00b7 '+esc(x.four):''); }).join('<br>')+
      (r.ok.length>4?'<br>\u2026 et '+(r.ok.length-4)+' autre'+(r.ok.length-4>1?'s':''):'')+'</div>'+
    (r.ok.length?'<button class="btn" style="margin-top:10px" onclick="csvImporter()">Ajouter ces '+r.ok.length+' r\u00e9f\u00e9rences</button>':'')+
    '</div>';
}
function csvImporter(){
  if(!CSV_LOT||!CSV_LOT.length){ toast('Rien \u00e0 importer'); return; }
  DB.achats=(DB.achats||[]).concat(CSV_LOT);
  save(); CSV_LOT=null;
  var t=document.getElementById('csv-txt'); if(t)t.value='';
  drawAchats(); toast('Base compl\u00e9t\u00e9e');
}
function csvFichier(inp){
  var f=inp.files&&inp.files[0]; if(!f)return;
  var r=new FileReader();
  r.onload=function(){ var t=document.getElementById('csv-txt'); if(t){ t.value=r.result; csvApercu(); } };
  r.readAsText(f);
}
function achDupliquer(art){
  var L=achDernier(art); if(!L)return;
  var a=document.getElementById('ac-art'), f=document.getElementById('ac-four'),
      u=document.getElementById('ac-unite'), p=document.getElementById('ac-pu'),e=document.getElementById('ac-esp');
  if(a)a.value=L.art; if(f)f.value=L.four||''; if(u)u.value=L.unite||'kg'; if(p)p.value=String(L.pu).replace('.',',');if(e)e.value=L.esp||'commun';
  try{ achPrefill(); }catch(e){}
  try{ a.scrollIntoView({block:'center',behavior:'smooth'}); a.focus(); }catch(e){}
  toast('Repris \u2014 corrigez ce qui a chang\u00e9');
}
function achFiltre(v){ DB._q=(v||'').toLowerCase(); drawAchats(); }
function csvHTML(){
  return '<details class="card" style="padding:14px 16px"><summary style="cursor:pointer;font-size:14px;color:var(--mut)">Importer mes r\u00e9f\u00e9rences depuis un fichier</summary>'+
    '<p class="note" style="margin:8px 0 10px">Un export de votre fournisseur, un tableur, un copier-coller\u00a0: Verdict reconna\u00eet les colonnes tout seul. Il vous montre ce qu\u2019il a compris <b>avant</b> d\u2019ajouter quoi que ce soit.</p>'+
    '<input type="file" accept=".csv,.txt,text/csv" onchange="csvFichier(this)" style="font-size:13px;margin-bottom:8px">'+
    '<textarea id="csv-txt" oninput="csvApercu()" placeholder="ou collez ici\u00a0: Article;Prix;Unit\u00e9;Fournisseur" '+
      'style="width:100%;height:72px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.12);border-radius:10px;color:var(--txt);font-family:var(--mono);font-size:12px;padding:9px"></textarea>'+
    '<div id="csv-res"></div></details>';
}

