function point6T(){var l=(typeof LOCALE==='string'?LOCALE:'fr');return POINT6_TEXT[l]||POINT6_TEXT.fr;}

function point6Calc(R){
  R=R||moteur();var m=invMoisCle(1),i=invLire(m),A=i?invAnalyse(i,R):null,ach=invAchatsMois(m),state='purchases',action='Enregistrer ou importer les achats du mois';
  if(ach>0&&!i){state='first';action='Faire un premier comptage pour créer le point de départ';}
  else if(i&&i.debut==null){state='baseline';action='Conserver le même périmètre et compter à la prochaine clôture';}
  else if(A&&A.invalid){state='invalid';action='Vérifier dates, achats, avoirs, transferts et stocks';}
  else if(A&&!A.comparable){state='scope';action='Refaire le même périmètre ou un inventaire complet';}
  else if(A&&A.ready&&!A.theo){state='menu';action='Importer les ventes caisse du même mois et compléter les fiches techniques';}
  else if(A&&A.ready&&A.theo){state='answer';action=Math.abs(A.theo.gap)>Math.max(50,A.conso*.03)?'Contrôler les références les plus chères et les pertes connues':'Maintenir le même comptage au prochain mois';}
  return {month:m,inv:i,analysis:A,purchases:ach,state:state,action:action};
}
function point6HTML(R){
  var P=point6Calc(R),A=P.analysis,t=point6T(),col=P.state==='invalid'?'#ef4444':(P.state==='scope'?'#f97316':(P.state==='answer'?'#22c55e':'#60a5fa'));
  var action=P.state==='answer'?(Math.abs(A.theo.gap)>Math.max(50,A.conso*.03)?t.actions.gap:t.actions.stable):t.actions[P.state];
  var h='<div id="point6-material" data-point="point6-material"><div class="au-tag">'+t.tag+'</div><h2 class="au-h">'+t.q+'</h2><div class="card" role="status" aria-live="polite" style="border-left:3px solid '+col+'"><h3>'+t.titles[P.state]+'</h3>';
  if(A&&A.ready)h+='<div class="autoline"><span class="k">'+t.consumption+'</span><b>'+eur(A.conso)+'</b></div>'+(A.fc!=null?'<div class="autoline"><span class="k">'+t.ratio+'</span><b>'+pct(A.fc)+'</b></div>':'')+(A.theo?'<div class="autoline"><span class="k">'+t.recipes+'</span><b>'+pct(A.theo.pct)+'</b></div><div class="autoline"><span class="k">'+t.gap+'</span><b style="color:'+(Math.abs(A.theo.gap)>Math.max(50,A.conso*.03)?'#f97316':'#22c55e')+'">'+(A.theo.gap>=0?'+':'−')+eur(Math.abs(A.theo.gap))+'</b></div>':'');
  else if(P.inv&&P.inv.fin!=null)h+='<div class="autoline"><span class="k">'+t.stock+'</span><b>'+eur(P.inv.fin)+'</b></div>';
  else h+='<div class="autoline"><span class="k">'+t.purchases+'</span><b>'+eur(P.purchases)+'</b></div>';
  h+='<p class="au-p" style="color:var(--txt)"><b>'+t.next+' :</b> '+action+'.</p><p class="note">'+t.note+'</p>'+
    '<div class="g2"><button class="btn sec" onclick="matAller(\'achats\')">'+t.seePurchases+'</button><button class="btn" onclick="matAller(\'stock\')">'+t.count+'</button></div></div></div>';
  return h;
}

function achSaisie(){
  return '<div class="card"><h3>\u2795 Ajouter un achat</h3>'+
    '<p class="note" style="margin:6px 0 10px">Six informations, dix secondes. Le prix se pr\u00e9-remplit au dernier pay\u00e9 : vous ne corrigez que ce qui a chang\u00e9.</p>'+
    '<div class="g2">'+
      '<label class="f"><span>Article</span><input id="ac-art" type="text" oninput="achPrefill()" placeholder="ex. filet de poulet"></label>'+
      '<label class="f"><span>Fournisseur</span><input id="ac-four" type="text" placeholder="ex. Metro"></label>'+
    '</div><div class="g2">'+
      '<label class="f"><span>Quantit\u00e9</span><input id="ac-qte" inputmode="decimal"></label>'+
      '<label class="f"><span>Unit\u00e9</span><select id="ac-unite"><option>kg</option><option>L</option><option>unit\u00e9</option><option>pi\u00e8ce</option></select></label>'+
    '</div><label class="f"><span>Espace concern\u00e9</span><select id="ac-esp"><option value="commun">Commun / les deux</option><option value="cuisine">Cuisine</option><option value="bar">Bar</option></select><small>Le module reste unique ; ce rep\u00e8re permet de filtrer sans ressaisir.</small></label>'+
    '<label class="f"><span>Prix unitaire HT (\u20ac)</span><input id="ac-pu" inputmode="decimal"></label>'+
    '<p class="note" id="ac-hint" style="margin:2px 0 10px"></p>'+
    '<button class="btn" onclick="achAjouter()">Enregistrer cet achat</button></div>';
}

function drawAchats(){
  var R=moteur(), el=document.getElementById("achatsBody");
  var _s=DB.matSub||'achats';
  var _obs=point6HTML(R)+matBarHTML(_s)+(
      _s==='four' ? matFourHTML() :
      _s==='prod' ? prodHTML('prod') :
      _s==='cmd'  ? prodHTML('cmd')  :
      (matQuiCompteHTML()+achSaisie()+csvHTML()+achObservatoire()));   /* l’observatoire d’abord, la répartition ensuite */
  if(!R.ready){ var _r0='';try{if(_s==='prod'||_s==='achats')_r0=refHTML();}catch(_e){} el.innerHTML=_obs+_r0; setTimeout(achPrefill,0); return; }
  setTimeout(achPrefill,0);
  var d=R.d;
  var rows=[["Nourriture",d.nour],["Boissons",d.boi],["Emballages / packaging",d.emb],["Autres co\u00fbts variables",d.autv],["Commissions plateformes",d.com]];
  var tot=rows.reduce(function(a,r){return a+r[1];},0);
  var h='<div class="kpis"><div class="kpi"><div class="k">Total achats variables / an</div><div class="v">'+eur(tot)+'</div><div class="d">'+pc(d.ca>0?tot/d.ca*100:0,1)+' du CA</div></div>'+
    '<div class="kpi"><div class="k">Food cost r\u00e9el</div><div class="v">'+pc(R.v.fc,1)+'</div><div class="d">achats nourriture seuls</div></div></div>';
  h+='<div class="card"><h3>R\u00e9partition</h3>';
  rows.forEach(function(r){
    var pct=tot>0?r[1]/tot*100:0;
    h+='<div class="ind"><div class="n"><b>'+r[0]+'</b><span>'+pc(d.ca>0?r[1]/d.ca*100:0,1)+' du CA</span></div>'+
      '<div class="bario" style="width:74px"><i style="width:'+Math.max(2,pct)+'%;background:#60a5fa"></i></div>'+
      '<div class="v" style="min-width:70px;text-align:right">'+eur(r[1])+'</div></div>';
  });
  h+='</div><button class="btn sec" onclick="go(\'in\')">Modifier dans Param\u00e8tres</button>';
  if(d.com>0){
    var pfPlats=DB.plats.filter(function(p){return p.pf;});
    var margeSurPlace=0,margePf=0,volPf=0;
    pfPlats.forEach(function(p){ var k=platCalc(p); if(k.pf){ margePf+=k.pf.marge*(p.vol||0); margeSurPlace+=k.marge*(p.vol||0); volPf+=(p.vol||0); } });
    h+='<div class="card"><h3>&#128666; Impact Uber Eats / Deliveroo</h3>'+
      '<div class="autoline"><span class="k">Commissions annuelles</span><b>'+eur(d.com)+'</b></div>'+
      '<div class="autoline"><span class="k">% du CA</span><b>'+pc(d.ca>0?d.com/d.ca*100:0,1)+'</b></div>'+
      (volPf>0?('<div class="autoline"><span class="k">Marge perdue vs vente sur place ('+volPf+' ventes/mois)</span><b style="color:var(--orange)">'+eur((margeSurPlace-margePf)*12)+'/an</b></div>'):'')+
      '</div><p class="note">Chaque point de commission au-dessus de 15 % du CA devient un signal dans Alertes.</p>';
  }
  var _ref='';try{if(_s==='prod'||_s==='achats')_ref=refHTML()+reglesHTML();}catch(_e){}
  el.innerHTML=_obs+h+_ref;
}
/* ═══ OBJECTIFS ═══ */
function drawObj(){
  var R=moteur(), el=document.getElementById("objBody");
  if(!R.ready){ needData(el); return; }
  var d=R.d;
  if(!d.obj||d.obj<=0){
    el.innerHTML='<div class="warn on">Aucun objectif fix\u00e9. Renseignez un objectif de r\u00e9sultat net annuel dans Param\u00e8tres.</div>'+
      '<button class="btn sec" onclick="goIn(\'i-obj\')">Fixer un objectif</button>';
    return;
  }
  var pctAtteint=d.obj>0?Math.max(0,Math.min(150,d.res/d.obj*100)):0;
  var col=d.res>=d.obj?"var(--green)":(d.res>=d.obj*0.6?"var(--yellow)":"var(--orange)");
  var manque=Math.max(0,d.obj-d.res);
  var h='<div class="score-hero"><div class="ring" style="--ringcol:'+col+'">'+ringSVG(Math.min(100,pctAtteint),col,116)+
    '<div class="num"><b style="color:'+col+'">'+Math.round(pctAtteint)+'%</b><span>de l\u2019objectif</span></div></div>'+
    '<div><div class="zt" style="color:'+col+'">'+(d.res>=d.obj?"Objectif atteint":"En cours")+'</div>'+
    '<div class="zs">R\u00e9sultat actuel '+eur(d.res)+' pour un objectif de '+eur(d.obj)+'.</div></div></div>';
  h+='<div class="kpis">'+
    '<div class="kpi"><div class="k">Objectif annuel</div><div class="v">'+eur(d.obj)+'</div><div class="d">fix\u00e9 dans Param\u00e8tres</div></div>'+
    '<div class="kpi"><div class="k">R\u00e9sultat actuel (structure)</div><div class="v">'+eur(d.res)+'</div><div class="d">avant imp\u00f4t</div></div>'+
    '<div class="kpi"><div class="k">Reste \u00e0 g\u00e9n\u00e9rer</div><div class="v" style="color:'+(manque>0?"var(--orange)":"var(--green)")+'">'+eur(manque)+'</div><div class="d">'+(manque>0?"pour atteindre l\u2019objectif":"objectif d\u00e9pass\u00e9")+'</div></div>'+
    '<div class="kpi"><div class="k">CA suppl\u00e9mentaire n\u00e9cessaire</div><div class="v">'+(R.v.mc>0&&manque>0?eur(manque/(d.mc/d.ca)):"\u2014")+'</div><div class="d">au taux de marge actuel</div></div></div>'+
    '<button class="btn sec" onclick="goIn(\'i-obj\')">Modifier l\u2019objectif</button>';
  el.innerHTML=h;
}
/* ═══ ALERTES ═══ */
var VERDICT_ALERT_PREFERENCES={verdict_score:true,verdict_cash:true,verdict_margin:true,verdict_deadline:true,inventory_submission:true,inventory_stockout:true,inventory_low:true,inventory_order:true,access_security:true};
var VERDICT_ALERT_PREFERENCES_READY=false;
function verdictAlertPreferenceOn(key){return VERDICT_ALERT_PREFERENCES[key]!==false;}
function verdictLoadAlertPreferences(){
  if(VERDICT_ALERT_PREFERENCES_READY||VERDICT_DEMO_SESSION||VERDICT_PRESENTATION_PROFILE||window.VERDICT_TEAM_API_READY!==true)return;
  VERDICT_ALERT_PREFERENCES_READY=true;
  fetch('/api/team/manager?scope=alerts',{credentials:'same-origin',cache:'no-store'}).then(function(response){if(!response.ok)throw new Error('unavailable');return response.json();}).then(function(result){
    var preferences=result&&result.preferences;if(!preferences||typeof preferences!=='object')return;
    Object.keys(VERDICT_ALERT_PREFERENCES).forEach(function(key){if(typeof preferences[key]==='boolean')VERDICT_ALERT_PREFERENCES[key]=preferences[key];});
    if(VIEW==='alertes')drawAlertes();
  }).catch(function(){});
}
function alertesState(){
  var R=moteur();if(!R||!R.ready)return {ready:false,checks:[],critical:[],warning:[],ok:[]};
  var v=R.v,d=R.d, st=DB.plats.length?carteStats():null;
  var checks=[
    {pref:"verdict_score",n:"Score Verdict",ok:R.score>=75,warn:R.score>=50,val:Math.round(R.score)+"/100",msg:zone(R.score).t},
    {pref:"verdict_margin",n:"Rentabilit\u00e9 nette",ok:v.rn>=8,warn:v.rn>=0,val:pc(v.rn,1),msg:v.rn<0?"Structure en perte":(v.rn<8?"Sous la zone saine (8\u201310 %)":"Zone saine")},
    {pref:"verdict_margin",n:"Masse salariale",ok:v.ms<=35,warn:v.ms<=38,val:pc(v.ms,0),msg:v.ms>38?"Seuil critique franchi (38 %)":(v.ms>35?"Vigilance (rep\u00e8re 35 %)":"Sous contr\u00f4le")},
    {pref:"verdict_margin",n:"Food cost",ok:v.fc<=35,warn:v.fc<=40,val:pc(v.fc,0),msg:v.fc>40?"Seuil critique franchi (40 %)":(v.fc>35?"Au-dessus du rep\u00e8re (35 %)":"Sous contr\u00f4le")},
    {pref:"verdict_cash",n:"Point mort",ok:v.pm<85,warn:v.pm<95,val:v.pm<999?pc(v.pm,0):"\u2014",msg:v.pm>=95?"Le mois ne suffit presque plus":(v.pm>=85?"Tardif dans le mois":"Confortable")},
    {pref:"verdict_margin",n:"Commissions plateformes",ok:v.com<=10,warn:v.com<=15,val:pc(v.com,0),msg:v.com>15?"Part command\u00e9e lourde":(v.com>10?"\u00c0 surveiller":"Faible")}
  ];
  if(st&&st.theoR>0){
    var pts=v.fc-st.theoR;
    checks.push({pref:"verdict_margin",n:"\u00c9cart food cost (th\u00e9orie vs r\u00e9el)",ok:pts<4,warn:pts<8,val:fr(pts,1)+" pts",msg:pts>=8?"\u00c9cart notable \u00e0 investiguer":(pts>=4?"\u00c9cart mod\u00e9r\u00e9":"Concorde")});
  }
  checks=checks.filter(function(check){return verdictAlertPreferenceOn(check.pref);});
  return {ready:true,checks:checks,critical:checks.filter(function(c){return !c.warn;}),warning:checks.filter(function(c){return c.warn&&!c.ok;}),ok:checks.filter(function(c){return c.ok;})};
}
function drawAlertes(){
  var el=document.getElementById("alertesBody"),state=alertesState();
  var prefButton=document.getElementById('alertPreferencesButton'),prefCopy=PLUS_ALERT_SETTINGS[LOCALE]||PLUS_ALERT_SETTINGS.fr;if(prefButton)prefButton.textContent='🔔 '+prefCopy.c;
  if(!state.ready){ needData(el); return; }
  var checks=state.checks,rouges=state.critical,oranges=state.warning,deadlines=verdictAlertPreferenceOn('verdict_deadline')?rappels():[];
  var h='<div class="kpis"><div class="kpi"><div class="v" style="color:var(--red)">'+rouges.length+'</div><div class="k">critique(s)</div></div>'+
    '<div class="kpi"><div class="v" style="color:var(--orange)">'+oranges.length+'</div><div class="k">vigilance</div></div><div class="kpi"><div class="v" style="color:var(--yellow)">'+deadlines.length+'</div><div class="k">échéance(s)</div></div></div>';
  deadlines.forEach(function(reminder){h+='<div class="item" style="border-left-color:var(--yellow)"><div class="l1"><div style="flex:1"><div class="nm">🟡 '+reminder.titre+'</div><div class="u">'+reminder.txt+'</div></div><button type="button" class="btn2" onclick="goRap(\''+reminder.cle+'\',\''+reminder.vue+'\')">'+reminder.btn+'</button></div></div>';});
  checks.forEach(function(c){
    var col=!c.warn?"var(--red)":(!c.ok?"var(--orange)":"var(--green)");
    var dot=!c.warn?"\ud83d\udd34":(!c.ok?"\ud83d\udfe0":"\ud83d\udfe2");
    h+='<div class="item" style="border-left-color:'+col+'"><div class="l1"><div style="flex:1"><div class="nm">'+dot+' '+c.n+'</div><div class="u">'+c.msg+'</div></div>'+
      '<div class="v" style="color:'+col+'">'+c.val+'</div></div></div>';
  });
  if(!checks.length&&!deadlines.length)h+='<div class="card"><b>Aucune famille d’alerte Verdict active.</b><p class="note">Rouvrez « Choisir les alertes que je reçois » pour en sélectionner une.</p></div>';
  try{h+=verdictNotifHTML();}catch(_n){}h+='<p class="note">'+aideEsc(typeof ntfSyncTexte==='function'?ntfSyncTexte():'')+'</p>';
  el.innerHTML=h;
}
/* ═══ SANTÉ ENTREPRISE ═══ */
function drawSante(){
  var R=moteur(), el=document.getElementById("santeBody");
  if(!R.ready){ needData(el); return; }
  var ser=DecisionEngine.SerenityEngine.compute(DB);
  function zoneCol(score){
    return zone(score).h;
  }
  function state(score){return score<30?'Critique':(score<55?'À renforcer':(score<75?'Correct':'Solide'));}
  var axes=[['Rentabilit\u00e9','rent'],['Carte','carte'],['Personnel','perso'],['Stock','stock'],['Point mort','pm'],['Tr\u00e9sorerie','tresor'],['R\u00e9silience','resilience']];
  axes.sort(function(a,b){return ser.scores[a[1]]-ser.scores[b[1]];});
  var h='<div class="card" data-v12-solidity-diagnostic><h3>Diagnostic de solidit\u00e9</h3>'+
    '<div class="solidarity-status" style="border-color:'+zoneCol(ser.total)+'"><b>'+state(ser.total)+'</b><span>Lecture compl\u00e9mentaire · aucun second score</span></div>'+
    '<p class="note" style="margin:0 0 12px">Sept domaines sont recoup\u00e9s pour montrer ce qui fragilise la structure. Cette lecture ne remplace pas et ne modifie jamais le score Verdict.</p>'+
    '<div class="solidarity-grid">'+axes.map(function(a){var s=ser.scores[a[1]];return '<div class="solidarity-axis"><span>'+a[0]+'</span><b style="color:'+zoneCol(s)+'">'+state(s)+'</b></div>';}).join('')+'</div>'+
    '<div class="warn on" style="margin:12px 0 0;border-color:'+zoneCol(ser.scores[axes[0][1]])+'"><b>Premier domaine à vérifier : '+axes[0][0]+'</b><br>Ouvrez le module correspondant pour lire les preuves, la couverture et les données manquantes.</div>'+
    '<p class="note" style="margin-top:12px">Les calculs historiques restent conservés pour la compatibilité des anciens dossiers, mais ne sont plus affichés comme une note concurrente.</p></div>';
  el.innerHTML=h;
}
/* ═══ SAUVEGARDE FICHIER ═══ */
function backup(){
  if(VERDICT_PRESENTATION_PROFILE||VERDICT_DEMO_SESSION){toast("Sauvegarde désactivée dans la démonstration fictive");return false;}
  try{
    if(!verdictPayloadAllowed(STORE)){toast("Sauvegarde refusée : une démonstration fictive ne peut pas entrer dans un dossier réel");return false;}
    var sm=verdictSafetyMeta();sm.manualBackupAt=new Date().toISOString();save("manual-backup");
    var blob=new Blob([JSON.stringify(STORE)],{type:"application/json"});
    var a=document.createElement("a"); a.href=URL.createObjectURL(blob);
    a.download="verdict-sauvegarde-"+new Date().toISOString().slice(0,10)+".json";
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(a.href); },1500);
    /* V2 : le navigateur ne dit pas si le fichier a vraiment été écrit (un aperçu intégré peut bloquer le
       téléchargement). Le message ne promet donc pas un fichier qui n’existe peut-être pas. */
    var _bkI={fr:"Sauvegarde envoyée au navigateur. Vérifiez vos téléchargements : un aperçu intégré peut bloquer le fichier.",
      en:"Backup sent to the browser. Check your downloads: an embedded preview may block the file.",
      es:"Copia enviada al navegador. Revise sus descargas: una vista previa integrada puede bloquear el archivo.",
      it:"Backup inviato al browser. Controlla i download: un’anteprima integrata può bloccare il file.",
      de:"Sicherung an den Browser übergeben. Prüfen Sie Ihre Downloads: Eine eingebettete Vorschau kann die Datei blockieren.",
      nl:"Back-up naar de browser gestuurd. Controleer uw downloads: een ingesloten voorbeeld kan het bestand blokkeren.",
      pt:"Cópia enviada ao navegador. Verifique as transferências: uma pré-visualização integrada pode bloquear o ficheiro."};
    toast(_bkI[typeof LOCALE==="string"?LOCALE:"fr"]||_bkI.fr);
    return true;
  }catch(e){ toast("Sauvegarde impossible ici"); }
}
function restore(input){
  if(VERDICT_PRESENTATION_PROFILE||VERDICT_DEMO_SESSION){if(input)input.value="";toast("Restauration désactivée dans la démonstration fictive");return false;}
  var f=input.files&&input.files[0]; if(!f)return;
  var r=new FileReader();
  r.onload=function(){
    try{ var o=JSON.parse(r.result);
      if(!verdictPayloadAllowed(o)){toast("Restauration refusée : ce fichier contient une démonstration fictive");return;}
      verdictBeforeRisk("before-file-restore").then(function(ok){if(!ok)return;
        if(o&&o.etabs&&o.ordre&&o.ordre.length){
          var n=o.ordre.length;if(verdictApplyStore(o,n+" \u00e9tablissement"+(n>1?"s":"")+" restaur\u00e9"+(n>1?"s":"")))return;
        }
        else if(validDB(o)){STORE.etabs[STORE.actif]=fixDB(o);setActif(STORE.actif);save("file-restore-single");fillInputs();readInputs();drawEtabs();refreshAll();go("pil");toast("Donn\u00e9es restaur\u00e9es");return;}
        toast("Fichier non reconnu");
      });
    }catch(e){ toast("Fichier illisible"); }
  };
  r.readAsText(f); input.value="";
}
/* Le filet tactile commun R10 utilise Pointer Events et ne diffère plus un
   clic de 320 ms. Il est chargé en fin de document. */
/* ═══ TRIAL BANNER ═══ */
/* Repartir du début : on rejoue l'ouverture avec le score du nouvel
   établissement. Le rythme est choisi ensuite selon données réelles ou modèle. */
var _introBusy=false;
function rejouerIntro(msg){ return replayIntro(msg); }
function replayIntro(msg,done,profile){
  /* Une demande en double ne doit jamais appeler done() pendant que la
     première révélation tourne : done() ouvre la visite guidée et couperait
     visuellement le score avant 100 puis son retour au score réel. */
  if(_introBusy)return false;
  var old=document.getElementById("splash");
  if(old&&old.parentNode)old.parentNode.removeChild(old);
  if(window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches){ if(msg)toast(msg); if(typeof done==='function')done(); return true; }
  var d=document.createElement("div"); d.id="splash";
  d.innerHTML='<div id="sp-bg"></div><div id="sp-lueur"></div><div id="sp-grain"></div>'+
    '<div id="sp-onde"></div><div id="sp-onde2"></div><div id="sp-tete"></div><div id="sp-scene"></div>'+
    '<div id="sp-line"></div>'+
    '<div id="sp-ring" role="status" aria-label="Ouverture de Verdict" data-progress="0"><svg viewBox="0 0 200 200" aria-hidden="true"><circle class="rb" cx="100" cy="100" r="86"/>'+
      '<circle class="ra" id="sp-arc" cx="100" cy="100" r="86"/></svg>'+
      '<div class="rv"><strong class="sp-load-word">VERDICT</strong><span class="sp-load-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="sp-score-readout"><b id="sp-num">0</b><i>/ 100</i></span></div></div>'+
    '<div id="sp-demo-context" aria-live="polite"></div>'+
    '<div id="sp-zones" aria-hidden="true"><span data-zone="crit">'+esc(t('z.crit'))+'</span><span data-zone="frag">'+esc(t('z.fragile'))+'</span><span data-zone="corr">'+esc(t('z.correct'))+'</span><span data-zone="saine">'+esc(t('z.sane'))+'</span></div>'+
    '<div id="sp-row"><span id="sp-logo">VERDICT<i>&reg;</i></span><b id="sp-score"></b></div>'+
    '<div id="sp-tag"></div>';
  document.body.appendChild(d);
  var replayTag=d.querySelector('#sp-tag');if(replayTag)replayTag.textContent=t('tagline');
  _introBusy=true;
  var replayDone=false,replayWatchdog;
  function terminerReplay(){
    if(replayDone)return;replayDone=true;
    if(replayWatchdog)clearTimeout(replayWatchdog);
    _introBusy=false;
    var s=document.getElementById("splash"); if(s&&s.parentNode)s.parentNode.removeChild(s);
    var t=document.querySelector(".top"); if(t)t.classList.remove("intro-hide");
    if(msg)toast(msg);
    if(profile==='discovery')setTimeout(function(){try{demoScoreCueStop();}catch(e){}},180);
    if(typeof done==='function')try{done();}catch(e){}
  }
  runIntro("replay",terminerReplay,profile||"auto");
  /* Filet uniquement : la fin normale vient du vrai handoff de l'animation.
     Il ne doit plus couper le cercle ou la phrase sur un téléphone lent. */
  if(!replayDone)replayWatchdog=setTimeout(terminerReplay,12000);
  return true;
}

/* ═══ Ouverture : progression neutre, jamais confondue avec le score ═══ */
function spZone(n){ return scoreZone(n); }
var SP_CIRC=2*Math.PI*86, SP_COULEUR="#22c55e";
var SP_ZONE_PREC=null,SP_RING_GEOM=null;
function spGeomRing(force){
  var rg=document.getElementById('sp-ring');if(!rg)return null;
  if(!SP_RING_GEOM||force){
    var q=rg.getBoundingClientRect();
    SP_RING_GEOM={width:q.width,height:q.height,cx:q.left+q.width/2,cy:q.top+q.height/2,radius:(q.width/2)*(86/100)};
  }
  return SP_RING_GEOM;
}
/* La pointe lumineuse suit la tête de l'arc : on la place sur le cercle. */
function spTete(n){
  var t=document.getElementById('sp-tete'), rg=document.getElementById('sp-ring');
  if(!t||!rg)return;
  var q=spGeomRing(false);if(!q)return;
  var a=(-90+n*3.6)*Math.PI/180;
  t.style.left=Math.round(q.cx+q.radius*Math.cos(a))+'px';
  t.style.top=Math.round(q.cy+q.radius*Math.sin(a))+'px';
  if(!t.dataset.spReady){t.style.transform='translate(-50%,-50%)';t.dataset.spReady='1';}
  var visible=(n>1&&n<100)?'1':'0';if(t.style.opacity!==visible)t.style.opacity=visible;
}
/* Onde brève au franchissement d'une zone : on marque le passage. */
function spOnde(){
  var o=document.getElementById('sp-onde'), rg=document.getElementById('sp-ring');
  if(!o||!rg)return;
  var q=spGeomRing(false);if(!q)return;
  o.style.width=Math.round(q.width)+'px'; o.style.height=Math.round(q.height)+'px';
  o.style.left=Math.round(q.cx)+'px'; o.style.top=Math.round(q.cy)+'px';
  o.classList.remove('on'); void o.offsetWidth; o.classList.add('on');
}
function spPeindre(n){
  var a=document.getElementById('sp-arc'),l=document.getElementById('sp-lueur'),
      ring=document.getElementById('sp-ring');
  SP_COULEUR="#22c55e";
  if(!a)return;
  n=Math.max(0,Math.min(100,Number(n)||0));
  var rounded=Math.round(n);
  if(ring&&ring.getAttribute('data-progress')!==String(rounded))ring.setAttribute('data-progress',String(rounded));
  a.style.strokeDashoffset=SP_CIRC*(1-n/100);
  if(SP_ZONE_PREC!=='opening'){
    a.style.strokeDasharray=SP_CIRC;a.style.stroke=SP_COULEUR;a.style.filter="drop-shadow(0 0 12px rgba(34,197,94,.55))";
    /* Le halo géant ne change qu'une fois : le repeindre à chaque image
       saturait inutilement le compositeur Safari. */
    if(l)l.style.backgroundImage="radial-gradient(closest-side, "+
      SP_COULEUR+"80 0%, "+SP_COULEUR+"55 22%, "+SP_COULEUR+"2A 44%, "+SP_COULEUR+"10 62%, rgba(8,9,11,0) 80%)";
    SP_ZONE_PREC='opening';
  }
  spTete(n);
}
/* Le nombre n'apparaît qu'après le choix explicite d'un modèle fictif. La
   première ouverture de l'application reste une progression de marque neutre. */
function spPeindreScore(n){
  var a=document.getElementById('sp-arc'),l=document.getElementById('sp-lueur'),
      ring=document.getElementById('sp-ring'),b=document.getElementById('sp-num'),zs=document.getElementById('sp-zones');
  if(!a)return;
  n=Math.max(0,Math.min(100,Number(n)||0));
  var z=spZone(n),rounded=Math.round(n),zc=z.c,zoneChanged=SP_ZONE_PREC!==zc;SP_COULEUR=z.h;
  if(ring&&ring.getAttribute('data-progress')!==String(rounded))ring.setAttribute('data-progress',String(rounded));
  if(b&&b.textContent!==String(rounded))b.textContent=String(rounded);
  a.style.strokeDashoffset=SP_CIRC*(1-n/100);
  if(zoneChanged){
    if(b)b.style.color=SP_COULEUR;
    a.style.strokeDasharray=SP_CIRC;a.style.stroke=SP_COULEUR;a.style.filter='drop-shadow(0 0 13px '+SP_COULEUR+'99)';
    if(l)l.style.backgroundImage='radial-gradient(closest-side, '+SP_COULEUR+'80 0%, '+SP_COULEUR+'55 22%, '+SP_COULEUR+'2A 44%, '+SP_COULEUR+'10 62%, rgba(8,9,11,0) 80%)';
    if(zs)[].forEach.call(zs.children,function(el){
      var on=el.getAttribute('data-zone')===zc;
      el.style.color=on?'#fff':'#5f6873';el.style.borderColor=on?SP_COULEUR:'rgba(255,255,255,.08)';
      el.style.background=on?SP_COULEUR+'26':'transparent';
    });
    if(SP_ZONE_PREC)spOnde();
  }
  spTete(n);SP_ZONE_PREC=zc;
}
