    fr:{demo:'Démonstration fictive',real:'Verdict de l’établissement',proof:'Score illustratif, jamais un score final client'},
    en:{demo:'Fictional demonstration',real:'Business verdict',proof:'Illustrative score, never a final client score'},
    es:{demo:'Demostración ficticia',real:'Veredicto del establecimiento',proof:'Puntuación ilustrativa, nunca una puntuación final'},
    it:{demo:'Dimostrazione fittizia',real:'Verdetto dell’attività',proof:'Punteggio illustrativo, mai un punteggio cliente finale'},
    de:{demo:'Fiktive Demonstration',real:'Betriebsbewertung',proof:'Beispielscore, niemals ein finaler Kundenscore'},
    nl:{demo:'Fictieve demonstratie',real:'Bedrijfsoordeel',proof:'Illustratieve score, nooit een definitieve klantscore'},
