var FORMAT_ORDER=["Restaurant traditionnel","Brasserie","Restaurant gastronomique","Table gastronomique d’exception",
 "Restaurant italien","Restaurant asiatique","Bar à tapas","Restaurant à burgers","Pizzeria","Kebab",
 "Food truck","Dark kitchen","Coffee shop","Traiteur","Boulangerie"];
function fmtActif(){ var t=DB&&DB.etabType; return (t&&FORMATS[t])?t:null; }
function famActive(){ var f=fmtActif(); return f?FAMILLES[FORMATS[f].f]:null; }
function repFormat(){ var f=fmtActif(); return f?FORMATS[f]:null; }
function repFamille(k){ var F=famActive(); return (F&&F[k])?F[k]:null; }

/* ═══ FACE AUX REPÈRES — seuils Verdict + statistique FIBEN vérifiée ═══ */
var SECT=[
 {k:"rn",n:"Marge avant imp\u00f4t",cli:null,sec:4,sain:10,u:"%",inv:false,d:"ce qui reste avant imp\u00f4t selon vos charges saisies"},
 {k:"mc",n:"Contribution % CA",cli:null,sec:55,sain:65,u:"%",inv:false,d:"ce que chaque vente laisse pour payer le fixe"},
 {k:"cv",n:"Co\u00fbts variables % CA",cli:null,sec:40,sain:35,u:"%",inv:true,d:"mati\u00e8re, packaging, commissions"},
 {k:"ms",n:"Masse salariale % CA",cli:null,sec:37.5,sain:30,u:"%",inv:true,d:"un poste majeur à surveiller"},
 {k:"acf",n:"Charges fixes % CA",cli:null,sec:20,sain:null,u:"%",inv:true,d:"loyer, \u00e9nergie, assurances \u2014 hors salaires"},
 {k:"pm",n:"Point mort % CA",cli:null,sec:85,sain:75,u:"%",inv:true,d:"la part du CA qui ne sert qu\u2019\u00e0 survivre"},
 {k:"sen",n:"Sensibilit\u00e9 \u00e0 \u221210 % CA",cli:null,sec:2,sain:10,u:"%",inv:false,d:"votre marge si le CA c\u00e8de de 10 %"},
 {k:"cas",n:"CA par ETP",cli:null,sec:75,sain:200,u:"k",inv:false,d:"productivit\u00e9 calcul\u00e9e uniquement sur les ETP renseign\u00e9s"},
 {k:"score",n:"Score Verdict\u00ae",cli:null,sec:45,sain:75,u:"pts",inv:false,d:"la structure compl\u00e8te, not\u00e9e"}
];
var RADAR_SCALE={rn:[-5,15],mc:[40,75],cv:[60,30],ms:[55,25],pm:[110,60],sen:[-5,12],cas:[40,220]};
function benchVals(R){
  var v=R.v,d=R.d;
  return {rn:v.rn,mc:v.mc,cv:v.cv,ms:v.ms,acf:v.acf,pm:v.pm<999?v.pm:120,sen:v.sen,
    cas:d.caSalarie==null?null:d.caSalarie/1000,score:R.score};
}
function bfmt(val,u){
  if(u==="k")return fr(val,0)+" k\u20ac";
  if(u==="pts")return fr(val,0);
  return pc(val,1);
}
function deltaChip(cli,ref,inv,u,lbl){
  if(ref==null)return "";
  var diff=cli-ref, good=inv?diff<=0:diff>=0;
  var col=good?"var(--green)":"var(--orange)";
  var sign=diff>=0?"+":"\u2212";
  var mag=Math.abs(diff);
  var txt=u==="k"?fr(mag,0)+" k":(u==="pts"?fr(mag,0)+" pt":fr(mag,1)+" pt");
  return '<span class="chipd" style="color:'+col+';border-color:'+col+'33">'+sign+txt+' '+lbl+'</span>';
}
function radarSVG(R){
  var bv=benchVals(R), axes=["rn","mc","cv","ms","pm","sen"];
  /* L'axe CA/ETP n'existe que si le client a réellement renseigné son
     effectif. Un point artificiel au centre ferait croire à une mauvaise
     productivité alors que la donnée est simplement absente. */
  if(bv.cas!=null)axes.push("cas");
  var names={rn:"Rentab.",mc:"Contrib.",cv:"Co\u00fbts var.",ms:"Salaires",pm:"Point mort",sen:"Choc \u221210 %",cas:"CA/ETP"};
  var cx=170,cy=158,rr=112,N=axes.length;
  function norm(k,val){
    var s=RADAR_SCALE[k],lo=s[0],hi=s[1];
    var t=(val-lo)/(hi-lo);
    if(hi<lo)t=(val-lo)/(hi-lo);
    return Math.max(0.06,Math.min(1,t));
  }
  function pt(i,t){
    var a=-Math.PI/2+i*2*Math.PI/N;
    return [(cx+Math.cos(a)*rr*t).toFixed(1),(cy+Math.sin(a)*rr*t).toFixed(1)];
  }
  function poly(vals){
    return vals.map(function(t,i){ return pt(i,t).join(","); }).join(" ");
  }
  function seriesFor(get){
    return axes.map(function(k){
      var val=get(k);
      return val==null?0.06:norm(k,val);
    });
  }
  var secV={rn:4,mc:55,cv:40,ms:37.5,pm:85,sen:2,cas:75};
  var sainV={rn:10,mc:65,cv:35,ms:30,pm:75,sen:10,cas:200};
  var svg='<svg viewBox="0 0 340 330" style="width:100%;max-width:420px;display:block;margin:0 auto">';
  [0.25,0.5,0.75,1].forEach(function(t){
    svg+='<polygon points="'+poly(axes.map(function(){return t;}))+'" fill="none" stroke="#1e242c" stroke-width="1"/>';
  });
  axes.forEach(function(k,i){
    var p=pt(i,1);
    svg+='<line x1="'+cx+'" y1="'+cy+'" x2="'+p[0]+'" y2="'+p[1]+'" stroke="#1e242c" stroke-width="1"/>';
    var lp=pt(i,1.19);
    svg+='<text x="'+lp[0]+'" y="'+lp[1]+'" fill="#8b94a0" font-size="10.5" font-weight="600" text-anchor="middle" dominant-baseline="middle">'+names[k]+'</text>';
  });
  svg+='<polygon points="'+poly(seriesFor(function(k){return sainV[k];}))+'" fill="rgba(34,197,94,.09)" stroke="rgba(34,197,94,.55)" stroke-width="1.4" stroke-dasharray="4 3"/>';
  svg+='<polygon points="'+poly(seriesFor(function(k){return secV[k];}))+'" fill="rgba(139,148,160,.10)" stroke="#5f6873" stroke-width="1.3"/>';
  var me=seriesFor(function(k){return bv[k];});
  var mz=zone(R.score);
  svg+='<polygon points="'+poly(me)+'" fill="'+mz.h+'22" stroke="'+mz.h+'" stroke-width="2.2" stroke-linejoin="round"/>';
  me.forEach(function(t,i){ var p=pt(i,t);
    svg+='<circle cx="'+p[0]+'" cy="'+p[1]+'" r="3.4" fill="'+mz.h+'"/>'; });
  svg+='</svg>';
  return svg+'<div class="rleg"><span><i style="background:'+mz.h+'"></i>Vous</span><span><i style="background:#5f6873"></i>Repère</span><span><i style="background:rgba(34,197,94,.7)"></i>Zone cible</span></div>';
}
function drawBench(R,el){
  var bv=benchVals(R), d=R.d, sc=R.score, z=zone(sc);
  /* ── 1. position globale ── */
  var dSain=sc-75;
  var phrase;
  if(sc>=75)phrase="Votre structure atteint la zone cible Verdict. Le score reste un indicateur de pilotage interne, pas un classement sectoriel.";
  else if(sc>=45)phrase="Votre structure d\u00e9passe le seuil de vigilance Verdict. La zone cible est \u00e0 "+fr(-dSain,0)+" point"+(-dSain>1?"s":"")+" \u2014 les indicateurs ci-dessous montrent o\u00f9 agir.";
  else phrase="Votre structure reste sous le seuil de vigilance Verdict. Les indicateurs ci-dessous montrent ce qui p\u00e8se le plus.";
  function mark(val,col,lb,strong){
    var x=Math.max(2,Math.min(98,val));
    return '<div class="gmark'+(strong?" gme":"")+'" style="left:'+x+'%;--mc:'+col+'"><i></i><b>'+lb+'</b></div>';
  }
  var h='<div class="card"><h3>Votre position <span class="r">score Verdict\u00ae</span></h3>'+
    '<div class="gauge"><div class="gtrack"><i class="gseg" style="left:0;width:45%;background:rgba(249,115,22,.16)"></i>'+
    '<i class="gseg" style="left:45%;width:30%;background:rgba(234,179,8,.14)"></i>'+
    '<i class="gseg" style="left:75%;width:25%;background:rgba(34,197,94,.16)"></i></div>'+
    mark(45,"#5f6873","Vigilance 45")+mark(75,"#22c55e","Cible 75")+mark(sc,z.h,"Vous "+fr(sc,0),true)+
    '</div><p class="gphrase">'+phrase+'</p></div>';
  /* ── 2. votre résultat et la statistique FIBEN : deux métriques séparées ── */
  var rn=bv.rn;
  h+='<div class="card"><h3>Marge avant imp\u00f4t <span class="r">mesure Verdict\u00ae</span></h3>'+
    '<div class="autoline"><span class="k">Votre r\u00e9sultat avant imp\u00f4t / CA HT</span><b style="color:'+z.h+'">'+pc(rn,1)+'</b></div>'+
    '<p class="note" style="margin:8px 0 12px">Ce ratio vient de vos charges saisies. Il ne doit pas \u00eatre compar\u00e9 directement \u00e0 un agr\u00e9gat FIBEN qui n\u2019a pas la m\u00eame d\u00e9finition comptable.</p>'+
    '<div style="padding:12px;border-radius:12px;background:rgba(96,165,250,.08);border:1px solid rgba(96,165,250,.18)">'+
      '<b>Banque de France FIBEN \u00b7 secteur 56 Restauration \u00b7 2024</b>'+
      '<p class="note" style="margin:6px 0 0">Taux d\u2019exc\u00e9dent brut global / CA HT : <b>Q1 4,6 %</b> \u00b7 <b>m\u00e9diane 8,8 %</b> \u00b7 <b>Q3 13,9 %</b>. Statistique sectorielle affich\u00e9e pour contexte, sans transformer votre marge avant imp\u00f4t en faux classement.</p>'+
    '</div></div>';
  /* ── 3. radar ── */
  h+='<div class="card"><h3>La structure en un regard <span class="r">'+(bv.cas==null?'6':'7')+' axes normalis\u00e9s</span></h3>'+radarSVG(R)+
    '<p class="note">Plus la surface colori\u00e9e s\u2019approche du polygone vert, plus elle rejoint la zone cible Verdict. Le polygone gris = le rep\u00e8re de pilotage Verdict, pas une moyenne statistique officielle.</p></div>';
  /* ── 4. forces & vigilance ── */
  var comps=[];
  SECT.forEach(function(s){
    if(s.k==="score")return;
    var cli=bv[s.k]; if(cli==null)return;
    var diff=cli-s.sec, good=s.inv?diff<=0:diff>=0;
    var mag=s.u==="k"?Math.abs(diff)/Math.max(s.sec,1)*10:Math.abs(diff);
    comps.push({n:s.n,cli:cli,s:s,good:good,mag:mag,diff:diff});
  });
  comps.sort(function(a,b){ return b.mag-a.mag; });
  var forces=comps.filter(function(x){return x.good;}).slice(0,3);
  var vigil=comps.filter(function(x){return !x.good;}).slice(0,3);
  h+='<div class="g2s">';
  h+='<div class="card"><h3 style="color:var(--green)">\u2714 Vos points solides</h3>'+
    (forces.length?forces.map(function(f){ return '<div class="ind"><div class="n"><b>'+f.n+'</b><span>vous '+bfmt(f.cli,f.s.u)+' \u00b7 rep\u00e8re '+bfmt(f.s.sec,f.s.u)+'</span></div><div class="s" style="width:auto">'+deltaChip(f.cli,f.s.sec,f.s.inv,f.s.u,"")+'</div></div>'; }).join(""):'<p class="sub">Aucun indicateur au-dessus de son rep\u00e8re pour l\u2019instant.</p>')+'</div>';
  h+='<div class="card"><h3 style="color:var(--orange)">\u26a0 Vos points \u00e0 travailler</h3>'+
    (vigil.length?vigil.map(function(f){ return '<div class="ind"><div class="n"><b>'+f.n+'</b><span>vous '+bfmt(f.cli,f.s.u)+' \u00b7 rep\u00e8re '+bfmt(f.s.sec,f.s.u)+'</span></div><div class="s" style="width:auto">'+deltaChip(f.cli,f.s.sec,f.s.inv,f.s.u,"")+'</div></div>'; }).join(""):'<p class="sub">Tous vos indicateurs atteignent leur rep\u00e8re Verdict.</p>')+'</div>';
  h+='</div>';
  /* ── 5. les 9 cartes détaillées ── */
  h+='<h2 class="sec">Les 9 rep\u00e8res de pilotage</h2>';
  SECT.forEach(function(s){
    var cli=bv[s.k]; if(cli==null)return;
    var vals=[cli,s.sec]; if(s.sain!=null)vals.push(s.sain);
    var mx=Math.max.apply(null,vals)*1.12||1;
    function bar(val,col,lb,strong){
      return '<div class="brow"><span>'+lb+'</span><div class="btrk"><i style="width:'+Math.max(2,Math.min(100,val/mx*100))+'%;background:'+col+(strong?'':';opacity:.55')+'"></i></div><b>'+bfmt(val,s.u)+'</b></div>';
    }
    var good=s.inv?(cli<=s.sec):(cli>=s.sec);
    var meCol=(s.sain!=null&&(s.inv?cli<=s.sain:cli>=s.sain))?"var(--green)":(good?"var(--yellow)":"var(--orange)");
    h+='<div class="card"><h3>'+s.n+' <span class="r">'+s.d+'</span></h3>'+
      bar(cli,meCol,"Vous",true)+bar(s.sec,"#5f6873","Rep\u00e8re")+
      (s.sain!=null?bar(s.sain,"rgba(34,197,94,.8)","Saine"):"")+
      '<div style="margin-top:7px">'+deltaChip(cli,s.sec,s.inv,s.u,"vs rep\u00e8re")+(s.sain!=null?" "+deltaChip(cli,s.sain,s.inv,s.u,"vs zone cible"):"")+'</div></div>';
  });
  h+='<p class="note"><b>Transparence :</b> les rep\u00e8res ci-dessus sont des rep\u00e8res de pilotage Verdict\u00ae, pas des moyennes officielles. La statistique sectorielle FIBEN v\u00e9rifi\u00e9e est affich\u00e9e s\u00e9par\u00e9ment plus haut. '+(d.etp>0?'Le CA/ETP utilise uniquement les '+fr(d.etp,1)+' ETP que vous avez renseign\u00e9s.':'Le CA/ETP est volontairement omis tant que vous n\u2019avez pas renseign\u00e9 votre effectif.')+'</p>';
  el.innerHTML=h;
}

